def _normalize_dictionary_origin_process(value: str | None) -> str:
    normalized = str(value or "").strip().lower()
    if normalized == "translations":
        normalized = "translations_block"
    elif normalized == "reader_selection_gpt_save":
        normalized = "reader"
    if normalized in DICTIONARY_ORIGIN_ALLOWED:
        return normalized
    return "unknown"


def build_translation_session_minutes_sql(alias: str = "p") -> str:
    safe_alias = re.sub(r"[^A-Za-z0-9_]", "", str(alias or "p")) or "p"
    return (
        f"CASE "
        f"WHEN {safe_alias}.active_seconds IS NOT NULL THEN "
        f"(COALESCE({safe_alias}.active_seconds, 0)::numeric / 60.0) "
        f"WHEN {safe_alias}.end_time IS NOT NULL AND {safe_alias}.start_time IS NOT NULL THEN "
        f"(EXTRACT(EPOCH FROM ({safe_alias}.end_time - {safe_alias}.start_time)) / 60.0) "
        f"ELSE 0 END"
    )


def refresh_user_display_name(user_id: int, display_name: str) -> int:
    """Persist the user's Telegram display name onto their progress rows.

    Analytics reads the username from the LATEST bt_3_user_progress row, so users whose
    rows have a blank username show up as "Unknown". We fill in the name for every user
    on their webapp visits — but only where it is currently blank/"Unknown", so an existing
    real name is never clobbered. Returns the number of rows updated.
    """
    name = str(display_name or "").strip()
    if not name or int(user_id or 0) <= 0:
        return 0
    with get_db_connection_context() as conn:
        with conn.cursor() as cursor:
            cursor.execute(
                """
                UPDATE bt_3_user_progress
                SET username = %s
                WHERE user_id = %s
                  AND (username IS NULL OR btrim(username) = '' OR username = 'Unknown')
                """,
                (name, int(user_id)),
            )
            return cursor.rowcount or 0


# === Кто есть кто: ОДНО имя пользователя на весь продукт ====================================
# Имя человека исторически копировалось в два десятка таблиц (переводы, прогресс, сообщения,
# результаты спринтов, участники баттлов…). Каждая копия писалась своим куском кода в свой
# момент, и стоило одному месту записать пусто — отчёт, который читал именно эту таблицу,
# здоровался с человеком как "None". Здесь один источник правды: пишет его одна функция
# (remember_user_identity — её зовут все точки касания: любое сообщение боту, любой вход в
# приложение), читает тоже одна (get_user_display_name / get_user_display_names). Старые
# колонки остаются как исторический след, но текстами для человека больше не управляют.
_USER_IDENTITY_SCHEMA_READY = False
_USER_IDENTITY_SCHEMA_LOCK = threading.Lock()
_USER_IDENTITY_CACHE: dict[int, tuple[str, float]] = {}
_USER_IDENTITY_CACHE_LOCK = threading.Lock()
_USER_IDENTITY_CACHE_TTL_SEC = max(
    0, int(str(os.getenv("USER_IDENTITY_CACHE_TTL_SEC") or "600").strip() or "600")
)

# Не имена, а служебные пометки и заглушки: их нельзя показывать человеку и нельзя
# запоминать как имя. Список закрытый — всё остальное считаем настоящим именем.
_IDENTITY_JUNK_NAMES = {
    "unknown",
    "unknown user",
    "unknown_user",
    "none",
    "null",
    "nan",
    "admin",
    "owner_admin",
    "student",
    "неизвестный пользователь",
}
_IDENTITY_JUNK_PATTERN = re.compile(r"^(user|useer|load[_\- ]?test)[_\- ]*\d*$", re.IGNORECASE)


def clean_identity_name(value: str | None) -> str:
    """Настоящее имя или "" — заглушки ("Unknown", "user_123", "load_test_…") отсекаются."""
    label = str(value or "").strip().lstrip("@").strip()
    if not label:
        return ""
    if label.lower() in _IDENTITY_JUNK_NAMES:
        return ""
    if _IDENTITY_JUNK_PATTERN.match(label):
        return ""
    return label


def ensure_user_identity_schema() -> None:
    global _USER_IDENTITY_SCHEMA_READY
    if _USER_IDENTITY_SCHEMA_READY:
        return
    with _USER_IDENTITY_SCHEMA_LOCK:
        if _USER_IDENTITY_SCHEMA_READY:
            return
        with get_db_connection_context() as conn:
            with conn.cursor() as cursor:
                cursor.execute("SELECT pg_advisory_xact_lock(%s);", (94081137,))
                cursor.execute(
                    """
                    CREATE TABLE IF NOT EXISTS bt_3_user_identity (
                        user_id BIGINT PRIMARY KEY,
                        display_name TEXT NOT NULL,
                        first_name TEXT,
                        last_name TEXT,
                        tg_username TEXT,
                        source TEXT,
                        refreshed_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
                        created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
                    );
                    """
                )
            conn.commit()
        _USER_IDENTITY_SCHEMA_READY = True


# Настоящий Telegram-id — это минимум шестизначное число. Всё, что меньше, приходит из
# тестов и заглушек: такие "пользователи" не должны попадать в таблицу личности, иначе
# прогон тестов дописывает в неё людей, которых не существует.
_MIN_REAL_TELEGRAM_USER_ID = 100_000


def is_real_telegram_user_id(user_id: int | None) -> bool:
    safe_user_id = int(user_id or 0)
    if safe_user_id < _MIN_REAL_TELEGRAM_USER_ID:
        return False
    return safe_user_id < SYNTHETIC_TELEGRAM_USER_ID_MIN


def _identity_cache_get(user_id: int) -> str | None:
    if _USER_IDENTITY_CACHE_TTL_SEC <= 0:
        return None
    with _USER_IDENTITY_CACHE_LOCK:
        hit = _USER_IDENTITY_CACHE.get(int(user_id))
    if not hit:
        return None
    name, stored_at = hit
    if (time.time() - stored_at) > _USER_IDENTITY_CACHE_TTL_SEC:
        return None
    return name


def _identity_cache_put(user_id: int, display_name: str) -> None:
    if _USER_IDENTITY_CACHE_TTL_SEC <= 0:
        return
    with _USER_IDENTITY_CACHE_LOCK:
        _USER_IDENTITY_CACHE[int(user_id)] = (str(display_name or ""), time.time())


def remember_user_identity(
    user_id: int,
    *,
    first_name: str | None = None,
    last_name: str | None = None,
    tg_username: str | None = None,
    display_name: str | None = None,
    source: str | None = None,
) -> str:
    """Запомнить, как зовут человека. Зовётся на КАЖДОМ касании (сообщение боту, вход в
    приложение, выдача сессии) — Telegram отдаёт свежее имя, мы его храним. Возвращает
    имя, которое теперь считается верным ("" — если ничего настоящего не передали и
    ничего не знали раньше). Пустое/служебное значение никогда не затирает настоящее."""
    safe_user_id = int(user_id or 0)
    if not is_real_telegram_user_id(safe_user_id):
        return ""
    first = clean_identity_name(first_name)
    last = str(last_name or "").strip()
    handle = clean_identity_name(tg_username)
    resolved = clean_identity_name(display_name) or " ".join(p for p in (first, last) if p).strip() or handle
    if not resolved:
        return get_user_display_name(safe_user_id)
    if _identity_cache_get(safe_user_id) == resolved:
        return resolved
    try:
        ensure_user_identity_schema()
        with get_db_connection_context() as conn:
            with conn.cursor() as cursor:
                cursor.execute(
                    """
                    INSERT INTO bt_3_user_identity
                        (user_id, display_name, first_name, last_name, tg_username, source, refreshed_at)
                    VALUES (%s, %s, %s, %s, %s, %s, NOW())
                    ON CONFLICT (user_id) DO UPDATE SET
                        display_name = EXCLUDED.display_name,
                        first_name = COALESCE(NULLIF(EXCLUDED.first_name, ''), bt_3_user_identity.first_name),
                        last_name = COALESCE(NULLIF(EXCLUDED.last_name, ''), bt_3_user_identity.last_name),
                        tg_username = COALESCE(NULLIF(EXCLUDED.tg_username, ''), bt_3_user_identity.tg_username),
                        source = EXCLUDED.source,
                        refreshed_at = NOW();
                    """,
                    (safe_user_id, resolved, first, last, handle, str(source or "").strip() or None),
                )
            conn.commit()
        _identity_cache_put(safe_user_id, resolved)
    except Exception:
        logging.warning("remember_user_identity failed user=%s", safe_user_id, exc_info=True)
    return resolved


# Откуда достать имя для того, кого мы ещё не записали в bt_3_user_identity: старые таблицы,
# куда имя копировалось раньше. Список доступа (bt_3_allowed_users) сюда НЕ входит — там
# лежат админские пометки вроде "owner_admin", а не имена.
_IDENTITY_LEGACY_SOURCES_SQL = """
    SELECT user_id, btrim(username) AS name, MAX(timestamp) AS seen_at
    FROM bt_3_translations
    WHERE user_id = ANY(%s) AND COALESCE(btrim(username), '') <> ''
    GROUP BY user_id, btrim(username)
    UNION ALL
    SELECT user_id, btrim(username), MAX(start_time)
    FROM bt_3_user_progress
    WHERE user_id = ANY(%s) AND COALESCE(btrim(username), '') <> ''
    GROUP BY user_id, btrim(username)
    UNION ALL
    SELECT user_id, btrim(username), MAX(timestamp)
    FROM bt_3_messages
    WHERE user_id = ANY(%s) AND COALESCE(btrim(username), '') <> ''
    GROUP BY user_id, btrim(username)
    UNION ALL
    SELECT user_id, btrim(user_name), MAX(created_at)
    FROM bt_3_challenge_results
    WHERE user_id = ANY(%s) AND COALESCE(btrim(user_name), '') <> ''
    GROUP BY user_id, btrim(user_name)
"""


def _load_identity_from_legacy_tables(user_ids: list[int]) -> dict[int, str]:
    if not user_ids:
        return {}
    out: dict[int, str] = {}
    try:
        with get_db_connection_context() as conn:
            with conn.cursor() as cursor:
                cursor.execute(
                    "WITH candidates AS ("
                    + _IDENTITY_LEGACY_SOURCES_SQL
                    + ") SELECT DISTINCT ON (user_id) user_id, name FROM candidates "
                    "ORDER BY user_id, seen_at DESC NULLS LAST;",
                    (user_ids, user_ids, user_ids, user_ids),
                )
                for uid, name in cursor.fetchall() or []:
                    cleaned = clean_identity_name(name)
                    if cleaned:
                        out[int(uid)] = cleaned
    except Exception:
        logging.warning("identity legacy lookup failed", exc_info=True)
    return out


def list_known_telegram_user_ids() -> list[int]:
    """Все, кого бот когда-либо видел, — по таблице личности (в неё пишется каждое
    обновление из телеграма). Нужно рассылке заданий: она обязана дотянуться и до того,
    кто нажал «Старт» и пропал, — следов в таблицах активности он не оставляет."""
    try:
        ensure_user_identity_schema()
        with get_db_connection_context() as conn:
            with conn.cursor() as cursor:
                cursor.execute("SELECT user_id FROM bt_3_user_identity WHERE user_id > 0;")
                rows = cursor.fetchall() or []
    except Exception:
        logging.warning("list_known_telegram_user_ids failed", exc_info=True)
        return []
    return sorted({int(row[0]) for row in rows if is_real_telegram_user_id(row[0])})


def get_user_display_names(user_ids: list[int] | set[int]) -> dict[int, str]:
    """Имена для набора пользователей. Сначала таблица личности; кого там нет — достаём из
    старых таблиц и тут же записываем в личность, чтобы второй раз не искать. Пользователи,
    про которых мы ничего не знаем, в ответе отсутствуют — звать их по id нельзя."""
    ids = sorted({int(uid) for uid in (user_ids or []) if is_real_telegram_user_id(uid)})
    if not ids:
        return {}
    out: dict[int, str] = {}
    missing: list[int] = []
    for uid in ids:
        cached = _identity_cache_get(uid)
        if cached:
            out[uid] = cached
        else:
            missing.append(uid)
    if missing:
        try:
            ensure_user_identity_schema()
            with get_db_connection_context() as conn:
                with conn.cursor() as cursor:
                    cursor.execute(
                        "SELECT user_id, display_name FROM bt_3_user_identity WHERE user_id = ANY(%s);",
                        (missing,),
                    )
                    for uid, name in cursor.fetchall() or []:
                        cleaned = clean_identity_name(name)
                        if cleaned:
                            out[int(uid)] = cleaned
                            _identity_cache_put(int(uid), cleaned)
        except Exception:
            logging.warning("identity lookup failed", exc_info=True)
    still_missing = [uid for uid in ids if uid not in out]
    for uid, name in _load_identity_from_legacy_tables(still_missing).items():
        out[uid] = name
        remember_user_identity(uid, display_name=name, source="legacy_tables")
    return out


def get_user_display_name(user_id: int) -> str:
    """Имя одного пользователя или "" — заглушки вроде "user_123" не возвращаются никогда."""
    safe_user_id = int(user_id or 0)
    if safe_user_id <= 0:
        return ""
    return get_user_display_names([safe_user_id]).get(safe_user_id, "")


def sync_translation_session_activity(
    *,
    user_id: int,
    session_id: int | str,
    action: str,
) -> dict[str, Any] | None:
    normalized_action = str(action or "").strip().lower()
    if normalized_action not in {"start", "resume", "pause", "stop"}:
        raise ValueError(f"Unsupported translation session activity action: {action}")

    with get_db_connection_context() as conn:
        with conn.cursor() as cursor:
            if normalized_action in {"start", "resume"}:
                cursor.execute(
                    """
                    UPDATE bt_3_user_progress
                    SET
                        active_seconds = COALESCE(active_seconds, 0),
                        active_started_at = CASE
                            WHEN completed = FALSE THEN NOW()
                            ELSE active_started_at
                        END,
                        active_running = CASE
                            WHEN completed = FALSE THEN TRUE
                            ELSE COALESCE(active_running, FALSE)
                        END
                    WHERE user_id = %s
                      AND session_id = %s
                    RETURNING
                        session_id,
                        completed,
                        COALESCE(active_seconds, 0),
                        COALESCE(active_running, FALSE),
                        active_started_at;
                    """,
                    (int(user_id), str(session_id)),
                )
            else:
                cursor.execute(
                    """
                    UPDATE bt_3_user_progress
                    SET
                        active_seconds = COALESCE(active_seconds, 0)
                            + CASE
                                WHEN COALESCE(active_running, FALSE) = TRUE
                                 AND active_started_at IS NOT NULL
                                    THEN GREATEST(
                                        0,
                                        EXTRACT(EPOCH FROM (NOW() - active_started_at))::BIGINT
                                    )
                                ELSE 0
                            END,
                        active_started_at = NULL,
                        active_running = FALSE
                    WHERE user_id = %s
                      AND session_id = %s
                    RETURNING
                        session_id,
                        completed,
                        COALESCE(active_seconds, 0),
                        COALESCE(active_running, FALSE),
                        active_started_at;
                    """,
                    (int(user_id), str(session_id)),
                )
            row = cursor.fetchone()

    if not row:
        return None

    return {
        "session_id": str(row[0]),
        "completed": bool(row[1]),
        "active_seconds": int(row[2] or 0),
        "active_running": bool(row[3]),
        "active_started_at": row[4].isoformat() if row[4] else None,
    }


def _coerce_json_object(value) -> dict:
    if isinstance(value, dict):
        return dict(value)
    if isinstance(value, str):
        try:
            parsed = json.loads(value)
            if isinstance(parsed, dict):
                return dict(parsed)
        except Exception:
            return {}
    return {}


def _normalize_dictionary_text_key(value: str | None) -> str:
    compact = re.sub(r"\s+", " ", str(value or "").strip())
    return compact.casefold()


_GERMAN_LEADING_ARTICLE_RE = re.compile(r"^(?:der|die|das|ein|eine|einen|einem|einer|eines)\s+")


def _normalize_dictionary_headword_key(value: str | None) -> str:
    """Ключ БЕЗ артикля: «der Durchfall» и «Durchfall» — одно и то же слово, и запрос
    любого из вариантов обязан находить запись.

    ВАЖНО: это ключ ПОИСКА, а не ключ уникальности. Сливать записи по нему нельзя —
    «der Kiefer» (челюсть) и «die Kiefer» (сосна) дают один заголовок, но это разные
    слова (замер 2026-07-21: из 733 «дублей» одинаковый перевод лишь у 3 групп)."""
    return _GERMAN_LEADING_ARTICLE_RE.sub("", _normalize_dictionary_text_key(value)).strip()


_MULTI_SPACE_RE = re.compile(r"\s+")


def _squash_space(value: str | None) -> str:
    """Схлопнуть пробелы и обрезать края. В соседних модулях это `_normalize_space`,
    но в этом файле такой функции нет — своя, чтобы не тащить импорт ради одной строки."""
    return _MULTI_SPACE_RE.sub(" ", str(value or "").strip())


_GERMAN_NOUN_SURFACE_RE = re.compile(r"^[A-ZÄÖÜ][^\s]*$")
# Отдельный, НЕЧУВСТВИТЕЛЬНЫЙ к регистру: в банке лежат и «die Fahne», и «Die Fahne»,
# а соседний _GERMAN_LEADING_ARTICLE_RE ловит только строчный вариант — с ним заголовок
# «Die Fahne» получил бы второй артикль.
_LEADING_ARTICLE_ANY_CASE_RE = re.compile(r"^(?:der|die|das|ein|eine|einen|einem|einer|eines)\s+", re.I)


def compose_german_headword(
    word: str | None,
    *,
    article: str | None = None,
    gender: str | None = None,
    number: str | None = None,
    pos: str | None = None,
) -> str:
    """Немецкий заголовок так, как его видит человек: слово вместе с артиклем.

    ОДНА формула на всё приложение. До 14.08.2026 их было две: список «мои слова» брал
    голую колонку `word_de`, а карточка складывала заголовок из разбора. Артикль живёт
    отдельным полем (`article`) и родом единицы (`gender`), в колонку попадает не всегда —
    и одно и то же слово выглядело по-разному: «die Sternschnuppen» в карточке и
    «Sternschnuppen» в списке. Замер 13.08.2026: из голых заголовков это больше половины,
    и род при этом известен почти у всех — добывать ничего не нужно, не хватало склейки.

    Правила те же, что у общей карточки (frontend/src/dictionary/WordBreakdown.jsx,
    resolveArticle), чтобы фронт и бэкенд не разъезжались:
      • у множественного числа артикль всегда «die» — род тут ни при чём;
      • иначе берётся артикль из разбора, а если его нет — род единицы;
      • артикль клеится ТОЛЬКО к одному слову с заглавной буквы: фразе и предложению он
        не положен, а к строке, где артикль уже стоит, второй не добавляется.

    Ничего не выдумывает: нет артикля и нет рода — возвращает слово как есть.
    """
    surface = _squash_space(word)
    if not surface:
        return ""
    # В немецком с заглавной пишутся только существительные. Глагол и прилагательное
    # приходят из сохранения как «Abbuchen», «Akut» — опускаем. Правило общее с
    # экраном и таблицами: german_grammar_tables.german_headword_case.
    from backend.german_grammar_tables import german_headword_case
    surface = german_headword_case(surface, pos)
    if _LEADING_ARTICLE_ANY_CASE_RE.match(surface):
        return surface  # артикль уже на месте
    if not _GERMAN_NOUN_SURFACE_RE.match(surface):
        return surface  # фраза, предложение или не немецкое существительное
    if str(number or "").strip().lower() in {"pl", "plural"}:
        return f"die {surface}"
    chosen = str(article or "").strip().lower() or str(gender or "").strip().lower()
    if chosen in {"der", "die", "das"}:
        return f"{chosen} {surface}"
    return surface


def _resolve_dictionary_source_target_texts(
    *,
    source_lang: str,
    target_lang: str,
    word_ru: str | None,
    translation_de: str | None,
    word_de: str | None,
    translation_ru: str | None,
    response_json: dict | None,
) -> tuple[str, str]:
    payload = _coerce_json_object(response_json)
    source_text = str(
        payload.get("source_text")
        or word_ru
        or payload.get("word_ru")
        or translation_ru
        or payload.get("translation_ru")
        or word_de
        or payload.get("word_de")
        or ""
    ).strip()
    target_text = str(
        payload.get("target_text")
        or translation_de
        or payload.get("translation_de")
        or word_de
        or payload.get("word_de")
        or translation_ru
        or payload.get("translation_ru")
        or ""
    ).strip()

    source_lang_value = _normalize_lang_code(source_lang)
    target_lang_value = _normalize_lang_code(target_lang)

    if not source_text and source_lang_value == "de":
        source_text = str(word_de or payload.get("word_de") or "").strip()
    if not target_text and target_lang_value == "de":
        target_text = str(translation_de or payload.get("translation_de") or "").strip()

    return source_text, target_text


def _apply_ru_de_dictionary_pair_alignment(
    *,
    source_lang: str,
    target_lang: str,
    german_text: str | None,
    russian_text: str | None,
    current_word_ru: str | None = None,
    current_translation_de: str | None = None,
    current_word_de: str | None = None,
    current_translation_ru: str | None = None,
    response_json: dict | None = None,
) -> tuple[dict, str, str, dict]:
    payload = _coerce_json_object(response_json)
    resolved_source_lang = _normalize_lang_code(source_lang)
    resolved_target_lang = _normalize_lang_code(target_lang)

    existing_source_text, existing_target_text = _resolve_dictionary_source_target_texts(
        source_lang=resolved_source_lang,
        target_lang=resolved_target_lang,
        word_ru=current_word_ru,
        translation_de=current_translation_de,
        word_de=current_word_de,
        translation_ru=current_translation_ru,
        response_json=payload,
    )

    normalized_german = str(german_text or "").strip()
    normalized_russian = str(russian_text or "").strip()

    source_text = existing_source_text
    target_text = existing_target_text

    if resolved_source_lang == "de" and normalized_german:
        source_text = normalized_german
    if resolved_target_lang == "de" and normalized_german:
        target_text = normalized_german
    if resolved_source_lang == "ru" and normalized_russian:
        source_text = normalized_russian
    if resolved_target_lang == "ru" and normalized_russian:
        target_text = normalized_russian

    word_ru = str(current_word_ru or "").strip()
    translation_de = str(current_translation_de or "").strip()
    word_de = str(current_word_de or "").strip()
    translation_ru = str(current_translation_ru or "").strip()

    if resolved_source_lang == "ru" and source_text:
        word_ru = source_text
        translation_ru = source_text
    if resolved_source_lang == "de" and source_text:
        word_de = source_text
        translation_de = source_text
    if resolved_target_lang == "de" and target_text:
        word_de = target_text
        translation_de = target_text
    if resolved_target_lang == "ru" and target_text:
        word_ru = target_text
        translation_ru = target_text

    payload["source_text"] = source_text
    payload["target_text"] = target_text
    payload["source_lang"] = resolved_source_lang or source_lang
    payload["target_lang"] = resolved_target_lang or target_lang
    payload["word_ru"] = word_ru
    payload["translation_de"] = translation_de
    payload["word_de"] = word_de
    payload["translation_ru"] = translation_ru

    return {
        "word_ru": word_ru,
        "translation_de": translation_de,
        "word_de": word_de,
        "translation_ru": translation_ru,
    }, source_text, target_text, payload


def _record_dedup_deleted_cards(cursor, *, user_id: int, keep_entry_id: int,
                                deleted_ids: list[int], origin: str) -> None:
    """Снять ПОЛНЫЙ снимок карточек прямо перед их удалением.

    До 13.08.2026 удаление дублей не оставляло следа вообще: писались только счётчики
    («за ночь удалено 6»), а что именно исчезло — не записывалось нигде. Восстановить
    было нечего и неоткуда: ни архивной таблицы, ни пометки «удалено», ни отмены.
    За два месяца так ушли 732 карточки, и что в них было — уже не узнать.

    Поэтому здесь лежит не запись о факте, а САМА карточка целиком, вместе с разбором,
    папкой и метками. Из этой таблицы карточку можно вернуть.

    Пишется в той же транзакции, что и удаление: если удаление откатится, откатится и
    след, и наоборот — не бывает удаления без записи."""
    if not deleted_ids:
        return
    cursor.execute(
        """
        CREATE TABLE IF NOT EXISTS bt_3_dict_dedup_deleted (
            id BIGSERIAL PRIMARY KEY,
            deleted_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
            user_id BIGINT NOT NULL,
            entry_id BIGINT NOT NULL,
            kept_entry_id BIGINT,
            origin TEXT,
            word_de TEXT,
            word_ru TEXT,
            translation_de TEXT,
            translation_ru TEXT,
            source_lang TEXT,
            target_lang TEXT,
            folder_id BIGINT,
            semantic_tag TEXT,
            response_json JSONB
        );
        """
    )
    cursor.execute(
        "CREATE INDEX IF NOT EXISTS idx_bt_3_dict_dedup_deleted_user_time "
        "ON bt_3_dict_dedup_deleted (user_id, deleted_at DESC);"
    )
    cursor.execute(
        """
        INSERT INTO bt_3_dict_dedup_deleted (
            user_id, entry_id, kept_entry_id, origin,
            word_de, word_ru, translation_de, translation_ru,
            source_lang, target_lang, folder_id, semantic_tag, response_json
        )
        SELECT q.user_id, q.id, %s, %s,
               q.word_de, q.word_ru, q.translation_de, q.translation_ru,
               q.source_lang, q.target_lang, q.folder_id, q.semantic_tag, q.response_json
        FROM bt_3_webapp_dictionary_queries q
        WHERE q.user_id = %s AND q.id = ANY(%s);
        """,
        (int(keep_entry_id), str(origin or "")[:40], int(user_id), list(deleted_ids)),
    )


def _dedupe_webapp_dictionary_entry_after_insert(
    conn,
    *,
    keep_entry_id: int,
    user_id: int,
    source_lang: str | None,
    target_lang: str | None,
    word_ru: str | None,
    translation_de: str | None,
    word_de: str | None,
    translation_ru: str | None,
    response_json: dict | None,
) -> int:
    normalized_source_lang = _normalize_lang_code(source_lang)
    normalized_target_lang = _normalize_lang_code(target_lang)
    source_text, target_text = _resolve_dictionary_source_target_texts(
        source_lang=normalized_source_lang,
        target_lang=normalized_target_lang,
        word_ru=word_ru,
        translation_de=translation_de,
        word_de=word_de,
        translation_ru=translation_ru,
        response_json=response_json,
    )
    normalized_source_text = _normalize_dictionary_text_key(source_text)
    normalized_target_text = _normalize_dictionary_text_key(target_text)
    if not normalized_source_text or not normalized_target_text:
        return 0

    # Отбор кандидатов сужен до ОДНОГО написания. Раньше здесь читались ВСЕ карточки
    # человека вместе с их разбором: замер 13.08.2026 — 14 170 карточек, 22 мс на сервере
    # и мегабайты JSON по сети. На пути сохранения такое недопустимо, а на масштабе
    # (2000 человек × 25 слов в сутки = 50 000 сохранений) — тем более.
    #
    # ⚠ Выражение обязано совпадать с индексом ДОСЛОВНО: индекс построен как
    # `(user_id, lower(btrim(word_de)))`, и стоит написать `lower(btrim(COALESCE(word_de,'')))`,
    # как планировщик уходит в полный перебор. Замер той же даты: 0,064 мс по индексу
    # против 22 мс с COALESCE — разница в 350 раз на ровном месте.
    #
    # Сужение может пропустить кандидата, у которого слово лежит только внутри
    # response_json, а колонка пуста. Это осознанный размен: непойманный дубль остаётся
    # лежать (его подберёт разовый прогон), а лишнего удаления не будет никогда.
    narrow_word = _squash_space(word_de).casefold()
    narrow_column = "LOWER(BTRIM(word_de))"
    if not narrow_word:
        narrow_word = _squash_space(word_ru).casefold()
        narrow_column = "LOWER(BTRIM(word_ru))"
    if not narrow_word:
        return 0

    with conn.cursor() as cursor:
        cursor.execute(
            f"""
            SELECT
                id,
                word_ru,
                translation_de,
                word_de,
                translation_ru,
                response_json,
                is_learned
            FROM bt_3_webapp_dictionary_queries
            WHERE user_id = %s
              AND id <> %s
              AND COALESCE(source_lang, '') = %s
              AND COALESCE(target_lang, '') = %s
              AND {narrow_column} = %s;
            """,
            (
                int(user_id),
                int(keep_entry_id),
                normalized_source_lang,
                normalized_target_lang,
                narrow_word,
            ),
        )
        rows = cursor.fetchall() or []

        duplicate_ids: list[int] = []
        preserve_learned = False
        for row in rows:
            existing_source_text, existing_target_text = _resolve_dictionary_source_target_texts(
                source_lang=normalized_source_lang,
                target_lang=normalized_target_lang,
                word_ru=row[1],
                translation_de=row[2],
                word_de=row[3],
                translation_ru=row[4],
                response_json=_coerce_json_object(row[5]),
            )
            if (
                _normalize_dictionary_text_key(existing_source_text) == normalized_source_text
                and _normalize_dictionary_text_key(existing_target_text) == normalized_target_text
            ):
                duplicate_ids.append(int(row[0]))
                preserve_learned = preserve_learned or bool(row[6])

        if preserve_learned:
            cursor.execute(
                """
                UPDATE bt_3_webapp_dictionary_queries
                SET is_learned = TRUE
                WHERE id = %s;
                """,
                (int(keep_entry_id),),
            )

        if duplicate_ids:
            _record_dedup_deleted_cards(
                cursor, user_id=user_id, keep_entry_id=keep_entry_id,
                deleted_ids=duplicate_ids, origin="сохранение",
            )
            # История обучения не должна пропадать вместе с дубликатом. Раньше строки
            # удалялись напрямую, а прогресс и журнал ответов оставались висеть в воздухе
            # (18 таких записей нашлось в проде) — то есть человек проходил слово, а после
            # схлопывания дублей это исчезало из его истории и из аналитики.
            cursor.execute(
                """
                UPDATE bt_3_card_review_log
                SET card_id = %s
                WHERE user_id = %s AND card_id = ANY(%s);
                """,
                (int(keep_entry_id), int(user_id), duplicate_ids),
            )
            # Прогресс переносим на выжившую карточку — но только если у неё своего ещё нет
            # (ключ user_id+card_id уникален). Берём самый продвинутый из дублей.
            cursor.execute(
                """
                WITH best AS (
                    SELECT id FROM bt_3_card_srs_state
                    WHERE user_id = %s AND card_id = ANY(%s)
                    ORDER BY reps DESC NULLS LAST, due_at DESC NULLS LAST
                    LIMIT 1
                )
                UPDATE bt_3_card_srs_state s
                SET card_id = %s
                FROM best
                WHERE s.id = best.id
                  AND NOT EXISTS (
                      SELECT 1 FROM bt_3_card_srs_state k
                      WHERE k.user_id = %s AND k.card_id = %s
                  );
                """,
                (int(user_id), duplicate_ids, int(keep_entry_id), int(user_id), int(keep_entry_id)),
            )
            cursor.execute(
                """
                DELETE FROM bt_3_card_srs_state
                WHERE user_id = %s AND card_id = ANY(%s);
                """,
                (int(user_id), duplicate_ids),
            )
            cursor.execute(
                """
                DELETE FROM bt_3_webapp_dictionary_queries
                WHERE user_id = %s
                  AND id = ANY(%s);
                """,
                (int(user_id), duplicate_ids),
            )

    return len(duplicate_ids)


def dedupe_personal_entry_after_save(user_id: int, entry_id: int) -> int:
    """Прибрать повторы ОДНОГО слова у ОДНОГО человека. Зовётся ИЗ ФОНА, после сохранения.

    Зачем отдельная дверь. Сохранение обязано оставаться мгновенным: человек нажал
    «сохранить» — увидел подтверждение и работает дальше. Поэтому уборка не висит в
    запросе, а уезжает в очередь и выполняется воркером (backend/job_queue.py,
    enqueue_dictionary_dedupe_after_save).

    Почему точечно, а не ночным проходом по всей базе (замерено 13.08.2026):
      • точечный поиск по индексу — 0,064 мс; ночной проход по словарю одного человека —
        60 мс, и он повторяется КАЖДУЮ ночь независимо от того, добавили что-то или нет;
      • расход точечной уборки растёт от НОВЫХ слов и выходит на полку, расход ночного
        прохода растёт от НАКОПЛЕННОГО и не остановится никогда;
      • ночной проход берёт максимум 500 человек за раз (bot_3.py) и 100 (веб-тир): на
        2000 пользователей он доходит до каждого раз в четыре дня, на 10 000 — раз в три
        недели. Это ломается раньше, чем становится дорого;
      • и главное: ночью правило ВЫНУЖДЕНО гадать, какая из двух карточек лучше (отсюда
        и «оставляем ту, где перевод длиннее» — прямой замер показал, что удаляемая
        оказывается богаче чаще, чем победитель). Здесь гадать нечего: мы знаем, какую
        карточку человек только что сохранил, и сносим лишь ПОЛНОЕ совпадение —
        совпали и слово, и перевод.

    Возвращает число убранных повторов. Ошибки не поднимает наружу: это уборка, она не
    имеет права уронить ничего выше себя.
    """
    safe_user_id = int(user_id or 0)
    safe_entry_id = int(entry_id or 0)
    if safe_user_id <= 0 or safe_entry_id <= 0:
        return 0
    try:
        with get_db_connection_context() as conn:
            with conn.cursor() as cursor:
                cursor.execute(
                    """
                    SELECT source_lang, target_lang, word_ru, translation_de,
                           word_de, translation_ru, response_json
                    FROM bt_3_webapp_dictionary_queries
                    WHERE id = %s AND user_id = %s;
                    """,
                    (safe_entry_id, safe_user_id),
                )
                row = cursor.fetchone()
            if not row:
                return 0
            removed = _dedupe_webapp_dictionary_entry_after_insert(
                conn,
                keep_entry_id=safe_entry_id,
                user_id=safe_user_id,
                source_lang=row[0],
                target_lang=row[1],
                word_ru=row[2],
                translation_de=row[3],
                word_de=row[4],
                translation_ru=row[5],
                response_json=_coerce_json_object(row[6]),
            )
        if removed:
            logging.info(
                "dedupe_personal_entry_after_save: user=%s entry=%s убрано повторов=%s",
                safe_user_id, safe_entry_id, removed,
            )
        return removed
    except Exception:
        logging.exception(
            "dedupe_personal_entry_after_save failed user=%s entry=%s",
            safe_user_id, safe_entry_id,
        )
        return 0


def dedupe_user_dictionary_by_source(
    user_id: int,
    since_datetime,  # datetime — only process groups that contain at least one entry newer than this
) -> dict:
    """
    Finds groups of user's dictionary entries sharing the same normalized source word,
    where at least one entry was added after since_datetime. For each such group:
    - Keeps the entry with the longest translation (most complete); ties broken by newest id.
    - Transfers is_learned=TRUE from any duplicate to the kept entry.
    - Transfers the best SRS state (most reps, highest stability) to the kept entry's card_id;
      removes weaker SRS states for deleted entries.
    - Deletes the duplicate entries.
    Returns a dict with stats (groups_found, entries_deleted, srs_transferred).
    """
    groups_found = 0
    entries_deleted = 0
    srs_transferred = 0

    with get_db_connection_context() as conn:
        with conn.cursor() as cursor:
            # Find all groups with 2+ entries sharing the same normalized source,
            # where at least one entry is newer than since_datetime.
            cursor.execute(
                """
                WITH all_entries AS (
                    SELECT
                        id,
                        source_lang,
                        target_lang,
                        LOWER(TRIM(REGEXP_REPLACE(
                            COALESCE(word_de, word_ru, ''), E'\\\\s+', ' ', 'g'
                        ))) AS source_norm,
                        COALESCE(
                            LENGTH(NULLIF(TRIM(COALESCE(translation_ru, '')), '')),
                            LENGTH(NULLIF(TRIM(COALESCE(translation_de, '')), '')),
                            0
                        ) AS translation_len,
                        -- Сам ТЕКСТ перевода, а не только его длина. Без него нельзя
                        -- отличить настоящий повтор от разных значений одного слова:
                        -- «die Fahne → перегар» и «die Fahne → Флаг, знамя» — не дубли.
                        LOWER(TRIM(REGEXP_REPLACE(
                            COALESCE(NULLIF(TRIM(COALESCE(translation_ru, '')), ''),
                                     TRIM(COALESCE(translation_de, '')), ''),
                            E'\\\\s+', ' ', 'g'
                        ))) AS translation_norm,
                        is_learned,
                        created_at
                    FROM bt_3_webapp_dictionary_queries
                    WHERE user_id = %s
                ),
                dup_groups AS (
                    SELECT source_norm, source_lang, target_lang
                    FROM all_entries
                    WHERE source_norm != ''
                    GROUP BY source_norm, source_lang, target_lang
                    HAVING COUNT(*) > 1
                       AND BOOL_OR(created_at > %s)
                )
                SELECT
                    e.id,
                    e.source_norm,
                    e.source_lang,
                    e.target_lang,
                    e.translation_len,
                    e.is_learned,
                    e.created_at,
                    e.translation_norm
                FROM all_entries e
                JOIN dup_groups d
                  ON d.source_norm = e.source_norm
                 AND d.source_lang IS NOT DISTINCT FROM e.source_lang
                 AND d.target_lang IS NOT DISTINCT FROM e.target_lang
                ORDER BY e.source_norm, e.source_lang, e.target_lang,
                         e.translation_len DESC, e.id DESC;
                """,
                (int(user_id), since_datetime),
            )
            rows = cursor.fetchall() or []

        if not rows:
            return {"groups_found": 0, "entries_deleted": 0, "srs_transferred": 0}

        # Group rows: first entry per (source_norm, source_lang, target_lang) = keep, rest = delete
        from collections import defaultdict
        groups: dict = defaultdict(list)
        for row in rows:
            (entry_id, source_norm, source_lang, target_lang, translation_len,
             is_learned, created_at, translation_norm) = row
            key = (source_norm, source_lang or "", target_lang or "")
            groups[key].append({
                "id": int(entry_id),
                "translation_len": int(translation_len or 0),
                "is_learned": bool(is_learned),
                "translation_norm": str(translation_norm or ""),
            })

        all_delete_ids: list[int] = []
        keep_learned_ids: list[int] = []  # keep_ids that should have is_learned set TRUE
        # Кому переезжает журнал ответов: (какая карточка остаётся, какие удаляются).
        # Без этого журнал уходил в никуда по каскаду — см. комментарий у самого переноса.
        review_moves: list[tuple[int, list[int]]] = []

        for key, entries in groups.items():
            if len(entries) < 2:
                continue
            keep = entries[0]  # already ordered: best translation len, newest id first
            # ─────────────────────────────────────────────────────────────────────────
            # ПРАВИЛО ИЗМЕНЕНО 13.08.2026 (решение владельца). Раньше удалялись ВСЕ
            # записи группы, кроме одной, а «лучшей» считалась та, где перевод длиннее
            # в символах. Прямой замер на живой базе показал, что посылка неверна:
            # из 309 записей, стоявших под удалением, точных близнецов было 10, а
            # удаляемая карточка оказывалась БОГАЧЕ победителя в 52 случаях против 45.
            # То есть правило чаще выбрасывало лучшее.
            # Хуже того, оно сносило разные значения одного слова:
            #     die Fahne → «перегар»       (7 знаков)  — удалялась
            #     die Fahne → «Флаг, знамя»  (11 знаков)  — оставалась
            # Теперь удаляется ТОЛЬКО полное совпадение: одинаковое слово И одинаковый
            # перевод. Всё остальное — разные значения, они остаются жить.
            # ─────────────────────────────────────────────────────────────────────────
            keep_translation = keep["translation_norm"]
            duplicates = [
                e for e in entries[1:]
                if e["translation_norm"] and e["translation_norm"] == keep_translation
            ]
            if not duplicates:
                continue
            groups_found += 1
            keep_id = keep["id"]
            delete_ids = [e["id"] for e in duplicates]
            any_learned = keep["is_learned"] or any(e["is_learned"] for e in duplicates)
            if any_learned and not keep["is_learned"]:
                keep_learned_ids.append(keep_id)
            all_delete_ids.extend(delete_ids)
            review_moves.append((keep_id, list(delete_ids)))

            # SRS: find best state among all entries in group, move it to keep_id
            all_group_ids = [keep_id] + delete_ids
            with conn.cursor() as cursor:
                cursor.execute(
                    """
                    SELECT card_id, reps, stability, status, due_at, last_review_at,
                           interval_days, lapses, step
                    FROM bt_3_card_srs_state
                    WHERE user_id = %s AND card_id = ANY(%s)
                    ORDER BY reps DESC, stability DESC NULLS LAST
                    LIMIT 1;
                    """,
                    (int(user_id), all_group_ids),
                )
                best_srs = cursor.fetchone()
                if best_srs and int(best_srs[0]) != keep_id:
                    # Best SRS state is on a duplicate — re-point it to keep_id
                    cursor.execute(
                        """
                        DELETE FROM bt_3_card_srs_state
                        WHERE user_id = %s AND card_id = %s;
                        """,
                        (int(user_id), int(keep_id)),
                    )
                    cursor.execute(
                        """
                        UPDATE bt_3_card_srs_state
                        SET card_id = %s, updated_at = NOW()
                        WHERE user_id = %s AND card_id = %s;
                        """,
                        (int(keep_id), int(user_id), int(best_srs[0])),
                    )
                    srs_transferred += 1

        if not all_delete_ids:
            return {"groups_found": groups_found, "entries_deleted": 0, "srs_transferred": srs_transferred}

        with conn.cursor() as cursor:
            # Transfer is_learned to kept entries
            if keep_learned_ids:
                cursor.execute(
                    """
                    UPDATE bt_3_webapp_dictionary_queries
                    SET is_learned = TRUE, updated_at = NOW()
                    WHERE user_id = %s AND id = ANY(%s);
                    """,
                    (int(user_id), keep_learned_ids),
                )
            # Remove SRS states for entries about to be deleted (weaker ones)
            # Журнал ответов ПЕРЕЕЗЖАЕТ на выжившую карточку, а не сгорает вместе с
            # удаляемой. У bt_3_card_review_log внешний ключ стоит ON DELETE CASCADE
            # (как и у bt_3_flashcard_stats, _seen, _manual_training_selection), поэтому
            # без этого переноса удаление тихо стирало историю: замер 13.08.2026 — 100
            # записей журнала на текущих кандидатах. В соседней функции этого файла
            # перенос сделан давно и с прямой пометкой «История обучения не должна
            # пропадать вместе с дубликатом» — здесь его просто забыли.
            for keep_target, moved_ids in review_moves:
                if not moved_ids:
                    continue
                _record_dedup_deleted_cards(
                    cursor, user_id=user_id, keep_entry_id=keep_target,
                    deleted_ids=moved_ids, origin="ночной прогон",
                )
                cursor.execute(
                    """
                    UPDATE bt_3_card_review_log
                    SET card_id = %s
                    WHERE user_id = %s AND card_id = ANY(%s);
                    """,
                    (int(keep_target), int(user_id), moved_ids),
                )
            cursor.execute(
                """
                DELETE FROM bt_3_card_srs_state
                WHERE user_id = %s AND card_id = ANY(%s);
                """,
                (int(user_id), all_delete_ids),
            )
            # Delete the duplicate dictionary entries
            cursor.execute(
                """
                DELETE FROM bt_3_webapp_dictionary_queries
                WHERE user_id = %s AND id = ANY(%s);
                """,
                (int(user_id), all_delete_ids),
            )
            entries_deleted = len(all_delete_ids)
        conn.commit()

    return {
        "groups_found": groups_found,
        "entries_deleted": entries_deleted,
        "srs_transferred": srs_transferred,
    }


def record_dict_dedup_run(
    *,
    users_processed: int,
    groups_found: int,
    entries_deleted: int,
) -> None:
    """Persist the totals of one nightly dictionary-dedup run.

    Stored durably in Postgres (not Redis) so the weekly admin report can prove the
    duplicate-removal job is actually doing work, surviving redeploys / Redis flushes.
    Best-effort: never raises into the scheduler job.
    """
    try:
        with get_db_connection_context() as conn:
            with conn.cursor() as cursor:
                cursor.execute(
                    """
                    CREATE TABLE IF NOT EXISTS bt_3_dict_dedup_runs (
                        id BIGSERIAL PRIMARY KEY,
                        ran_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
                        users_processed INTEGER NOT NULL DEFAULT 0,
                        groups_found INTEGER NOT NULL DEFAULT 0,
                        entries_deleted INTEGER NOT NULL DEFAULT 0
                    );
                    """
                )
                cursor.execute(
                    "CREATE INDEX IF NOT EXISTS idx_bt_3_dict_dedup_runs_ran_at "
                    "ON bt_3_dict_dedup_runs (ran_at);"
                )
                cursor.execute(
                    """
                    INSERT INTO bt_3_dict_dedup_runs (users_processed, groups_found, entries_deleted)
                    VALUES (%s, %s, %s);
                    """,
                    (int(users_processed), int(groups_found), int(entries_deleted)),
                )
            conn.commit()
    except Exception:
        logging.exception("record_dict_dedup_run failed")


def record_artikel_nightly_metrics(
    *,
    run_date,
    words_added: dict | None = None,
    words_total: int = 0,
    mnemonics: int = 0,
    audio: int = 0,
    images: int = 0,
) -> None:
    """Accumulate one date's Artikel-Trainer nightly generation totals (for the
    morning admin report). Several jobs contribute on the same Vienna date (02:30
    word autofill, 03:40 + 08:00 media prewarm), so MEDIA counters add up while the
    word fields are set once by the autofill job. One row per run_date. Best-effort;
    never raises into a scheduler job."""
    try:
        import json as _json
        wa_json = _json.dumps(words_added or {}, ensure_ascii=False)
        with get_db_connection_context() as conn:
            with conn.cursor() as cursor:
                cursor.execute(
                    """
                    CREATE TABLE IF NOT EXISTS bt_3_artikel_nightly_runs (
                        run_date    DATE PRIMARY KEY,
                        words_added JSONB NOT NULL DEFAULT '{}'::jsonb,
                        words_total INTEGER NOT NULL DEFAULT 0,
                        mnemonics   INTEGER NOT NULL DEFAULT 0,
                        audio       INTEGER NOT NULL DEFAULT 0,
                        images      INTEGER NOT NULL DEFAULT 0,
                        updated_at  TIMESTAMPTZ NOT NULL DEFAULT NOW()
                    );
                    """
                )
                cursor.execute(
                    """
                    INSERT INTO bt_3_artikel_nightly_runs
                        (run_date, words_added, words_total, mnemonics, audio, images, updated_at)
                    VALUES (%s, %s::jsonb, %s, %s, %s, %s, NOW())
                    ON CONFLICT (run_date) DO UPDATE SET
                        words_added = CASE WHEN EXCLUDED.words_added <> '{}'::jsonb
                                          THEN EXCLUDED.words_added
                                          ELSE bt_3_artikel_nightly_runs.words_added END,
                        words_total = CASE WHEN EXCLUDED.words_total > 0
                                          THEN EXCLUDED.words_total
                                          ELSE bt_3_artikel_nightly_runs.words_total END,
                        mnemonics   = bt_3_artikel_nightly_runs.mnemonics + EXCLUDED.mnemonics,
                        audio       = bt_3_artikel_nightly_runs.audio     + EXCLUDED.audio,
                        images      = bt_3_artikel_nightly_runs.images    + EXCLUDED.images,
                        updated_at  = NOW();
                    """,
                    (run_date, wa_json, int(words_total),
                     int(mnemonics), int(audio), int(images)),
                )
            conn.commit()
    except Exception:
        logging.exception("record_artikel_nightly_metrics failed")


def get_artikel_nightly_metrics(run_date=None) -> dict | None:
    """The Artikel-Trainer nightly totals for a date (default: the most recent run).
    Returns {run_date, words_added:{theme:n}, words_total, mnemonics, audio, images}
    or None when there's no data yet."""
    try:
        with get_db_connection_context() as conn:
            with conn.cursor() as cursor:
                cursor.execute("SELECT to_regclass('public.bt_3_artikel_nightly_runs');")
                if not (cursor.fetchone() or [None])[0]:
                    return None
                cursor.execute(
                    """
                    SELECT run_date, words_added, words_total, mnemonics, audio, images
                    FROM bt_3_artikel_nightly_runs
                    WHERE (%s::date IS NULL OR run_date = %s::date)
                    ORDER BY run_date DESC
                    LIMIT 1;
                    """,
                    (run_date, run_date),
                )
                r = cursor.fetchone()
        if not r:
            return None
        wa = r[1]
        if isinstance(wa, str):
            import json as _json
            try:
                wa = _json.loads(wa)
            except Exception:
                wa = {}
        return {"run_date": r[0], "words_added": wa or {}, "words_total": int(r[2] or 0),
                "mnemonics": int(r[3] or 0), "audio": int(r[4] or 0), "images": int(r[5] or 0)}
    except Exception:
        logging.exception("get_artikel_nightly_metrics failed")
        return None


def run_dictionary_dedup_now(*, max_users: int = 200, since_days: int = 7) -> dict:
    """Run the dictionary dedup immediately (admin /dedupnow), independent of the
    nightly scheduler and of Redis: scans the last `since_days` for up to
    `max_users` users, dedupes, records the run, and returns totals. Dedup is
    idempotent, so a fixed window is safe."""
    from datetime import datetime as _dt, timedelta as _td
    since = _dt.utcnow() - _td(days=int(since_days))
    processed = total_groups = total_deleted = total_srs = 0
    user_ids: list[int] = []
    try:
        with get_db_connection_context() as conn:
            with conn.cursor() as cursor:
                cursor.execute(
                    "SELECT DISTINCT user_id FROM bt_3_webapp_dictionary_queries ORDER BY user_id;"
                )
                user_ids = [int(r[0]) for r in (cursor.fetchall() or [])]
    except Exception:
        logging.exception("run_dictionary_dedup_now: failed to list users")
        return {"ok": False, "users_total": 0, "users_processed": 0,
                "groups_found": 0, "entries_deleted": 0, "srs_transferred": 0}
    for uid in user_ids[: int(max_users)]:
        try:
            res = dedupe_user_dictionary_by_source(user_id=uid, since_datetime=since)
        except Exception:
            logging.exception("run_dictionary_dedup_now: error user_id=%s", uid)
            continue
        total_groups += int(res.get("groups_found") or 0)
        total_deleted += int(res.get("entries_deleted") or 0)
        total_srs += int(res.get("srs_transferred") or 0)
        processed += 1
    record_dict_dedup_run(users_processed=processed, groups_found=total_groups, entries_deleted=total_deleted)
    return {"ok": True, "users_total": len(user_ids), "users_processed": processed,
            "groups_found": total_groups, "entries_deleted": total_deleted,
            "srs_transferred": total_srs}


# ── "Работа над ошибками": durable mistakes store + spaced repetition ─────────
_MISTAKE_INTERVALS = [1, 3, 7, 16]  # days; a correct review advances; past the top → mastered

# A review becomes due at the START of the local day N days ahead (Europe/Vienna) — NOT a
# rolling +24h. So a mistake made this afternoon surfaces with tomorrow morning's review
# batch alongside everything else, instead of only after a literal 24h (same Europe/Vienna
# calendar convention the trial policy uses). N=1 → next local midnight.
_REVIEW_TZ = "Europe/Vienna"


def _due_at_next_local_day_sql(days_sql: str) -> str:
    """SQL expr (timestamptz) = midnight starting the day `days_sql` days from today in
    _REVIEW_TZ. `days_sql` must be a trusted int literal (e.g. '1') or a '%s' placeholder —
    never raw user input."""
    return (
        "((date_trunc('day', (NOW() AT TIME ZONE '" + _REVIEW_TZ + "'))"
        " + ((" + days_sql + ")::text || ' days')::interval)"
        " AT TIME ZONE '" + _REVIEW_TZ + "')"
    )


def ensure_aufgabe_mistakes_schema() -> None:
    with get_db_connection_context() as conn:
        with conn.cursor() as cur:
            cur.execute(
                """
                CREATE TABLE IF NOT EXISTS bt_3_aufgabe_mistakes (
                    id BIGSERIAL PRIMARY KEY,
                    user_id BIGINT NOT NULL,
                    content_hash TEXT NOT NULL,
                    format TEXT NOT NULL,
                    payload JSONB NOT NULL DEFAULT '{}'::jsonb,
                    correct_answer TEXT,
                    last_wrong_answer TEXT,
                    interval_days INT NOT NULL DEFAULT 1,
                    review_count INT NOT NULL DEFAULT 0,
                    mastered BOOLEAN NOT NULL DEFAULT FALSE,
                    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
                    due_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
                    updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
                );
                """
            )
            cur.execute(
                "CREATE UNIQUE INDEX IF NOT EXISTS uq_bt3_mistakes_user_hash "
                "ON bt_3_aufgabe_mistakes (user_id, content_hash);"
            )
            cur.execute(
                "CREATE INDEX IF NOT EXISTS idx_bt3_mistakes_due "
                "ON bt_3_aufgabe_mistakes (user_id, mastered, due_at);"
            )
            # Отметка «это задание разобрали вот тогда». Нужна отдельная от updated_at:
            # updated_at двигает и запись НОВОЙ ошибки, а порция дня должна считать
            # только разборы. Старые строки остаются NULL — в первый день после
            # выкладки человек просто получит полную порцию, дальше счёт точный.
            cur.execute(
                "ALTER TABLE bt_3_aufgabe_mistakes "
                "ADD COLUMN IF NOT EXISTS last_review_at TIMESTAMPTZ;"
            )
            cur.execute(
                "CREATE INDEX IF NOT EXISTS idx_bt3_mistakes_reviewed "
                "ON bt_3_aufgabe_mistakes (user_id, last_review_at);"
            )
        conn.commit()


def _mistake_hash(fmt: str, payload: dict, correct_answer: str) -> str:
    import hashlib
    p = payload or {}
    seed = "|".join([
        str(fmt or ""),
        str(correct_answer or ""),
        str(p.get("satz") or p.get("before") or p.get("original")
            or p.get("wort") or p.get("s") or " ".join(p.get("woerter") or [])),
    ])
    return hashlib.sha1(seed.encode("utf-8")).hexdigest()[:32]


def _norm_degenerate_token(s) -> str:
    """Lowercase + strip surrounding punctuation/space for degeneracy comparisons."""
    return str(s or "").strip().strip(".,!?;:()[]{}\"'«»").strip().lower()


# The "glue" a wortbildung gap must contain besides the derived noun: the case-marked
# article and/or the preposition the noun governs. Supplying it IS the grammar part of
# the exercise ("Lieferung der", "Interesse an der", "Furcht vor", "Teilnahme am").
_WORTBILDUNG_ARTICLES = {"der", "die", "das", "des", "dem", "den"}
_WORTBILDUNG_PREPOSITIONS = {
    "an", "auf", "aus", "bei", "durch", "für", "gegen", "gegenüber", "in", "mit",
    "nach", "ohne", "seit", "trotz", "über", "um", "unter", "von", "vor", "wegen",
    "zu", "zwischen",
}
# Preposition+article merges — one token, but the case is baked in.
_WORTBILDUNG_MERGED = {
    "am", "ans", "aufs", "beim", "fürs", "im", "ins", "ums", "vom", "zum", "zur",
}
_WORTBILDUNG_GLUE = _WORTBILDUNG_ARTICLES | _WORTBILDUNG_PREPOSITIONS | _WORTBILDUNG_MERGED


def wortbildung_gap_is_grammatical(correct) -> bool:
    """True when a wortbildung answer is «Nomen + Funktionswort(e)» — i.e. the gap
    makes the learner decide a case/rection, not just retype a noun. Shape:
    the first token is the derived noun, every following token (1–2 of them) is an
    article, a governed preposition or a merged form. Shared by the build-time gate
    in bot_3._aufgabe_payload_from_item and by is_degenerate_aufgabe, so an item that
    passes generation is never killed later (and vice versa)."""
    toks = str(correct or "").split()
    if not (2 <= len(toks) <= 3):
        return False
    return all(_norm_degenerate_token(t) in _WORTBILDUNG_GLUE for t in toks[1:])


# ── Hörlücke difficulty ──────────────────────────────────────────────────────
# A blank that hides ONE unstressed function word ("_____ das Wochenende" → "auf")
# is no exercise: the learner guesses the preposition from the printed rest without
# hearing anything. So a gap must swallow a whole WORTGRUPPE — verb + governed
# preposition ("kümmert sich um"), preposition + article + noun ("mit den Kollegen"),
# da-compound + participle ("darüber gesprochen"). Deterministic rule: 2–4 tokens,
# at least one of them carrying content (noun/verb/participle/adjective), i.e. NOT a
# chunk built purely of articles, prepositions, pronouns, particles and auxiliaries.
_HOER_PRONOUNS = {
    "ich", "du", "er", "sie", "es", "wir", "ihr", "man", "mich", "dich", "sich",
    "uns", "euch", "mir", "dir", "ihm", "ihn", "ihnen", "wer", "wen", "wem",
    "mein", "meine", "meinem", "meinen", "meiner", "meines",
    "dein", "deine", "deinem", "deinen", "deiner", "deines",
    "sein", "seine", "seinem", "seinen", "seiner", "seines",
    "ihre", "ihrem", "ihren", "ihrer", "ihres",
    "unser", "unsere", "unserem", "unseren", "unserer", "unseres",
    "euer", "eure", "eurem", "euren", "eurer", "eures",
}
_HOER_DA_WO_COMPOUNDS = {
    "dabei", "dadurch", "dafür", "dagegen", "damit", "danach", "daran", "darauf",
    "daraus", "darin", "darüber", "darum", "darunter", "davon", "davor", "dazu",
    "hierfür", "hiermit", "wobei", "wodurch", "wofür", "womit", "wonach", "woran",
    "worauf", "woraus", "worin", "worüber", "worum", "wovon", "wovor", "wozu",
}
_HOER_PARTICLES = {
    "auch", "denn", "doch", "eben", "etwa", "ja", "mal", "nicht", "noch", "nur",
    "schon", "sehr", "so", "wohl", "zwar", "dann", "da",
}
_HOER_AUXILIARIES = {
    "habe", "hast", "hat", "haben", "habt", "hatte", "hattest", "hatten", "hattet",
    "bin", "bist", "ist", "sind", "seid", "war", "warst", "waren", "wart",
    "werde", "wirst", "wird", "werden", "werdet", "wurde", "wurdest", "wurden", "wurdet",
}
_HOER_FUNCTION_WORDS = (
    _WORTBILDUNG_GLUE | _HOER_PRONOUNS | _HOER_DA_WO_COMPOUNDS
    | _HOER_PARTICLES | _HOER_AUXILIARIES
)
_HOER_GAP_MIN_WORDS, _HOER_GAP_MAX_WORDS = 2, 5   # 6+ words is a whole clause, not a group
_HOER_MIN_GAPS = 3
# ≥7 words hidden across ≥3 gaps ⇒ they can't ALL be minimal two-word chunks: at least
# one gap is a real construction (verb + preposition + object, prep + article + noun).
_HOER_MIN_HIDDEN_WORDS = 7


def _hoer_gap_correct(gap) -> str:
    return str((gap.get("correct") if isinstance(gap, dict) else gap) or "")


def hoerluecke_gap_is_hard(correct) -> bool:
    """True when ONE Hörlücke gap is a real Wortgruppe (2–5 words, at least one
    content word) instead of a single word / a pure function-word chunk."""
    toks = [t for t in (_norm_degenerate_token(t) for t in str(correct or "").split()) if t]
    if not (_HOER_GAP_MIN_WORDS <= len(toks) <= _HOER_GAP_MAX_WORDS):
        return False
    return any(t not in _HOER_FUNCTION_WORDS for t in toks)


def hoerluecke_gaps_are_hard(gaps) -> bool:
    """True when a Hörlücke item is worth serving: ≥3 gaps (as many blanks as before —
    only the SIZE of each blank grows), EVERY gap a Wortgruppe, and ≥7 words hidden in
    total so the item can't be three minimal chunks either. The learner has to hear a
    whole construction and write it out — hearing plus writing, twice the memory hook.

    ONE rule shared by the build-time gate in bot_3._aufgabe_payload_from_item, the ingest
    guard and is_degenerate_aufgabe — if these ever diverge the pool either drains
    (generate → instantly purge) or serves one-word blanks again."""
    if not (isinstance(gaps, list) and len(gaps) >= _HOER_MIN_GAPS):
        return False
    if not all(hoerluecke_gap_is_hard(_hoer_gap_correct(g)) for g in gaps):
        return False
    return sum(len(_hoer_gap_correct(g).split()) for g in gaps) >= _HOER_MIN_HIDDEN_WORDS


def hoerluecke_transcript_matches_audio(transcript, gaps, satz_voll) -> bool:
    """True when the printed text with every gap filled by its own solution is word for
    word the text that gets read aloud. The model sometimes rewrites a detail between
    "satz_voll" and "transcript" — then the learner hears one sentence and reads another,
    and the "correct" answer is not what was spoken. Punctuation/case are ignored (TTS
    doesn't pronounce commas); a differing WORD is a broken item."""
    transcript = str(transcript or "")
    gaps = gaps if isinstance(gaps, list) else []
    if transcript.count("_____") != len(gaps) or not gaps:
        return False
    filled = transcript
    for gap in gaps:
        filled = filled.replace("_____", _hoer_gap_correct(gap).strip(), 1)

    def _words(text):
        return [w for w in (_norm_degenerate_token(t) for t in str(text or "").split()) if w]

    return _words(filled) == _words(satz_voll)


def hoerluecke_payload_is_hard(payload) -> bool:
    """The whole serve-time contract for a Hörlücke item: gaps are real Wortgruppen AND
    the printed text matches the audio. Shared by the build gate, the ingest guard and
    is_degenerate_aufgabe."""
    p = payload if isinstance(payload, dict) else {}
    return (hoerluecke_gaps_are_hard(p.get("gaps"))
            and hoerluecke_transcript_matches_audio(
                p.get("transcript"), p.get("gaps"), p.get("satz_voll")))


def hoerluecke_repair_item(transcript, gaps):
    """Drop the gaps that aren't real Wortgruppen and give their words BACK to the
    printed transcript, instead of throwing away an otherwise good 4-gap item because
    one blank came out as "haben wir" or as a whole 7-word clause. Returns
    (transcript, kept_gaps); the caller still validates with `hoerluecke_gaps_are_hard`.

    Safe by construction: a gap's "correct" is exactly the spoken words, so splicing it
    into its own "_____" slot reproduces the audio text verbatim."""
    transcript = str(transcript or "")
    gaps = gaps if isinstance(gaps, list) else []
    segments = transcript.split("_____")
    if len(segments) != len(gaps) + 1:   # structurally broken item — leave it to the gate
        return transcript, gaps
    kept, out = [], [segments[0]]
    for gap, seg in zip(gaps, segments[1:]):
        if hoerluecke_gap_is_hard(_hoer_gap_correct(gap)):
            kept.append(gap)
            out.append("_____")
        else:
            out.append(_hoer_gap_correct(gap).strip())
        out.append(seg)
    return "".join(out), kept


def _word_after_gap(satz) -> str:
    """The first word right AFTER the "_____" gap in a sentence ('' if none)."""
    m = re.search(r"_{2,}", str(satz or ""))
    if not m:
        return ""
    rest = str(satz)[m.end():].strip()
    toks = rest.split()
    return toks[0] if toks else ""


def normalize_error_payload(payload) -> list:
    """Single source of truth for a 'Finde den Fehler' payload — normalize BOTH shapes to a
    list of error dicts [{'index':int,'correct_word':str,'aliases':[str],'erklaerung':str,
    'hint_ru':str}] sorted by index:
      - v2 multi:   payload['errors'] = [{index, correct_word, aliases, erklaerung, hint_ru}, …]
      - v1 single (legacy): top-level error_index/correct_word/aliases/erklaerung/hint_ru
    Malformed entries are dropped; a legacy single-error item becomes a 1-element list, so
    grading / degeneracy / the verifier can treat every item uniformly."""
    payload = payload if isinstance(payload, dict) else {}

    def _mk(idx_raw, correct_raw, aliases_raw, erk_raw, hint_raw):
        try:
            idx = int(idx_raw)
        except (TypeError, ValueError):
            return None
        cw = str(correct_raw or "").strip()
        if not cw:
            return None
        return {
            "index": idx,
            "correct_word": cw,
            "aliases": [str(a) for a in (aliases_raw or []) if str(a).strip()],
            "erklaerung": str(erk_raw or "").strip(),
            "hint_ru": str(hint_raw or "").strip(),
        }

    out = []
    raw = payload.get("errors")
    if isinstance(raw, list) and raw:
        for e in raw:
            if not isinstance(e, dict):
                continue
            got = _mk(e.get("index"), e.get("correct_word"), e.get("aliases"),
                      e.get("erklaerung"), e.get("hint_ru"))
            if got:
                out.append(got)
    else:
        got = _mk(payload.get("error_index"), payload.get("correct_word"),
                  payload.get("aliases"), payload.get("erklaerung"), payload.get("hint_ru"))
        if got:
            out.append(got)
    out.sort(key=lambda e: e["index"])
    return out


# ─── Wortgruppe: the shown words must be BASE forms OF THE ANSWER ────────────
# The whole exercise is "put the given words into the right case, gender, ending
# and article yourself". So a Stützwort shown WITH its ending ("langjährigen",
# "ihrer", "im") hands the learner the very answer the task is about. And a
# Stützwort that is NOT part of the answer at all — worst of all one already
# PRINTED in the sentence ("Arbeiter" next to a gap wanting "unter welchen
# Bedingungen") — is a false lead: the learner tries to fit a word that has no
# place in the gap. Both directions must hold: every shown word belongs to the
# answer, and every content word of the answer is shown. These are the
# deterministic checks; the LLM verifier (check_wortgruppe_batch, rules (c)+(d))
# covers what needs morphology. ONE rule, used by the build-time gate in
# bot_3._aufgabe_payload_from_item AND by is_degenerate_aufgabe — so items that
# predate the rule are retired at serve time / by the nightly purge instead of
# being served with the answer written on them.

# Declension endings an attributive adjective/participle or an article word can carry.
# Longest first: "langjährigen" → stem "langjährig", not "langjährige".
_WG_ENDINGS = ("en", "em", "er", "es", "e")

# Article words + glue. Never a Stützwort: finding them IS the task. Contractions
# ("im", "zum") are here too — they hide a preposition AND an article.
_WG_FUNCTION_WORDS = {
    "der", "die", "das", "den", "dem", "des", "ein", "eine", "einen", "einem",
    "eines", "einer", "zu", "ob", "dass", "und", "oder", "aber", "sich", "nicht",
    "mit", "von", "für", "auf", "an", "in", "bei", "zwischen", "über", "unter",
    "aus", "nach", "um", "durch", "gegen", "ohne", "vor", "wegen", "trotz",
    "im", "am", "beim", "vom", "zum", "zur", "ins", "ans", "aufs", "fürs", "übers",
    "seit", "während", "dank", "statt", "anstatt", "gemäß", "laut", "bis", "als",
    "wenn", "weil", "damit", "sondern", "denn", "zwar", "wie", "es",
    # secondary prepositions — the C1 favourites this format keeps hiding in the gap
    "aufgrund", "auf grund", "infolge", "angesichts", "hinsichtlich", "bezüglich",
    "mittels", "anhand", "seitens", "zwecks", "binnen", "innerhalb", "außerhalb",
    "oberhalb", "unterhalb", "entlang", "gegenüber", "neben", "hinter", "samt",
    "außer", "entgegen", "entsprechend", "zufolge", "anlässlich", "mangels",
    "ungeachtet", "zugunsten", "zulasten", "jenseits", "diesseits", "ab",
    # Fragewörter: finding "unter WELCHEN Bedingungen" is the task, so the
    # interrogative is hidden glue and never a Stützwort — bare "welch" included.
    "welch", "welche", "welchen", "welcher", "welches", "welchem", "wessen",
    "was", "wer", "wen", "wem", "wo", "wohin", "woher", "wann", "warum", "wieso",
    "weshalb", "wodurch", "womit", "wofür", "worauf", "worüber", "woran", "wovon",
    "inwiefern", "inwieweit", "wieviel", "wieviele",
    "dieser", "diese", "dieses", "diesen", "diesem", "jener", "jene", "jenes",
}

# Possessives are article words: shown at all, they may only appear in the bare
# base form ("ihr"), never declined ("ihrer" — that IS the case ending to supply).
_WG_POSSESSIVE_STEMS = {"mein", "dein", "sein", "ihr", "unser", "euer", "eur", "kein"}

# Words INSIDE the answer that need no Stützwort: the learner is supposed to find
# them (that IS the hidden glue), or they carry no lexical meaning to hint at —
# subordinating conjunctions, quantifiers, auxiliaries. Everything else in the
# answer is a content word and MUST have a Stützwort. Kept separate from
# _WG_FUNCTION_WORDS because "sein"/"ihr" are legal Stützwörter (base-form
# possessives) but never need one when they appear in the answer.
_WG_ANSWER_GLUE = _WG_FUNCTION_WORDS | _WG_POSSESSIVE_STEMS | {
    "obwohl", "nachdem", "indem", "bevor", "seitdem", "sobald", "falls", "sofern",
    "sodass", "soweit", "obgleich", "wenngleich", "je", "desto", "umso", "da",
    "all", "alle", "aller", "allen", "alles", "allem", "beide", "beiden",
    "meine", "deine", "seine", "ihre", "unsere", "eure", "keine",
    "meinen", "deinen", "seinen", "ihren", "unseren", "keinen",
    "meines", "deines", "seines", "ihres", "unseres", "keines",
    "meiner", "deiner", "seiner", "ihrer", "unserer", "keiner",
    "meinem", "deinem", "seinem", "ihrem", "unserem", "keinem",
    "ist", "sind", "war", "waren", "gewesen", "hat", "habe", "haben", "hatte",
    "hatten", "wird", "werden", "wurde", "wurden", "worden", "würde", "wäre",
    "hätte", "sei", "seien",
}


def _wg_norm(value) -> str:
    return " ".join(str(value or "").split()).strip().casefold()


def _wg_fold(word: str) -> str:
    """Strip punctuation, casefold, flatten umlauts — so a base form and its
    inflected form share a prefix even when the plural adds one
    ("Kraft" → "krafte" for "Kräften")."""
    out = str(word or "").strip(".,;:!?…\"'»«()[]–—").casefold()
    for a, b in (("ä", "a"), ("ö", "o"), ("ü", "u"), ("ß", "ss")):
        out = out.replace(a, b)
    return out


def _wg_stem(word: str) -> str:
    """Word minus ONE declension ending, if stripping leaves a real stem."""
    for end in _WG_ENDINGS:
        if word.endswith(end) and len(word) - len(end) >= 3:
            return word[: -len(end)]
    return word


def _wg_tokens(text) -> list[str]:
    """Words of a sentence/phrase, gap markers and punctuation removed."""
    raw = str(text or "").replace("_", " ").split()
    return [t for t in (w.strip(".,;:!?…\"'»«()[]–—") for w in raw) if t]


def _wg_same_word(lemma: str, token: str) -> bool:
    """True when `token` is (a form of) `lemma`. German inflection changes the
    END of a word, so a shared stem decides: "Vorteil"↔"Vorteilen",
    "steigend"↔"steigenden", "neu"↔"neuesten"."""
    a, b = _wg_fold(lemma), _wg_fold(token)
    if not a or not b:
        return False
    if a == b:
        return True
    shared = 0
    for ca, cb in zip(a, b):
        if ca != cb:
            break
        shared += 1
    return shared >= 3 and shared >= min(len(a), len(b)) - 3


def wortgruppe_lemma_leak(payload) -> str:
    """Empty string when the shown Stützwörter are base forms AND match the answer
    exactly; otherwise a short Russian reason. Catches every defect seen in the pool:
      • an article word / contraction shown as a Stützwort ("im");
      • a declined possessive ("ihrer" instead of "ihr");
      • an attributive adjective/participle carrying its ending — either verbatim
        ("steigenden" before "Nachfrage") or in another declined form
        ("alternde" shown, "alternden" wanted);
      • a Stützwort that is NOT in the answer — a false lead, doubly so when it is
        already printed in the sentence ("Arbeiter" for "unter welchen Bedingungen");
      • a content word of the answer with NO Stützwort — unguessable.
    A correctly built item ("steigend", "alternd") never matches: the check fires
    only when the Stützwort ITSELF still carries an ending."""
    payload = payload if isinstance(payload, dict) else {}
    lemmas = [str(w).strip() for w in (payload.get("lemmas") or []) if str(w).strip()]
    if not lemmas:
        return "нет опорных слов"
    for lemma in lemmas:
        norm = _wg_norm(lemma)
        if norm in _WG_FUNCTION_WORDS:
            return f"служебное слово в подсказке: «{lemma}»"
        if " " not in norm:
            stem = _wg_stem(norm)
            if stem != norm and stem in _WG_POSSESSIVE_STEMS:
                return f"притяжательное с окончанием: «{lemma}»"
    # Attributive slot: a lowercase word standing directly before a capitalised noun
    # ALWAYS carries a declension ending in German, so whatever stands there is an
    # inflected form. A Stützwort that matches it — as-is or after stripping its own
    # ending — has given the ending away.
    tokens = [t.strip(".,;:!?…\"'»«()") for t in str(payload.get("correct") or "").split()]
    lemma_norms = {_wg_norm(l) for l in lemmas}
    for cur, nxt in zip(tokens, tokens[1:]):
        if not cur or not nxt or not cur[:1].islower() or not nxt[:1].isupper():
            continue
        cur_norm = _wg_norm(cur)
        if cur_norm in lemma_norms:
            return f"склонённое слово в подсказке: «{cur}»"
        cur_stem = _wg_stem(cur_norm)
        for lemma in lemmas:
            norm = _wg_norm(lemma)
            if " " in norm:
                continue
            stem = _wg_stem(norm)
            if stem != norm and stem == cur_stem:
                return f"подсказка с окончанием: «{lemma}» (в ответе «{cur}»)"

    # Both directions must hold between the shown words and the answer.
    answer_tokens = _wg_tokens(payload.get("correct"))
    if not answer_tokens:
        return "нет ответа"
    # A Stützwort that IS the whole answer ("Zum Beispiel" hinted as "zum Beispiel")
    # leaves nothing to do — copy the hint into the box and you are done. Slips past
    # the single-word checks above because the phrase itself is in no word list.
    answer_norm = _wg_norm(" ".join(answer_tokens))
    for lemma in lemmas:
        if _wg_norm(lemma) == answer_norm:
            return f"подсказка повторяет весь ответ: «{lemma}»"
    # (1) A shown word that is nowhere in the answer sends the learner to write a
    #     word that has no slot. The nastiest case is a word taken from the VISIBLE
    #     part of the sentence — it reads as "insert me" while it is already there.
    sentence_tokens = [t for t in _wg_tokens(payload.get("satz"))
                       if not any(_wg_same_word(t, a) for a in answer_tokens)]
    for lemma in lemmas:
        for word in lemma.split():
            if _wg_norm(word) in _WG_ANSWER_GLUE:
                continue
            if any(_wg_same_word(word, tok) for tok in answer_tokens):
                continue
            if any(_wg_same_word(word, tok) for tok in sentence_tokens):
                return f"подсказка «{lemma}» уже стоит в предложении, а не в пропуске"
            return f"подсказка «{lemma}» не встречается в ответе"
    # (2) A content word of the answer with no Stützwort is pure guessing: the
    #     learner has to invent the exact noun/verb we happen to expect.
    for tok in answer_tokens:
        if _wg_norm(tok) in _WG_ANSWER_GLUE or len(_wg_fold(tok)) < 3:
            continue
        if not any(_wg_same_word(word, tok) for lemma in lemmas for word in lemma.split()):
            return f"в ответе слово «{tok}», для которого нет подсказки"
    return ""


def wortgruppe_key_uses_same_words(correct: str, candidate: str) -> bool:
    """True when `candidate` is the SAME answer said with different glue.

    The answer key is what grading compares against without asking any model, so an
    extra key is worse than a missing one: it credits a wrong answer. A legitimate
    second key differs from `correct` only in the hidden glue — another preposition,
    the resolved merge, a repeated article. It may NOT bring in a content word the
    learner was never shown ("Nach Meinung" for "Nach Ansicht"), and may not drop one.
    Grammar is not judged here — that is the bounded judge's job."""
    a = [t for t in _wg_tokens(correct) if _wg_norm(t) not in _WG_ANSWER_GLUE]
    b = [t for t in _wg_tokens(candidate) if _wg_norm(t) not in _WG_ANSWER_GLUE]
    if not b:
        return False
    return (all(any(_wg_same_word(x, y) for y in b) for x in a)
            and all(any(_wg_same_word(y, x) for x in a) for y in b))


def _wortgruppe_repair_carrier(payload) -> None:
    """Re-cut the gap when the model blanked only PART of its own answer.

    It writes "correct" = "warum die Kosten" but hides only "warum", so "die Kosten"
    stays printed right next to the gap — the reconstruction check then fails and a
    perfectly good sentence is thrown away. "vollsatz" is the ground truth here, so
    the fix is the mechanical step the prompt asks for: delete the whole "correct"
    from "vollsatz" and put ONE gap in its place. Only runs when the item's own
    "satz" does NOT reconstruct — a correctly cut item is never touched."""
    correct = str(payload.get("correct") or "").strip()
    voll = " ".join(str(payload.get("vollsatz") or "").split())
    satz = str(payload.get("satz") or "")
    if not correct or not voll:
        return
    if _wg_norm(satz.replace("_____", correct)) == _wg_norm(voll):
        return
    at = voll.find(correct)
    if at < 0:
        at = voll.casefold().find(correct.casefold())
    if at < 0:
        return  # the answer isn't in the sentence at all — not repairable, drop it
    rebuilt = f"{voll[:at]}_____{voll[at + len(correct):]}"
    if rebuilt.count("_____") == 1:
        payload["satz"] = " ".join(rebuilt.split())


def wortgruppe_repair_item(payload) -> dict:
    """Re-cut the gap if needed, then remove the Stützwörter that don't belong —
    instead of losing the whole item.

    Two slips make up most of what the model gets wrong, and BOTH are just a word
    too many in the list — the sentence, the answer and the remaining hints are
    perfectly fine once it's gone:
      • a word copied from the VISIBLE part of the sentence ("Vorgesetzte" next to a
        gap wanting "dass ihre Leistung") — a false lead;
      • the glue itself as a hint ("auf", "im", "alle", "welch") — finding it IS
        the task, so it was never a hint to begin with.
    Deleting them turns a rejected item into a correct one. What is NOT repairable —
    a hint carrying its ending, a content word of the answer with no hint at all —
    still falls to wortgruppe_lemma_leak afterwards. Mutates and returns payload."""
    payload = payload if isinstance(payload, dict) else {}
    _wortgruppe_repair_carrier(payload)
    lemmas = [str(w).strip() for w in (payload.get("lemmas") or []) if str(w).strip()]
    answer_tokens = _wg_tokens(payload.get("correct"))
    if not lemmas or not answer_tokens:
        return payload
    kept: list[str] = []
    for lemma in lemmas:
        content = [w for w in lemma.split() if _wg_norm(w) not in _WG_ANSWER_GLUE]
        if not content:
            continue  # pure glue — hidden by design
        if not all(any(_wg_same_word(w, tok) for tok in answer_tokens) for w in content):
            continue  # not in the gap — a false lead
        kept.append(lemma)
    if kept != lemmas:
        payload["lemmas"] = kept
    return payload


def is_degenerate_aufgabe(fmt, payload, correct_answer=None) -> bool:
    """True for a meaningless item that should never be served/reviewed:
    - wortbildung: the derived noun == the stem (no real word-formation, e.g.
      stamm "krise" → "Krise"), OR the gap is just the noun without the linking
      function word (a 1-word answer teaches nothing — the point of the format is
      Nomen + Kasus-Artikel/regierte Präposition, e.g. "Lieferung der",
      "Interesse an der").
    - error ("Finde den Fehler"): the tapped token already equals the correction
      (no real error, e.g. "zumachen?" → "zumachen") — also covers word-order
      "errors" the format can't express.
    The hardened prompts forbid both; this catches slips + pre-hardening items."""
    fmt = str(fmt or "")
    payload = payload if isinstance(payload, dict) else {}
    if fmt == "wortbildung":
        correct = correct_answer if correct_answer is not None else payload.get("correct")
        c = str(correct or "").strip()
        if not c:
            return False
        toks = c.split()
        stamm = str(payload.get("stamm") or "").strip()
        # (a) no real word-formation: the derived noun == the stem (krise→Krise).
        if stamm and _norm_degenerate_token(toks[0]) == _norm_degenerate_token(stamm):
            return True
        # (b) no grammar in the gap: the answer is only the noun, without the
        #     article/preposition that links it on. Then the exercise is "type the
        #     noun you were just shown the stem of" — no case decision, no rection,
        #     no learning value. Same rule as the build-time gate, so pre-gate
        #     leftovers are retired at serve time / by the nightly purge.
        if not wortbildung_gap_is_grammatical(c):
            return True
        # (c) the answer's trailing function word is ALREADY printed in the sentence
        #     right after the gap → the learner can't/shouldn't type it (would double
        #     it); a broken item (it belongs IN the gap, not in the sentence).
        glue = _norm_degenerate_token(toks[-1])
        after = _norm_degenerate_token(_word_after_gap(payload.get("satz")))
        if glue and after and glue == after:
            return True
        return False
    if fmt == "error":
        # Degenerate iff there are no parseable errors, OR any error points outside the
        # sentence, OR any tapped token already EQUALS its correction (no real error at that
        # slot — e.g. "zumachen?"→"zumachen"). Covers single AND multi via normalization.
        woerter = payload.get("woerter")
        errs = normalize_error_payload(payload)
        if not isinstance(woerter, list) or not woerter or not errs:
            return True
        for e in errs:
            idx = e["index"]
            if not (0 <= idx < len(woerter)):
                return True
            if _norm_degenerate_token(woerter[idx]) == _norm_degenerate_token(e["correct_word"]):
                return True
        return False
    if fmt == "hoerluecke":
        # Too easy to be an exercise: a legacy item with ONE single-word blank, or a
        # multi-gap item whose gaps are single words / pure function-word chunks (a bare
        # preposition is guessable from the printed sentence without hearing anything).
        # Same rule as the build gate, so pre-hardening pool rows are retired on pick.
        # Also drops items whose printed text drifted away from the spoken one.
        return not hoerluecke_payload_is_hard(payload)
    if fmt == "wortgruppe":
        # Two ways to be broken, both covered by wortgruppe_lemma_leak():
        #  • no lemmas at all → unanswerable synonym-guessing (only the RU meaning
        #    is given); old pre-change items look like this;
        #  • a lemma shown WITH its ending / an article word → the item hands over
        #    the grammar it is supposed to test.
        return bool(wortgruppe_lemma_leak(payload))
    if fmt == "wofrage":
        # Wo-Fragen: карточка в очереди ошибок — СОБСТВЕННАЯ копия задания, собранная
        # когда-то давно. Стражи генератора её уже не защищают (они стоят на сборке),
        # поэтому перед показом прогоняем её по тем же правилам: одушевлённость плюс
        # управление глагола из банка. Класс, из-за которого это написано: карточка
        # «Worauf … — Ребёнок» от 21.07 всплыла у владельца 24.08, через месяц после
        # починки генератора. Проверка стоит ~1 мкс, базы не трогает.
        from backend.wofrage_generator import stored_item_problems
        return bool(stored_item_problems(payload))
    return False


def _purge_degenerate_aufgabe(
    table: str, *, id_col: str = "id", retire_col: str | None = None
) -> int:
    """Shared: remove degenerate wortbildung/error/wortgruppe/hoerluecke rows from an
    aufgabe table (bank or mistakes) by checking each candidate in Python. Returns
    count removed.

    When ``retire_col`` is given the rows are soft-retired (UPDATE SET <col>=TRUE)
    instead of hard-deleted: the bank is referenced by bt_3_aufgabe_dispatches via
    a NO ACTION foreign key, so DELETE-ing an already-dispatched item raises
    ForeignKeyViolation and rolls back the whole purge. Retiring mirrors what
    pick_next_aufgabe already does at serve time. Tables with no FK/retired column
    (mistakes) pass retire_col=None and are hard-deleted."""
    try:
        with get_db_connection_context() as conn:
            with conn.cursor() as cur:
                cur.execute(
                    f"SELECT {id_col}, format, payload FROM {table} "
                    f"WHERE format IN ('wortbildung', 'error', 'wortgruppe', 'hoerluecke');"
                )
                rows = cur.fetchall() or []
                bad_ids = []
                for r in rows:
                    payload = _coerce_json_object(r[2]) if not isinstance(r[2], dict) else r[2]
                    if is_degenerate_aufgabe(r[1], payload):
                        bad_ids.append(r[0])
                if bad_ids:
                    if retire_col:
                        cur.execute(
                            f"UPDATE {table} SET {retire_col} = TRUE "
                            f"WHERE {id_col} = ANY(%s) AND {retire_col} = FALSE;",
                            (bad_ids,),
                        )
                    else:
                        cur.execute(
                            f"DELETE FROM {table} WHERE {id_col} = ANY(%s);", (bad_ids,)
                        )
            conn.commit()
        return len(bad_ids)
    except Exception:
        logging.warning("_purge_degenerate_aufgabe failed table=%s", table, exc_info=True)
        return 0


def purge_degenerate_aufgabe_bank() -> int:
    """Remove degenerate wortbildung/error items from the aufgabe pool.

    Soft-retire (not DELETE): the bank is referenced by bt_3_aufgabe_dispatches,
    so hard-deleting an already-dispatched item raises ForeignKeyViolation."""
    return _purge_degenerate_aufgabe(
        "bt_3_aufgabe_bank", id_col="aufgabe_id", retire_col="retired"
    )


def purge_degenerate_aufgabe_mistakes() -> int:
    """Remove degenerate wortbildung/error items from the review queue."""
    try:
        ensure_aufgabe_mistakes_schema()
    except Exception:
        pass
    return _purge_degenerate_aufgabe("bt_3_aufgabe_mistakes", id_col="id")


# table → primary-key column, whitelisted so the raw-SQL helpers below can't be
# pointed at an arbitrary table/column.
_AUFGABE_TABLE_ID = {"bt_3_aufgabe_bank": "aufgabe_id", "bt_3_aufgabe_mistakes": "id"}


def fetch_aufgabe_error_items(table: str, *, limit: int = 300) -> list[tuple]:
    """Return [(id, payload_dict), …] for 'error'-format rows in an aufgabe table
    (bank or mistakes), for the LLM validity re-check (run_verify_aufgabe_error)."""
    id_col = _AUFGABE_TABLE_ID.get(table)
    if not id_col:
        return []
    out: list[tuple] = []
    try:
        with get_db_connection_context() as conn:
            with conn.cursor() as cur:
                cur.execute(
                    f"SELECT {id_col}, payload FROM {table} WHERE format = 'error' LIMIT %s;",
                    (int(limit),),
                )
                for r in cur.fetchall() or []:
                    payload = _coerce_json_object(r[1]) if not isinstance(r[1], dict) else r[1]
                    out.append((r[0], payload if isinstance(payload, dict) else {}))
    except Exception:
        logging.warning("fetch_aufgabe_error_items failed table=%s", table, exc_info=True)
    return out


def fetch_aufgabe_items_by_format(table: str, fmt: str, *, limit: int = 300) -> list[tuple]:
    """Return [(id, payload_dict), …] for rows of ONE format in an aufgabe table
    (bank or mistakes), for an LLM re-check sweep over items already in the pool.
    The bank is filtered to servable rows — retired/unapproved ones aren't worth tokens."""
    id_col = _AUFGABE_TABLE_ID.get(table)
    if not id_col:
        return []
    where = "format = %s"
    if table == "bt_3_aufgabe_bank":
        where += " AND retired = FALSE"
    out: list[tuple] = []
    try:
        with get_db_connection_context() as conn:
            with conn.cursor() as cur:
                cur.execute(
                    f"SELECT {id_col}, payload FROM {table} WHERE {where} LIMIT %s;",
                    (str(fmt), int(limit)),
                )
                for r in cur.fetchall() or []:
                    payload = _coerce_json_object(r[1]) if not isinstance(r[1], dict) else r[1]
                    out.append((r[0], payload if isinstance(payload, dict) else {}))
    except Exception:
        logging.warning("fetch_aufgabe_items_by_format failed table=%s fmt=%s", table, fmt, exc_info=True)
    return out


def remove_aufgabe_items(table: str, ids: list) -> int:
    """Take rows out of rotation. The bank is soft-retired (bt_3_aufgabe_dispatches
    holds a NO ACTION FK — DELETE-ing a dispatched item raises and rolls back the whole
    batch); every other table is hard-deleted. Returns the number of rows affected."""
    if table == "bt_3_aufgabe_bank":
        if not ids:
            return 0
        try:
            with get_db_connection_context() as conn:
                with conn.cursor() as cur:
                    cur.execute(
                        "UPDATE bt_3_aufgabe_bank SET retired = TRUE "
                        "WHERE aufgabe_id = ANY(%s) AND retired = FALSE;",
                        (list(ids),),
                    )
                    affected = cur.rowcount or 0
                conn.commit()
            return int(affected)
        except Exception:
            logging.warning("remove_aufgabe_items retire failed", exc_info=True)
            return 0
    return delete_aufgabe_items(table, ids)


def delete_aufgabe_items(table: str, ids: list) -> int:
    """Delete rows by primary key from a whitelisted aufgabe table. Returns count."""
    id_col = _AUFGABE_TABLE_ID.get(table)
    if not id_col or not ids:
        return 0
    try:
        with get_db_connection_context() as conn:
            with conn.cursor() as cur:
                cur.execute(f"DELETE FROM {table} WHERE {id_col} = ANY(%s);", (list(ids),))
            conn.commit()
        return len(ids)
    except Exception:
        logging.warning("delete_aufgabe_items failed table=%s", table, exc_info=True)
        return 0


def one_shot_flag_done(key: str) -> bool:
    """True iff a one-shot maintenance flag (stored in bt_3_schema_migrations) has already
    been applied — lets a background job run an expensive cleanup EXACTLY ONCE across the
    fleet instead of on every startup/nightly tick. Fail-safe: on a store error, report
    'done' so a broken flag store can never loop an expensive (token-spending) job."""
    try:
        with get_db_connection_context() as conn:
            with conn.cursor() as cur:
                cur.execute(
                    "SELECT 1 FROM bt_3_schema_migrations WHERE migration_key = %s LIMIT 1;",
                    (str(key),),
                )
                return cur.fetchone() is not None
    except Exception:
        logging.warning("one_shot_flag_done failed key=%s (fail-safe: done)", key, exc_info=True)
        return True


def mark_one_shot_flag(key: str) -> None:
    """Persist a one-shot maintenance flag so it never runs again (idempotent)."""
    try:
        with get_db_connection_context() as conn:
            with conn.cursor() as cur:
                cur.execute(
                    "INSERT INTO bt_3_schema_migrations (migration_key) VALUES (%s) "
                    "ON CONFLICT DO NOTHING;",
                    (str(key),),
                )
            conn.commit()
    except Exception:
        logging.warning("mark_one_shot_flag failed key=%s", key, exc_info=True)


def record_aufgabe_mistake(*, user_id: int, fmt: str, payload: dict,
                           correct_answer: str, wrong_answer: str) -> None:
    """Store (or refresh) a wrong answer for spaced-repetition review. Best-effort;
    one upsert keyed by (user, content) so the same item isn't duplicated."""
    import json as _json
    # Never queue a degenerate task (no real error / no real word-formation).
    if is_degenerate_aufgabe(fmt, payload, correct_answer):
        logging.info("skip degenerate aufgabe mistake user_id=%s fmt=%s", user_id, fmt)
        return
    try:
        ensure_aufgabe_mistakes_schema()
        h = _mistake_hash(fmt, payload, correct_answer)
        due_sql = _due_at_next_local_day_sql("1")  # due at the start of the next local day
        with get_db_connection_context() as conn:
            with conn.cursor() as cur:
                cur.execute(
                    f"""
                    INSERT INTO bt_3_aufgabe_mistakes
                      (user_id, content_hash, format, payload, correct_answer, last_wrong_answer,
                       interval_days, review_count, mastered, due_at, updated_at)
                    VALUES (%s,%s,%s,%s::jsonb,%s,%s, 1, 0, FALSE, {due_sql}, NOW())
                    ON CONFLICT (user_id, content_hash) DO UPDATE SET
                      last_wrong_answer = EXCLUDED.last_wrong_answer,
                      payload           = EXCLUDED.payload,
                      correct_answer    = EXCLUDED.correct_answer,
                      format            = EXCLUDED.format,
                      interval_days     = 1,
                      mastered          = FALSE,
                      due_at            = EXCLUDED.due_at,
                      updated_at        = NOW();
                    """,
                    (int(user_id), h, str(fmt), _json.dumps(payload or {}, ensure_ascii=False),
                     str(correct_answer or ""), str(wrong_answer or "")),
                )
            conn.commit()
    except Exception:
        logging.warning("record_aufgabe_mistake failed user_id=%s fmt=%s", user_id, fmt, exc_info=True)


# Grouping of review formats into user-facing "families" (sections of работа над ошибками).
# `artikel` gets its own section (der/die/das); everything else is grammar drills.
def _mistake_family_clause(family: str | None) -> str:
    """Условие семьи для запросов, где таблица ошибок идёт под алиасом `m`."""
    fam = str(family or "").strip().lower()
    if fam == "artikel":
        return "AND m.format = 'artikel'"
    if fam == "wofrage":
        return "AND m.format = 'wofrage'"
    if fam == "grammar":
        return "AND m.format NOT IN ('artikel', 'wofrage')"
    return ""  # all families


# Очередь ошибок хранит СВОЮ копию карточки и про уборку словника не знает: слово,
# снятое с показа в банке артиклей («Ranvier-Schnürring», «Schmetterlings-Tramete»),
# продолжало приходить в «работу над ошибками» ещё месяцами. Условие пускает только
# слова, у которых в банке ЕСТЬ живая строка. Осторожно: срабатывает лишь тогда, когда
# слово в банке есть и оно ретайрнуто; «в банке вообще нет» — не наш случай, не трогаем.
_ARTIKEL_LIVE_WORD_SQL = """
AND NOT (
    m.format = 'artikel'
    AND EXISTS (SELECT 1 FROM bt_3_article_sprint_nouns rn
                WHERE lower(rn.word) = lower(m.payload->>'wort')
                  AND COALESCE(rn.retired, FALSE) = TRUE)
    AND NOT EXISTS (SELECT 1 FROM bt_3_article_sprint_nouns an
                    WHERE lower(an.word) = lower(m.payload->>'wort')
                      AND COALESCE(an.retired, FALSE) = FALSE)
)"""


def purge_retired_artikel_mistakes(user_id: int | None = None) -> int:
    """Убрать из очереди ошибок карточки слов, снятых с показа в банке артиклей.

    Зеркалит самолечение в get_next_due_mistake: строка, которой в игре больше нет,
    удаляется, а не остаётся ждать. Без user_id — по всем пользователям (разовая уборка
    после чистки словника)."""
    try:
        ensure_aufgabe_mistakes_schema()
        where = "WHERE m.format = 'artikel'"
        params: tuple = ()
        if user_id is not None:
            where += " AND m.user_id = %s"
            params = (int(user_id),)
        with get_db_connection_context() as conn:
            with conn.cursor() as cur:
                cur.execute(
                    "DELETE FROM bt_3_aufgabe_mistakes m " + where
                    + " AND EXISTS (SELECT 1 FROM bt_3_article_sprint_nouns rn"
                      "             WHERE lower(rn.word) = lower(m.payload->>'wort')"
                      "               AND COALESCE(rn.retired, FALSE) = TRUE)"
                      " AND NOT EXISTS (SELECT 1 FROM bt_3_article_sprint_nouns an"
                      "                 WHERE lower(an.word) = lower(m.payload->>'wort')"
                      "                   AND COALESCE(an.retired, FALSE) = FALSE);",
                    params,
                )
                n = int(cur.rowcount or 0)
            conn.commit()
        if n:
            logging.info("purge_retired_artikel_mistakes: снято %s карточек user_id=%s", n, user_id)
        return n
    except Exception:
        logging.warning("purge_retired_artikel_mistakes failed user_id=%s", user_id, exc_info=True)
        return 0


# Порция на день: человеку показываем не всю кучу, а 30 самых старых ошибок.
# Замер 15.08.2026: у людей копилось до 188 просроченных заданий, а за один заход
# разбиралось 20-50 — куча была физически неразбираема и только росла. Решение
# владельца: «давал бы короткими порциями по 30 ошибок за день, все ошибки собираем,
# показываем самые старшие 30». Очередь при этом не режется: копится всё, меняется
# только то, сколько видно за раз.
#
# 16.08.2026 — ДЕФЕКТ и починка. Первая версия брала «30 самых старых из просроченных»
# заново ПОСЛЕ КАЖДОГО ОТВЕТА. Разобранное уходило на завтра, а на его место тут же
# вставало 31-е по старшинству — окно всегда полное. Владелец видел вечное «Weiter (30)»
# при очереди в 185 и не видел своего продвижения; дневного предела при этом не было
# вовсе — окно доливалось бесконечно, ограничена была только надпись.
# Теперь порция считается ОТ ДНЯ: сколько из 30 ещё не разобрано сегодня
# (review_portion_left). Дошёл до нуля — на сегодня всё, следующие 30 завтра.
REVIEW_DAILY_PORTION = 30

# Окно порции. LIMIT — параметр (сколько осталось на сегодня), а не константа:
# при нуле запрос честно отдаёт пусто, и экран говорит «на сегодня всё».
_DAILY_PORTION_SQL = (
    " AND m.id IN (SELECT id FROM bt_3_aufgabe_mistakes "
    "              WHERE user_id=%s AND mastered=FALSE AND due_at<=NOW() "
    "              ORDER BY due_at ASC, id ASC LIMIT %s)")


def _local_day_start_sql() -> str:
    """SQL-выражение (timestamptz) = полночь СЕГОДНЯШНЕГО местного дня в _REVIEW_TZ.
    Та же граница суток, по которой назначается due_at, — иначе порция обнулялась бы
    не тогда, когда для человека наступает новый день."""
    return ("(date_trunc('day', (NOW() AT TIME ZONE '" + _REVIEW_TZ + "'))"
            " AT TIME ZONE '" + _REVIEW_TZ + "')")


def count_mistakes_reviewed_today(user_id: int) -> int:
    """Сколько ошибок человек уже разобрал сегодня (по местному дню)."""
    try:
        ensure_aufgabe_mistakes_schema()
        with get_db_connection_context() as conn:
            with conn.cursor() as cur:
                cur.execute(
                    "SELECT COUNT(*) FROM bt_3_aufgabe_mistakes "
                    "WHERE user_id=%s AND last_review_at >= " + _local_day_start_sql() + ";",
                    (int(user_id),),
                )
                return int((cur.fetchone() or [0])[0])
    except Exception:
        return 0


def review_portion_left(user_id: int) -> int:
    """Сколько ошибок человеку ещё осталось из сегодняшней порции. 0 = на сегодня всё."""
    return max(0, REVIEW_DAILY_PORTION - count_mistakes_reviewed_today(int(user_id)))


def count_due_mistakes(user_id: int, *, family: str | None = None,
                       portion_left: int | None = None) -> int:
    """Сколько человеку осталось разобрать СЕГОДНЯ (а не сколько лежит в очереди).
    `portion_left` можно передать, если он уже посчитан, — чтобы не ходить в базу дважды."""
    try:
        left = review_portion_left(int(user_id)) if portion_left is None else max(0, int(portion_left))
        if left <= 0:
            return 0
        ensure_aufgabe_mistakes_schema()
        with get_db_connection_context() as conn:
            with conn.cursor() as cur:
                cur.execute(
                    "SELECT COUNT(*) FROM bt_3_aufgabe_mistakes m "
                    "WHERE m.user_id=%s AND m.mastered=FALSE AND m.due_at<=NOW() "
                    f"{_mistake_family_clause(family)}{_ARTIKEL_LIVE_WORD_SQL}"
                    f"{_DAILY_PORTION_SQL};",
                    (int(user_id), int(user_id), int(left)),
                )
                return int((cur.fetchone() or [0])[0])
    except Exception:
        return 0


def count_due_mistakes_in_queue(user_id: int) -> int:
    """Вся очередь просроченных ошибок, БЕЗ дневной порции. Нужна ровно для одного:
    отличить «разобрал всё» от «на сегодня всё, но куча ещё есть»."""
    try:
        ensure_aufgabe_mistakes_schema()
        with get_db_connection_context() as conn:
            with conn.cursor() as cur:
                cur.execute(
                    "SELECT COUNT(*) FROM bt_3_aufgabe_mistakes m "
                    "WHERE m.user_id=%s AND m.mastered=FALSE AND m.due_at<=NOW()"
                    + _ARTIKEL_LIVE_WORD_SQL + ";",
                    (int(user_id),),
                )
                return int((cur.fetchone() or [0])[0])
    except Exception:
        return 0


def count_due_mistakes_by_family(user_id: int) -> dict:
    """Due-mistake counts split into user-facing sections for работа над ошибками:
    {'artikel': n, 'wofrage': w, 'grammar': m, 'total': t}. Powers the review
    overview/section picker (each grammar-game family gets its own block)."""
    try:
        left = review_portion_left(int(user_id))
        if left <= 0:
            return {"artikel": 0, "wofrage": 0, "grammar": 0, "total": 0}
        ensure_aufgabe_mistakes_schema()
        with get_db_connection_context() as conn:
            with conn.cursor() as cur:
                cur.execute(
                    "SELECT "
                    "  COUNT(*) FILTER (WHERE m.format = 'artikel'), "
                    "  COUNT(*) FILTER (WHERE m.format = 'wofrage'), "
                    "  COUNT(*) FILTER (WHERE m.format NOT IN ('artikel', 'wofrage')), "
                    "  COUNT(*) "
                    "FROM bt_3_aufgabe_mistakes m "
                    "WHERE m.user_id=%s AND m.mastered=FALSE AND m.due_at<=NOW()"
                    + _ARTIKEL_LIVE_WORD_SQL + _DAILY_PORTION_SQL + ";",
                    (int(user_id), int(user_id), int(left)),
                )
                row = cur.fetchone() or [0, 0, 0, 0]
                return {"artikel": int(row[0] or 0), "wofrage": int(row[1] or 0),
                        "grammar": int(row[2] or 0), "total": int(row[3] or 0)}
    except Exception:
        return {"artikel": 0, "wofrage": 0, "grammar": 0, "total": 0}


def force_due_mistakes(user_id: int, *, fmt: str | None = None) -> int:
    """TEST/admin: make this user's review items due right now (due_at=NOW,
    un-master). Scoped to one format (e.g. 'artikel') or all when fmt is None.
    Returns rows affected."""
    try:
        ensure_aufgabe_mistakes_schema()
        with get_db_connection_context() as conn:
            with conn.cursor() as cur:
                if fmt:
                    cur.execute(
                        "UPDATE bt_3_aufgabe_mistakes SET due_at=NOW(), mastered=FALSE "
                        "WHERE user_id=%s AND format=%s;",
                        (int(user_id), str(fmt)),
                    )
                else:
                    cur.execute(
                        "UPDATE bt_3_aufgabe_mistakes SET due_at=NOW(), mastered=FALSE "
                        "WHERE user_id=%s;",
                        (int(user_id),),
                    )
                affected = cur.rowcount
            conn.commit()
        return int(affected or 0)
    except Exception:
        logging.warning("force_due_mistakes failed user_id=%s fmt=%s", user_id, fmt, exc_info=True)
        return 0


def get_next_due_mistake(user_id: int, *, family: str | None = None) -> dict | None:
    try:
        left = review_portion_left(int(user_id))
        if left <= 0:
            return None
        ensure_aufgabe_mistakes_schema()
        with get_db_connection_context() as conn:
            with conn.cursor() as cur:
                cur.execute(
                    """SELECT m.id, m.format, m.payload, m.correct_answer
                       FROM bt_3_aufgabe_mistakes m
                       WHERE m.user_id=%s AND m.mastered=FALSE AND m.due_at<=NOW() """
                    + _mistake_family_clause(family) + _ARTIKEL_LIVE_WORD_SQL
                    + _DAILY_PORTION_SQL +
                    """ ORDER BY m.due_at ASC, m.id ASC LIMIT 12;""",
                    (int(user_id), int(user_id), int(left)),
                )
                rows = cur.fetchall() or []
                # Serve-time self-heal (mirrors pick_next_aufgabe for the pool): the review
                # queue keeps its OWN copy of each task, so a degenerate item that was purged
                # from the bank can still linger here until the next nightly purge. Skip +
                # DELETE any degenerate row so it never reaches the learner again, and serve
                # the first clean one. (This is the deterministic class — the tapped token
                # already equals the correction; the fake-case / hidden-second-error class is
                # cleaned by the one-shot LLM sweep in prepare_aufgabe_pool_job.)
                picked = None
                bad_ids = []
                for row in rows:
                    payload = row[2] if isinstance(row[2], dict) else {}
                    if str(row[1]) == "wofrage" and is_degenerate_aufgabe("wofrage", payload):
                        # Wo-Fragen чинятся по банку управления, а не выбрасываются:
                        # человек ошибся на этой конструкции — она и должна вернуться,
                        # только верной. Непочинимую _heal_wofrage_row убирает сам.
                        payload, why = _heal_wofrage_row(cur, int(row[0]), payload)
                        logging.warning("wofrage: карточка %s в очереди ошибок — %s (%s)",
                                        row[0], "починена" if payload else "убрана", why)
                        if payload is None:
                            continue
                        row = (row[0], row[1], payload, str(payload.get("correct") or ""))
                    elif is_degenerate_aufgabe(str(row[1]), payload, row[3]):
                        bad_ids.append(row[0])
                        continue
                    picked = {"id": int(row[0]), "format": str(row[1]),
                              "payload": payload, "correct_answer": str(row[3] or "")}
                    break
                if bad_ids:
                    cur.execute(
                        "DELETE FROM bt_3_aufgabe_mistakes WHERE id = ANY(%s);", (bad_ids,)
                    )
                    conn.commit()
        return picked
    except Exception:
        logging.warning("get_next_due_mistake failed user_id=%s", user_id, exc_info=True)
        return None


def get_aufgabe_mistake(user_id: int, mistake_id: int) -> dict | None:
    try:
        with get_db_connection_context() as conn:
            with conn.cursor() as cur:
                cur.execute(
                    "SELECT id, format, payload, correct_answer FROM bt_3_aufgabe_mistakes "
                    "WHERE id=%s AND user_id=%s;",
                    (int(mistake_id), int(user_id)),
                )
                row = cur.fetchone()
        if not row:
            return None
        return {"id": int(row[0]), "format": str(row[1]),
                "payload": row[2] or {}, "correct_answer": str(row[3] or "")}
    except Exception:
        logging.warning("get_aufgabe_mistake failed id=%s", mistake_id, exc_info=True)
        return None


def reschedule_mistake(*, mistake_id: int, user_id: int, is_correct: bool) -> None:
    # last_review_at — «эту ошибку разобрали вот тогда». Порция дня считает СТРОКИ с
    # сегодняшней отметкой, а не события, поэтому повторная досылка одного и того же
    # ответа (очередь досылки в браузере) порцию не съедает дважды.
    try:
        with get_db_connection_context() as conn:
            with conn.cursor() as cur:
                if is_correct:
                    cur.execute(
                        "SELECT interval_days FROM bt_3_aufgabe_mistakes WHERE id=%s AND user_id=%s;",
                        (int(mistake_id), int(user_id)),
                    )
                    r = cur.fetchone()
                    cur_int = int(r[0]) if r else 1
                    nxt = next((d for d in _MISTAKE_INTERVALS if d > cur_int), None)
                    if nxt is None:
                        cur.execute(
                            "UPDATE bt_3_aufgabe_mistakes SET mastered=TRUE, "
                            "review_count=review_count+1, last_review_at=NOW(), "
                            "updated_at=NOW() WHERE id=%s AND user_id=%s;",
                            (int(mistake_id), int(user_id)),
                        )
                    else:
                        cur.execute(
                            "UPDATE bt_3_aufgabe_mistakes SET interval_days=%s, "
                            f"due_at={_due_at_next_local_day_sql('%s')}, "
                            "review_count=review_count+1, last_review_at=NOW(), "
                            "updated_at=NOW() WHERE id=%s AND user_id=%s;",
                            (int(nxt), int(nxt), int(mistake_id), int(user_id)),
                        )
                else:
                    cur.execute(
                        "UPDATE bt_3_aufgabe_mistakes SET interval_days=1, "
                        f"due_at={_due_at_next_local_day_sql('1')}, review_count=review_count+1, "
                        "last_review_at=NOW(), updated_at=NOW() WHERE id=%s AND user_id=%s;",
                        (int(mistake_id), int(user_id)),
                    )
            conn.commit()
    except Exception:
        logging.warning("reschedule_mistake failed id=%s", mistake_id, exc_info=True)


def list_users_with_due_mistakes(*, min_count: int = 1, limit: int = 5000) -> list[dict]:
    """Для ежедневного напоминания в личку: кому есть что разобрать СЕГОДНЯ и сколько.

    `count` — размер сегодняшней порции, а не всей кучи. Иначе в личку уходило «у тебя
    185 на повтор»: такое число не зовёт разбирать, а отпугивает (замер 15.08.2026).
    Кто сегодняшнюю порцию уже добил, напоминания не получает вовсе.
    """
    try:
        ensure_aufgabe_mistakes_schema()
        day_start = _local_day_start_sql()
        with get_db_connection_context() as conn:
            with conn.cursor() as cur:
                cur.execute(
                    f"""SELECT q.user_id,
                               LEAST(q.n, GREATEST(0, {REVIEW_DAILY_PORTION} - COALESCE(d.done, 0))) AS portion
                        FROM (SELECT user_id, COUNT(*) AS n
                              FROM bt_3_aufgabe_mistakes
                              WHERE mastered=FALSE AND due_at<=NOW()
                              GROUP BY user_id) q
                        LEFT JOIN (SELECT user_id, COUNT(*) AS done
                                   FROM bt_3_aufgabe_mistakes
                                   WHERE last_review_at >= {day_start}
                                   GROUP BY user_id) d ON d.user_id = q.user_id
                        WHERE LEAST(q.n, GREATEST(0, {REVIEW_DAILY_PORTION} - COALESCE(d.done, 0))) >= %s
                        ORDER BY portion DESC LIMIT %s;""",
                    (int(min_count), int(limit)),
                )
                return [{"user_id": int(r[0]), "count": int(r[1])} for r in (cur.fetchall() or [])]
    except Exception:
        logging.warning("list_users_with_due_mistakes failed", exc_info=True)
        return []


# ── Adjektiv Sprint: timed 15-item adjective-ending game (clone of Artikel) ───
_ADJEKTIV_SPRINT_SCHEMA_DONE = False


def ensure_adjektiv_sprint_schema() -> None:
    # DDL (CREATE TABLE/INDEX IF NOT EXISTS) only needs to run once per process;
    # the endpoints call this on the hot path, so skip after the first success.
    global _ADJEKTIV_SPRINT_SCHEMA_DONE
    if _ADJEKTIV_SPRINT_SCHEMA_DONE:
        return
    with get_db_connection_context() as conn:
        with conn.cursor() as cur:
            cur.execute(
                """CREATE TABLE IF NOT EXISTS bt_3_adjektiv_sprint_sets (
                    set_id TEXT PRIMARY KEY,
                    items_json JSONB NOT NULL DEFAULT '[]'::jsonb,
                    total INT NOT NULL DEFAULT 0,
                    kind TEXT NOT NULL DEFAULT 'daily',
                    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
                );"""
            )
            cur.execute(
                """CREATE TABLE IF NOT EXISTS bt_3_adjektiv_sprint_daily (
                    play_date DATE NOT NULL,
                    slot INT NOT NULL DEFAULT 0,
                    set_id TEXT NOT NULL,
                    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
                    PRIMARY KEY (play_date, slot)
                );"""
            )
            cur.execute(
                """CREATE TABLE IF NOT EXISTS bt_3_adjektiv_sprint_dispatches (
                    id BIGSERIAL PRIMARY KEY,
                    set_id TEXT NOT NULL,
                    slot_date DATE NOT NULL,
                    slot_hour INT NOT NULL,
                    chat_id BIGINT NOT NULL,
                    telegram_message_id BIGINT,
                    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
                    UNIQUE (slot_date, slot_hour, chat_id)
                );"""
            )
            cur.execute(
                """CREATE TABLE IF NOT EXISTS bt_3_adjektiv_sprint_results (
                    set_id TEXT NOT NULL,
                    user_id BIGINT NOT NULL,
                    user_name TEXT,
                    correct INT NOT NULL DEFAULT 0,
                    answered INT NOT NULL DEFAULT 0,
                    total INT NOT NULL DEFAULT 0,
                    time_ms BIGINT NOT NULL DEFAULT 0,
                    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
                    PRIMARY KEY (set_id, user_id)
                );"""
            )
            cur.execute(
                "CREATE INDEX IF NOT EXISTS idx_adj_sprint_results_rank "
                "ON bt_3_adjektiv_sprint_results (set_id, correct DESC, time_ms ASC);"
            )
        conn.commit()
    _ADJEKTIV_SPRINT_SCHEMA_DONE = True


def adjektiv_cell_key(item: dict) -> str:
    """Клетка таблицы окончаний: тип склонения × падеж × род. Их всего 27, и люди
    обычно стабильно валят две-три — по ним и подбираем."""
    it = item or {}
    return f"{it.get('typ') or ''}:{it.get('case') or ''}:{it.get('gender') or ''}"


def ensure_adjektiv_item_answers_schema() -> None:
    """Ответ по КАЖДОМУ заданию прилагательных. До 15.08.2026 хранился только итог
    «12 из 15», поэтому сказать, на какой клетке человек спотыкается, было не из чего."""
    if _task_rotation_writes_disabled():
        return
    with get_db_connection_context() as conn:
        with conn.cursor() as cur:
            cur.execute("""
                CREATE TABLE IF NOT EXISTS bt_3_adjektiv_item_answers (
                    id         BIGSERIAL PRIMARY KEY,
                    user_id    BIGINT NOT NULL,
                    set_id     TEXT,
                    cell       TEXT NOT NULL,
                    typ        TEXT, "case" TEXT, gender TEXT,
                    chosen     TEXT NOT NULL DEFAULT '',
                    correct    BOOLEAN NOT NULL DEFAULT FALSE,
                    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
                );
            """)
            cur.execute("CREATE INDEX IF NOT EXISTS idx_bt_3_adjektiv_answers_user "
                        "ON bt_3_adjektiv_item_answers (user_id, created_at DESC);")
        conn.commit()


def record_adjektiv_item_answers(rows: list) -> None:
    """Поштучные ответы пачкой, в фоне. Игра ждать этого не должна."""
    if _task_rotation_writes_disabled() or not rows:
        return
    try:
        ensure_adjektiv_item_answers_schema()
        with get_db_connection_context() as conn:
            with conn.cursor() as cur:
                for r in rows:
                    cur.execute(
                        'INSERT INTO bt_3_adjektiv_item_answers '
                        '(user_id, set_id, cell, typ, "case", gender, chosen, correct) '
                        "VALUES (%s,%s,%s,%s,%s,%s,%s,%s);",
                        (int(r.get("user_id") or 0), str(r.get("set_id") or ""),
                         str(r.get("cell") or ""), str(r.get("typ") or ""),
                         str(r.get("case") or ""), str(r.get("gender") or ""),
                         str(r.get("chosen") or ""), bool(r.get("correct"))),
                    )
            conn.commit()
    except Exception:
        logging.warning("record_adjektiv_item_answers failed", exc_info=True)


def get_user_adjektiv_weakness(user_id: int, *, days: int = 90) -> dict:
    """Где ИМЕННО этот человек спотыкается в окончаниях: по клеткам таблицы."""
    if _task_rotation_writes_disabled():
        return {"attempts": 0, "cells": {}}
    try:
        ensure_adjektiv_item_answers_schema()
        with get_db_connection_context() as conn:
            with conn.cursor() as cur:
                cur.execute(
                    """SELECT cell, COUNT(*), SUM(CASE WHEN correct THEN 1 ELSE 0 END)
                       FROM bt_3_adjektiv_item_answers
                       WHERE user_id=%s AND chosen <> ''
                         AND created_at > NOW() - (%s || ' days')::interval
                       GROUP BY cell;""",
                    (int(user_id), int(days)),
                )
                rows = cur.fetchall() or []
        cells, total = {}, 0
        for cell, cnt, corr in rows:
            cnt, corr = int(cnt or 0), int(corr or 0)
            total += cnt
            cells[str(cell or "")] = {"attempts": cnt, "correct": corr}
        return {"attempts": total, "cells": cells}
    except Exception:
        logging.warning("get_user_adjektiv_weakness failed user=%s", user_id, exc_info=True)
        return {"attempts": 0, "cells": {}}


def pick_adjektiv_payloads_for_user(user_id: int, n: int = 15) -> list[dict]:
    """То же, что `pick_adjektiv_payloads`, но с упором на клетки, где человек валится.

    Пока ответов мало (меньше 20), работает обычная случайная выдача: доля ошибок по
    одной-двум попыткам — это шум, а не замер.
    """
    want = max(1, int(n))
    try:
        pool = pick_adjektiv_payloads(want * 4)
        if not pool:
            return []
        weak = get_user_adjektiv_weakness(int(user_id))
        if int(weak.get("attempts") or 0) < 20:
            return pool[:want]
        from backend.weak_spot import order_by_weakness
        return order_by_weakness(pool, weak.get("cells"), adjektiv_cell_key)[:want]
    except Exception:
        logging.warning("pick_adjektiv_payloads_for_user failed user=%s", user_id,
                        exc_info=True)
        return pick_adjektiv_payloads(want)


def adjektiv_gap_rebuilds(payload: dict | None) -> bool:
    """Склеивается ли задание на окончание обратно в свою же фразу.

    Единственная проверка, которая ловит «пропуск стоит не на том слове»:

        показано: ohne ein[___] gutes Argument   ответ «e»
        выйдет:   ohne eine gutes Argument       а верно: ohne ein gutes Argument

    Здесь ничего не выводится и не додумывается — сравнивается то, что задание
    само про себя говорит. Задание без `full` проверить нечем: оно приходит из
    детерминированного генератора, который собирает фразу из тех же кусков, и там
    склейка верна по построению.
    """
    p = payload or {}
    full = str(p.get("full") or "")
    if not full:
        return True
    correct = str(p.get("correct") or p.get("a") or "")
    before = str(p.get("before") or "")
    after = str(p.get("after") or "")
    der = derive_adjektiv_split(full, correct)
    if der:
        before, after = der
    return (before + correct + after) == full


def pick_adjektiv_payloads(n: int = 15) -> list[dict]:
    """`n` adjective items. Primary source: the DETERMINISTIC rule-based generator
    (unlimited, 100% correct, no LLM). Falls back to the aufgabe bank only if that
    ever fails."""
    try:
        from backend.adjektiv_endings import build_adjektiv_items
        items = build_adjektiv_items(int(n))
        if items:
            return items
    except Exception:
        logging.warning("pick_adjektiv_payloads: deterministic gen failed", exc_info=True)
    try:
        with get_db_connection_context() as conn:
            with conn.cursor() as cur:
                cur.execute(
                    "SELECT payload FROM bt_3_aufgabe_bank "
                    "WHERE retired=FALSE AND format='adjektiv' ORDER BY random() LIMIT %s;",
                    (int(n) * 3,),
                )
                rows = [r[0] for r in (cur.fetchall() or []) if r and r[0]]
    except Exception:
        logging.warning("pick_adjektiv_payloads failed", exc_info=True)
        return []
    seen: set[str] = set()
    uniq: list[dict] = []
    for p in rows:
        # Второй рубеж, на выдаче: задание из банка обязано склеиваться обратно.
        # Страж на входе (bot_3.py, разбор ответа модели) закрыт 21.08.2026, но в
        # банке уже лежало написанное до него, а банк переживает любую правку кода.
        # Проверка та же и цена ей ноль: подставили ответ — вышла та же фраза.
        if not adjektiv_gap_rebuilds(p):
            logging.warning("задание на окончания не выдано: пропуск не склеивается: %r",
                            (p or {}).get("full"))
            continue
        key = f"{(p or {}).get('before', '')}|{(p or {}).get('correct', '')}"
        if key in seen:
            continue
        seen.add(key)
        uniq.append(p)
    if not uniq:
        return []
    out: list[dict] = []
    i = 0
    while len(out) < int(n):
        out.append(uniq[i % len(uniq)])
        i += 1
    return out[: int(n)]


def derive_adjektiv_split(full: str, correct: str):
    """Rebuild (before, after) from the full phrase + the ending, so the ending can
    never leak into `after`/`before` (the LLM sometimes mis-split, e.g.
    "ein interessant" + "es Buch"). The attributive adjective is the lowercase word
    right before the final (capitalised) noun and ends with `correct`. Returns
    (before, after) or None if it can't be derived safely."""
    full = str(full or "").strip()
    ending = str(correct or "").strip().lower()
    if not full or ending not in ("e", "en", "er", "es", "em"):
        return None
    tokens = full.split()
    if len(tokens) < 2:
        return None
    noun_idx = None
    for i in range(len(tokens) - 1, -1, -1):
        if tokens[i][:1].isupper():
            noun_idx = i
            break
    if not noun_idx:  # no noun, or noun is the first token → can't place an adjective before it
        return None
    adj = tokens[noun_idx - 1]
    if not adj.lower().endswith(ending) or len(adj) <= len(ending):
        return None
    stem = adj[: -len(ending)]
    before = (" ".join(tokens[: noun_idx - 1] + [stem])).strip()
    after = " " + " ".join(tokens[noun_idx:])
    return (before, after)


def _adjektiv_item_for_game(p: dict) -> dict:
    p = p or {}
    correct = str(p.get("correct") or "").lower()
    full = str(p.get("full") or "")
    before = str(p.get("before") or "")
    after = str(p.get("after") or "")
    der = derive_adjektiv_split(full, correct)
    if der:
        before, after = der
    return {
        "before": before,
        "after": after,
        "a": correct,  # correct ending (client local-grades)
        "full": full,
        "erklaerung": str(p.get("erklaerung") or ""),
        "tip": str(p.get("tip") or ""),
        "example": str(p.get("example") or ""),
        "ru": str(p.get("hint_ru") or ""),
        # КЛЕТКА ТАБЛИЦЫ ЕДЕТ ВМЕСТЕ С ЗАДАНИЕМ. Без неё ответ человека сохраняется
        # обезличенным, и весь смысл поштучной записи пропадает.
        #
        # Как это выглядело: набор кладётся в базу этой функцией, а при сдаче ответов
        # `adjektiv_cell_key` читает у задания `typ`/`case`/`gender` — которых здесь не
        # было. Замер 22.08.2026 по 200 последним наборам: у ВСЕХ 2430 заданий ключ
        # клетки пустой («::»). То есть первый же сыгравший записал бы 15 ответов ни о
        # чём, а персональный подбор по слабым клеткам (27 штук, обычно валятся две-три)
        # не получил бы ни одной пригодной строки.
        #
        # Ответы не терялись — терялся их смысл, а это тот же класс: человек отвечает,
        # а система от этого не умнеет.
        "typ": str(p.get("typ") or ""),
        "case": str(p.get("case") or ""),
        "gender": str(p.get("gender") or ""),
    }


def create_adjektiv_sprint_set(items: list[dict], *, kind: str = "daily") -> str:
    import json as _json
    import uuid as _uuid
    ensure_adjektiv_sprint_schema()
    set_id = str(_uuid.uuid4())
    game_items = [_adjektiv_item_for_game(p) for p in (items or [])]
    with get_db_connection_context() as conn:
        with conn.cursor() as cur:
            cur.execute(
                "INSERT INTO bt_3_adjektiv_sprint_sets (set_id, items_json, total, kind) "
                "VALUES (%s,%s::jsonb,%s,%s);",
                (set_id, _json.dumps(game_items, ensure_ascii=False), len(game_items), str(kind)),
            )
        conn.commit()
    return set_id


