def get_user_wofrage_weakness(user_id: int, *, days: int = 90) -> dict:
    """Где ИМЕННО этот человек спотыкается: доля ошибок по предлогам и по типу вопроса.

    Дневной набор один на всех (иначе рушится общий зачёт), а вот личная тренировка
    может подбираться под человека: слабые предлоги — чаще, освоенные — реже.
    """
    try:
        ensure_wofrage_sprint_schema()
        with get_db_connection_context() as conn:
            with conn.cursor() as cur:
                cur.execute(
                    """SELECT prep, target, COUNT(*),
                              SUM(CASE WHEN correct THEN 1 ELSE 0 END)
                       FROM bt_3_wofrage_item_answers
                       WHERE user_id=%s AND chosen <> ''
                         AND created_at > NOW() - (%s || ' days')::interval
                       GROUP BY prep, target;""",
                    (int(user_id), int(days)),
                )
                rows = cur.fetchall()
        preps: dict = {}
        targets: dict = {}
        total = correct_total = 0
        for prep, target, cnt, corr in rows:
            cnt, corr = int(cnt or 0), int(corr or 0)
            total += cnt
            correct_total += corr
            p = preps.setdefault(str(prep or ""), {"attempts": 0, "correct": 0})
            p["attempts"] += cnt
            p["correct"] += corr
            t = targets.setdefault(str(target or ""), {"attempts": 0, "correct": 0})
            t["attempts"] += cnt
            t["correct"] += corr
        return {"attempts": total, "correct": correct_total, "preps": preps, "targets": targets}
    except Exception:
        logging.warning("get_user_wofrage_weakness failed user=%s", user_id, exc_info=True)
        return {"attempts": 0, "correct": 0, "preps": {}, "targets": {}}


def pick_wofrage_payloads(n: int = 10) -> list[dict]:
    """`n` Wo-Frage items from the DETERMINISTIC rule engine (unlimited, 100% correct,
    no LLM). Returns [] only if the engine ever fails (no bank fallback needed —
    the engine ships with its own bank)."""
    try:
        from backend.wofrage_generator import build_wofrage_items
        want = max(1, int(n))
        banned = get_quarantined_wofrage_keys()
        # Собираем с запасом и выбрасываем задания, отправленные в карантин цифрами.
        items = [it for it in build_wofrage_items(want * 2 if banned else want)
                 if str(it.get("key") or "") not in banned]
        if items:
            return items[:want]
    except Exception:
        logging.warning("pick_wofrage_payloads: deterministic gen failed", exc_info=True)
    return []


# Ниже трёх ответов доля ошибок — не замер, а шум: одна промашка даёт 100%.
_WOFRAGE_MIN_ATTEMPTS = 3
# Вес того, что про человека ещё НЕ измерено. Замер 14.08.2026: пока здесь стояло 0.5,
# неизмеренное било любое измеренное с долей ошибок ниже половины (при 0.2 — 0% побед,
# при 0.3 — 2%), а живой человек ошибается на 15-30%. Из-за этого «упор на мои ошибки»
# включался только у того, кто валит предлог чаще чем через раз: у единственного
# человека, прошедшего порог, доля заданий на измеренные предлоги вышла 0.000 против
# 0.231 при случайной выдаче — перекос шёл в обратную сторону. 0.32 ставит неизмеренное
# ВЫШЕ освоенного, но НИЖЕ всего, где человек ошибается чаще трети.
_WOFRAGE_UNMEASURED_WEIGHT = 0.32
# Доля вклада второго измерения — «вещь или человек» (Worüber ↔ Über wen). Это самая
# частая реальная ошибка формата; она измерялась с самого начала и до 14.08.2026
# выбрасывалась — формула смотрела только на предлог.
_WOFRAGE_TARGET_SHARE = 0.35
# Шум, чтобы верхушка колоды не была одной и той же пачку за пачкой.
_WOFRAGE_PICK_NOISE = 0.20


def pick_wofrage_payloads_for_user(user_id: int, n: int = 12) -> list[dict]:
    """То же, но с оглядкой на этого человека: где он ошибается — того больше.

    Дневной набор общий (общий зачёт), а личная тренировка подстраивается: и предлог,
    и тип вопроса (о вещи или о человеке), на которых человек валится, встречаются
    чаще; освоенное — реже. Пока ответов мало, работает обычная случайная выдача.
    """
    want = max(1, int(n))
    try:
        pool = pick_wofrage_payloads(want * 4)
        if not pool:
            return []
        weak = get_user_wofrage_weakness(int(user_id))
        if int(weak.get("attempts") or 0) < 20:
            return pool[:want]
        import random as _random

        def measured(stats: dict, key: str) -> float:
            """Доля ошибок по одному измерению; где мерить ещё нечего — средний вес."""
            stat = (stats or {}).get(key) or {}
            attempts = int(stat.get("attempts") or 0)
            if attempts < _WOFRAGE_MIN_ATTEMPTS:
                return _WOFRAGE_UNMEASURED_WEIGHT
            return 1.0 - (int(stat.get("correct") or 0) / attempts)

        def score(item: dict) -> float:
            by_prep = measured(weak.get("preps"), str(item.get("prep") or ""))
            by_target = measured(weak.get("targets"), str(item.get("target") or ""))
            return ((1.0 - _WOFRAGE_TARGET_SHARE) * by_prep
                    + _WOFRAGE_TARGET_SHARE * by_target
                    + _random.random() * _WOFRAGE_PICK_NOISE)

        pool.sort(key=score, reverse=True)
        return pool[:want]
    except Exception:
        logging.warning("pick_wofrage_payloads_for_user failed user=%s", user_id, exc_info=True)
        return pick_wofrage_payloads(want)


def _wofrage_item_for_game(p: dict) -> dict:
    """Normalize a generator item to the stored/client shape. The client renders
    `s`/`clue`/`opts` and local-grades against `a`; the server re-grades on submit."""
    p = p or {}
    opts = [str(o) for o in (p.get("opts") or []) if str(o).strip()]
    return {
        "s": str(p.get("s") or ""),
        "clue": str(p.get("clue") or ""),
        "a": str(p.get("a") or ""),
        "opts": opts,
        "target": str(p.get("target") or "thing"),
        "prep": str(p.get("prep") or ""),
        "case": str(p.get("case") or ""),
        "lemma": str(p.get("lemma") or ""),
        "verb_ru": str(p.get("verb_ru") or ""),
        "obj": str(p.get("obj") or ""),
        "obj_ru": str(p.get("obj_ru") or ""),
        "erklaerung": str(p.get("erklaerung") or ""),
        "tip": str(p.get("tip") or ""),
        # Перевод вопроса: в разборе человек должен видеть, что фраза значит.
        "frage_ru": str(p.get("frage_ru") or ""),
        # Второй верный ответ и объяснение разницы. Раньше здесь терялись, и сет,
        # где верны обе формы («Woran/Worunter leidest du?»), засчитывал только одну —
        # хотя и сервер, и клиент готовы принять обе.
        "also_ok": [str(a) for a in (p.get("also_ok") or []) if str(a).strip()],
        "unterschied": str(p.get("unterschied") or ""),
        # Ключ задания — по нему копится статистика ответов по КОНКРЕТНОМУ заданию.
        "key": str(p.get("key") or ""),
    }


def create_wofrage_sprint_set(items: list[dict], *, kind: str = "daily") -> str:
    import json as _json
    import uuid as _uuid
    ensure_wofrage_sprint_schema()
    set_id = str(_uuid.uuid4())
    game_items = [_wofrage_item_for_game(p) for p in (items or [])]
    with get_db_connection_context() as conn:
        with conn.cursor() as cur:
            cur.execute(
                "INSERT INTO bt_3_wofrage_sprint_sets (set_id, items_json, total, kind) "
                "VALUES (%s,%s::jsonb,%s,%s);",
                (set_id, _json.dumps(game_items, ensure_ascii=False), len(game_items), str(kind)),
            )
        conn.commit()
    return set_id


def get_wofrage_sprint_set(set_id: str) -> dict | None:
    try:
        with get_db_connection_context() as conn:
            with conn.cursor() as cur:
                cur.execute(
                    "SELECT set_id, items_json, total, kind FROM bt_3_wofrage_sprint_sets WHERE set_id=%s;",
                    (str(set_id),),
                )
                r = cur.fetchone()
        if not r:
            return None
        return {"set_id": r[0], "items": r[1] or [], "total": int(r[2] or 0), "kind": str(r[3] or "daily")}
    except Exception:
        return None


def get_or_create_daily_wofrage_set(play_date, slot: int) -> str | None:
    ensure_wofrage_sprint_schema()
    with get_db_connection_context() as conn:
        with conn.cursor() as cur:
            cur.execute(
                "SELECT set_id FROM bt_3_wofrage_sprint_daily WHERE play_date=%s AND slot=%s;",
                (play_date, int(slot)),
            )
            r = cur.fetchone()
            if r:
                return str(r[0])
    items = pick_wofrage_payloads(10)
    if not items:
        return None
    set_id = create_wofrage_sprint_set(items, kind="daily")
    with get_db_connection_context() as conn:
        with conn.cursor() as cur:
            cur.execute(
                "INSERT INTO bt_3_wofrage_sprint_daily (play_date, slot, set_id) VALUES (%s,%s,%s) "
                "ON CONFLICT (play_date, slot) DO NOTHING;",
                (play_date, int(slot), set_id),
            )
        conn.commit()
    return set_id


