def get_dict_dedup_report(*, days: int = 7) -> dict:
    """Aggregate dedup-run stats for the weekly admin report.

    Returns window totals (last `days` days), all-time totals, and the timestamp of the
    most recent run. Returns zeros (ok=True) when the table does not exist yet so the
    report can still say "0 removed this week".
    """
    empty = {
        "days": int(days),
        "window_entries_deleted": 0,
        "window_groups_found": 0,
        "window_runs": 0,
        "window_active_runs": 0,
        "total_entries_deleted": 0,
        "total_groups_found": 0,
        "last_run_at": None,
        "ok": True,
    }
    try:
        with get_db_connection_context() as conn:
            with conn.cursor() as cursor:
                cursor.execute("SELECT to_regclass('public.bt_3_dict_dedup_runs');")
                regclass = cursor.fetchone()
                if not regclass or regclass[0] is None:
                    return empty
                cursor.execute(
                    """
                    SELECT
                        COALESCE(SUM(entries_deleted) FILTER (WHERE ran_at >= NOW() - %s::interval), 0),
                        COALESCE(SUM(groups_found)    FILTER (WHERE ran_at >= NOW() - %s::interval), 0),
                        COUNT(*)                      FILTER (WHERE ran_at >= NOW() - %s::interval),
                        COUNT(*)                      FILTER (WHERE ran_at >= NOW() - %s::interval AND entries_deleted > 0),
                        COALESCE(SUM(entries_deleted), 0),
                        COALESCE(SUM(groups_found), 0),
                        MAX(ran_at)
                    FROM bt_3_dict_dedup_runs;
                    """,
                    (f"{int(days)} days",) * 4,
                )
                row = cursor.fetchone()
    except Exception:
        logging.exception("get_dict_dedup_report failed")
        return {**empty, "ok": False}
    if not row:
        return empty
    return {
        "days": int(days),
        "window_entries_deleted": int(row[0] or 0),
        "window_groups_found": int(row[1] or 0),
        "window_runs": int(row[2] or 0),
        "window_active_runs": int(row[3] or 0),
        "total_entries_deleted": int(row[4] or 0),
        "total_groups_found": int(row[5] or 0),
        "last_run_at": row[6].isoformat() if row[6] else None,
        "ok": True,
    }


# «Богатая» карточка = та, которую пул РЕАЛЬНО отдаст. Держать в согласии с питоновским
# `_dictionary_payload_needs_enrichment`, иначе записи зависают: SQL считает их полными
# (значит ночной добор их не берёт), а выдача — тонкими (значит и не отдаёт).
# Именно поэтому `forms` и пустой одиночный `dictionary_senses` сюда НЕ входят: артикль
# со склонением без единого примера карточкой не является.
def _dictionary_pool_rich_sql(alias: str) -> str:
    """Полнота карточки по СОДЕРЖИМОМУ, а не по наличию ключа.

    Раньше здесь стояло `response_json ? 'usage_examples'` — проверка присутствия ключа.
    Тонкое сохранение (быстрый перевод, тап в тренажёре, личный чат бота) кладёт
    `usage_examples: []` и `meanings: {}`: ключи есть, карточки нет. SQL считал такую
    строку полной и ставил её первой в выдаче пула, а питоновский гейт
    `_dictionary_payload_needs_enrichment` тут же её отбраковывал — и мы шли в GPT за
    словом, полный разбор которого лежал в этой же таблице (замер 04.08.2026:
    72 написания, 227 заголовков). Тот же предикат решает, кто победит в upsert'е, —
    то есть пустышка ещё и не давала лечь поверх себя настоящей карточке."""
    def _nonempty_array(path: str, minimum: int = 1) -> str:
        # CASE (не AND): Postgres не гарантирует короткое замыкание, а jsonb_array_length
        # падает на скаляре. Возвращаем строгие TRUE/FALSE, без NULL.
        return (
            f"(CASE WHEN jsonb_typeof({path}) = 'array' "
            f"THEN jsonb_array_length({path}) >= {int(minimum)} ELSE FALSE END)"
        )

    def _nonempty_text(path: str) -> str:
        return f"NULLIF(TRIM(COALESCE({path}, '')), '') IS NOT NULL"

    parts = [
        _nonempty_array(f"{alias}->'usage_examples'"),
        _nonempty_array(f"{alias}->'translations'"),
        _nonempty_array(f"{alias}->'meanings'->'secondary'"),
        _nonempty_text(f"{alias}->'meanings'->'primary'->>'value'"),
        # grammar_tables приходит и объектом, и списком — пустые оба варианта отсекаем
        f"(CASE WHEN jsonb_typeof({alias}->'grammar_tables') = 'object' "
        f"THEN {alias}->'grammar_tables' <> '{{}}'::jsonb "
        f"WHEN jsonb_typeof({alias}->'grammar_tables') = 'array' "
        f"THEN jsonb_array_length({alias}->'grammar_tables') >= 1 ELSE FALSE END)",
        # два и более смысла — тоже полноценная карточка (совпадает с питоновским гейтом)
        _nonempty_array(f"{alias}->'dictionary_senses'", 2),
        # один смысл считается карточкой, только если у него есть контекст или пример
        _nonempty_text(f"{alias}->'dictionary_senses'->0->>'context'"),
        _nonempty_text(f"{alias}->'dictionary_senses'->0->>'example_source'"),
        _nonempty_text(f"{alias}->'dictionary_senses'->0->>'example_target'"),
    ]
    return "(" + " OR ".join(parts) + ")"


# Содержательные блоки разбора. По ним, а НЕ по длине текста, решается, какая версия
# полнее: длину раздувают служебные поля и сырой текст запроса, а ценность карточки —
# в этих блоках.
CARD_CONTENT_KEYS = (
    "usage_examples", "meanings", "dictionary_senses", "forms", "grammar_tables",
    "government_patterns", "common_collocations", "synonym_differences", "false_friends",
    "word_formation", "register_examples", "common_mistakes", "pronunciation",
    "etymology_note", "memory_tip", "translations",
    # Синонимы, антонимы и близкие слова. Их здесь НЕ БЫЛО, и это тихо стоило нам
    # целого блока карточки: мост «единица → карточка» работал, но именно эти блоки
    # через него не проходили, потому что список решает, что переносить.
    #
    # Замер 08.08.2026: секции разбора 1–4 доезжают до личной карточки в 14 489 случаях
    # из 24 554, а пятая («extra», где лежат синонимы) — в 670. На самих единицах она
    # есть у 4 098 из 9 711. То есть модель их присылала, мы за них платили, они
    # сохранялись на слове — и не показывались человеку.
    #
    # Соседний блок «чем отличаются синонимы» (synonym_differences) в списке был, а
    # сами синонимы — нет: разбор показывал разницу между словами, которых на экране
    # не видно.
    "synonyms", "antonyms", "related_words",
    "when_to_use", "real_life_usage", "usage_note", "register_note",
)


# Опознавательные поля карточки: кто это слово, в какую сторону и какого рода. Они
# лёгкие и нужны самой строке. Всё остальное — разбор, и он живёт на единице.
CARD_IDENTITY_KEYS = (
    "source_text", "target_text", "source_lang", "target_lang", "language_pair",
    "word_de", "word_ru", "translation_de", "translation_ru",
    "article", "part_of_speech", "entry_kind", "semantic_category",
)


def strip_card_content_for_subscription(payload: dict | None) -> dict:
    """Оставить в подписной карточке только опознавательные поля.

    Подписка — это отметка «у человека есть это слово», а не копия слова. Разбор
    приезжает с общей единицы при показе, поэтому таскать его копию в каждой из тысяч
    строк незачем: она никем не читается и живёт своей жизнью.

    Артикль и часть речи оставляем намеренно: они нужны самой строке (род в заголовке,
    правила показа) и весят ничего."""
    if not isinstance(payload, dict):
        return {}
    return {key: value for key, value in payload.items() if key in CARD_IDENTITY_KEYS}


def card_content_score(card: dict | None) -> int:
    """Сколько содержательных блоков реально заполнено в разборе."""
    if not isinstance(card, dict):
        return 0
    score = 0
    for key in CARD_CONTENT_KEYS:
        value = card.get(key)
        if isinstance(value, str):
            filled = bool(value.strip())
        elif isinstance(value, (list, dict)):
            filled = bool(len(value))
        else:
            filled = value not in (None, "", [], {})
        if filled:
            score += 1
    return score


# Отдавать ли человеку разбор с ЕДИНИЦЫ. Рубильник на случай, если что-то пойдёт не так:
# гасится переменной окружения без выкатки кода.
DICTIONARY_UNITS_SERVE_ENABLED = str(
    os.getenv("DICTIONARY_UNITS_SERVE_ENABLED") or "1"
).strip().lower() in {"1", "true", "yes", "on"}


def _card_block_is_filled(value) -> bool:
    if isinstance(value, str):
        return bool(value.strip())
    if isinstance(value, (list, dict)):
        return bool(len(value))
    return value not in (None, "", [], {})


def _block_is_more_structured(candidate, other) -> bool:
    """Список словарей содержательнее списка голых строк, даже если он короче.

    Живой случай, из-за которого это правило и появилось (замер 14.08.2026, 292 карточки):
        у человека:  ["Die Arbeit ist belohnend.", "Es fühlt sich belohnend an.", …]  — 3 строки
        на слове:    [{"source": "…", "target": "После работы она ощутила…"}]        — 1 пара
    По длине побеждает список человека — и человек видит примеры БЕЗ ПЕРЕВОДА, хотя
    перевод лежит рядом на общем слове. Длина оказалась плохой мерой богатства."""
    if not isinstance(candidate, list) or not candidate:
        return False
    if not isinstance(other, list) or not other:
        return True
    return (any(isinstance(x, dict) for x in candidate)
            and not any(isinstance(x, dict) for x in other))


def _example_key(item) -> str:
    """Ключ примера — его немецкая сторона. По ней и понимаем, что пример тот же."""
    if isinstance(item, dict):
        for name in ("source", "example_source", "de", "text"):
            value = item.get(name)
            if isinstance(value, str) and value.strip():
                return " ".join(value.split()).strip().casefold()
        return ""
    return " ".join(str(item or "").split()).strip().casefold()


def _merge_examples_shared_first(mine, theirs):
    """Примеры: сначала примеры ОБЩЕГО СЛОВА, следом свои, которых там нет.

    ЗАЧЕМ ОТДЕЛЬНО ОТ ОБЩЕГО ПРАВИЛА. Правило «своих больше — оставляем своё» писалось
    для синонимов: три синонима против одного, отнимать нельзя. На примерах оно даёт
    обратный эффект — держит УСТАРЕВШУЮ копию.

    Живой случай, владелец 22.08.2026. Карточка «die Hose anhaben» сохранена со смыслом
    «быть главным». Слово пересобрано под этот смысл, у него примеры про то, кто в доме
    решает. У человека в карточке с 02.06 лежат два примера про брюки — их не меньше, и
    по длине они побеждали. Значение на экране уже поменялось на «быть главным», а
    примеры остались про одежду: подпись и содержимое снова про разное.

    Замер 22.08.2026: 9 915 пар «карточка + слово» с примерами, у 551 своих больше. Если
    просто отдать победу общему, эти 551 потеряют примеры, которых на слове нет, — а это
    прямо запрещено правилом «человек не должен увидеть меньше, чем видел вчера».
    Поэтому не выбор, а порядок: свежее сверху, старое ниже, ничего не пропадает.
    """
    if not isinstance(mine, list) or not isinstance(theirs, list):
        return None
    merged = list(theirs)
    seen = {_example_key(item) for item in theirs if _example_key(item)}
    for item in mine:
        key = _example_key(item)
        if key and key not in seen:
            seen.add(key)
            merged.append(item)
    return merged


def _prefer_shared_without_losing(mine, theirs, *, key: str = ""):
    """Взять общее, но не потерять то, чего в общем нет.

    Три случая:
      • оба словаря  → сливаем по ключам: общее побеждает там, где заполнено, своё
        остаётся там, где на общем пусто. Так спасаются 70 карточек, где у человека
        заполнено прошедшее время, а на слове стоит пусто (замер 14.08.2026);
      • список  → общее побеждает, кроме случая, когда СВОЁ структурнее (см. выше);
      • всё остальное → общее побеждает.
    Правило одно: человек не должен увидеть меньше, чем видел вчера."""
    if isinstance(mine, dict) and isinstance(theirs, dict):
        merged = dict(mine)
        for key, value in theirs.items():
            if _card_block_is_filled(value):
                merged[key] = value
        return merged
    if not _card_block_is_filled(mine):
        return theirs
    # Порядок проверок значим.
    if _block_is_more_structured(theirs, mine):
        return theirs          # общее содержательнее — примеры с переводом против голых строк
    if _block_is_more_structured(mine, theirs):
        return mine            # своё содержательнее — не отнимаем
    if key == "usage_examples":
        # Примеры не выбираем, а СКЛАДЫВАЕМ: свежие с общего слова сверху, свои ниже.
        merged = _merge_examples_shared_first(mine, theirs)
        if merged is not None:
            return merged
    if isinstance(mine, list) and isinstance(theirs, list) and len(mine) > len(theirs):
        return mine            # одинаковой формы, но своих больше: три синонима против одного
    return theirs


def merge_unit_card_for_serve(card: dict | None, unit_card: dict | None,
                              overrides: dict | None = None) -> dict:
    """Собрать то, что человек увидит: ОБЩЕЕ СЛОВО, сверху личные правки.

    Правило (решение владельца 14.08.2026, схема WaniKani + AnkiHub):
      • содержимое живёт на общем слове — оно и есть источник правды;
      • поле, которое человек написал СВОЕЙ РУКОЙ, побеждает общее (`overrides`);
      • у общего слова блок пуст — остаётся то, что лежит в карточке: лучше старое,
        чем ничего. На этом держатся 153 карточки, у слов которых разбора нет вовсе.

    ЧТО ИЗМЕНИЛОСЬ И ПОЧЕМУ. Раньше правило было «только дополняем, никогда не
    заменяем»: с общего слова брался блок, лишь если своего нет или он короче.
    Обоснование в коде звучало так: «у 0.9% карточек указатель ведёт на соседнее
    слово, и замена показала бы чужой разбор».

    Замер 14.08.2026 это опроверг: битых указателей практически нет (1 из 24 908 без
    указателя, 0 в несуществующее слово), а 1095 «несовпадений» были формами одного и
    того же слова, и 1077 из них подтвердил справочник форм. То есть правило защищало
    от беды, которой нет, а заодно защищало устаревшие копии: 4 703 карточки показывали
    свой перевод, разошедшийся с общим словом, и у ВСЕХ у них слово улучшали позже.

    Теперь личное защищается точечно — тем, что человек правил сам, а не тем, что
    когда-то скопировалось. Отличить одно от другого стало можно: см.
    bt_3_user_word_overrides и ensure_user_word_overrides_schema()."""
    base = dict(card) if isinstance(card, dict) else {}
    if isinstance(unit_card, dict) and unit_card:
        for key in CARD_CONTENT_KEYS:
            theirs = unit_card.get(key)
            if not _card_block_is_filled(theirs):
                continue
            base[key] = _prefer_shared_without_losing(base.get(key), theirs, key=key)
    # Личные правки — последними, поверх всего. Их не перебивает ничто.
    if isinstance(overrides, dict):
        for key, value in overrides.items():
            if key in USER_EDITABLE_CARD_FIELDS and value not in (None, "", [], {}):
                base[key] = value
    return dedupe_card_meanings(base)


def normalize_card_meanings_for_storage(card: dict, *, german_pos: str = "") -> dict:
    """Привести значения и переводы к тому виду, в каком они должны ЛЕЖАТЬ В БАЗЕ.

    ЗАЧЕМ ОТДЕЛЬНО ОТ ПОКАЗА. Три дня чинились правила показа: свалки с номерами
    разрезаются, повторы отсеиваются, регистр опускается. Но всё это спасало ЭКРАН, а
    в базу продолжало ложиться прежнее. Владелец 16.08.2026: «мы просто работаем с
    последствиями, а в будущем ничего не защитили?» — верно, и это тот же заслон, но
    на входе.

    Почему правило показа при этом остаётся: базу оно не чинит задним числом, а
    накопленное всё ещё лежит. Уберут одно — второе прикроет.

    Чем это важнее «и так же показывается правильно»: базу читают не только экраны —
    выгрузки, квизы, задания, переезды. Им правило показа не достаётся.

    Порядок шагов значим:
      1. разрезать свалку с номерами («1 колоть 2 жалить» — два значения, не одно);
      2. опустить регистр («Аккуратный, опрятный» — словарная статья, не предложение);
      3. убрать перевод, целиком сидящий внутри соседнего («скобка» ⊂ «Скобка, скрепка»);
      4. убрать полные повторы («утилизировать» дважды с разным пояснением).
    Иначе шаги мешают друг другу: неразрезанная свалка не считается повтором, а
    неопущенный регистр делает «Перемена» и «перемена» разными строками.
    """
    if not isinstance(card, dict):
        return card
    from backend.lex_units import (
        drop_nested_translations,
        normalize_translation_case,
        split_numbered_senses,
    )
    for key in _MEANING_LIST_KEYS:
        values = card.get(key)
        if not isinstance(values, list) or not values:
            continue
        values = [_swap_inverted_translation(item) for item in values]
        pieces: list = []
        for item in values:
            text = item.get("value") if isinstance(item, dict) else item
            for part in split_numbered_senses(str(text or "")):
                part = normalize_translation_case(part, german_pos=german_pos)
                pieces.append({**item, "value": part} if isinstance(item, dict) else part)
        kept = set(drop_nested_translations([
            (p.get("value") if isinstance(p, dict) else p) for p in pieces
        ]))
        card[key] = [p for p in pieces if (p.get("value") if isinstance(p, dict) else p) in kept]
    return dedupe_card_meanings(card)


# Поля, где модель повторяет одно и то же значение по два раза.
_MEANING_LIST_KEYS = ("dictionary_senses", "translations")


def _swap_inverted_translation(item):
    """Перевод и пояснение поменялись местами — вернуть их на свои места.

    Модель иногда кладёт в поле перевода САМ НЕМЕЦКИЙ текст, а русский перевод уносит
    в пояснение:
        value:   «obwohl es mir bewusst gewesen wäre»
        context: «Хотя я бы это осознавал»
    Такое слово становится немым: страж связей правильно отказывается считать немецкий
    текст переводом, и человек открывает карточку, не узнавая, что слово значит.
    Класс повторяющийся — 18.08.2026 он пришёл третий раз («Das Risiko willkürlicher
    Festnahmen», «Ich möchte das noch einmal präzisieren», это слово), поэтому чиним не
    записи, а вход.

    Признак абсолютный и не требует модели: РУССКИЙ ТЕКСТ ПИШЕТСЯ КИРИЛЛИЦЕЙ. Меняем
    местами только когда в переводе кириллицы нет ВООБЩЕ, а в пояснении она есть.
    """
    if not isinstance(item, dict):
        return item
    value = str(item.get("value") or "").strip()
    context = str(item.get("context") or "").strip()
    if not value or not context:
        return item
    if _CYRILLIC_TEXT_RE.search(value) or not _CYRILLIC_TEXT_RE.search(context):
        return item
    # ⚠ В пояснении не всегда лежит перевод. Часто там ОПИСАНИЕ: «перевод фразы с
    # русского на немецкий», «общее слово для спортивных соревнований», «употребляется
    # в официальных текстах». Переставив такое в перевод, мы поменяли бы одну неверную
    # строку на другую. Поймано прогоном 18.08.2026: из 354 перестановок такими
    # оказались десятки. Признак — служебные слова описания и длина.
    if _MEANING_DESCRIPTION_RE.search(context) or len(context) > 70:
        return item
    return {**item, "value": context, "context": None}


_CYRILLIC_TEXT_RE = re.compile(r"[А-Яа-яЁё]")
# Слова, по которым видно, что перед нами ПОЯСНЕНИЕ, а не перевод.
_MEANING_DESCRIPTION_RE = re.compile(
    r"(перевод|буквальн|дословн|слово для|выражение|употребляется|используется|"
    r"означает|обозначает|говорят|в смысле|синоним|фраза|оборот|конструкц|"
    r"описыва|подчёркива|подчеркива)", re.I)


def _meaning_key(value) -> str:
    return _squash_space(str(value or "")).casefold().strip(" .,;")


def dedupe_card_meanings(card: dict) -> dict:
    """Убрать повторы значений внутри одного разбора.

    ЗАЧЕМ. Модель пишет одно значение дважды, меняя пояснение: у «entsorgen» пять
    значений, а разных три — «утилизировать» и «избавляться» стоят по два раза.
    Замер 15.08.2026: в личных карточках 11 848 повторов из 33 954 значений (у 6 642
    карточек), на общих словах — 614 из 13 799 (у 349 слов). Человек видит «пять
    значений» и думает, что слово богаче, чем оно есть.

    Сравниваем по ТЕКСТУ значения, пояснение в расчёт не берём: именно разным
    пояснением модель и оправдывает повтор. Остаётся первое вхождение — оно идёт под
    первым рангом, то есть признано главным. Ранги после отсева пересчитываются, иначе
    на карточке будет «1, 3, 5».

    Из базы ничего не удаляется: это правило показа. Страж на приёмке стоит отдельно,
    в _prepare_dictionary_response_json_for_save.
    """
    if not isinstance(card, dict):
        return card
    for key in _MEANING_LIST_KEYS:
        values = card.get(key)
        if not isinstance(values, list) or len(values) < 2:
            continue
        kept, seen = [], {}
        for item in values:
            text = item.get("value") if isinstance(item, dict) else item
            marker = _meaning_key(text)
            if not marker:
                continue
            if marker in seen:
                # Рядом лежит тот же перевод со СТРОЧНОЙ — значит это обычное слово, а
                # не имя собственное, и заглавная в нём лишняя. Только здесь это и можно
                # доказать: правило регистра само по себе одиночное слово не трогает,
                # потому что под ним прячутся «Афины» и «Марокко».
                index = seen[marker]
                current = kept[index].get("value") if isinstance(kept[index], dict) else kept[index]
                fresh = str(text or "")
                if str(current or "")[:1].isupper() and fresh[:1].islower():
                    if isinstance(kept[index], dict):
                        kept[index] = {**kept[index], "value": fresh}
                    else:
                        kept[index] = fresh
                continue
            seen[marker] = len(kept)
            kept.append(item)
        if len(kept) == len(values):
            continue
        for index, item in enumerate(kept):
            if isinstance(item, dict) and "rank" in item:
                item["rank"] = index + 1
        card[key] = kept
    return card


def attach_unit_content_to_cards(items, *, id_key: str = "id", json_key: str = "response_json",
                                 cursor=None):
    """Дополнить разбор пачки карточек тем, что лежит на их единице.

    Одно место на всех раздатчиков — тренажёры, повторения, подсказка. Иначе правило
    «разбор живёт на единице» пришлось бы повторять в каждом запросе, и первый же новый
    экран про него забыл бы.

    Один запрос на всю пачку. Правила те же, что в библиотеке: только дополняем, и
    только если единица про это же слово.

    cursor обязателен, когда вызывающий уже держит транзакцию (ответ на повторении):
    иначе мы возьмём из пула второе соединение, не отпустив первое.
    """
    if not DICTIONARY_UNITS_SERVE_ENABLED or not items:
        return items
    ids = []
    for item in items:
        if not isinstance(item, dict):
            continue
        try:
            card_id = int(item.get(id_key) or 0)
        except (TypeError, ValueError):
            continue
        if card_id > 0:
            ids.append(card_id)
    if not ids:
        return items
    def _load(cur):
        cur.execute(
            """
            -- Заметки человека берём тем же запросом: они лежат в этой же
            -- строке, отдельный поход в базу был бы ради ничего. Связь с
            -- единицей здесь необязательна — заметка есть и у слова без неё.
            SELECT q.id, q.word_de, u.card, u.lemma_key, q.user_notes,
                   -- Принадлежит ли написание карточки этому слову — спрашиваем
                   -- справочник форм, а не сравниваем буквы. Без этого «Die
                   -- Strümpfe» не признаётся формой слова «Strumpf», и разбор с
                   -- общего слова не показывается вовсе (1077 таких карточек).
                   COALESCE(""" + UNIT_OWNS_CARD_SURFACE_SQL.format(q="q", u="u") + """, FALSE)
            FROM bt_3_webapp_dictionary_queries q
            LEFT JOIN bt_3_lex_units u ON u.id = q.lex_unit_id
            WHERE q.id = ANY(%s)
            """,
            (ids,),
        )
        return cur.fetchall()

    try:
        if cursor is not None:
            rows = _load(cursor)
        else:
            with get_db_connection_context() as conn:
                with conn.cursor() as own_cursor:
                    rows = _load(own_cursor)
    except Exception as exc:
        logging.debug("разбор с единиц не подтянулся: %s", exc)
        return items

    by_card = {
        int(row[0]): (row[1], _coerce_json_object(row[2]), row[3], normalize_user_notes(row[4]), bool(row[5]))
        for row in rows
    }
    # Личные правки человека — то, что он написал своей рукой. Ложатся поверх общего.
    overrides = get_user_word_overrides(ids, cursor=cursor)
    for item in items:
        if not isinstance(item, dict):
            continue
        try:
            found = by_card.get(int(item.get(id_key) or 0))
        except (TypeError, ValueError):
            found = None
        if not found:
            continue
        word_de, unit_card, lemma_key, user_notes, surface_confirms = found
        # Заметки человека — рядом с разбором, но НИКОГДА не внутри него: разбор общий
        # и обновляется, заметка личная и обновлениям не подлежит.
        if user_notes:
            item["user_notes"] = user_notes
        if not unit_card:
            continue
        card = _coerce_json_object(item.get(json_key))
        if not unit_card_is_about_the_same_word_sql(
            unit_lemma_key=lemma_key,
            card_word=word_de or card.get("word_de"),
            surface_confirms=surface_confirms,
        ):
            continue
        item[json_key] = merge_unit_card_for_serve(card, unit_card, overrides.get(int(item.get(id_key) or 0)))
    return items


def unit_card_is_about_the_same_word(*, unit_lemma_key: str | None, card_word: str | None) -> bool:
    """Разбор с единицы можно показывать, только если единица про ЭТО слово.

    ЭТО БЫСТРАЯ ПРОВЕРКА ПО БУКВАМ. Она отвечает «да» только на точное совпадение, а
    значит говорит «нет» на любую ФОРМУ слова. Одной её недостаточно — см. ниже.
    Полная проверка: unit_card_is_about_the_same_word_sql().

    ╔══════════════════════════════════════════════════════════════════════════════╗
    ║  УКАЗАТЕЛИ НЕ БИТЫЕ. ПЕРЕСЧИТЫВАТЬ ЗАНОВО НЕ НАДО. Замер 14.08.2026.          ║
    ║                                                                              ║
    ║  Что такое указатель: колонка lex_unit_id в карточке человека — номер общего  ║
    ║  слова в bt_3_lex_units. Одно слово на всех, карточек на него много.          ║
    ║                                                                              ║
    ║  Эта функция сравнивает ЗАГОЛОВОК карточки с ЛЕММОЙ слова буква в букву.      ║
    ║  Поэтому она отвечает «не то слово» на всё, что стоит в форме:                ║
    ║        Die Strümpfe   → Strumpf      множественное с умлаутом                 ║
    ║        angekündigt    → ankündigen   причастие                                ║
    ║        des Umbruchs   → Umbruch      родительный падеж                        ║
    ║        umgewandelt    → umwandeln    причастие с отделяемой приставкой        ║
    ║  Это ОДНО И ТО ЖЕ слово, указатель ведёт правильно.                           ║
    ║                                                                              ║
    ║  ЧИСЛА (24 908 карточек людей):                                              ║
    ║    указателя нет вовсе ................................. 1                   ║
    ║    указатель в несуществующее слово .................... 0                   ║
    ║    сравнение по буквам не сошлось ...................... 1095 (4,4%)         ║
    ║      из них подтверждает таблица написаний ............. 1077 (98%)          ║
    ║      осталось разобрать глазами ........................ 18                  ║
    ║                                                                              ║
    ║  ЭТИ 18 РАЗОБРАНЫ 14.08.2026. Указателей «на чужое слово» среди них НОЛЬ.     ║
    ║  Поломано не указание, а НАЗВАНИЕ САМОГО СЛОВА в словаре:                     ║
    ║     ernten → «ernen» (потеряна буква) · ansonsten → «ansonst» (обрублено)      ║
    ║     Der Umfang → «umfa» · Ärgernisse → «argernisse» (потерян умлаут)           ║
    ║     die Beförderung → «diebeförderung» (артикль вклеен без пробела)            ║
    ║     auferlegen → «auferlegen - auferlegt» (приклеено причастие)                ║
    ║     Er will ins Freibad gehen → «pov: er will ins freibad gehen!» (мусор)      ║
    ║  Плюс 6 случаев, где у слова просто снят артикль, и 1 русская карточка,        ║
    ║  указывающая на английское слово («дерзкий поступок» → «a bold act»).          ║
    ║  Это семья дефектов «испорченный заголовок», а НЕ «битый указатель».           ║
    ║                                                                              ║
    ║  СКОЛЬКО КАРТОЧЕК ДЕРЖИТСЯ НА СВОЕЙ КОПИИ РАЗБОРА (замер 14.08.2026):         ║
    ║    было по СТАРОЙ проверке (сравнение букв) ............ 926                  ║
    ║       у слова разбора нет вообще ....................... 153                  ║
    ║       сверка заголовка не пускала ...................... 773                  ║
    ║    стало по НОВОЙ проверке (справочник форм) ........... 153                  ║
    ║       из 773 новая проверка пропускает ................. 773  (все)          ║
    ║                                                                              ║
    ║  То есть замена проверки сама вылечила 773 карточки из 926. Осталось 153, и   ║
    ║  их копия — ЕДИНСТВЕННЫЙ источник: у слова нет разбора, снимешь копию —       ║
    ║  человек останется с пустой карточкой. Их разбирать отдельно.                  ║
    ║                                                                              ║
    ║  ⚠ ЛОВУШКА ПРИ ЛЮБОМ ПОВТОРНОМ ЗАМЕРЕ: считать надо НОВОЙ проверкой           ║
    ║    (unit_card_is_about_the_same_word_sql со справочником форм). Посчитаешь     ║
    ║    старой — получишь 926 и решишь, что дело в шесть раз хуже, чем есть.        ║
    ║                                                                              ║
    ║  КАК СЧИТАТЬ ПРАВИЛЬНО: не сравнивать строки, а спросить bt_3_lex_surfaces —  ║
    ║  справочник «какая форма какому слову принадлежит», 56 тысяч записей. Он для  ║
    ║  того и заведён. Строковые правила («снять умлаут», «убрать ge-») пробовались ║
    ║  трижды и каждый раз давали завышенный ответ: 510, 539, 585 — все три числа   ║
    ║  разваливались при проверке глазами.                                          ║
    ║                                                                              ║
    ║  ЧЕМ ЭТО ВАЖНО: на «битые указатели» ссылается merge_unit_card_for_serve,     ║
    ║  оправдывая правило «только дополняем, никогда не заменяем». Битых указателей ║
    ║  нет — значит и это правило держится на мисмежерении, а не на факте.          ║
    ╚══════════════════════════════════════════════════════════════════════════════╝
    """
    key = _normalize_dictionary_headword_key(card_word)
    if not key:
        return False
    return key == _normalize_dictionary_headword_key(unit_lemma_key)


# Кусок SQL, отвечающий «принадлежит ли написание из карточки этому слову».
# Спрашивает справочник форм bt_3_lex_surfaces вместо сравнения букв. Подставляется
# в запросы, которые и так тянут карточку с единицей, — отдельного похода в базу не нужно.
# %(q)s — псевдоним таблицы карточек, %(u)s — псевдоним таблицы единиц.
UNIT_OWNS_CARD_SURFACE_SQL = """
    EXISTS (
        SELECT 1 FROM bt_3_lex_surfaces s
        WHERE s.unit_id = {u}.id
          AND s.lang = {u}.lang
          AND s.surface_key = LOWER(BTRIM(REGEXP_REPLACE(
                  COALESCE({q}.word_de, ''),
                  '^(der|die|das|ein|eine|einen|einem|einer|eines)[[:space:]]+', '', 'i')))
    )
"""


def unit_card_is_about_the_same_word_sql(
    *, unit_lemma_key: str | None, card_word: str | None, surface_confirms: bool
) -> bool:
    """Полная проверка: совпали буквы ИЛИ справочник форм подтвердил связь.

    surface_confirms приходит из запроса, куда подставлен UNIT_OWNS_CARD_SURFACE_SQL.
    Замер 14.08.2026: справочник подтверждает 1077 из 1095 случаев, которые проверка
    по буквам объявляла «не то слово»."""
    if surface_confirms:
        return True
    return unit_card_is_about_the_same_word(unit_lemma_key=unit_lemma_key, card_word=card_word)


# Принимает ли общий пул НОВЫЙ разбор. Выключено с 05.08.2026: дом разбора — единица,
# а два склада одного и того же неизбежно расходятся (весь день 04–05.08 ушёл на то,
# чтобы свести их обратно). Пул при этом остаётся читаемым: 6 363 готовых разбора никуда
# не деваются и продолжают находиться, просто новых там не появляется.
#
# Строки пула по-прежнему заводятся: на них держится связь карточки с общим словом
# (`canonical_entry_id`) и вся защита от дублей. Замирает только содержимое разбора.
#
# Включить обратно — DICTIONARY_POOL_CARD_WRITES_ENABLED=1, без выкатки кода.
DICTIONARY_POOL_CARD_WRITES_ENABLED = str(
    os.getenv("DICTIONARY_POOL_CARD_WRITES_ENABLED") or "0"
).strip().lower() in {"1", "true", "yes", "on"}


def _pool_card_update_sql(new_value_sql: str, stored_column: str = "response_json") -> str:
    """Кусок SQL, решающий судьбу разбора в пуле при обновлении строки.

    Пул закрыт для записи — оставляем что лежит. Открыт — прежнее правило «полная
    карточка вытесняет тонкую». Вынесено функцией, чтобы правило было ОДНО на оба
    места записи и его можно было проверить тестом, не поднимая базу."""
    if not DICTIONARY_POOL_CARD_WRITES_ENABLED:
        return stored_column
    return (
        f"CASE WHEN {stored_column} IS NULL THEN {new_value_sql}"
        f" WHEN {new_value_sql} IS NULL THEN {stored_column}"
        f" WHEN {_dictionary_pool_rich_sql(f'({new_value_sql})')}"
        f"      AND NOT {_dictionary_pool_rich_sql(stored_column)}"
        f"     THEN {new_value_sql}"
        f" ELSE {stored_column} END"
    )


DICTIONARY_POOL_RICH_SQL_STORED = _dictionary_pool_rich_sql("bt_3_dictionary_entries.response_json")
DICTIONARY_POOL_RICH_SQL_EXCLUDED = _dictionary_pool_rich_sql("EXCLUDED.response_json")


def _dictionary_pool_word_fully_rich_sql(alias: str) -> str:
    """STRICTER richness test than _dictionary_pool_rich_sql — used ONLY by the nightly
    enrichment selection, never by the pool serve/upsert gate.

    The serve gate treats a card with mere usage_examples as "full" (so lookups stay free).
    But such a card can still be the THIN-prompt output — forms + examples, no Rektion /
    collocations / meanings / etymology. This predicate is True only when the RICH blocks the
    live prompt produces are actually present, so the nightly job re-enriches those
    thin-with-examples words automatically (no manual card-opening). Mirrors the Python
    _dictionary_word_card_is_thin. Array checks are type-guarded so a stray non-array value
    can never raise."""
    def _nonempty_array(key: str) -> str:
        # CASE (not AND) so jsonb_array_length only runs when the value IS an array — Postgres
        # does not guarantee short-circuit, and it raises on a scalar. Returns strict TRUE/FALSE
        # (never NULL), so `NOT (…)` on a thin card is TRUE, not NULL — the bug that silently
        # excluded every thin word from the nightly selection.
        return (
            f"(CASE WHEN jsonb_typeof({alias}->'{key}') = 'array' "
            f"THEN jsonb_array_length({alias}->'{key}') >= 1 ELSE FALSE END)"
        )
    def _nonempty_text(path: str) -> str:
        return f"NULLIF(TRIM(COALESCE({path}, '')), '') IS NOT NULL"
    parts = [
        _nonempty_array("government_patterns"),
        _nonempty_array("common_collocations"),
        _nonempty_array("translations"),
        _nonempty_text(f"{alias}->'meanings'->'primary'->>'value'"),
        # memory_tip / etymology_note are no longer generated (card trimmed 2026-07-24) —
        # dropped from the richness test so lean cards count as complete and the nightly
        # enricher does not loop re-enriching them. [[project_dict_card_trim]]
    ]
    return "(" + " OR ".join(parts) + ")"


DICTIONARY_POOL_WORD_FULLY_RICH_SQL = _dictionary_pool_word_fully_rich_sql("bt_3_dictionary_entries.response_json")


_GERMAN_DEFINITE_ARTICLE_WORDS = ("der", "die", "das")


def _dictionary_leading_definite_article(value: object) -> str:
    """Артикль в начале написания: «die Mündung» → «die». Не артикль → пусто."""
    raw = str(value or "").strip().casefold()
    if raw in _GERMAN_DEFINITE_ARTICLE_WORDS:  # поле `article` хранит голый артикль
        return raw
    head = raw.split(" ", 1)[0]
    return head if head in _GERMAN_DEFINITE_ARTICLE_WORDS else ""


def _dictionary_entry_article(source_text: object, response_json: object = None) -> str:
    """Род записи пула. Смотрим и в написание, и в карточку: слово могло прийти без
    артикля («Mündung»), но разбор внутри знает, что оно «die». Без этого второй заход
    того же слова с ДРУГИМ артиклем слился бы с чужим родом — ровно тот случай
    «der Kiefer» (челюсть) против «die Kiefer» (сосна)."""
    payload = _coerce_json_object(response_json)
    for candidate in (
        source_text,
        payload.get("article"),
        payload.get("word_de"),
        payload.get("source_text"),
        payload.get("translation_de"),
    ):
        article = _dictionary_leading_definite_article(candidate)
        if article:
            return article
    return ""


def _dictionary_text_is_single_word(value: object) -> bool:
    headword = _normalize_dictionary_headword_key(value)
    return bool(headword) and " " not in headword


def _resolve_canonical_entry_slot_with_cursor(
    cursor,
    *,
    source_lang: str,
    target_lang: str,
    source_text: str,
    target_text: str,
    payload: dict | None,
) -> int | None:
    """ОДНО СЛОВО — ОДНА СТРОКА ПУЛА. Ключ уникальности («пара языков + текст запроса +
    текст ответа») заводил НОВУЮ строку и на артикль («die Mündung» против «Mündung»),
    и на другую формулировку перевода («устье» против «устье, дуло»). Из-за этого одно
    слово жило в трёх записях с разными переводами, и человек видел разное в зависимости
    от того, набрал он артикль или нет (замер 04.08.2026: 698 заголовков).

    Поэтому перед вставкой ищем УЖЕ СУЩЕСТВУЮЩУЮ строку того же слова и дописываем её.

    ⚠️ Слово опознаём по НЕМЕЦКОЙ стороне, и вот почему направления разные:
    в de→ru немецкое слово — это сам запрос, и «устье» против «устье, дуло» — просто две
    формулировки одного перевода. А в ru→de запрос русский, и одно русское слово даёт
    РАЗНЫЕ немецкие: «Молния» — это и `der Blitz`, и `der Reißverschluss`. Слить их значило
    бы потерять слово, поэтому там требуем совпадения и немецкой стороны тоже.
    Разный род — разные слова («der Kiefer» челюсть против «die Kiefer» сосна).
    Фразы и предложения не трогаем: у них значим весь текст целиком."""
    if not _dictionary_text_is_single_word(source_text):
        return None
    headword = _normalize_dictionary_headword_key(source_text)
    if not headword:
        return None
    german_is_source = source_lang == "de"
    target_headword = _normalize_dictionary_headword_key(target_text)
    if not german_is_source and (not target_headword or not _dictionary_text_is_single_word(target_text)):
        return None
    incoming_article = (
        _dictionary_entry_article(source_text, payload)
        if german_is_source
        else _dictionary_entry_article(target_text, payload)
    )
    cursor.execute(
        f"""
        SELECT id, source_text, target_text, response_json,
               (response_json IS NOT NULL AND {DICTIONARY_POOL_RICH_SQL_STORED}) AS is_rich
        FROM bt_3_dictionary_entries
        WHERE source_lang = %s AND target_lang = %s
          AND source_headword_norm = %s
          AND (%s::text IS NULL OR target_headword_norm = %s)
          AND COALESCE(response_json->>'merged_into', '') = ''
        ORDER BY id
        LIMIT 20;
        """,
        (
            source_lang, target_lang, headword,
            None if german_is_source else target_headword,
            target_headword,
        ),
    )
    rows = cursor.fetchall() or []
    best: tuple[tuple[int, int, int], int] | None = None
    for row_id, row_source_text, row_target_text, row_payload, row_is_rich in rows:
        row_article = _dictionary_entry_article(
            row_source_text if german_is_source else row_target_text, row_payload
        )
        if incoming_article and row_article and incoming_article != row_article:
            continue  # чужой род — чужое слово
        rank = (
            1 if (incoming_article and row_article == incoming_article) else 0,
            1 if row_is_rich else 0,
            -int(row_id),  # при равенстве побеждает самая старая строка
        )
        if best is None or rank > best[0]:
            best = (rank, int(row_id))
    return best[1] if best else None


def _upsert_dictionary_canonical_entry_with_cursor(
    cursor,
    *,
    source_lang: str | None,
    target_lang: str | None,
    source_text: str | None,
    target_text: str | None,
    word_ru: str | None,
    translation_de: str | None,
    word_de: str | None,
    translation_ru: str | None,
    response_json: dict | None,
) -> int:
    normalized_source_lang = _normalize_lang_code(source_lang)
    normalized_target_lang = _normalize_lang_code(target_lang)
    # Механическая чистка на самом дне записи в общий словарь: сюда приходят и живой
    # путь, и дообогащение, и разовые прогоны. Слово с невидимым знаком или переводом
    # строки внутри заводит ВТОРУЮ запись, которую поиск не найдёт по её же тексту.
    source_text, target_text, word_ru, word_de, translation_ru, translation_de = intake.clean_all(
        source_text, target_text, word_ru, word_de, translation_ru, translation_de
    )
    resolved_source_text = str(source_text or "").strip()
    resolved_target_text = str(target_text or "").strip()
    normalized_source_text = _normalize_dictionary_text_key(resolved_source_text)
    normalized_target_text = _normalize_dictionary_text_key(resolved_target_text)
    if not normalized_source_lang or not normalized_target_lang:
        raise ValueError("dictionary canonical entry requires language pair")
    if not normalized_source_text or not normalized_target_text:
        raise ValueError("dictionary canonical entry requires source and target text")
    # ── ЧТО В ОБЩИЙ СЛОВАРЬ НЕ КЛАДЁТСЯ НИКОГДА ──────────────────────────────────
    #
    # Пул общий: ошибка одного достаётся всем следующим, кто наберёт то же слово.
    # Замер 21.08.2026 по 17 333 записям — два класса, которые туда попали и дошли до
    # экрана (проверено запросом к пулу тем же кодом, что и в продукте):
    #
    #   1. ЗАДАНИЕ ТРЕНАЖЁРА вместо слова: «Ich ___ mein Geld lieber langfristig.» →
    #      «anlegen». Таких 143, из них 119 побеждали в поиске. Решение владельца
    #      21.08.2026: «им там не место».
    #   2. ОТВЕТ НА ЧУЖОМ ЯЗЫКЕ: спросили «Укладывать» (рус→нем) — ответ «Складывать».
    #      Таких 48. Человек получает русское слово как немецкий перевод.
    #
    # Проверяется ТОЛЬКО ответ. Запрос имеет право быть каким угодно — это ключ поиска,
    # и находить по нему польза: из 334 записей, где хоть одна сторона «грязная», в 133
    # грязь набрал сам человек («Мой телефон ist kaputt» → «Mein Handy ist hin»), и
    # ответ там верный. Узкое правило вместо широкого — намеренно.
    if intake.is_exercise_blank(resolved_source_text) or intake.is_exercise_blank(resolved_target_text):
        raise ValueError("dictionary pool does not accept exercise blanks")
    if intake.answer_language_is_wrong(resolved_target_text, normalized_target_lang):
        raise ValueError(
            f"dictionary pool answer is not in {normalized_target_lang}: "
            f"{resolved_target_text[:60]!r}"
        )
    payload = _coerce_json_object(response_json)

    # Сначала пробуем дописать УЖЕ СУЩЕСТВУЮЩУЮ строку этого слова — иначе на каждый
    # артикль и каждую формулировку перевода заводилась бы своя (см. слот-резолвер).
    slot_id = _resolve_canonical_entry_slot_with_cursor(
        cursor,
        source_lang=normalized_source_lang,
        target_lang=normalized_target_lang,
        source_text=resolved_source_text,
        target_text=resolved_target_text,
        payload=payload,
    )
    if slot_id:
        cursor.execute(
            f"""
            UPDATE bt_3_dictionary_entries SET
                source_headword_norm = COALESCE(source_headword_norm, %(source_headword)s),
                target_headword_norm = COALESCE(target_headword_norm, %(target_headword)s),
                word_ru = COALESCE(NULLIF(word_ru, ''), %(word_ru)s),
                translation_de = COALESCE(NULLIF(translation_de, ''), %(translation_de)s),
                word_de = COALESCE(NULLIF(word_de, ''), %(word_de)s),
                translation_ru = COALESCE(NULLIF(translation_ru, ''), %(translation_ru)s),
                -- Текст и его нормализованные ключи НЕ трогаем: они держат уникальность
                -- строки, а мы сюда пришли именно для того, чтобы новой строки не заводить.
                response_json = {_pool_card_update_sql("%(payload)s::jsonb")},
                updated_at = NOW()
            WHERE id = %(slot_id)s
            RETURNING id;
            """,
            {
                "source_headword": _normalize_dictionary_headword_key(resolved_source_text) or None,
                "target_headword": _normalize_dictionary_headword_key(resolved_target_text) or None,
                "word_ru": str(word_ru or "").strip() or None,
                "translation_de": str(translation_de or "").strip() or None,
                "word_de": str(word_de or "").strip() or None,
                "translation_ru": str(translation_ru or "").strip() or None,
                "payload": Json(payload) if payload else None,
                "slot_id": int(slot_id),
            },
        )
        row = cursor.fetchone()
        if row and row[0] is not None:
            return int(row[0])

    cursor.execute(
        f"""
        INSERT INTO bt_3_dictionary_entries (
            source_lang,
            target_lang,
            source_text,
            target_text,
            source_text_norm,
            target_text_norm,
            source_headword_norm,
            target_headword_norm,
            word_ru,
            translation_de,
            word_de,
            translation_ru,
            response_json,
            created_at,
            updated_at
        )
        VALUES (%s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s, NOW(), NOW())
        ON CONFLICT (source_lang, target_lang, source_text_norm, target_text_norm)
        DO UPDATE SET
            source_headword_norm = COALESCE(bt_3_dictionary_entries.source_headword_norm, EXCLUDED.source_headword_norm),
            target_headword_norm = COALESCE(bt_3_dictionary_entries.target_headword_norm, EXCLUDED.target_headword_norm),
            source_text = COALESCE(NULLIF(bt_3_dictionary_entries.source_text, ''), EXCLUDED.source_text),
            target_text = COALESCE(NULLIF(bt_3_dictionary_entries.target_text, ''), EXCLUDED.target_text),
            word_ru = COALESCE(NULLIF(bt_3_dictionary_entries.word_ru, ''), EXCLUDED.word_ru),
            translation_de = COALESCE(NULLIF(bt_3_dictionary_entries.translation_de, ''), EXCLUDED.translation_de),
            word_de = COALESCE(NULLIF(bt_3_dictionary_entries.word_de, ''), EXCLUDED.word_de),
            translation_ru = COALESCE(NULLIF(bt_3_dictionary_entries.translation_ru, ''), EXCLUDED.translation_ru),
            -- Общий пул: побеждает БОЛЕЕ ПОЛНАЯ карточка, а не первый писатель.
            -- Раньше стоял COALESCE(старое, новое) — тонкая запись (сохранение из
            -- личного чата бота, импорт, тап в тренажёре) навсегда фиксировала пустую
            -- карточку, и богатый разбор поверх неё уже не ложился.
            response_json = {_pool_card_update_sql("EXCLUDED.response_json", "bt_3_dictionary_entries.response_json")},
            updated_at = NOW()
        RETURNING id;
        """,
        (
            normalized_source_lang,
            normalized_target_lang,
            resolved_source_text,
            resolved_target_text,
            normalized_source_text,
            normalized_target_text,
            _normalize_dictionary_headword_key(resolved_source_text) or None,
            _normalize_dictionary_headword_key(resolved_target_text) or None,
            str(word_ru or "").strip() or None,
            str(translation_de or "").strip() or None,
            str(word_de or "").strip() or None,
            str(translation_ru or "").strip() or None,
            # Пул закрыт для разбора — новая строка заводится как опознавательная:
            # тексты и связь есть, содержимого нет. Разбор живёт на единице.
            Json(payload) if (payload and DICTIONARY_POOL_CARD_WRITES_ENABLED) else None,
        ),
    )
    row = cursor.fetchone()
    return int(row[0]) if row and row[0] is not None else 0


def _create_or_attach_user_dictionary_entry_with_cursor(
    cursor,
    *,
    user_id: int,
    word_ru: str | None,
    translation_de: str | None,
    word_de: str | None,
    translation_ru: str | None,
    response_json: dict,
    folder_id: int | None = None,
    source_lang: str | None = None,
    target_lang: str | None = None,
    canonical_entry_id: int | None = None,
    origin_process: str | None = None,
    origin_meta: dict | None = None,
    semantic_tag: str | None = None,
) -> tuple[int, bool]:
    normalized_origin = _normalize_dictionary_origin_process(origin_process)
    normalized_meta = _coerce_json_object(origin_meta)
    normalized_response_json = _coerce_json_object(response_json)
    normalized_source_lang = _normalize_lang_code(source_lang)
    normalized_target_lang = _normalize_lang_code(target_lang)
    # Единственное место, где заводится строка личной карточки. Механическая чистка
    # стоит ЗДЕСЬ, а не у каждой двери: сохраняют из окна словаря, из мобильного, из
    # бота, из «Ярлыка» и из импортов, и заводить проверку в каждом входе — тот самый
    # способ, которым дырка открывалась заново с каждой задачей.
    word_ru, translation_de, word_de, translation_ru = intake.clean_all(
        word_ru, translation_de, word_de, translation_ru
    )
    normalized_semantic_tag = normalize_dictionary_semantic_tag(semantic_tag)
    freq_rank = compute_frequency_rank(word_de, normalized_response_json)
    # Фраза — это всё, что не сводится к одному немецкому слову (артикль не в счёт).
    # То же правило, по которому слову ищется частотный ранг: если ранга нет, потому что
    # это не одиночная лемма — значит фраза. Считаем ЗДЕСЬ, при сохранении, чтобы выдача
    # карточек не разбирала текст на каждом запросе.
    is_phrase_value = not bool(normalize_frequency_lemma(word_de))
    if canonical_entry_id:
        cursor.execute(
            """
            INSERT INTO bt_3_webapp_dictionary_queries (
                user_id,
                word_ru,
                folder_id,
                translation_de,
                word_de,
                translation_ru,
                source_lang,
                target_lang,
                canonical_entry_id,
                origin_process,
                origin_meta,
                semantic_tag,
                response_json,
                frequency_rank,
                is_phrase
            )
            VALUES (%s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s)
            ON CONFLICT (user_id, canonical_entry_id) WHERE canonical_entry_id IS NOT NULL
            DO UPDATE SET
                frequency_rank = COALESCE(EXCLUDED.frequency_rank, bt_3_webapp_dictionary_queries.frequency_rank),
                is_phrase = COALESCE(EXCLUDED.is_phrase, bt_3_webapp_dictionary_queries.is_phrase),
                folder_id = COALESCE(EXCLUDED.folder_id, bt_3_webapp_dictionary_queries.folder_id),
                origin_process = EXCLUDED.origin_process,
                origin_meta = COALESCE(EXCLUDED.origin_meta, bt_3_webapp_dictionary_queries.origin_meta),
                semantic_tag = COALESCE(EXCLUDED.semantic_tag, bt_3_webapp_dictionary_queries.semantic_tag),
                response_json = COALESCE(bt_3_webapp_dictionary_queries.response_json, EXCLUDED.response_json),
                word_ru = COALESCE(NULLIF(bt_3_webapp_dictionary_queries.word_ru, ''), EXCLUDED.word_ru),
                translation_de = COALESCE(NULLIF(bt_3_webapp_dictionary_queries.translation_de, ''), EXCLUDED.translation_de),
                word_de = COALESCE(NULLIF(bt_3_webapp_dictionary_queries.word_de, ''), EXCLUDED.word_de),
                translation_ru = COALESCE(NULLIF(bt_3_webapp_dictionary_queries.translation_ru, ''), EXCLUDED.translation_ru),
                source_lang = COALESCE(NULLIF(bt_3_webapp_dictionary_queries.source_lang, ''), EXCLUDED.source_lang),
                target_lang = COALESCE(NULLIF(bt_3_webapp_dictionary_queries.target_lang, ''), EXCLUDED.target_lang),
                canonical_entry_id = COALESCE(bt_3_webapp_dictionary_queries.canonical_entry_id, EXCLUDED.canonical_entry_id),
                is_learned = COALESCE(bt_3_webapp_dictionary_queries.is_learned, FALSE) OR COALESCE(EXCLUDED.is_learned, FALSE),
                updated_at = NOW()
            RETURNING id, (xmax = 0) AS inserted;
            """,
            (
                int(user_id),
                str(word_ru or "").strip() or None,
                int(folder_id) if folder_id is not None else None,
                str(translation_de or "").strip() or None,
                str(word_de or "").strip() or None,
                str(translation_ru or "").strip() or None,
                normalized_source_lang,
                normalized_target_lang,
                int(canonical_entry_id),
                normalized_origin,
                Json(normalized_meta) if normalized_meta else None,
                normalized_semantic_tag or None,
                Json(normalized_response_json),
                freq_rank,
                is_phrase_value,
            ),
        )
        row = cursor.fetchone()
        return (
            int(row[0]) if row and row[0] is not None else 0,
            bool(row[1]) if row and len(row) > 1 else False,
        )

    cursor.execute(
        """
        INSERT INTO bt_3_webapp_dictionary_queries (
            user_id,
            word_ru,
            folder_id,
            translation_de,
            word_de,
            translation_ru,
            source_lang,
            target_lang,
            canonical_entry_id,
            origin_process,
            origin_meta,
            semantic_tag,
            response_json,
            frequency_rank
        )
        VALUES (%s, %s, %s, %s, %s, %s, %s, %s, NULL, %s, %s, %s, %s, %s)
        RETURNING id;
        """,
        (
            int(user_id),
            str(word_ru or "").strip() or None,
            int(folder_id) if folder_id is not None else None,
            str(translation_de or "").strip() or None,
            str(word_de or "").strip() or None,
            str(translation_ru or "").strip() or None,
            normalized_source_lang,
            normalized_target_lang,
            normalized_origin,
            Json(normalized_meta) if normalized_meta else None,
            normalized_semantic_tag or None,
            Json(normalized_response_json),
            freq_rank,
            is_phrase_value,
        ),
    )
    row = cursor.fetchone()
    return int(row[0]) if row and row[0] is not None else 0, True


def _fix_plural_article_on_headword(value: str | None) -> str | None:
    """У формы множественного числа артикль может быть только «die».

    «der Handschuhe» — невозможная строка: род принадлежит слову, а множественное
    число рода не имеет. Владелец нашёл такую карточку 16.08.2026, и заведена она была
    в тот же день — то есть правило существовало (compose_german_headword ставит «die»
    на показе), но на ЗАПИСЬ не стояло, и в базу легло невозможное.

    Судим ТОЛЬКО по справочнику форм: german_surface отвечает «множественное» с высокой
    уверенностью лишь тогда, когда это подтверждено страницей de.wiktionary. Догадка по
    окончанию сюда не допускается — «der Streifen», «das Abkommen», «der Laster»
    окончанием от множественного неотличимы, и правило-угадайка сделало бы из них
    «die». Не знаем — не трогаем: строка остаётся ровно такой, какой пришла.
    """
    text = _squash_space(value)
    if not text:
        return value
    match = _LEADING_ARTICLE_ANY_CASE_RE.match(text)
    if not match:
        return value
    article = match.group(0).strip().lower()
    if article == "die":
        return value
    bare = text[match.end():].strip()
    if not bare or " " in bare:
        return value
    # ⚠ «das» + окончание -en — единственная форма, где мы обязаны ПРОМОЛЧАТЬ.
    # Так выглядит субстантивированный инфинитив: «das Schleifen» (шлифовка), «das
    # Putzen» (уборка), «das Essen», «das Leben». Наши источники его не отличают от
    # множественного: de.wiktionary не заводит на такие слова страницу существительного
    # (проверено живым запросом 16.08.2026 — на «Schleifen» и «Putzen» отвечает «рода
    # нет»), а указатель форм честно знает их как мн. ч. от «die Schleife» и «die Putze».
    # Догадаться тут нечем, поэтому строку не трогаем.
    #
    # С «der» такой неоднозначности НЕТ: у субстантивированного инфинитива артикль
    # всегда «das», значит «der Handschuhe» ничем иным, кроме ошибки, быть не может.
    if article == "das" and bare.casefold().endswith("en"):
        return value
    from backend.german_surface import PL, german_surface
    verdict = german_surface(bare)
    if verdict["number"] == PL and verdict["confidence"] == "high":
        return f"die {bare}"
    return value


def _lowercase_when_russian_says_not_a_noun(german: str | None, russian: str | None) -> str | None:
    """Снять заглавную у немецкого слова, если РУССКИЙ перевод доказал: это не существительное.

    Зачем (владелец, 24–25.08.2026). Человек ищет слово, и с клавиатуры оно приходит с
    ЗАГЛАВНОЙ буквы — это первое и единственное слово запроса. В немецком заглавная
    означает существительное, поэтому прилагательное «reif» ложилось в базу как «Reif»,
    справочник честно отвечал про существительное «der Reif» (иней), а модель сочиняла
    под него смыслы. Так родилась карточка «die Mies» — «Паршивый» с выдуманными
    значениями про неудачников, которую владелец увидел на экране. Замер 25.08.2026:
    111 таких заголовков, 11 сломаны однозначно.

    ВТОРОЙ ГОЛОС — русская сторона: её писал человек, и она не врёт. «Зрелый» —
    прилагательное, «Грести» — глагол, «Нос» — существительное. Источник разбора:
    `backend/russian_part_of_speech.py` (pymorphy3, MIT, офлайн, по одному слову).

    ЧТО ЭТА ФУНКЦИЯ ДЕЛАЕТ, А ЧЕГО НЕ ДЕЛАЕТ. Она только ОПУСКАЕТ заглавную и только
    когда русская сторона ДОКАЗАЛА «не существительное». Она не поднимает заглавную,
    не меняет само слово, не трогает фразы и ничего не выдумывает:

    • «спорно» — не доказательство. «Простой» это и прилагательное, и существительное;
      «Правда» — и существительное, и частица. Такое слово не трогаем;
    • «не знаем» — не доказательство. Многословный перевод («держать пари») тоже;
    • ФРАЗА не трогается: правило работает только на ОДНОМ немецком слове. В «eine
      Pressekonferenz abhalten» регистр принадлежит фразе;
    • артикль впереди («die Mies») означает, что кто-то уже счёл слово существительным,
      — снимаем и его вместе с заглавной.

    ⚠ ЛОВУШКА, ПОЙМАННАЯ НА ЖИВЫХ ДАННЫХ. Русский перевод бывает НЕВЕРЕН сам: у «das
    Frühstück» (завтрак) стоял перевод «Завтракать», у «der/die Angeklagte» —
    «Обвиняемый». В обоих случаях немецкое слово ВЕРНОЕ, а прилагательным/глаголом
    выглядит перевод. Поэтому правило снимает заглавную ТОЛЬКО у слов, чей род нам
    неизвестен: если справочник знает «das Frühstück», значит существительное есть, и
    спорить с ним по переводу мы не будем. Это сужает правило, зато оно не ломает верное.
    """
    text = str(german or "").strip()
    if not text or " " in text.replace("der ", "").replace("die ", "").replace("das ", "").strip():
        # Несколько слов после снятия артикля — это фраза, регистр принадлежит ей.
        if not re.fullmatch(r"(?:(?:der|die|das)\s+)?[A-ZÄÖÜ][A-Za-zÄÖÜäöüß-]*", text):
            return german
    if not re.fullmatch(r"(?:(?:der|die|das)\s+)?[A-ZÄÖÜ][A-Za-zÄÖÜäöüß-]*", text):
        return german
    bare = re.sub(r"^(?:der|die|das)\s+", "", text)
    try:
        from backend.russian_part_of_speech import proves_not_a_noun
        if not proves_not_a_noun(russian):
            return german
    except Exception:
        logging.warning("второй голос: разбор русской стороны не отработал", exc_info=True)
        return german
    # ⚠ СТОРОЖА «А ВДРУГ ТАКОЕ СУЩЕСТВИТЕЛЬНОЕ ЕСТЬ?» ЗДЕСЬ НЕТ, И ЭТО ОСОЗНАННО.
    # Пробовал 25.08.2026 — он глушит правило целиком: у ВСЕХ сломанных слов немецкое
    # существительное тоже существует. «der Reif» — иней, «das Rudern» — гребля,
    # «die Mies» — место. В этом и была беда: справочник отвечал про существительное,
    # которого карточка не касается.
    #
    # ЦЕНА ЭТОГО РЕШЕНИЯ, НАЗВАННАЯ ВСЛУХ. Отличить «Reif/Зрелый» (немецкое неверно) от
    # «Frühstück/Завтракать» (неверен ПЕРЕВОД) по данным невозможно: в обоих случаях
    # существительное есть, а русская сторона не существительное. Разницу решает СМЫСЛ,
    # то есть модель, а не правило. Поэтому правило опускает заглавную в обоих случаях.
    #
    # Почему так, а не наоборот (владелец, 25.08.2026): выдуманный разбор — катастрофа,
    # он учит человека несуществующему немецкому («Die Mies sind wieder nicht
    # erfolgreich»). Неверный регистр у карточки, где ЧЕЛОВЕК и так написал корявый
    # перевод, — беда меньшего порядка. Из двух ошибок выбираем дешёвую.
    return bare.lower()


def _save_webapp_dictionary_query_returning_id_with_conn(
    conn,
    *,
    user_id: int,
    word_ru: str | None,
    translation_de: str | None,
    word_de: str | None,
    translation_ru: str | None,
    response_json: dict,
    folder_id: int | None = None,
    source_lang: str | None = None,
    target_lang: str | None = None,
    origin_process: str | None = None,
    origin_meta: dict | None = None,
    semantic_tag: str | None = None,
) -> tuple[int, bool]:
    normalized_response_json = _coerce_json_object(response_json)
    # Заголовок приводится к словарной форме ЗДЕСЬ — это единственное место, через
    # которое проходит запись любой карточки: и бот, и веб, и импорт. Прежде правило
    # стояло выше по течению, в веб-слое, и обходилось: замер 16.08.2026 нашёл
    # «klarzukommen» и «die eine Pleite» в колонке translation_de при уже исправленной
    # word_de — а крупный заголовок на экране разбора берётся именно из translation_de.
    from backend.german_grammar_tables import german_dictionary_headword
    word_de = german_dictionary_headword(word_de) if word_de else word_de
    translation_de = german_dictionary_headword(translation_de) if translation_de else translation_de
    word_de = _fix_plural_article_on_headword(word_de)
    translation_de = _fix_plural_article_on_headword(translation_de)
    # ВТОРОЙ ГОЛОС: русский перевод решает, существительное ли это (владелец, 25.08.2026).
    word_de = _lowercase_when_russian_says_not_a_noun(word_de, word_ru)
    translation_de = _lowercase_when_russian_says_not_a_noun(translation_de, word_ru)
    normalized_source_lang = _normalize_lang_code(source_lang)
    normalized_target_lang = _normalize_lang_code(target_lang)
    source_text, target_text = _resolve_dictionary_source_target_texts(
        source_lang=normalized_source_lang,
        target_lang=normalized_target_lang,
        word_ru=word_ru,
        translation_de=translation_de,
        word_de=word_de,
        translation_ru=translation_ru,
        response_json=normalized_response_json,
    )
    with conn.cursor() as cursor:
        canonical_entry_id = None
        if source_text and target_text and normalized_source_lang and normalized_target_lang:
            # ⚠ ОТКАЗ ПУЛА НЕ РОНЯЕТ СОХРАНЕНИЕ ЧЕЛОВЕКА. Дверь пула может отказать
            # (задание тренажёра, ответ на чужом языке) — это её работа. Но карточку
            # человек сохранил себе, и она обязана лечь: побочная запись не имеет права
            # утащить за собой главную. Точка отката, потому что отказ приходит из
            # ТОЙ ЖЕ транзакции и без неё курсор остаётся в сорванном состоянии.
            # Молчания здесь нет: причина отказа уходит в лог целиком.
            cursor.execute("SAVEPOINT pool_entry;")
            try:
                canonical_entry_id = _upsert_dictionary_canonical_entry_with_cursor(
                    cursor,
                    source_lang=normalized_source_lang,
                    target_lang=normalized_target_lang,
                    source_text=source_text,
                    target_text=target_text,
                    word_ru=word_ru,
                    translation_de=translation_de,
                    word_de=word_de,
                    translation_ru=translation_ru,
                    response_json=normalized_response_json,
                )
                cursor.execute("RELEASE SAVEPOINT pool_entry;")
            except ValueError as exc:
                cursor.execute("ROLLBACK TO SAVEPOINT pool_entry;")
                cursor.execute("RELEASE SAVEPOINT pool_entry;")
                canonical_entry_id = None
                logging.warning("в общий словарь не положили: %s", exc)
        return _create_or_attach_user_dictionary_entry_with_cursor(
            cursor,
            user_id=int(user_id),
            word_ru=word_ru,
            translation_de=translation_de,
            word_de=word_de,
            translation_ru=translation_ru,
            response_json=normalized_response_json,
            folder_id=folder_id,
            source_lang=normalized_source_lang,
            target_lang=normalized_target_lang,
            canonical_entry_id=canonical_entry_id,
            origin_process=origin_process,
            origin_meta=origin_meta,
            semantic_tag=semantic_tag,
        )


def _run_rebus_rute_fix_migration(conn) -> None:
    """One-time fix: reset wrongly-generated 'Rute' component image and
    angelrute_001 composed image so pool top-up regenerates them with the
    corrected DALL-E prompts and corrected parts (Angel+Rute, not Rute+Fisch)."""
    KEY = "rebus_fix_rute_angelrute_001_20260604"
    with conn.cursor() as cur:
        cur.execute(
            "SELECT 1 FROM bt_3_schema_migrations WHERE migration_key = %s LIMIT 1",
            (KEY,),
        )
        if cur.fetchone():
            return
        cur.execute(
            """UPDATE bt_3_rebus_component_images
               SET generation_status = 'pending', image_object_key = NULL, updated_at = NOW()
               WHERE word = 'Rute'""",
        )
        cur.execute(
            """UPDATE bt_3_rebus_bank
               SET composed_status = 'pending', composed_image_object_key = NULL, updated_at = NOW()
               WHERE compound_id = 'angelrute_001'""",
        )
        cur.execute(
            "INSERT INTO bt_3_schema_migrations (migration_key) VALUES (%s) ON CONFLICT DO NOTHING",
            (KEY,),
        )
    conn.commit()


def _run_rebus_freetext_migration(conn) -> None:
    """Drop the A/B/C/D CHECK constraint on bt_3_rebus_answers.selected_option
    so we can store the user's typed word directly."""
    KEY = "rebus_answers_freetext_selected_option_20260604"
    with conn.cursor() as cur:
        cur.execute(
            "SELECT 1 FROM bt_3_schema_migrations WHERE migration_key = %s LIMIT 1",
            (KEY,),
        )
        if cur.fetchone():
            return
        # Find and drop the check constraint by name pattern
        cur.execute(
            """
            SELECT conname FROM pg_constraint
            WHERE conrelid = 'bt_3_rebus_answers'::regclass
              AND contype = 'c'
              AND conname ILIKE '%selected_option%'
            LIMIT 1
            """
        )
        row = cur.fetchone()
        if row:
            cur.execute(
                f"ALTER TABLE bt_3_rebus_answers DROP CONSTRAINT IF EXISTS {row[0]}"
            )
        cur.execute(
            "INSERT INTO bt_3_schema_migrations (migration_key) VALUES (%s) ON CONFLICT DO NOTHING",
            (KEY,),
        )
    conn.commit()


def _run_dictionary_canonical_schema_migration(conn, *, batch_size: int = 250) -> None:
    with conn.cursor() as cursor:
        cursor.execute(
            """
            SELECT 1
            FROM bt_3_schema_migrations
            WHERE migration_key = %s
            LIMIT 1;
            """,
            (DICTIONARY_CANONICAL_SCHEMA_MIGRATION_KEY,),
        )
        if cursor.fetchone():
            return

    safe_batch_size = max(50, min(int(batch_size or 250), 1000))
    while True:
        with conn.cursor() as cursor:
            cursor.execute(
                """
                SELECT
                    id,
                    user_id,
                    word_ru,
                    translation_de,
                    word_de,
                    translation_ru,
                    source_lang,
                    target_lang,
                    response_json
                FROM bt_3_webapp_dictionary_queries
                WHERE canonical_entry_id IS NULL
                ORDER BY id ASC
                LIMIT %s;
                """,
                (safe_batch_size,),
            )
            rows = cursor.fetchall() or []
        if not rows:
            break
        processed_count = 0
        for row in rows:
            entry_id = int(row[0])
            response_payload = _coerce_json_object(row[8])
            normalized_source_lang = _normalize_lang_code(row[6])
            normalized_target_lang = _normalize_lang_code(row[7])
            source_text, target_text = _resolve_dictionary_source_target_texts(
                source_lang=normalized_source_lang,
                target_lang=normalized_target_lang,
                word_ru=row[2],
                translation_de=row[3],
                word_de=row[4],
                translation_ru=row[5],
                response_json=response_payload,
            )
            if not normalized_source_lang or not normalized_target_lang or not source_text or not target_text:
                continue
            with conn.cursor() as cursor:
                canonical_entry_id = _upsert_dictionary_canonical_entry_with_cursor(
                    cursor,
                    source_lang=normalized_source_lang,
                    target_lang=normalized_target_lang,
                    source_text=source_text,
                    target_text=target_text,
                    word_ru=row[2],
                    translation_de=row[3],
                    word_de=row[4],
                    translation_ru=row[5],
                    response_json=response_payload,
                )
                cursor.execute(
                    """
                    UPDATE bt_3_webapp_dictionary_queries
                    SET canonical_entry_id = %s
                    WHERE id = %s;
                    """,
                    (int(canonical_entry_id), entry_id),
                )
            processed_count += 1
        if processed_count <= 0:
            break

    with conn.cursor() as cursor:
        cursor.execute(
            """
            WITH ranked AS (
                SELECT
                    id,
                    user_id,
                    canonical_entry_id,
                    FIRST_VALUE(id) OVER (
                        PARTITION BY user_id, canonical_entry_id
                        ORDER BY created_at DESC NULLS LAST, id DESC
                    ) AS keep_id,
                    BOOL_OR(COALESCE(is_learned, FALSE)) OVER (
                        PARTITION BY user_id, canonical_entry_id
                    ) AS any_learned,
                    FIRST_VALUE(folder_id) OVER (
                        PARTITION BY user_id, canonical_entry_id
                        ORDER BY CASE WHEN folder_id IS NULL THEN 1 ELSE 0 END, created_at DESC NULLS LAST, id DESC
                    ) AS preferred_folder_id
                FROM bt_3_webapp_dictionary_queries
                WHERE canonical_entry_id IS NOT NULL
            ),
            keep_rows AS (
                SELECT DISTINCT keep_id, any_learned, preferred_folder_id
                FROM ranked
            )
            UPDATE bt_3_webapp_dictionary_queries AS q
            SET
                is_learned = COALESCE(keep_rows.any_learned, FALSE),
                folder_id = COALESCE(q.folder_id, keep_rows.preferred_folder_id)
            FROM keep_rows
            WHERE q.id = keep_rows.keep_id;
            """
        )
        cursor.execute(
            """
            WITH ranked AS (
                SELECT
                    id,
                    FIRST_VALUE(id) OVER (
                        PARTITION BY user_id, canonical_entry_id
                        ORDER BY created_at DESC NULLS LAST, id DESC
                    ) AS keep_id
                FROM bt_3_webapp_dictionary_queries
                WHERE canonical_entry_id IS NOT NULL
            )
            DELETE FROM bt_3_webapp_dictionary_queries AS q
            USING ranked
            WHERE q.id = ranked.id
              AND ranked.id <> ranked.keep_id;
            """
        )
        cursor.execute(
            """
            CREATE UNIQUE INDEX IF NOT EXISTS uq_bt_3_webapp_dictionary_queries_user_canonical
            ON bt_3_webapp_dictionary_queries (user_id, canonical_entry_id)
            WHERE canonical_entry_id IS NOT NULL;
            """
        )
        cursor.execute(
            """
            INSERT INTO bt_3_schema_migrations (migration_key)
            VALUES (%s)
            ON CONFLICT (migration_key) DO NOTHING;
            """,
            (DICTIONARY_CANONICAL_SCHEMA_MIGRATION_KEY,),
        )


def get_translation_focus_pool_bucket_counts(
    *,
    source_lang: str,
    target_lang: str,
) -> list[dict[str, Any]]:
    normalized_source_lang = _normalize_lang_code(source_lang)
    normalized_target_lang = _normalize_lang_code(target_lang)
    with get_db_connection_context() as conn:
        with conn.cursor() as cursor:
            cursor.execute(
                """
                SELECT
                    focus_key,
                    COALESCE(NULLIF(MAX(focus_label), ''), focus_key) AS focus_label,
                    level,
                    COUNT(*)::BIGINT AS ready_count
                FROM bt_3_translation_sentence_pool
                WHERE source_lang = %s
                  AND target_lang = %s
                  AND is_active = TRUE
                GROUP BY focus_key, level
                ORDER BY focus_key, level;
                """,
                (normalized_source_lang, normalized_target_lang),
            )
            rows = cursor.fetchall() or []
    return [
        {
            "focus_key": str(row[0] or "").strip(),
            "focus_label": str(row[1] or row[0] or "").strip(),
            "level": str(row[2] or "").strip().lower(),
            "ready_count": int(row[3] or 0),
        }
        for row in rows
        if str(row[0] or "").strip() and str(row[2] or "").strip()
    ]


def upsert_translation_focus_pool_daily_snapshot(
    *,
    snapshot_date: date,
    source_lang: str,
    target_lang: str,
    rows: list[dict[str, Any]],
) -> int:
    normalized_source_lang = _normalize_lang_code(source_lang)
    normalized_target_lang = _normalize_lang_code(target_lang)
    payload_rows: list[tuple[Any, ...]] = []
    for item in list(rows or []):
        focus_key = str((item or {}).get("focus_key") or "").strip()
        level = str((item or {}).get("level") or "").strip().lower()
        if not focus_key or not level:
            continue
        payload_rows.append(
            (
                snapshot_date,
                normalized_source_lang,
                normalized_target_lang,
                focus_key,
                str((item or {}).get("focus_label") or focus_key).strip(),
                level,
                int((item or {}).get("ready_count") or 0),
                int((item or {}).get("low_watermark") or 0),
                int((item or {}).get("target_ready") or 0),
            )
        )
    if not payload_rows:
        return 0
    with get_db_connection_context() as conn:
        with conn.cursor() as cursor:
            cursor.executemany(
                """
                INSERT INTO bt_3_translation_focus_pool_daily_snapshots (
                    snapshot_date,
                    source_lang,
                    target_lang,
                    focus_key,
                    focus_label,
                    level,
                    ready_count,
                    low_watermark,
                    target_ready
                )
                VALUES (%s, %s, %s, %s, %s, %s, %s, %s, %s)
                ON CONFLICT (snapshot_date, source_lang, target_lang, focus_key, level) DO UPDATE
                SET focus_label = EXCLUDED.focus_label,
                    ready_count = EXCLUDED.ready_count,
                    low_watermark = EXCLUDED.low_watermark,
                    target_ready = EXCLUDED.target_ready,
                    recorded_at = NOW();
                """,
                payload_rows,
            )
    return len(payload_rows)


