def _reader_audio_unlimited_user_ids() -> frozenset[int]:
    raw = os.getenv("READER_AUDIO_UNLIMITED_USER_IDS", "")
    result = set()
    for part in raw.split(","):
        part = part.strip()
        if part.isdigit():
            result.add(int(part))
    return frozenset(result)

