def _skill_state_v2_classify_outcome(per_skill_outcome: str | None) -> str:
    normalized = str(per_skill_outcome or "").strip().lower()
    if normalized in {"fail_new", "fail_repeat_no_progress", "fail_repeat_progress", "untargeted_error_fail", "catastrophic_fail_fallback"}:
        return "fail"
    if normalized in {"recovered_partial", "recovered_final"}:
        return "recovery"
    if normalized in {"clean_success", "clean_progress_credit"}:
        return "success"
    return "neutral"


def _compute_skill_state_v2_confidence(tested_events: int) -> float:
    safe_tested_events = max(0, int(tested_events or 0))
    return max(0.0, min(1.0, 1.0 - math.exp(-float(safe_tested_events) / SKILL_STATE_V2_CONFIDENCE_SPREAD)))


def _compute_skill_state_v2_mastery(net_evidence_recent: float, net_evidence_lifetime: float) -> float:
    mastery = (
        50.0
        + SKILL_STATE_V2_MASTERY_RECENT_WEIGHT
        * math.tanh(float(net_evidence_recent or 0.0) / SKILL_STATE_V2_MASTERY_RECENT_SPREAD)
        + SKILL_STATE_V2_MASTERY_LIFETIME_WEIGHT
        * math.tanh(float(net_evidence_lifetime or 0.0) / SKILL_STATE_V2_MASTERY_LIFETIME_SPREAD)
    )
    return max(5.0, min(99.0, float(mastery)))


def _get_skill_state_v2_snapshot_since_date(
    *,
    user_id: int,
    source_lang: str,
    target_lang: str,
    reset_date: date | None,
    include_debug_meta: bool = False,
) -> dict[str, dict[str, Any]] | tuple[dict[str, dict[str, Any]], dict[str, Any]]:
    if reset_date is None:
        empty_state: dict[str, dict[str, Any]] = {}
        if include_debug_meta:
            return empty_state, {
                "query_count": 0,
                "query_rows_count": 0,
                "query_duration_ms": 0,
                "aggregation_duration_ms": 0,
                "python_under_checkout_ms": 0,
                "checkout_spans_cpu_work": False,
                "checkout_spans_aggregation": False,
                "checkout_spans_serialization": False,
            }
        return empty_state
    normalized_source = str(source_lang or "ru").strip().lower() or "ru"
    normalized_target = str(target_lang or "de").strip().lower() or "de"
    start_dt = datetime.combine(reset_date, dt_time.min, tzinfo=timezone.utc)
    query_started_perf = time.perf_counter()
    with get_db_connection_context() as conn:
        with conn.cursor() as cursor:
            cursor.execute(
                """
                SELECT
                    skill_id,
                    created_at,
                    is_tested,
                    per_skill_outcome,
                    shadow_delta_signal
                FROM bt_3_skill_events_v2
                WHERE user_id = %s
                  AND source_lang = %s
                  AND target_lang = %s
                  AND created_at >= %s
                ORDER BY skill_id ASC, created_at ASC, id ASC;
                """,
                (int(user_id), normalized_source, normalized_target, start_dt),
            )
            rows = cursor.fetchall() or []
    query_duration_ms = int((time.perf_counter() - query_started_perf) * 1000)

    state_map: dict[str, dict[str, Any]] = {}
    tau_seconds = SKILL_STATE_V2_RECENT_TAU_DAYS * 24.0 * 60.0 * 60.0
    aggregation_started_perf = time.perf_counter()
    for row in rows:
        skill_id = str(row[0] or "").strip()
        if not skill_id:
            continue
        event_created_at = row[1] or start_dt
        is_tested = bool(row[2])
        per_skill_outcome = row[3]
        shadow_delta_signal = float(row[4] or 0.0)
        current = state_map.setdefault(
            skill_id,
            {
                "mastery": 50.0,
                "confidence": 0.0,
                "net_evidence_recent": 0.0,
                "net_evidence_lifetime": 0.0,
                "tested_events": 0,
                "total_events": 0,
                "last_practiced_at": None,
                "last_event_at": None,
            },
        )
        last_event_at = current.get("last_event_at")
        if isinstance(last_event_at, datetime):
            delta_seconds = max(0.0, float((event_created_at - last_event_at).total_seconds()))
            if tau_seconds > 0:
                current["net_evidence_recent"] *= math.exp(-delta_seconds / tau_seconds)
        current["net_evidence_recent"] += shadow_delta_signal
        current["net_evidence_lifetime"] += shadow_delta_signal
        current["total_events"] = int(current.get("total_events") or 0) + 1
        if is_tested:
            current["tested_events"] = int(current.get("tested_events") or 0) + 1
        current["confidence"] = _compute_skill_state_v2_confidence(int(current.get("tested_events") or 0))
        current["mastery"] = _compute_skill_state_v2_mastery(
            float(current.get("net_evidence_recent") or 0.0),
            float(current.get("net_evidence_lifetime") or 0.0),
        )
        current["last_event_at"] = event_created_at
        current["last_practiced_at"] = event_created_at
        current["outcome_bucket"] = _skill_state_v2_classify_outcome(per_skill_outcome)

    for item in state_map.values():
        item.pop("last_event_at", None)
        last_practiced_at = item.get("last_practiced_at")
        if isinstance(last_practiced_at, datetime):
            item["last_practiced_at"] = last_practiced_at.isoformat()
        else:
            item["last_practiced_at"] = None
    if include_debug_meta:
        return state_map, {
            "query_count": 1,
            "query_rows_count": len(rows),
            "query_duration_ms": query_duration_ms,
            "aggregation_duration_ms": int((time.perf_counter() - aggregation_started_perf) * 1000),
            "python_under_checkout_ms": 0,
            "checkout_spans_cpu_work": False,
            "checkout_spans_aggregation": False,
            "checkout_spans_serialization": False,
        }
    return state_map


def _list_prorated_weekly_goals(
    *,
    user_id: int,
    source_lang: str,
    target_lang: str,
    start_date: date,
    end_date: date,
) -> dict[str, int]:
    normalized_source = str(source_lang or "ru").strip().lower() or "ru"
    normalized_target = str(target_lang or "de").strip().lower() or "de"
    totals = {
        "translations_goal": 0.0,
        "learned_words_goal": 0.0,
        "agent_minutes_goal": 0.0,
        "reading_minutes_goal": 0.0,
    }
    if end_date < start_date:
        return {key: 0 for key in totals}
    with get_db_connection_context() as conn:
        with conn.cursor() as cursor:
            cursor.execute(
                """
                SELECT
                    week_start,
                    translations_goal,
                    learned_words_goal,
                    agent_minutes_goal,
                    reading_minutes_goal
                FROM bt_3_weekly_goals
                WHERE user_id = %s
                  AND source_lang = %s
                  AND target_lang = %s
                  AND week_start <= %s
                  AND (week_start + INTERVAL '6 days')::date >= %s;
                """,
                (int(user_id), normalized_source, normalized_target, end_date, start_date),
            )
            rows = cursor.fetchall() or []
    for row in rows:
        week_start = row[0]
        if not isinstance(week_start, date):
            continue
        week_end = week_start + timedelta(days=6)
        overlap_start = max(start_date, week_start)
        overlap_end = min(end_date, week_end)
        if overlap_end < overlap_start:
            continue
        overlap_days = (overlap_end - overlap_start).days + 1
        ratio = max(0.0, min(1.0, overlap_days / 7.0))
        totals["translations_goal"] += float(row[1] or 0) * ratio
        totals["learned_words_goal"] += float(row[2] or 0) * ratio
        totals["agent_minutes_goal"] += float(row[3] or 0) * ratio
        totals["reading_minutes_goal"] += float(row[4] or 0) * ratio
    return {key: max(0, int(round(value))) for key, value in totals.items()}


def claim_skill_state_v2_dirty_keys(*, limit: int, lease_owner: str, lease_seconds: int) -> list[dict]:
    safe_limit = max(1, min(int(limit or 1), 500))
    safe_lease_owner = str(lease_owner or "").strip()[:64] or f"skill-v2-{uuid4().hex[:12]}"
    safe_lease_seconds = max(5, int(lease_seconds or 30))
    with get_db_connection_context() as conn:
        with conn.cursor() as cursor:
            cursor.execute(
                """
                WITH candidates AS (
                    SELECT user_id, skill_id, source_lang, target_lang
                    FROM bt_3_skill_state_v2_dirty
                    WHERE next_attempt_at <= NOW()
                      AND (lease_expires_at IS NULL OR lease_expires_at <= NOW())
                    ORDER BY updated_at ASC
                    LIMIT %s
                    FOR UPDATE SKIP LOCKED
                )
                UPDATE bt_3_skill_state_v2_dirty AS dirty
                SET
                    lease_owner = %s,
                    lease_expires_at = NOW() + (%s * INTERVAL '1 second'),
                    updated_at = NOW()
                FROM candidates
                WHERE dirty.user_id = candidates.user_id
                  AND dirty.skill_id = candidates.skill_id
                  AND dirty.source_lang = candidates.source_lang
                  AND dirty.target_lang = candidates.target_lang
                RETURNING
                    dirty.user_id,
                    dirty.skill_id,
                    dirty.source_lang,
                    dirty.target_lang,
                    dirty.max_event_id,
                    dirty.retry_count,
                    dirty.enqueue_count,
                    dirty.first_enqueued_at,
                    dirty.updated_at;
                """,
                (safe_limit, safe_lease_owner, safe_lease_seconds),
            )
            rows = cursor.fetchall() or []
    return [
        {
            "user_id": int(row[0]),
            "skill_id": str(row[1]),
            "source_lang": str(row[2] or "ru"),
            "target_lang": str(row[3] or "de"),
            "max_event_id": int(row[4] or 0),
            "retry_count": int(row[5] or 0),
            "enqueue_count": int(row[6] or 0),
            "first_enqueued_at": row[7].isoformat() if row[7] else None,
            "updated_at": row[8].isoformat() if row[8] else None,
        }
        for row in rows
    ]


def process_skill_state_v2_dirty_key(
    *,
    user_id: int,
    skill_id: str,
    source_lang: str,
    target_lang: str,
    claimed_max_event_id: int,
    lease_owner: str,
) -> dict:
    safe_user_id = int(user_id)
    safe_skill_id = str(skill_id or "").strip()
    safe_source_lang = str(source_lang or "ru")
    safe_target_lang = str(target_lang or "de")
    safe_claimed_max_event_id = max(0, int(claimed_max_event_id or 0))
    safe_lease_owner = str(lease_owner or "").strip()[:64]
    try:
        with get_db_connection_context() as conn:
            with conn.cursor() as cursor:
                cursor.execute(
                    """
                    SELECT
                        mastery,
                        confidence,
                        net_evidence_recent,
                        net_evidence_lifetime,
                        tested_events,
                        fail_events,
                        success_events,
                        recovery_events,
                        last_event_id,
                        last_event_at
                    FROM bt_3_user_skill_state_v2
                    WHERE user_id = %s
                      AND skill_id = %s
                      AND source_lang = %s
                      AND target_lang = %s
                    FOR UPDATE;
                    """,
                    (safe_user_id, safe_skill_id, safe_source_lang, safe_target_lang),
                )
                state_row = cursor.fetchone()
                mastery = float(state_row[0]) if state_row else 50.0
                confidence = float(state_row[1]) if state_row else 0.0
                net_recent = float(state_row[2]) if state_row else 0.0
                net_lifetime = float(state_row[3]) if state_row else 0.0
                tested_events = int(state_row[4]) if state_row else 0
                fail_events = int(state_row[5]) if state_row else 0
                success_events = int(state_row[6]) if state_row else 0
                recovery_events = int(state_row[7]) if state_row else 0
                last_event_id = int(state_row[8]) if state_row and state_row[8] is not None else 0
                last_event_at = state_row[9] if state_row else None

                cursor.execute(
                    """
                    SELECT
                        id,
                        created_at,
                        is_tested,
                        per_skill_outcome,
                        shadow_delta_signal
                    FROM bt_3_skill_events_v2
                    WHERE user_id = %s
                      AND skill_id = %s
                      AND source_lang = %s
                      AND target_lang = %s
                      AND id > %s
                      AND id <= %s
                    ORDER BY id ASC;
                    """,
                    (
                        safe_user_id,
                        safe_skill_id,
                        safe_source_lang,
                        safe_target_lang,
                        last_event_id,
                        safe_claimed_max_event_id,
                    ),
                )
                event_rows = cursor.fetchall() or []
                if event_rows:
                    for event_id, created_at, is_tested, per_skill_outcome, shadow_delta_signal in event_rows:
                        event_created_at = created_at or datetime.now(timezone.utc)
                        if last_event_at is not None:
                            delta_seconds = max(
                                0.0,
                                float((event_created_at - last_event_at).total_seconds()),
                            )
                            tau_seconds = SKILL_STATE_V2_RECENT_TAU_DAYS * 24.0 * 60.0 * 60.0
                            if tau_seconds > 0:
                                net_recent *= math.exp(-delta_seconds / tau_seconds)
                        delta_value = float(shadow_delta_signal or 0.0)
                        net_recent += delta_value
                        net_lifetime += delta_value
                        if bool(is_tested):
                            tested_events += 1
                        outcome_bucket = _skill_state_v2_classify_outcome(per_skill_outcome)
                        if outcome_bucket == "fail":
                            fail_events += 1
                        elif outcome_bucket == "success":
                            success_events += 1
                        elif outcome_bucket == "recovery":
                            recovery_events += 1
                        last_event_id = int(event_id or last_event_id)
                        last_event_at = event_created_at

                    confidence = _compute_skill_state_v2_confidence(tested_events)
                    mastery = _compute_skill_state_v2_mastery(net_recent, net_lifetime)
                    cursor.execute(
                        """
                        INSERT INTO bt_3_user_skill_state_v2 (
                            user_id,
                            skill_id,
                            source_lang,
                            target_lang,
                            mastery,
                            confidence,
                            net_evidence_recent,
                            net_evidence_lifetime,
                            tested_events,
                            fail_events,
                            success_events,
                            recovery_events,
                            last_event_id,
                            last_event_at,
                            updated_at
                        )
                        VALUES (%s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s, NOW())
                        ON CONFLICT (user_id, skill_id, source_lang, target_lang) DO UPDATE
                        SET
                            mastery = EXCLUDED.mastery,
                            confidence = EXCLUDED.confidence,
                            net_evidence_recent = EXCLUDED.net_evidence_recent,
                            net_evidence_lifetime = EXCLUDED.net_evidence_lifetime,
                            tested_events = EXCLUDED.tested_events,
                            fail_events = EXCLUDED.fail_events,
                            success_events = EXCLUDED.success_events,
                            recovery_events = EXCLUDED.recovery_events,
                            last_event_id = EXCLUDED.last_event_id,
                            last_event_at = EXCLUDED.last_event_at,
                            updated_at = NOW();
                        """,
                        (
                            safe_user_id,
                            safe_skill_id,
                            safe_source_lang,
                            safe_target_lang,
                            mastery,
                            confidence,
                            net_recent,
                            net_lifetime,
                            tested_events,
                            fail_events,
                            success_events,
                            recovery_events,
                            last_event_id if last_event_id > 0 else None,
                            last_event_at,
                        ),
                    )

                cursor.execute(
                    """
                    DELETE FROM bt_3_skill_state_v2_dirty
                    WHERE user_id = %s
                      AND skill_id = %s
                      AND source_lang = %s
                      AND target_lang = %s
                      AND lease_owner = %s
                      AND max_event_id <= %s;
                    """,
                    (
                        safe_user_id,
                        safe_skill_id,
                        safe_source_lang,
                        safe_target_lang,
                        safe_lease_owner,
                        last_event_id,
                    ),
                )
                deleted_dirty_row = int(cursor.rowcount or 0) > 0
                if not deleted_dirty_row:
                    cursor.execute(
                        """
                        UPDATE bt_3_skill_state_v2_dirty
                        SET
                            lease_owner = NULL,
                            lease_expires_at = NULL,
                            retry_count = 0,
                            next_attempt_at = NOW(),
                            last_error = NULL,
                            updated_at = NOW()
                        WHERE user_id = %s
                          AND skill_id = %s
                          AND source_lang = %s
                          AND target_lang = %s
                          AND lease_owner = %s;
                        """,
                        (safe_user_id, safe_skill_id, safe_source_lang, safe_target_lang, safe_lease_owner),
                    )

        return {
            "ok": True,
            "user_id": safe_user_id,
            "skill_id": safe_skill_id,
            "source_lang": safe_source_lang,
            "target_lang": safe_target_lang,
            "processed_events": len(event_rows),
            "last_event_id": int(last_event_id or 0),
            "dirty_row_deleted": bool(deleted_dirty_row),
            "mastery": float(mastery),
            "confidence": float(confidence),
        }
    except Exception as exc:
        with get_db_connection_context() as conn:
            with conn.cursor() as cursor:
                cursor.execute(
                    """
                    UPDATE bt_3_skill_state_v2_dirty
                    SET
                        lease_owner = NULL,
                        lease_expires_at = NULL,
                        retry_count = retry_count + 1,
                        next_attempt_at = NOW() + (LEAST(300, 5 * CAST(POWER(2, LEAST(retry_count + 1, 5)) AS INT)) * INTERVAL '1 second'),
                        last_error = %s,
                        updated_at = NOW()
                    WHERE user_id = %s
                      AND skill_id = %s
                      AND source_lang = %s
                      AND target_lang = %s
                      AND lease_owner = %s;
                    """,
                    (
                        str(exc)[:500],
                        safe_user_id,
                        safe_skill_id,
                        safe_source_lang,
                        safe_target_lang,
                        safe_lease_owner,
                    ),
                )
        return {
            "ok": False,
            "user_id": safe_user_id,
            "skill_id": safe_skill_id,
            "source_lang": safe_source_lang,
            "target_lang": safe_target_lang,
            "processed_events": 0,
            "error": str(exc),
        }


def get_skill_state_v2_dirty_summary() -> dict[str, Any]:
    with get_db_connection_context() as conn:
        with conn.cursor() as cursor:
            cursor.execute(
                """
                SELECT
                    COUNT(*) AS dirty_count,
                    COUNT(*) FILTER (
                        WHERE lease_expires_at IS NOT NULL
                          AND lease_expires_at > NOW()
                    ) AS leased_count,
                    COALESCE(SUM(retry_count), 0) AS retry_count_total,
                    COALESCE(MAX(retry_count), 0) AS retry_count_max,
                    MIN(first_enqueued_at) AS oldest_dirty_at
                FROM bt_3_skill_state_v2_dirty;
                """
            )
            row = cursor.fetchone() or (0, 0, 0, 0, None)
    oldest_dirty_at = row[4]
    oldest_dirty_age_seconds = None
    if oldest_dirty_at:
        oldest_dirty_age_seconds = max(
            0,
            int((datetime.now(timezone.utc) - oldest_dirty_at).total_seconds()),
        )
    return {
        "dirty_count": int(row[0] or 0),
        "leased_count": int(row[1] or 0),
        "retry_count_total": int(row[2] or 0),
        "retry_count_max": int(row[3] or 0),
        "oldest_dirty_at": oldest_dirty_at.isoformat() if oldest_dirty_at else None,
        "oldest_dirty_age_seconds": oldest_dirty_age_seconds,
    }


def record_skill_state_v2_worker_run(
    *,
    worker_name: str,
    keys_processed: int,
    events_processed: int,
    duration_ms: int,
    error: str | None = None,
) -> None:
    safe_worker_name = str(worker_name or "").strip()[:128] or "skill-state-v2-aggregator"
    safe_keys_processed = max(0, int(keys_processed or 0))
    safe_events_processed = max(0, int(events_processed or 0))
    safe_duration_ms = max(0, int(duration_ms or 0))
    safe_error = str(error or "").strip()[:2000] or None
    with get_db_connection_context() as conn:
        with conn.cursor() as cursor:
            cursor.execute(
                """
                INSERT INTO bt_3_skill_state_v2_worker_stats (
                    worker_name,
                    runs_total,
                    keys_processed_total,
                    events_processed_total,
                    last_run_at,
                    last_success_at,
                    last_duration_ms,
                    last_keys_processed,
                    last_events_processed,
                    last_error,
                    errors_total,
                    updated_at
                )
                VALUES (
                    %s,
                    1,
                    %s,
                    %s,
                    NOW(),
                    CASE WHEN %s IS NULL AND %s > 0 THEN NOW() ELSE NULL END,
                    %s,
                    %s,
                    %s,
                    %s,
                    CASE WHEN %s IS NULL THEN 0 ELSE 1 END,
                    NOW()
                )
                ON CONFLICT (worker_name) DO UPDATE
                SET
                    runs_total = bt_3_skill_state_v2_worker_stats.runs_total + 1,
                    keys_processed_total = bt_3_skill_state_v2_worker_stats.keys_processed_total + EXCLUDED.keys_processed_total,
                    events_processed_total = bt_3_skill_state_v2_worker_stats.events_processed_total + EXCLUDED.events_processed_total,
                    last_run_at = NOW(),
                    last_success_at = CASE
                        WHEN EXCLUDED.last_success_at IS NOT NULL THEN EXCLUDED.last_success_at
                        ELSE bt_3_skill_state_v2_worker_stats.last_success_at
                    END,
                    last_duration_ms = EXCLUDED.last_duration_ms,
                    last_keys_processed = EXCLUDED.last_keys_processed,
                    last_events_processed = EXCLUDED.last_events_processed,
                    last_error = EXCLUDED.last_error,
                    errors_total = bt_3_skill_state_v2_worker_stats.errors_total + CASE WHEN EXCLUDED.last_error IS NULL THEN 0 ELSE 1 END,
                    updated_at = NOW();
                """,
                (
                    safe_worker_name,
                    safe_keys_processed,
                    safe_events_processed,
                    safe_error,
                    safe_keys_processed,
                    safe_duration_ms,
                    safe_keys_processed,
                    safe_events_processed,
                    safe_error,
                    safe_error,
                ),
            )


def get_skill_state_v2_worker_summary() -> dict[str, Any]:
    with get_db_connection_context() as conn:
        with conn.cursor() as cursor:
            cursor.execute(
                """
                WITH aggregated AS (
                    SELECT
                        COUNT(*) AS worker_rows,
                        COALESCE(SUM(runs_total), 0) AS runs_total,
                        COALESCE(SUM(keys_processed_total), 0) AS keys_processed_total,
                        COALESCE(SUM(events_processed_total), 0) AS events_processed_total,
                        MAX(last_run_at) AS last_run_at,
                        MAX(last_success_at) AS last_success_at,
                        COALESCE(SUM(errors_total), 0) AS errors_total,
                        MAX(updated_at) AS updated_at
                    FROM bt_3_skill_state_v2_worker_stats
                ),
                latest AS (
                    SELECT
                        last_duration_ms,
                        last_keys_processed,
                        last_events_processed,
                        last_error
                    FROM bt_3_skill_state_v2_worker_stats
                    ORDER BY updated_at DESC, worker_name ASC
                    LIMIT 1
                )
                SELECT
                    aggregated.worker_rows,
                    aggregated.runs_total,
                    aggregated.keys_processed_total,
                    aggregated.events_processed_total,
                    aggregated.last_run_at,
                    aggregated.last_success_at,
                    aggregated.errors_total,
                    aggregated.updated_at,
                    COALESCE(latest.last_duration_ms, 0) AS last_duration_ms,
                    COALESCE(latest.last_keys_processed, 0) AS last_keys_processed,
                    COALESCE(latest.last_events_processed, 0) AS last_events_processed,
                    latest.last_error
                FROM aggregated
                LEFT JOIN latest ON TRUE;
                """
            )
            row = cursor.fetchone() or (0, 0, 0, 0, None, None, 0, None, 0, 0, 0, None)
    return {
        "worker_rows": int(row[0] or 0),
        "runs_total": int(row[1] or 0),
        "keys_processed_total": int(row[2] or 0),
        "events_processed_total": int(row[3] or 0),
        "last_run_at": row[4].isoformat() if row[4] else None,
        "last_success_at": row[5].isoformat() if row[5] else None,
        "errors_total": int(row[6] or 0),
        "updated_at": row[7].isoformat() if row[7] else None,
        "last_duration_ms": int(row[8] or 0),
        "last_keys_processed": int(row[9] or 0),
        "last_events_processed": int(row[10] or 0),
        "last_error": str(row[11]).strip() if row[11] is not None and str(row[11]).strip() else None,
    }


def get_skill_state_v2_comparison(
    *,
    user_id: int,
    source_lang: str = "ru",
    target_lang: str = "de",
    limit: int = 20,
) -> list[dict[str, Any]]:
    safe_limit = max(1, min(int(limit or 20), 200))
    with get_db_connection_context() as conn:
        with conn.cursor() as cursor:
            cursor.execute(
                """
                WITH compared AS (
                    SELECT
                        COALESCE(v2.skill_id, v1.skill_id) AS skill_id,
                        v1.mastery AS v1_mastery,
                        v2.mastery AS v2_mastery,
                        v2.confidence,
                        v2.net_evidence_recent,
                        v2.net_evidence_lifetime,
                        v2.tested_events,
                        v2.fail_events,
                        v2.success_events,
                        v2.recovery_events,
                        v2.last_event_id,
                        v2.last_event_at,
                        v2.updated_at
                    FROM bt_3_user_skill_state_v2 v2
                    FULL OUTER JOIN bt_3_user_skill_state v1
                      ON v1.user_id = v2.user_id
                     AND v1.skill_id = v2.skill_id
                     AND v1.source_lang = v2.source_lang
                     AND v1.target_lang = v2.target_lang
                    WHERE COALESCE(v2.user_id, v1.user_id) = %s
                      AND COALESCE(v2.source_lang, v1.source_lang) = %s
                      AND COALESCE(v2.target_lang, v1.target_lang) = %s
                )
                SELECT
                    compared.skill_id,
                    COALESCE(sk.title, compared.skill_id) AS skill_title,
                    compared.v1_mastery,
                    compared.v2_mastery,
                    compared.confidence,
                    compared.net_evidence_recent,
                    compared.net_evidence_lifetime,
                    compared.tested_events,
                    compared.fail_events,
                    compared.success_events,
                    compared.recovery_events,
                    compared.last_event_id,
                    compared.last_event_at,
                    compared.updated_at
                FROM compared
                LEFT JOIN bt_3_skills sk
                  ON sk.skill_id = compared.skill_id
                ORDER BY
                    COALESCE(compared.v2_mastery, compared.v1_mastery, 999.0) ASC,
                    compared.skill_id ASC
                LIMIT %s;
                """,
                (int(user_id), source_lang or "ru", target_lang or "de", safe_limit),
            )
            rows = cursor.fetchall() or []
    results: list[dict[str, Any]] = []
    for row in rows:
        results.append(
            {
                "skill_id": str(row[0]),
                "skill_title": str(row[1] or row[0]),
                "v1_mastery": float(row[2]) if row[2] is not None else None,
                "v2_mastery": float(row[3]) if row[3] is not None else None,
                "confidence": float(row[4]) if row[4] is not None else None,
                "net_evidence_recent": float(row[5]) if row[5] is not None else None,
                "net_evidence_lifetime": float(row[6]) if row[6] is not None else None,
                "tested_events": int(row[7] or 0),
                "fail_events": int(row[8] or 0),
                "success_events": int(row[9] or 0),
                "recovery_events": int(row[10] or 0),
                "last_event_id": int(row[11]) if row[11] is not None else None,
                "last_event_at": row[12].isoformat() if row[12] else None,
                "updated_at": row[13].isoformat() if row[13] else None,
            }
        )
    return results


_ADMIN_IDS_KV_KEY = "bot_admin_telegram_ids"
_ADMIN_IDS_CACHE: set[int] | None = None  # process-lifetime cache (admins ~never change)


def _parse_admin_ids_csv(merged: str) -> set[int]:
    result: set[int] = set()
    for token in str(merged or "").replace(";", ",").split(","):
        value = token.strip()
        if not value:
            continue
        try:
            result.add(int(value))
        except ValueError:
            continue
    return result


def get_admin_telegram_ids() -> set[int]:
    """Admin Telegram IDs from env, with a durable DB fallback.

    Root cause of the recurring "Доступ к боту закрыт" lockout: admin detection
    used ONLY the env var, so a process that didn't see BOT_ADMIN_TELEGRAM_IDS
    (e.g. right after a redeploy) treated the admin as a normal — denied — user.
    Now: when the env is present we cache it AND persist it to bt_3_admin_kv;
    when the env is missing we fall back to that stored value (cached in-process,
    so the hot path stays O(1) with no per-call DB read)."""
    global _ADMIN_IDS_CACHE
    merged = ",".join(v for v in (
        os.getenv("BOT_ADMIN_TELEGRAM_IDS"),
        os.getenv("TELEGRAM_ADMIN_IDS"),
        os.getenv("BOT_ADMIN_TELEGRAM_ID"),
        os.getenv("TELEGRAM_ADMIN_ID"),
    ) if v)
    if merged:
        ids = _parse_admin_ids_csv(merged)
        if ids:
            if _ADMIN_IDS_CACHE != ids:
                _ADMIN_IDS_CACHE = set(ids)
                try:
                    admin_kv_set(_ADMIN_IDS_KV_KEY, ",".join(str(i) for i in sorted(ids)))
                except Exception:
                    logging.debug("persist admin ids to kv failed", exc_info=True)
            return set(_ADMIN_IDS_CACHE)
    if _ADMIN_IDS_CACHE:
        return set(_ADMIN_IDS_CACHE)
    try:
        stored = admin_kv_get(_ADMIN_IDS_KV_KEY)
    except Exception:
        stored = None
    _ADMIN_IDS_CACHE = _parse_admin_ids_csv(stored or "")
    return set(_ADMIN_IDS_CACHE)


# In-memory TTL cache for the Telegram allow-list lookup.
# enforce_user_access runs is_telegram_user_allowed on every update (group=-2,
# block=True). Without a cache that was an uncached, event-loop-blocking DB query
# per non-admin update. The allow-list changes rarely (manual admin grant/revoke),
# so the per-user cache turns the hot path into an O(1) memory hit.
#
# All mutators of bt_3_allowed_users run in the single bot process and explicitly
# invalidate this cache: allow_telegram_user(), revoke_telegram_user(), and
# purge_telegram_user_personal_data(). Because invalidation is complete, the TTL
# is only a bounded safety-net against any future un-invalidated drift (e.g. a new
# mutation path or a second writer process), so it can be long. Default 24h; set
# TELEGRAM_ALLOWED_USER_CACHE_TTL_SEC=0 to disable the cache entirely.
# Admins are NOT cached here (they short-circuit before the DB in both entry points).
TELEGRAM_ALLOWED_USER_CACHE_TTL_SEC = max(
    0, int(os.getenv("TELEGRAM_ALLOWED_USER_CACHE_TTL_SEC", "86400"))
)
# DENIED results are cached only briefly: if a user is granted access out of
# this process (added straight in the DB, or by another worker), a stale "denied"
# must NOT lock them out for the full positive TTL (was up to 24h). 60s self-heal.
TELEGRAM_ALLOWED_USER_NEG_CACHE_TTL_SEC = max(
    0, min(TELEGRAM_ALLOWED_USER_CACHE_TTL_SEC,
           int(os.getenv("TELEGRAM_ALLOWED_USER_NEG_CACHE_TTL_SEC", "60")))
)
_ALLOWED_USER_CACHE_LOCK = threading.Lock()
_ALLOWED_USER_CACHE: dict[int, tuple[float, bool]] = {}


def _allowed_user_cache_get(user_id: int) -> bool | None:
    """Return cached allow-decision for a non-admin user, or None on miss/expiry."""
    if TELEGRAM_ALLOWED_USER_CACHE_TTL_SEC <= 0:
        return None
    now = time.monotonic()
    with _ALLOWED_USER_CACHE_LOCK:
        entry = _ALLOWED_USER_CACHE.get(int(user_id))
        if entry is None:
            return None
        expiry, allowed = entry
        if expiry < now:
            _ALLOWED_USER_CACHE.pop(int(user_id), None)
            return None
        return allowed


def _allowed_user_cache_put(user_id: int, allowed: bool) -> None:
    if TELEGRAM_ALLOWED_USER_CACHE_TTL_SEC <= 0:
        return
    # Allowed → cache for the full (long) TTL; denied → only the short TTL so a
    # freshly granted user is never locked out beyond a minute.
    ttl = TELEGRAM_ALLOWED_USER_CACHE_TTL_SEC if allowed else TELEGRAM_ALLOWED_USER_NEG_CACHE_TTL_SEC
    if ttl <= 0:
        return
    with _ALLOWED_USER_CACHE_LOCK:
        _ALLOWED_USER_CACHE[int(user_id)] = (time.monotonic() + ttl, bool(allowed))


def invalidate_telegram_user_allowed_cache(user_id: int | None = None) -> None:
    """Drop one (or all) cached allow-decisions. Called on grant/revoke so a
    change in access never lingers beyond the next lookup."""
    with _ALLOWED_USER_CACHE_LOCK:
        if user_id is None:
            _ALLOWED_USER_CACHE.clear()
        else:
            _ALLOWED_USER_CACHE.pop(int(user_id), None)


CACHE_INVALIDATION_FEED_KEY = "webapp:cache:invalidations"
CACHE_INVALIDATION_FEED_RETENTION_SEC = max(
    60, min(3600, int(os.getenv("CACHE_INVALIDATION_FEED_RETENTION_SEC", "600") or "600"))
)


def publish_cache_invalidation(kind: str, user_id: int) -> None:
    """Announce «this user's cached decision is stale» to every OTHER process.

    Deleting a shared Redis key is not enough: each web worker also keeps the decision in
    its own memory for up to its TTL, and a delete performed by the bot process cannot
    reach that memory. Workers read this feed on a timer (see the reader in the web tier),
    so the fix propagates without any process paying a Redis call per request.

    Best-effort by design: no Redis, or a failed write, simply means the old TTL-bounded
    behaviour — never an error on the caller's path.
    """
    try:
        from backend.job_queue import get_redis_client
        client = get_redis_client()
        if client is None:
            return
        now = time.time()
        # Unique member per event: a plain "kind:uid" would be de-duplicated by ZADD and a
        # later invalidation would silently keep the FIRST timestamp, so a reader that has
        # already passed that point would never see the new event. The random suffix is not
        # decoration — a timestamp alone collides when two events land in the same
        # millisecond (e.g. a payment webhook and a manual grant), and the second one would
        # then vanish exactly when it matters most.
        member = f"{str(kind or 'unknown').strip()}:{int(user_id)}:{now:.3f}:{uuid4().hex[:8]}"
        client.zadd(CACHE_INVALIDATION_FEED_KEY, {member: now})
        client.zremrangebyscore(
            CACHE_INVALIDATION_FEED_KEY, 0, now - CACHE_INVALIDATION_FEED_RETENTION_SEC
        )
    except Exception:
        logging.debug("publish cache invalidation failed kind=%s uid=%s", kind, user_id, exc_info=True)


def _invalidate_webapp_allowlist_redis(user_id: int) -> None:
    """Delete the shared Redis webapp-allowlist cache key so the web tier
    re-evaluates this user immediately after an allow/revoke (its hot-path cache
    then refills from the DB). Key format mirrors backend_server._allowlist_redis_key."""
    try:
        from backend.job_queue import get_redis_client
        client = get_redis_client()
        if client is not None:
            client.delete(f"webapp:allowlist:{int(user_id)}")
    except Exception:
        logging.debug("invalidate webapp allowlist redis failed uid=%s", user_id, exc_info=True)
    # Shared key is gone; now tell the web workers to drop their in-memory copy too —
    # otherwise a /deny stays invisible to a warm worker for the full positive TTL.
    publish_cache_invalidation("allowlist", int(user_id))


def is_telegram_user_allowed(user_id: int) -> bool:
    if not user_id:
        return False
    if int(user_id) in get_admin_telegram_ids():
        return True

    cached = _allowed_user_cache_get(int(user_id))
    if cached is not None:
        return cached

    with get_db_connection_context() as conn:
        with conn.cursor() as cursor:
            cursor.execute(
                "SELECT 1 FROM bt_3_allowed_users WHERE user_id = %s LIMIT 1;",
                (int(user_id),),
            )
            allowed = cursor.fetchone() is not None
    _allowed_user_cache_put(int(user_id), allowed)
    return allowed


async def is_telegram_user_allowed_async(user_id: int) -> bool:
    """Event-loop-safe allow check for the per-update hot path.

    A fresh in-memory cache hit (or admin short-circuit) returns without touching
    the database or a worker thread. On a cache miss the blocking DB lookup runs
    via ``asyncio.to_thread`` so it never blocks the event loop. Decision and
    caching semantics are identical to is_telegram_user_allowed().
    """
    uid = int(user_id) if user_id else 0
    if not uid:
        return False
    if uid in get_admin_telegram_ids():
        return True
    cached = _allowed_user_cache_get(uid)
    if cached is not None:
        return cached
    return await asyncio.to_thread(is_telegram_user_allowed, uid)


def allow_telegram_user(
    user_id: int,
    username: str | None = None,
    added_by: int | None = None,
    note: str | None = None,
) -> None:
    with get_db_connection_context() as conn:
        with conn.cursor() as cursor:
            cursor.execute(
                """
                INSERT INTO bt_3_allowed_users (user_id, username, added_by, note)
                VALUES (%s, %s, %s, %s)
                ON CONFLICT (user_id)
                DO UPDATE SET
                    username = COALESCE(EXCLUDED.username, bt_3_allowed_users.username),
                    added_by = EXCLUDED.added_by,
                    note = COALESCE(EXCLUDED.note, bt_3_allowed_users.note),
                    updated_at = CURRENT_TIMESTAMP;
                """,
                (int(user_id), username, added_by, note),
            )
    # Access just changed — drop any stale cached decision for this user, in this
    # process AND in the shared Redis cache the web tier reads (else a just-approved
    # user stays denied until the long cache TTL expires).
    invalidate_telegram_user_allowed_cache(int(user_id))
    _invalidate_webapp_allowlist_redis(int(user_id))


AUTO_ACCESS_NOTE_PREFIX = "self-serve access"


def is_access_denied_for_user(user_id: int) -> bool:
    """True when an admin explicitly closed the door for this user.

    Self-serve access opens the app to anyone who follows an invite, so «denied»
    has to be remembered somewhere — otherwise a /deny is undone by the user's very
    next /start. Two independent traces count, because /deny writes different rows
    depending on how the user got in:
      * a rejected access request — the user came through the old approval queue;
      * a removal-queue row that is NOT 'canceled' — the user was already inside
        (auto-granted or approved) and got revoked. 'canceled' means an admin gave
        access back via /allow, so it is deliberately not a denial.
    """
    uid = int(user_id)
    with get_db_connection_context() as conn:
        with conn.cursor() as cursor:
            cursor.execute(
                "SELECT 1 FROM bt_3_access_requests WHERE user_id = %s AND status = 'rejected' LIMIT 1;",
                (uid,),
            )
            if cursor.fetchone() is not None:
                return True
            cursor.execute(
                """
                SELECT 1 FROM bt_3_user_removal_queue
                WHERE user_id = %s AND status <> 'canceled'
                LIMIT 1;
                """,
                (uid,),
            )
            return cursor.fetchone() is not None


def auto_grant_telegram_user(
    user_id: int,
    username: str | None = None,
    source: str = "direct",
) -> bool:
    """Self-serve access grant. Returns True only when the row is genuinely NEW.

    ON CONFLICT DO NOTHING (not DO UPDATE) on purpose: an existing row may carry an
    admin's own note/added_by, and two entry points can race on the same brand-new
    user (bot /start and the Mini App opening at once). The RETURNING tells the caller
    whether it is the one that actually let this person in, so the admin gets exactly
    one «+1» notification and the daily digest can't double-count.
    """
    uid = int(user_id)
    if is_access_denied_for_user(uid):
        return False
    note = f"{AUTO_ACCESS_NOTE_PREFIX}: {str(source or 'direct').strip() or 'direct'}"
    with get_db_connection_context() as conn:
        with conn.cursor() as cursor:
            cursor.execute(
                """
                INSERT INTO bt_3_allowed_users (user_id, username, added_by, note)
                VALUES (%s, %s, NULL, %s)
                ON CONFLICT (user_id) DO NOTHING
                RETURNING user_id;
                """,
                (uid, username, note),
            )
            granted = cursor.fetchone() is not None
    if granted:
        invalidate_telegram_user_allowed_cache(uid)
        _invalidate_webapp_allowlist_redis(uid)
    return granted


def get_access_growth_snapshot(hours: int = 24) -> dict:
    """Numbers behind the admin's daily «кто подключился» digest.

    Synthetic load-test users live in the same table, so they are filtered out by
    user_id floor AND by their note prefixes — otherwise a load run reads as 60 new
    signups. Returns the fresh arrivals (with how they got in) plus the running total.

    Отсекается ОБА конца диапазона, а не только верхний. 11.08.2026 прогон кода
    приложения против боевой базы записал в аллоулист три выдуманных id (5555, 987654,
    776655) — верхний порог их пропустил, и утренний отчёт объявил владельцу «+3
    подключились за сутки» при нуле настоящих новичков. Нижняя граница —
    _MIN_REAL_TELEGRAM_USER_ID: настоящий Telegram-id не короче шести знаков.
    По username фильтровать НЕЛЬЗЯ: живой человек, зашедший с иконки на домашнем экране,
    приходит без имени (backend_server.py: _authenticate_webapp_request → _is_webapp_user_allowed).
    """
    window_hours = max(1, int(hours or 24))
    synthetic_floor = SYNTHETIC_TELEGRAM_USER_ID_MIN
    real_user_filter = """
        user_id < %s
        AND user_id >= %s
        AND COALESCE(note, '') NOT LIKE 'load_test%%'
        AND COALESCE(note, '') NOT LIKE '%%smoke%%'
        AND COALESCE(note, '') NOT LIKE '%%synthetic%%'
        AND COALESCE(note, '') NOT LIKE '%%runtime validation%%'
        AND COALESCE(note, '') NOT LIKE 'phase_c_worker%%'
        AND COALESCE(note, '') NOT LIKE 'postclaim_timeout%%'
    """
    with get_db_connection_context() as conn:
        with conn.cursor() as cursor:
            cursor.execute(
                f"""
                SELECT user_id, username, note, created_at
                FROM bt_3_allowed_users
                WHERE {real_user_filter}
                  AND created_at >= NOW() - (%s * INTERVAL '1 hour')
                ORDER BY created_at DESC;
                """,
                (synthetic_floor, _MIN_REAL_TELEGRAM_USER_ID, window_hours),
            )
            new_rows = [
                {
                    "user_id": int(row[0]),
                    "username": row[1],
                    "note": row[2],
                    "created_at": row[3],
                }
                for row in cursor.fetchall()
            ]
            cursor.execute(
                f"SELECT COUNT(*) FROM bt_3_allowed_users WHERE {real_user_filter};",
                (synthetic_floor, _MIN_REAL_TELEGRAM_USER_ID),
            )
            total_real = int((cursor.fetchone() or [0])[0])
    return {
        "window_hours": window_hours,
        "new_users": new_rows,
        "new_count": len(new_rows),
        "total_real": total_real,
    }


def revoke_telegram_user(user_id: int) -> bool:
    with get_db_connection_context() as conn:
        with conn.cursor() as cursor:
            cursor.execute(
                "DELETE FROM bt_3_allowed_users WHERE user_id = %s;",
                (int(user_id),),
            )
            removed = cursor.rowcount > 0
    # Access just changed — drop any stale cached decision for this user, in this
    # process AND in the shared Redis cache the web tier reads.
    invalidate_telegram_user_allowed_cache(int(user_id))
    _invalidate_webapp_allowlist_redis(int(user_id))
    return removed


def _serialize_user_removal_row(row) -> dict[str, Any] | None:
    if not row:
        return None
    return {
        "user_id": int(row[0]),
        "username": row[1],
        "revoked_at": row[2].isoformat() if row[2] else None,
        "grace_until": row[3].isoformat() if row[3] else None,
        "status": row[4],
        "scheduled_by": row[5],
        "reason": row[6],
        "notification_sent_at": row[7].isoformat() if row[7] else None,
        "notification_message_refs": row[8] if isinstance(row[8], list) else [],
        "decision_at": row[9].isoformat() if row[9] else None,
        "decision_by": row[10],
        "decision_note": row[11],
        "purged_at": row[12].isoformat() if row[12] else None,
        "purge_summary": row[13] if isinstance(row[13], dict) else {},
        "billing_cancel_snapshot": row[14] if isinstance(row[14], dict) else {},
        "created_at": row[15].isoformat() if row[15] else None,
        "updated_at": row[16].isoformat() if row[16] else None,
    }


def get_user_removal_request(user_id: int) -> dict[str, Any] | None:
    with get_db_connection_context() as conn:
        with conn.cursor() as cursor:
            cursor.execute(
                """
                SELECT
                    user_id,
                    username,
                    revoked_at,
                    grace_until,
                    status,
                    scheduled_by,
                    reason,
                    notification_sent_at,
                    notification_message_refs,
                    decision_at,
                    decision_by,
                    decision_note,
                    purged_at,
                    purge_summary,
                    billing_cancel_snapshot,
                    created_at,
                    updated_at
                FROM bt_3_user_removal_queue
                WHERE user_id = %s
                LIMIT 1;
                """,
                (int(user_id),),
            )
            row = cursor.fetchone()
    return _serialize_user_removal_row(row)


def schedule_telegram_user_removal(
    *,
    user_id: int,
    username: str | None = None,
    scheduled_by: int | None = None,
    reason: str | None = None,
    grace_days: int | None = None,
) -> dict[str, Any]:
    normalized_username = str(username or "").strip() or None
    normalized_reason = str(reason or "").strip() or None
    resolved_grace_days = max(1, int(grace_days or USER_REMOVAL_GRACE_DAYS))
    with get_db_connection_context() as conn:
        with conn.cursor() as cursor:
            cursor.execute(
                """
                INSERT INTO bt_3_user_removal_queue (
                    user_id,
                    username,
                    revoked_at,
                    grace_until,
                    status,
                    scheduled_by,
                    reason,
                    notification_sent_at,
                    notification_message_refs,
                    decision_at,
                    decision_by,
                    decision_note,
                    purged_at,
                    purge_summary,
                    billing_cancel_snapshot,
                    updated_at
                )
                VALUES (
                    %s,
                    %s,
                    NOW(),
                    NOW() + (%s * INTERVAL '1 day'),
                    'scheduled',
                    %s,
                    %s,
                    NULL,
                    '[]'::jsonb,
                    NULL,
                    NULL,
                    NULL,
                    NULL,
                    '{}'::jsonb,
                    NOW()
                )
                ON CONFLICT (user_id) DO UPDATE
                SET
                    username = COALESCE(EXCLUDED.username, bt_3_user_removal_queue.username),
                    revoked_at = NOW(),
                    grace_until = EXCLUDED.grace_until,
                    status = 'scheduled',
                    scheduled_by = EXCLUDED.scheduled_by,
                    reason = COALESCE(EXCLUDED.reason, bt_3_user_removal_queue.reason),
                    notification_sent_at = NULL,
                    notification_message_refs = '[]'::jsonb,
                    decision_at = NULL,
                    decision_by = NULL,
                    decision_note = NULL,
                    purged_at = NULL,
                    purge_summary = '{}'::jsonb,
                    billing_cancel_snapshot = '{}'::jsonb,
                    updated_at = NOW()
                RETURNING
                    user_id,
                    username,
                    revoked_at,
                    grace_until,
                    status,
                    scheduled_by,
                    reason,
                    notification_sent_at,
                    notification_message_refs,
                    decision_at,
                    decision_by,
                    decision_note,
                    purged_at,
                    purge_summary,
                    billing_cancel_snapshot,
                    created_at,
                    updated_at;
                """,
                (
                    int(user_id),
                    normalized_username,
                    resolved_grace_days,
                    int(scheduled_by) if scheduled_by is not None else None,
                    normalized_reason,
                ),
            )
            row = cursor.fetchone()
    result = _serialize_user_removal_row(row)
    if not result:
        raise RuntimeError("failed to schedule telegram user removal")
    return result


def cancel_telegram_user_removal(
    *,
    user_id: int,
    canceled_by: int | None = None,
    note: str | None = None,
) -> dict[str, Any] | None:
    normalized_note = str(note or "").strip() or None
    with get_db_connection_context() as conn:
        with conn.cursor() as cursor:
            cursor.execute(
                """
                UPDATE bt_3_user_removal_queue
                SET
                    status = 'canceled',
                    decision_at = NOW(),
                    decision_by = %s,
                    decision_note = %s,
                    updated_at = NOW()
                WHERE user_id = %s
                  AND status IN ('scheduled', 'awaiting_admin_confirmation')
                RETURNING
                    user_id,
                    username,
                    revoked_at,
                    grace_until,
                    status,
                    scheduled_by,
                    reason,
                    notification_sent_at,
                    notification_message_refs,
                    decision_at,
                    decision_by,
                    decision_note,
                    purged_at,
                    purge_summary,
                    billing_cancel_snapshot,
                    created_at,
                    updated_at;
                """,
                (
                    int(canceled_by) if canceled_by is not None else None,
                    normalized_note,
                    int(user_id),
                ),
            )
            row = cursor.fetchone()
    return _serialize_user_removal_row(row)


def list_due_user_removals_for_admin_confirmation(limit: int = 20) -> list[dict[str, Any]]:
    with get_db_connection_context() as conn:
        with conn.cursor() as cursor:
            cursor.execute(
                """
                SELECT
                    user_id,
                    username,
                    revoked_at,
                    grace_until,
                    status,
                    scheduled_by,
                    reason,
                    notification_sent_at,
                    notification_message_refs,
                    decision_at,
                    decision_by,
                    decision_note,
                    purged_at,
                    purge_summary,
                    billing_cancel_snapshot,
                    created_at,
                    updated_at
                FROM bt_3_user_removal_queue
                WHERE status = 'scheduled'
                  AND grace_until <= NOW()
                  AND notification_sent_at IS NULL
                ORDER BY grace_until ASC, revoked_at ASC
                LIMIT %s;
                """,
                (max(1, int(limit)),),
            )
            rows = cursor.fetchall()
    return [_serialize_user_removal_row(row) for row in rows if row]


def list_user_removal_queue(
    *,
    statuses: list[str] | tuple[str, ...] | set[str] | None = None,
    limit: int = 100,
) -> list[dict[str, Any]]:
    normalized_statuses = [
        str(item or "").strip().lower()
        for item in (statuses or [])
        if str(item or "").strip()
    ]
    allowed_statuses = {"scheduled", "awaiting_admin_confirmation", "canceled", "purged"}
    normalized_statuses = [item for item in normalized_statuses if item in allowed_statuses]
    with get_db_connection_context() as conn:
        with conn.cursor() as cursor:
            if normalized_statuses:
                cursor.execute(
                    """
                    SELECT
                        user_id,
                        username,
                        revoked_at,
                        grace_until,
                        status,
                        scheduled_by,
                        reason,
                        notification_sent_at,
                        notification_message_refs,
                        decision_at,
                        decision_by,
                        decision_note,
                        purged_at,
                        purge_summary,
                        billing_cancel_snapshot,
                        created_at,
                        updated_at
                    FROM bt_3_user_removal_queue
                    WHERE status = ANY(%s)
                    ORDER BY
                        CASE status
                            WHEN 'awaiting_admin_confirmation' THEN 1
                            WHEN 'scheduled' THEN 2
                            WHEN 'canceled' THEN 3
                            WHEN 'purged' THEN 4
                            ELSE 9
                        END ASC,
                        grace_until ASC NULLS LAST,
                        revoked_at DESC
                    LIMIT %s;
                    """,
                    (normalized_statuses, max(1, int(limit))),
                )
            else:
                cursor.execute(
                    """
                    SELECT
                        user_id,
                        username,
                        revoked_at,
                        grace_until,
                        status,
                        scheduled_by,
                        reason,
                        notification_sent_at,
                        notification_message_refs,
                        decision_at,
                        decision_by,
                        decision_note,
                        purged_at,
                        purge_summary,
                        billing_cancel_snapshot,
                        created_at,
                        updated_at
                    FROM bt_3_user_removal_queue
                    ORDER BY
                        CASE status
                            WHEN 'awaiting_admin_confirmation' THEN 1
                            WHEN 'scheduled' THEN 2
                            WHEN 'canceled' THEN 3
                            WHEN 'purged' THEN 4
                            ELSE 9
                        END ASC,
                        grace_until ASC NULLS LAST,
                        revoked_at DESC
                    LIMIT %s;
                    """,
                    (max(1, int(limit)),),
                )
            rows = cursor.fetchall() or []
    return [_serialize_user_removal_row(row) for row in rows if row]


