def deactivate_user_subscription(
    *,
    user_id: int,
    status: str = "canceled",
    plan_code: str = "free",
    clear_stripe_subscription_id: bool = False,
) -> dict | None:
    status_value = _normalize_subscription_status(status)
    plan_code_value = str(plan_code or "free").strip().lower() or "free"
    with get_db_connection_context() as conn:
        with conn.cursor() as cursor:
            cursor.execute(
                """
                UPDATE user_subscriptions
                SET
                    plan_code = %s,
                    status = %s,
                    trial_ends_at = NULL,
                    current_period_end = NULL,
                    stripe_subscription_id = CASE
                        WHEN %s THEN NULL
                        ELSE stripe_subscription_id
                    END,
                    updated_at = NOW()
                WHERE user_id = %s
                RETURNING
                    user_id,
                    plan_code,
                    status,
                    trial_ends_at,
                    current_period_end,
                    stripe_customer_id,
                    stripe_subscription_id,
                    created_at,
                    updated_at;
                """,
                (
                    plan_code_value,
                    status_value,
                    bool(clear_stripe_subscription_id),
                    int(user_id),
                ),
            )
            row = cursor.fetchone()
    return _subscription_row_to_dict(row) if row else None


def list_active_pro_subscription_user_ids() -> list[int]:
    """Every user_id currently on a paid (pro) subscription — for the one-time Stripe→Stars
    reset. Includes active/trialing/past_due so leftover Stripe TEST-mode subs are caught."""
    with get_db_connection_context() as conn:
        with conn.cursor() as cursor:
            cursor.execute(
                """
                SELECT user_id FROM user_subscriptions
                WHERE plan_code <> 'free'
                  AND status IN ('active', 'trialing', 'past_due')
                ORDER BY user_id;
                """
            )
            return [int(r[0]) for r in (cursor.fetchall() or [])]


def reset_pro_subscriptions_except(keep_user_ids: set[int] | list[int] | None) -> dict:
    """One-time Stripe→Stars migration: force every paid (pro) user EXCEPT keep_user_ids back
    to Free (status 'canceled', Stripe id cleared) and bust their entitlement cache. They get
    a fresh 7-day welcome trial on their next Mini-App open (they never consumed one while
    paid). Idempotent — re-running only touches users still on pro. Returns {reset, kept}."""
    keep = {int(u) for u in (keep_user_ids or [])}
    targets = [u for u in list_active_pro_subscription_user_ids() if u not in keep]
    done: list[int] = []
    for uid in targets:
        try:
            deactivate_user_subscription(
                user_id=uid, status="canceled", plan_code="free",
                clear_stripe_subscription_id=True,
            )
            _bust_entitlement_cache(uid)
            done.append(uid)
        except Exception:
            logging.warning("reset_pro_subscriptions_except: failed user=%s", uid, exc_info=True)
    return {"reset": done, "kept": sorted(keep)}


def purge_telegram_user_personal_data(
    *,
    user_id: int,
    approved_by: int | None = None,
    note: str | None = None,
) -> dict[str, Any] | None:
    normalized_note = str(note or "").strip() or None
    delete_statements: list[tuple[str, str]] = [
        ("daily_plan_items", """
            DELETE FROM bt_3_daily_plan_items i
            USING bt_3_daily_plans p
            WHERE i.plan_id = p.id
              AND p.user_id = %s;
        """),
        ("translation_check_sessions", "DELETE FROM bt_3_translation_check_sessions WHERE user_id = %s;"),
        ("webapp_dictionary_queries", "DELETE FROM bt_3_webapp_dictionary_queries WHERE user_id = %s;"),
        ("dictionary_folders", "DELETE FROM bt_3_dictionary_folders WHERE user_id = %s;"),
        ("translation_draft_state", "DELETE FROM bt_3_translation_draft_state WHERE user_id = %s;"),
        ("youtube_watch_state", "DELETE FROM bt_3_youtube_watch_state WHERE user_id = %s;"),
        ("flashcard_feel_feedback_queue", "DELETE FROM bt_3_flashcard_feel_feedback_queue WHERE user_id = %s;"),
        ("flashcard_seen", "DELETE FROM bt_3_flashcard_seen WHERE user_id = %s;"),
        ("flashcard_stats", "DELETE FROM bt_3_flashcard_stats WHERE user_id = %s;"),
        ("video_recommendation_votes", "DELETE FROM bt_3_video_recommendation_votes WHERE user_id = %s;"),
        ("support_messages", "DELETE FROM bt_3_support_messages WHERE user_id = %s;"),
        ("card_review_log", "DELETE FROM bt_3_card_review_log WHERE user_id = %s;"),
        ("card_srs_state", "DELETE FROM bt_3_card_srs_state WHERE user_id = %s;"),
        ("daily_plans", "DELETE FROM bt_3_daily_plans WHERE user_id = %s;"),
        ("weekly_goals", "DELETE FROM bt_3_weekly_goals WHERE user_id = %s;"),
        ("agent_voice_sessions", "DELETE FROM bt_3_agent_voice_sessions WHERE user_id = %s;"),
        ("reader_sessions", "DELETE FROM bt_3_reader_sessions WHERE user_id = %s;"),
        ("reader_library", "DELETE FROM bt_3_reader_library WHERE user_id = %s;"),
        ("today_reminder_settings", "DELETE FROM bt_3_today_reminder_settings WHERE user_id = %s;"),
        ("audio_grammar_settings", "DELETE FROM bt_3_audio_grammar_settings WHERE user_id = %s;"),
        ("youtube_proxy_subtitles_access", "DELETE FROM bt_3_youtube_proxy_subtitles_access WHERE user_id = %s;"),
        ("reader_audio_limit_overrides", "DELETE FROM bt_3_reader_audio_limit_overrides WHERE user_id = %s;"),
        ("today_regenerate_limits", "DELETE FROM bt_3_today_regenerate_limits WHERE user_id = %s;"),
        ("default_topics", "DELETE FROM bt_3_default_topics WHERE user_id = %s;"),
        ("telegram_quiz_attempts", "DELETE FROM bt_3_telegram_quiz_attempts WHERE user_id = %s;"),
        ("webapp_group_contexts", "DELETE FROM bt_3_webapp_group_contexts WHERE user_id = %s;"),
        ("webapp_scope_state", "DELETE FROM bt_3_webapp_scope_state WHERE user_id = %s;"),
        ("webapp_instance_leases", "DELETE FROM bt_3_webapp_instance_leases WHERE user_id = %s;"),
        ("webapp_checks", "DELETE FROM bt_3_webapp_checks WHERE user_id = %s;"),
        ("user_language_profile", "DELETE FROM bt_3_user_language_profile WHERE user_id = %s;"),
        ("skill_state_v2_dirty", "DELETE FROM bt_3_skill_state_v2_dirty WHERE user_id = %s;"),
        ("user_skill_state_v2", "DELETE FROM bt_3_user_skill_state_v2 WHERE user_id = %s;"),
        ("user_skill_state", "DELETE FROM bt_3_user_skill_state WHERE user_id = %s;"),
        ("daily_sentences", "DELETE FROM bt_3_daily_sentences WHERE user_id = %s;"),
        ("detailed_mistakes", "DELETE FROM bt_3_detailed_mistakes WHERE user_id = %s;"),
        ("attempts", "DELETE FROM bt_3_attempts WHERE user_id = %s;"),
        ("successful_translations", "DELETE FROM bt_3_successful_translations WHERE user_id = %s;"),
        ("translations", "DELETE FROM bt_3_translations WHERE user_id = %s;"),
        ("messages", "DELETE FROM bt_3_messages WHERE user_id = %s;"),
        ("conversation_errors", "DELETE FROM bt_3_conversation_errors WHERE user_id = %s;"),
        ("bookmarks", "DELETE FROM bt_3_bookmarks WHERE user_id = %s;"),
        ("user_progress", "DELETE FROM bt_3_user_progress WHERE user_id = %s;"),
        ("translation_errors", "DELETE FROM bt_3_translation_errors WHERE user_id = %s;"),
        ("access_allowed", "DELETE FROM bt_3_allowed_users WHERE user_id = %s;"),
    ]

    with get_db_connection_context() as conn:
        with conn.cursor() as cursor:
            cursor.execute(
                """
                SELECT
                    user_id,
                    username,
                    revoked_at,
                    grace_until,
                    status,
                    scheduled_by,
                    reason,
                    notification_sent_at,
                    notification_message_refs,
                    decision_at,
                    decision_by,
                    decision_note,
                    purged_at,
                    purge_summary,
                    billing_cancel_snapshot,
                    created_at,
                    updated_at
                FROM bt_3_user_removal_queue
                WHERE user_id = %s
                FOR UPDATE;
                """,
                (int(user_id),),
            )
            existing_row = cursor.fetchone()
            if not existing_row:
                return None
            existing = _serialize_user_removal_row(existing_row)
            if not existing:
                return None
            if existing.get("status") == "purged":
                return existing

            purge_summary: dict[str, Any] = {}
            total_deleted_rows = 0
            for label, query in delete_statements:
                cursor.execute(query, (int(user_id),))
                deleted_rows = int(cursor.rowcount or 0)
                purge_summary[label] = deleted_rows
                total_deleted_rows += deleted_rows

            purge_summary["total_deleted_rows"] = total_deleted_rows
            purge_summary["grace_days"] = USER_REMOVAL_GRACE_DAYS

            cursor.execute(
                """
                UPDATE bt_3_user_removal_queue
                SET
                    status = 'purged',
                    decision_at = NOW(),
                    decision_by = %s,
                    decision_note = %s,
                    purged_at = NOW(),
                    purge_summary = %s,
                    updated_at = NOW()
                WHERE user_id = %s
                RETURNING
                    user_id,
                    username,
                    revoked_at,
                    grace_until,
                    status,
                    scheduled_by,
                    reason,
                    notification_sent_at,
                    notification_message_refs,
                    decision_at,
                    decision_by,
                    decision_note,
                    purged_at,
                    purge_summary,
                    billing_cancel_snapshot,
                    created_at,
                    updated_at;
                """,
                (
                    int(approved_by) if approved_by is not None else None,
                    normalized_note,
                    Json(purge_summary),
                    int(user_id),
                ),
            )
            row = cursor.fetchone()
    # Purge deletes the bt_3_allowed_users row directly (not via revoke_telegram_user),
    # so invalidate here too — otherwise a purged user could retain cached access
    # until the TTL expires.
    invalidate_telegram_user_allowed_cache(int(user_id))
    return _serialize_user_removal_row(row)


def list_allowed_telegram_users(limit: int = 100) -> list[dict]:
    with get_db_connection_context() as conn:
        with conn.cursor() as cursor:
            cursor.execute(
                """
                SELECT user_id, username, added_by, note, created_at, updated_at
                FROM bt_3_allowed_users
                ORDER BY updated_at DESC
                LIMIT %s;
                """,
                (max(1, min(int(limit), 500)),),
            )
            rows = cursor.fetchall()

    return [
        {
            "user_id": row[0],
            "username": row[1],
            "added_by": row[2],
            "note": row[3],
            "created_at": row[4].isoformat() if row[4] else None,
            "updated_at": row[5].isoformat() if row[5] else None,
        }
        for row in rows
    ]


def _normalize_lang_code(value: str | None) -> str:
    return str(value or "").strip().lower()


def get_user_language_profile(user_id: int) -> dict:
    with get_db_connection_context() as conn:
        with conn.cursor() as cursor:
            cursor.execute(
                """
                SELECT learning_language, native_language, updated_at
                FROM bt_3_user_language_profile
                WHERE user_id = %s
                LIMIT 1;
                """,
                (int(user_id),),
            )
            row = cursor.fetchone()
    if not row:
        return {
            "user_id": int(user_id),
            "learning_language": DEFAULT_LEARNING_LANGUAGE,
            "native_language": DEFAULT_NATIVE_LANGUAGE,
            "updated_at": None,
            "has_profile": False,
        }
    learning_language = _normalize_lang_code(row[0]) or DEFAULT_LEARNING_LANGUAGE
    native_language = _normalize_lang_code(row[1]) or DEFAULT_NATIVE_LANGUAGE
    if learning_language not in SUPPORTED_LEARNING_LANGUAGES:
        learning_language = DEFAULT_LEARNING_LANGUAGE
    if native_language not in SUPPORTED_NATIVE_LANGUAGES:
        native_language = DEFAULT_NATIVE_LANGUAGE
    return {
        "user_id": int(user_id),
        "learning_language": learning_language,
        "native_language": native_language,
        "updated_at": row[2].isoformat() if row[2] else None,
        "has_profile": True,
    }


def upsert_user_language_profile(user_id: int, learning_language: str, native_language: str) -> dict:
    learning = _normalize_lang_code(learning_language)
    native = _normalize_lang_code(native_language)
    if learning not in SUPPORTED_LEARNING_LANGUAGES:
        raise ValueError(f"Unsupported learning language: {learning_language}")
    if native not in SUPPORTED_NATIVE_LANGUAGES:
        raise ValueError(f"Unsupported native language: {native_language}")
    with get_db_connection_context() as conn:
        with conn.cursor() as cursor:
            cursor.execute(
                """
                INSERT INTO bt_3_user_language_profile (user_id, learning_language, native_language, updated_at)
                VALUES (%s, %s, %s, CURRENT_TIMESTAMP)
                ON CONFLICT (user_id) DO UPDATE
                SET learning_language = EXCLUDED.learning_language,
                    native_language = EXCLUDED.native_language,
                    updated_at = CURRENT_TIMESTAMP
                RETURNING learning_language, native_language, updated_at;
                """,
                (int(user_id), learning, native),
            )
            row = cursor.fetchone()
    return {
        "user_id": int(user_id),
        "learning_language": row[0],
        "native_language": row[1],
        "updated_at": row[2].isoformat() if row[2] else None,
        "has_profile": True,
    }


def get_user_progress_reset(
    user_id: int,
    *,
    source_lang: str,
    target_lang: str,
) -> dict:
    normalized_source = str(source_lang or "ru").strip().lower() or "ru"
    normalized_target = str(target_lang or "de").strip().lower() or "de"
    with get_db_connection_context() as conn:
        with conn.cursor() as cursor:
            cursor.execute(
                """
                SELECT reset_date, created_at, updated_at
                FROM bt_3_user_progress_resets
                WHERE user_id = %s
                  AND source_lang = %s
                  AND target_lang = %s
                LIMIT 1;
                """,
                (int(user_id), normalized_source, normalized_target),
            )
            row = cursor.fetchone()
    if not row:
        return {
            "user_id": int(user_id),
            "source_lang": normalized_source,
            "target_lang": normalized_target,
            "has_reset": False,
            "reset_date": None,
            "created_at": None,
            "updated_at": None,
        }
    return {
        "user_id": int(user_id),
        "source_lang": normalized_source,
        "target_lang": normalized_target,
        "has_reset": True,
        "reset_date": row[0].isoformat() if row[0] else None,
        "created_at": row[1].isoformat() if row[1] else None,
        "updated_at": row[2].isoformat() if row[2] else None,
    }


def upsert_user_progress_reset(
    user_id: int,
    *,
    source_lang: str,
    target_lang: str,
    reset_date: date,
) -> dict:
    normalized_source = str(source_lang or "ru").strip().lower() or "ru"
    normalized_target = str(target_lang or "de").strip().lower() or "de"
    if not isinstance(reset_date, date):
        raise ValueError("reset_date must be a date")
    with get_db_connection_context() as conn:
        with conn.cursor() as cursor:
            cursor.execute(
                """
                INSERT INTO bt_3_user_progress_resets (
                    user_id,
                    source_lang,
                    target_lang,
                    reset_date,
                    created_at,
                    updated_at
                )
                VALUES (%s, %s, %s, %s, NOW(), NOW())
                ON CONFLICT (user_id, source_lang, target_lang) DO UPDATE
                SET reset_date = EXCLUDED.reset_date,
                    updated_at = NOW()
                RETURNING reset_date, created_at, updated_at;
                """,
                (int(user_id), normalized_source, normalized_target, reset_date),
            )
            row = cursor.fetchone()
    return {
        "user_id": int(user_id),
        "source_lang": normalized_source,
        "target_lang": normalized_target,
        "has_reset": True,
        "reset_date": row[0].isoformat() if row and row[0] else reset_date.isoformat(),
        "created_at": row[1].isoformat() if row and row[1] else None,
        "updated_at": row[2].isoformat() if row and row[2] else None,
    }


def get_user_progress_reset_date(
    user_id: int,
    *,
    source_lang: str,
    target_lang: str,
) -> date | None:
    reset = get_user_progress_reset(
        user_id=user_id,
        source_lang=source_lang,
        target_lang=target_lang,
    )
    raw_reset_date = reset.get("reset_date")
    if not raw_reset_date:
        return None
    try:
        return date.fromisoformat(str(raw_reset_date))
    except Exception:
        return None


def _resolve_progress_window_start(
    user_id: int,
    *,
    source_lang: str,
    target_lang: str,
    start_date: date,
) -> date:
    reset_date = get_user_progress_reset_date(
        user_id=user_id,
        source_lang=source_lang,
        target_lang=target_lang,
    )
    if reset_date is None:
        return start_date
    return max(start_date, reset_date)


def _normalize_webapp_scope_kind(value: str | None) -> str:
    kind = str(value or "").strip().lower()
    if kind == "group":
        return "group"
    return "personal"


def _build_webapp_scope_key(scope_kind: str, scope_chat_id: int | None) -> str:
    if scope_kind == "group" and scope_chat_id is not None:
        return f"group:{int(scope_chat_id)}"
    return "personal"


def _normalize_webapp_instance_id(value: str | None) -> str:
    raw = str(value or "").strip()
    if not raw:
        raise ValueError("instance_id обязателен")
    compact = re.sub(r"[^a-zA-Z0-9._:-]+", "-", raw).strip("-")
    if not compact:
        raise ValueError("instance_id пуст после нормализации")
    return compact[:128]


def _map_webapp_instance_lease_row(row: Any, *, user_id: int | None = None) -> dict | None:
    if not row:
        return None
    resolved_user_id = int(row[0]) if row[0] is not None else int(user_id or 0)
    if resolved_user_id <= 0:
        return None
    return {
        "user_id": resolved_user_id,
        "instance_id": str(row[1] or "").strip(),
        "session_id": str(row[2] or "").strip() or None,
        "platform": str(row[3] or "").strip() or None,
        "app_context": str(row[4] or "").strip() or None,
        "claimed_at": row[5].isoformat() if row[5] else None,
        "last_seen_at": row[6].isoformat() if row[6] else None,
        "updated_at": row[7].isoformat() if row[7] else None,
    }


def get_webapp_instance_lease(user_id: int) -> dict | None:
    with get_db_connection_context() as conn:
        with conn.cursor() as cursor:
            cursor.execute(
                """
                SELECT
                    user_id,
                    instance_id,
                    session_id,
                    platform,
                    app_context,
                    claimed_at,
                    last_seen_at,
                    updated_at
                FROM bt_3_webapp_instance_leases
                WHERE user_id = %s
                LIMIT 1;
                """,
                (int(user_id),),
            )
            return _map_webapp_instance_lease_row(cursor.fetchone(), user_id=int(user_id))


def claim_webapp_instance_lease(
    *,
    user_id: int,
    instance_id: str,
    session_id: str | None = None,
    platform: str | None = None,
    app_context: str | None = None,
) -> dict:
    normalized_instance_id = _normalize_webapp_instance_id(instance_id)
    normalized_session_id = str(session_id or "").strip()[:128] or None
    normalized_platform = str(platform or "").strip()[:64] or None
    normalized_app_context = str(app_context or "").strip()[:64] or None
    with get_db_connection_context() as conn:
        with conn.cursor() as cursor:
            cursor.execute(
                """
                INSERT INTO bt_3_webapp_instance_leases (
                    user_id,
                    instance_id,
                    session_id,
                    platform,
                    app_context,
                    claimed_at,
                    last_seen_at,
                    updated_at
                )
                VALUES (%s, %s, %s, %s, %s, NOW(), NOW(), NOW())
                ON CONFLICT (user_id) DO UPDATE
                SET
                    instance_id = EXCLUDED.instance_id,
                    session_id = EXCLUDED.session_id,
                    platform = EXCLUDED.platform,
                    app_context = EXCLUDED.app_context,
                    last_seen_at = NOW(),
                    updated_at = NOW()
                RETURNING
                    user_id,
                    instance_id,
                    session_id,
                    platform,
                    app_context,
                    claimed_at,
                    last_seen_at,
                    updated_at;
                """,
                (
                    int(user_id),
                    normalized_instance_id,
                    normalized_session_id,
                    normalized_platform,
                    normalized_app_context,
                ),
            )
            row = cursor.fetchone()
    lease = _map_webapp_instance_lease_row(row, user_id=int(user_id))
    if not lease:
        raise RuntimeError("Не удалось сохранить lease WebApp instance")
    return lease


def release_webapp_instance_lease(*, user_id: int, instance_id: str) -> bool:
    normalized_instance_id = _normalize_webapp_instance_id(instance_id)
    with get_db_connection_context() as conn:
        with conn.cursor() as cursor:
            cursor.execute(
                """
                DELETE FROM bt_3_webapp_instance_leases
                WHERE user_id = %s
                  AND instance_id = %s;
                """,
                (int(user_id), normalized_instance_id),
            )
            return bool(cursor.rowcount)


def _map_user_api_snapshot_row(row) -> dict | None:
    if not row:
        return None
    return {
        "user_id": int(row[0]),
        "snapshot_kind": str(row[1] or "").strip(),
        "snapshot_key": str(row[2] or "").strip(),
        "source_lang": str(row[3] or "").strip() or None,
        "target_lang": str(row[4] or "").strip() or None,
        "payload": row[5] if isinstance(row[5], dict) else {},
        "meta": row[6] if isinstance(row[6], dict) else {},
        "refreshed_at": row[7].isoformat() if row[7] else None,
        "fresh_until_at": row[8].isoformat() if row[8] else None,
        "stale_until_at": row[9].isoformat() if row[9] else None,
        "updated_at": row[10].isoformat() if row[10] else None,
    }


def _ensure_phase1_projection_schema_for_snapshot_access() -> None:
    if _ENSURE_PHASE1_PROJECTION_SCHEMA_DONE:
        return
    logging.info("Phase1 projection schema lazy ensure triggered for snapshot access")
    ensure_phase1_projection_schema()


def get_user_api_snapshot(
    *,
    user_id: int,
    snapshot_kind: str,
    snapshot_key: str,
) -> dict | None:
    _ensure_phase1_projection_schema_for_snapshot_access()
    with get_db_connection_context() as conn:
        with conn.cursor() as cursor:
            cursor.execute(
                """
                SELECT
                    user_id,
                    snapshot_kind,
                    snapshot_key,
                    source_lang,
                    target_lang,
                    payload,
                    meta,
                    refreshed_at,
                    fresh_until_at,
                    stale_until_at,
                    updated_at
                FROM bt_3_user_api_snapshots
                WHERE user_id = %s
                  AND snapshot_kind = %s
                  AND snapshot_key = %s
                LIMIT 1;
                """,
                (int(user_id), str(snapshot_kind or "").strip(), str(snapshot_key or "").strip()),
            )
            return _map_user_api_snapshot_row(cursor.fetchone())


def upsert_user_api_snapshot(
    *,
    user_id: int,
    snapshot_kind: str,
    snapshot_key: str,
    payload: dict,
    source_lang: str | None = None,
    target_lang: str | None = None,
    meta: dict | None = None,
    fresh_ttl_seconds: int = 30,
    stale_ttl_seconds: int = 300,
) -> dict | None:
    normalized_kind = str(snapshot_kind or "").strip()
    normalized_key = str(snapshot_key or "").strip()
    if not normalized_kind or not normalized_key:
        raise ValueError("snapshot_kind and snapshot_key are required")
    _ensure_phase1_projection_schema_for_snapshot_access()
    safe_payload = payload if isinstance(payload, dict) else {}
    safe_meta = meta if isinstance(meta, dict) else {}
    safe_fresh_ttl = max(1, int(fresh_ttl_seconds or 1))
    safe_stale_ttl = max(safe_fresh_ttl, int(stale_ttl_seconds or safe_fresh_ttl))
    with get_db_connection_context() as conn:
        with conn.cursor() as cursor:
            cursor.execute(
                """
                INSERT INTO bt_3_user_api_snapshots (
                    user_id,
                    snapshot_kind,
                    snapshot_key,
                    source_lang,
                    target_lang,
                    payload,
                    meta,
                    refreshed_at,
                    fresh_until_at,
                    stale_until_at,
                    updated_at
                )
                VALUES (
                    %s, %s, %s, %s, %s, %s::jsonb, %s::jsonb,
                    NOW(),
                    NOW() + (%s * INTERVAL '1 second'),
                    NOW() + (%s * INTERVAL '1 second'),
                    NOW()
                )
                ON CONFLICT (user_id, snapshot_kind, snapshot_key) DO UPDATE
                SET
                    source_lang = EXCLUDED.source_lang,
                    target_lang = EXCLUDED.target_lang,
                    payload = EXCLUDED.payload,
                    meta = EXCLUDED.meta,
                    refreshed_at = EXCLUDED.refreshed_at,
                    fresh_until_at = EXCLUDED.fresh_until_at,
                    stale_until_at = EXCLUDED.stale_until_at,
                    updated_at = NOW()
                RETURNING
                    user_id,
                    snapshot_kind,
                    snapshot_key,
                    source_lang,
                    target_lang,
                    payload,
                    meta,
                    refreshed_at,
                    fresh_until_at,
                    stale_until_at,
                    updated_at;
                """,
                (
                    int(user_id),
                    normalized_kind,
                    normalized_key,
                    str(source_lang or "").strip() or None,
                    str(target_lang or "").strip() or None,
                    json.dumps(safe_payload, ensure_ascii=False),
                    json.dumps(safe_meta, ensure_ascii=False),
                    safe_fresh_ttl,
                    safe_stale_ttl,
                ),
            )
            return _map_user_api_snapshot_row(cursor.fetchone())


def mark_user_api_snapshots_stale(
    *,
    user_id: int,
    snapshot_kind: str | None = None,
    snapshot_key: str | None = None,
) -> int:
    _ensure_phase1_projection_schema_for_snapshot_access()
    conditions = ["user_id = %s"]
    params: list[Any] = [int(user_id)]
    normalized_kind = str(snapshot_kind or "").strip()
    normalized_key = str(snapshot_key or "").strip()
    if normalized_kind:
        conditions.append("snapshot_kind = %s")
        params.append(normalized_kind)
    if normalized_key:
        conditions.append("snapshot_key = %s")
        params.append(normalized_key)
    where_sql = " AND ".join(conditions)
    with get_db_connection_context() as conn:
        with conn.cursor() as cursor:
            cursor.execute(
                f"""
                UPDATE bt_3_user_api_snapshots
                SET
                    fresh_until_at = LEAST(fresh_until_at, NOW() - INTERVAL '1 second'),
                    updated_at = NOW()
                WHERE {where_sql};
                """,
                params,
            )
            return int(cursor.rowcount or 0)


def _map_projection_job_row(row: tuple | None) -> dict | None:
    if not row:
        return None
    return {
        "id": int(row[0]),
        "job_kind": str(row[1] or "").strip(),
        "projection_kind": str(row[2] or "").strip(),
        "user_id": int(row[3]),
        "source_session_id": str(row[4] or "").strip() or None,
        "plan_date": row[5].isoformat() if row[5] else None,
        "lookback_days": int(row[6]) if row[6] is not None else None,
        "job_source": str(row[7] or "").strip() or "live",
        "queue_name": str(row[8] or "").strip() or None,
        "status": str(row[9] or "").strip(),
        "attempt_count": int(row[10] or 0),
        "lease_token": str(row[11] or "").strip() or None,
        "next_attempt_at": row[12].isoformat() if row[12] else None,
        "last_error": str(row[13] or "").strip() or None,
        "enqueued_at": row[14].isoformat() if row[14] else None,
        "started_at": row[15].isoformat() if row[15] else None,
        "completed_at": row[16].isoformat() if row[16] else None,
        "created_at": row[17].isoformat() if row[17] else None,
        "updated_at": row[18].isoformat() if row[18] else None,
    }


def upsert_projection_job(
    *,
    job_kind: str,
    projection_kind: str,
    user_id: int,
    source_session_id: str | None = None,
    plan_date: date | None = None,
    lookback_days: int | None = None,
    job_source: str | None = None,
    queue_name: str | None = None,
) -> dict | None:
    ensure_phase1_projection_schema()
    normalized_job_kind = str(job_kind or "").strip()
    normalized_projection_kind = str(projection_kind or "").strip()
    normalized_source_session_id = str(source_session_id or "").strip()
    if not normalized_job_kind or not normalized_projection_kind:
        raise ValueError("job_kind and projection_kind are required")
    with get_db_connection_context() as conn:
        with conn.cursor() as cursor:
            cursor.execute(
                """
                INSERT INTO bt_3_projection_jobs (
                    job_kind,
                    projection_kind,
                    user_id,
                    source_session_id,
                    plan_date,
                    lookback_days,
                    job_source,
                    queue_name,
                    status,
                    attempt_count,
                    lease_token,
                    next_attempt_at,
                    last_error,
                    enqueued_at,
                    started_at,
                    completed_at,
                    created_at,
                    updated_at
                )
                VALUES (
                    %s, %s, %s, %s, %s, %s, %s, %s,
                    'pending', 0, NULL, NOW(), NULL, NOW(), NULL, NULL, NOW(), NOW()
                )
                ON CONFLICT (job_kind, projection_kind, user_id, source_session_id) DO UPDATE
                SET
                    plan_date = COALESCE(EXCLUDED.plan_date, bt_3_projection_jobs.plan_date),
                    lookback_days = COALESCE(EXCLUDED.lookback_days, bt_3_projection_jobs.lookback_days),
                    job_source = COALESCE(EXCLUDED.job_source, bt_3_projection_jobs.job_source),
                    queue_name = COALESCE(EXCLUDED.queue_name, bt_3_projection_jobs.queue_name),
                    status = CASE
                        WHEN bt_3_projection_jobs.status = 'running' THEN bt_3_projection_jobs.status
                        ELSE 'pending'
                    END,
                    lease_token = CASE
                        WHEN bt_3_projection_jobs.status = 'running' THEN bt_3_projection_jobs.lease_token
                        ELSE NULL
                    END,
                    next_attempt_at = CASE
                        WHEN bt_3_projection_jobs.status = 'running' THEN bt_3_projection_jobs.next_attempt_at
                        ELSE NOW()
                    END,
                    last_error = CASE
                        WHEN bt_3_projection_jobs.status = 'running' THEN bt_3_projection_jobs.last_error
                        ELSE NULL
                    END,
                    enqueued_at = CASE
                        WHEN bt_3_projection_jobs.status = 'running' THEN bt_3_projection_jobs.enqueued_at
                        ELSE NOW()
                    END,
                    started_at = CASE
                        WHEN bt_3_projection_jobs.status = 'running' THEN bt_3_projection_jobs.started_at
                        ELSE NULL
                    END,
                    completed_at = NULL,
                    updated_at = NOW()
                RETURNING
                    id,
                    job_kind,
                    projection_kind,
                    user_id,
                    source_session_id,
                    plan_date,
                    lookback_days,
                    job_source,
                    queue_name,
                    status,
                    attempt_count,
                    lease_token,
                    next_attempt_at,
                    last_error,
                    enqueued_at,
                    started_at,
                    completed_at,
                    created_at,
                    updated_at;
                """,
                (
                    normalized_job_kind,
                    normalized_projection_kind,
                    int(user_id),
                    normalized_source_session_id,
                    plan_date,
                    int(lookback_days) if lookback_days is not None else None,
                    str(job_source or "").strip() or "live",
                    str(queue_name or "").strip() or "projection_materialization_live",
                ),
            )
            return _map_projection_job_row(cursor.fetchone())


def claim_projection_job(
    *,
    job_id: int,
    expected_job_source: str | None = None,
    expected_queue_name: str | None = None,
) -> dict | None:
    ensure_phase1_projection_schema()
    safe_job_id = int(job_id or 0)
    if safe_job_id <= 0:
        return None
    lease_token = str(uuid4())
    conditions = [
        "id = %s",
        "status = 'pending'",
        "next_attempt_at <= NOW()",
    ]
    params: list[Any] = [lease_token, safe_job_id]
    normalized_expected_source = str(expected_job_source or "").strip()
    normalized_expected_queue = str(expected_queue_name or "").strip()
    if normalized_expected_source:
        conditions.append("job_source = %s")
        params.append(normalized_expected_source)
    if normalized_expected_queue:
        conditions.append("queue_name = %s")
        params.append(normalized_expected_queue)
    with get_db_connection_context() as conn:
        with conn.cursor() as cursor:
            cursor.execute(
                f"""
                UPDATE bt_3_projection_jobs
                SET
                    status = 'running',
                    attempt_count = attempt_count + 1,
                    lease_token = %s,
                    started_at = NOW(),
                    updated_at = NOW()
                WHERE {" AND ".join(conditions)}
                RETURNING
                    id,
                    job_kind,
                    projection_kind,
                    user_id,
                    source_session_id,
                    plan_date,
                    lookback_days,
                    job_source,
                    queue_name,
                    status,
                    attempt_count,
                    lease_token,
                    next_attempt_at,
                    last_error,
                    enqueued_at,
                    started_at,
                    completed_at,
                    created_at,
                    updated_at;
                """,
                params,
            )
            return _map_projection_job_row(cursor.fetchone())


def complete_projection_job(*, job_id: int, lease_token: str) -> dict | None:
    ensure_phase1_projection_schema()
    normalized_lease_token = str(lease_token or "").strip()
    if int(job_id or 0) <= 0 or not normalized_lease_token:
        return None
    with get_db_connection_context() as conn:
        with conn.cursor() as cursor:
            cursor.execute(
                """
                UPDATE bt_3_projection_jobs
                SET
                    status = 'done',
                    lease_token = NULL,
                    last_error = NULL,
                    completed_at = NOW(),
                    updated_at = NOW()
                WHERE id = %s
                  AND status = 'running'
                  AND lease_token = %s
                RETURNING
                    id,
                    job_kind,
                    projection_kind,
                    user_id,
                    source_session_id,
                    plan_date,
                    lookback_days,
                    job_source,
                    queue_name,
                    status,
                    attempt_count,
                    lease_token,
                    next_attempt_at,
                    last_error,
                    enqueued_at,
                    started_at,
                    completed_at,
                    created_at,
                    updated_at;
                """,
                (int(job_id), normalized_lease_token),
            )
            return _map_projection_job_row(cursor.fetchone())


def fail_projection_job(
    *,
    job_id: int,
    lease_token: str,
    error_text: str,
    max_attempts: int = 4,
) -> dict | None:
    ensure_phase1_projection_schema()
    normalized_lease_token = str(lease_token or "").strip()
    if int(job_id or 0) <= 0 or not normalized_lease_token:
        return None
    safe_error = str(error_text or "").strip() or "projection_job_failed"
    safe_max_attempts = max(1, int(max_attempts or 1))
    retry_schedule_seconds = [30, 120, 600, 1800]
    with get_db_connection_context() as conn:
        with conn.cursor() as cursor:
            cursor.execute(
                """
                SELECT attempt_count
                FROM bt_3_projection_jobs
                WHERE id = %s
                  AND status = 'running'
                  AND lease_token = %s
                LIMIT 1;
                """,
                (int(job_id), normalized_lease_token),
            )
            row = cursor.fetchone()
            if not row:
                return None
            attempt_count = int(row[0] or 0)
            if attempt_count >= safe_max_attempts:
                cursor.execute(
                    """
                    UPDATE bt_3_projection_jobs
                    SET
                        status = 'failed',
                        lease_token = NULL,
                        last_error = %s,
                        completed_at = NOW(),
                        updated_at = NOW()
                    WHERE id = %s
                      AND status = 'running'
                      AND lease_token = %s
                    RETURNING
                        id,
                        job_kind,
                        projection_kind,
                        user_id,
                        source_session_id,
                        plan_date,
                        lookback_days,
                        job_source,
                        queue_name,
                        status,
                        attempt_count,
                        lease_token,
                        next_attempt_at,
                        last_error,
                        enqueued_at,
                        started_at,
                        completed_at,
                        created_at,
                        updated_at;
                    """,
                    (safe_error, int(job_id), normalized_lease_token),
                )
                return _map_projection_job_row(cursor.fetchone())
            retry_delay = retry_schedule_seconds[min(max(0, attempt_count - 1), len(retry_schedule_seconds) - 1)]
            cursor.execute(
                """
                UPDATE bt_3_projection_jobs
                SET
                    status = 'pending',
                    lease_token = NULL,
                    next_attempt_at = NOW() + (%s * INTERVAL '1 second'),
                    last_error = %s,
                    completed_at = NULL,
                    updated_at = NOW()
                WHERE id = %s
                  AND status = 'running'
                  AND lease_token = %s
                RETURNING
                    id,
                    job_kind,
                    projection_kind,
                    user_id,
                    source_session_id,
                    plan_date,
                    lookback_days,
                    job_source,
                    queue_name,
                    status,
                    attempt_count,
                    lease_token,
                    next_attempt_at,
                    last_error,
                    enqueued_at,
                    started_at,
                    completed_at,
                    created_at,
                    updated_at;
                """,
                (int(retry_delay), safe_error, int(job_id), normalized_lease_token),
            )
            return _map_projection_job_row(cursor.fetchone())


def get_projection_job_status_counts(*, job_source: str | None = None) -> dict[str, int]:
    ensure_phase1_projection_schema()
    conditions = []
    params: list[Any] = []
    normalized_job_source = str(job_source or "").strip()
    if normalized_job_source:
        conditions.append("job_source = %s")
        params.append(normalized_job_source)
    where_sql = f"WHERE {' AND '.join(conditions)}" if conditions else ""
    with get_db_connection_context() as conn:
        with conn.cursor() as cursor:
            cursor.execute(
                f"""
                SELECT
                    COALESCE(SUM(CASE WHEN status = 'pending' THEN 1 ELSE 0 END), 0),
                    COALESCE(SUM(CASE WHEN status = 'running' THEN 1 ELSE 0 END), 0),
                    COALESCE(SUM(CASE WHEN status = 'done' THEN 1 ELSE 0 END), 0),
                    COALESCE(SUM(CASE WHEN status = 'failed' THEN 1 ELSE 0 END), 0),
                    COALESCE(SUM(CASE WHEN status = 'pending' AND attempt_count > 0 THEN 1 ELSE 0 END), 0)
                FROM bt_3_projection_jobs
                {where_sql};
                """,
                params,
            )
            row = cursor.fetchone() or (0, 0, 0, 0, 0)
            return {
                "pending": int(row[0] or 0),
                "running": int(row[1] or 0),
                "done": int(row[2] or 0),
                "failed": int(row[3] or 0),
                "retrying": int(row[4] or 0),
            }


def list_webapp_projection_target_user_ids(*, lookback_days: int = 30) -> list[int]:
    safe_days = max(1, int(lookback_days or 1))
    with get_db_connection_context() as conn:
        with conn.cursor() as cursor:
            cursor.execute(
                """
                WITH allowlist_users AS (
                    SELECT
                        user_id,
                        MAX(updated_at) AS activity_at
                    FROM bt_3_allowed_users
                    GROUP BY user_id
                ),
                recent_activity AS (
                    SELECT q.user_id, MAX(q.created_at) AS activity_at
                    FROM bt_3_webapp_dictionary_queries q
                    WHERE q.created_at >= NOW() - (%s || ' days')::interval
                    GROUP BY q.user_id
                    UNION ALL
                    SELECT c.user_id, MAX(c.created_at) AS activity_at
                    FROM bt_3_webapp_checks c
                    WHERE c.created_at >= NOW() - (%s || ' days')::interval
                    GROUP BY c.user_id
                    UNION ALL
                    SELECT p.user_id, MAX(COALESCE(p.end_time, p.start_time)) AS activity_at
                    FROM bt_3_user_progress p
                    WHERE COALESCE(p.end_time, p.start_time) >= NOW() - (%s || ' days')::interval
                    GROUP BY p.user_id
                ),
                unioned AS (
                    SELECT user_id, activity_at FROM allowlist_users
                    UNION ALL
                    SELECT user_id, activity_at FROM recent_activity
                )
                SELECT user_id
                FROM unioned
                WHERE user_id IS NOT NULL
                GROUP BY user_id
                ORDER BY MAX(activity_at) DESC NULLS LAST, user_id DESC;
                """,
                (safe_days, safe_days, safe_days),
            )
            rows = cursor.fetchall() or []
    return [int(row[0]) for row in rows if row and row[0] is not None]


def get_webapp_scope_state(user_id: int) -> dict:
    with get_db_connection_context() as conn:
        with conn.cursor() as cursor:
            cursor.execute(
                """
                SELECT
                    s.scope_kind,
                    s.scope_chat_id,
                    g.chat_title,
                    s.updated_at
                FROM bt_3_webapp_scope_state s
                LEFT JOIN bt_3_webapp_group_contexts g
                  ON g.user_id = s.user_id
                 AND g.chat_id = s.scope_chat_id
                WHERE s.user_id = %s
                LIMIT 1;
                """,
                (int(user_id),),
            )
            row = cursor.fetchone()

    if not row:
        return {
            "user_id": int(user_id),
            "scope_kind": "personal",
            "scope_chat_id": None,
            "scope_chat_title": None,
            "scope_key": "personal",
            "updated_at": None,
            "has_state": False,
        }

    scope_kind = _normalize_webapp_scope_kind(row[0])
    scope_chat_id = int(row[1]) if row[1] is not None else None
    scope_chat_title = str(row[2] or "").strip() or None
    return {
        "user_id": int(user_id),
        "scope_kind": scope_kind,
        "scope_chat_id": scope_chat_id,
        "scope_chat_title": scope_chat_title,
        "scope_key": _build_webapp_scope_key(scope_kind, scope_chat_id),
        "updated_at": row[3].isoformat() if row[3] else None,
        "has_state": True,
    }


def upsert_webapp_scope_state(
    *,
    user_id: int,
    scope_kind: str,
    scope_chat_id: int | None = None,
) -> dict:
    normalized_kind = _normalize_webapp_scope_kind(scope_kind)
    normalized_chat_id = int(scope_chat_id) if scope_chat_id is not None else None
    if normalized_kind == "group" and normalized_chat_id is None:
        raise ValueError("scope_chat_id обязателен для group scope")
    if normalized_kind == "personal":
        normalized_chat_id = None

    with get_db_connection_context() as conn:
        with conn.cursor() as cursor:
            cursor.execute(
                """
                INSERT INTO bt_3_webapp_scope_state (
                    user_id,
                    scope_kind,
                    scope_chat_id,
                    updated_at
                )
                VALUES (%s, %s, %s, NOW())
                ON CONFLICT (user_id) DO UPDATE
                SET
                    scope_kind = EXCLUDED.scope_kind,
                    scope_chat_id = EXCLUDED.scope_chat_id,
                    updated_at = NOW()
                RETURNING scope_kind, scope_chat_id, updated_at;
                """,
                (int(user_id), normalized_kind, normalized_chat_id),
            )
            row = cursor.fetchone()

    resolved_kind = _normalize_webapp_scope_kind(row[0] if row else normalized_kind)
    resolved_chat_id = int(row[1]) if row and row[1] is not None else None
    return {
        "user_id": int(user_id),
        "scope_kind": resolved_kind,
        "scope_chat_id": resolved_chat_id,
        "scope_key": _build_webapp_scope_key(resolved_kind, resolved_chat_id),
        "updated_at": row[2].isoformat() if row and row[2] else None,
        "has_state": True,
    }


def upsert_webapp_group_context(
    *,
    user_id: int,
    chat_id: int,
    chat_type: str | None = None,
    chat_title: str | None = None,
) -> dict:
    normalized_chat_type = str(chat_type or "").strip().lower()
    if normalized_chat_type not in {"group", "supergroup"}:
        normalized_chat_type = "group"
    normalized_chat_title = str(chat_title or "").strip() or None

    with get_db_connection_context() as conn:
        with conn.cursor() as cursor:
            cursor.execute(
                """
                INSERT INTO bt_3_webapp_group_contexts (
                    user_id,
                    chat_id,
                    chat_type,
                    chat_title,
                    participation_confirmed,
                    participation_confirmed_at,
                    participation_confirmed_source,
                    first_seen_at,
                    last_seen_at
                )
                VALUES (%s, %s, %s, %s, FALSE, NULL, NULL, NOW(), NOW())
                ON CONFLICT (user_id, chat_id) DO UPDATE
                SET
                    chat_type = EXCLUDED.chat_type,
                    chat_title = COALESCE(NULLIF(EXCLUDED.chat_title, ''), bt_3_webapp_group_contexts.chat_title),
                    last_seen_at = NOW()
                RETURNING
                    user_id,
                    chat_id,
                    chat_type,
                    chat_title,
                    participation_confirmed,
                    participation_confirmed_at,
                    participation_confirmed_source,
                    first_seen_at,
                    last_seen_at;
                """,
                (int(user_id), int(chat_id), normalized_chat_type, normalized_chat_title),
            )
            row = cursor.fetchone()

    return {
        "user_id": int(row[0]),
        "chat_id": int(row[1]),
        "chat_type": str(row[2] or "group"),
        "chat_title": str(row[3] or "").strip() or None,
        "participation_confirmed": bool(row[4]),
        "participation_confirmed_at": row[5].isoformat() if row[5] else None,
        "participation_confirmed_source": str(row[6] or "").strip() or None,
        "first_seen_at": row[7].isoformat() if row[7] else None,
        "last_seen_at": row[8].isoformat() if row[8] else None,
    }


def confirm_webapp_group_participation(
    *,
    user_id: int,
    chat_id: int,
    chat_type: str | None = None,
    chat_title: str | None = None,
    source: str | None = None,
) -> dict:
    normalized_chat_type = str(chat_type or "").strip().lower()
    if normalized_chat_type not in {"group", "supergroup"}:
        normalized_chat_type = "group"
    normalized_chat_title = str(chat_title or "").strip() or None
    normalized_source = str(source or "").strip() or None

    with get_db_connection_context() as conn:
        with conn.cursor() as cursor:
            cursor.execute(
                """
                SELECT participation_confirmed
                FROM bt_3_webapp_group_contexts
                WHERE user_id = %s AND chat_id = %s
                LIMIT 1;
                """,
                (int(user_id), int(chat_id)),
            )
            previous = cursor.fetchone()

            cursor.execute(
                """
                INSERT INTO bt_3_webapp_group_contexts (
                    user_id,
                    chat_id,
                    chat_type,
                    chat_title,
                    participation_confirmed,
                    participation_confirmed_at,
                    participation_confirmed_source,
                    first_seen_at,
                    last_seen_at
                )
                VALUES (%s, %s, %s, %s, TRUE, NOW(), %s, NOW(), NOW())
                ON CONFLICT (user_id, chat_id) DO UPDATE
                SET
                    chat_type = EXCLUDED.chat_type,
                    chat_title = COALESCE(NULLIF(EXCLUDED.chat_title, ''), bt_3_webapp_group_contexts.chat_title),
                    participation_confirmed = TRUE,
                    participation_confirmed_at = COALESCE(
                        bt_3_webapp_group_contexts.participation_confirmed_at,
                        NOW()
                    ),
                    participation_confirmed_source = COALESCE(
                        EXCLUDED.participation_confirmed_source,
                        bt_3_webapp_group_contexts.participation_confirmed_source
                    ),
                    last_seen_at = NOW()
                RETURNING
                    user_id,
                    chat_id,
                    chat_type,
                    chat_title,
                    participation_confirmed,
                    participation_confirmed_at,
                    participation_confirmed_source,
                    first_seen_at,
                    last_seen_at;
                """,
                (
                    int(user_id),
                    int(chat_id),
                    normalized_chat_type,
                    normalized_chat_title,
                    normalized_source,
                ),
            )
            row = cursor.fetchone()

    was_confirmed_before = bool(previous and previous[0])
    return {
        "user_id": int(row[0]),
        "chat_id": int(row[1]),
        "chat_type": str(row[2] or "group"),
        "chat_title": str(row[3] or "").strip() or None,
        "participation_confirmed": bool(row[4]),
        "participation_confirmed_at": row[5].isoformat() if row[5] else None,
        "participation_confirmed_source": str(row[6] or "").strip() or None,
        "first_seen_at": row[7].isoformat() if row[7] else None,
        "last_seen_at": row[8].isoformat() if row[8] else None,
        "was_confirmed_before": was_confirmed_before,
    }


def list_webapp_group_contexts(
    user_id: int,
    limit: int = 20,
    *,
    only_confirmed: bool = False,
) -> list[dict]:
    safe_limit = max(1, min(int(limit or 20), 100))
    with get_db_connection_context() as conn:
        with conn.cursor() as cursor:
            cursor.execute(
                """
                SELECT
                    user_id,
                    chat_id,
                    chat_type,
                    chat_title,
                    participation_confirmed,
                    participation_confirmed_at,
                    participation_confirmed_source,
                    first_seen_at,
                    last_seen_at
                FROM bt_3_webapp_group_contexts
                WHERE user_id = %s
                  AND (%s = FALSE OR participation_confirmed = TRUE)
                  AND participation_confirmed_source IS DISTINCT FROM 'auto_group_dead'
                ORDER BY last_seen_at DESC, chat_id DESC
                LIMIT %s;
                """,
                (int(user_id), bool(only_confirmed), safe_limit),
            )
            rows = cursor.fetchall()
    return [
        {
            "user_id": int(row[0]),
            "chat_id": int(row[1]),
            "chat_type": str(row[2] or "group"),
            "chat_title": str(row[3] or "").strip() or None,
            "participation_confirmed": bool(row[4]),
            "participation_confirmed_at": row[5].isoformat() if row[5] else None,
            "participation_confirmed_source": str(row[6] or "").strip() or None,
            "first_seen_at": row[7].isoformat() if row[7] else None,
            "last_seen_at": row[8].isoformat() if row[8] else None,
        }
        for row in rows
    ]


def list_webapp_group_member_user_ids(
    chat_id: int,
    limit: int = 2000,
    *,
    only_confirmed: bool = True,
) -> list[int]:
    safe_limit = max(1, min(int(limit or 2000), 10000))
    with get_db_connection_context() as conn:
        with conn.cursor() as cursor:
            cursor.execute(
                """
                SELECT user_id
                FROM bt_3_webapp_group_contexts
                WHERE chat_id = %s
                  AND (%s = FALSE OR participation_confirmed = TRUE)
                  AND participation_confirmed_source IS DISTINCT FROM 'auto_group_dead'
                ORDER BY last_seen_at DESC, user_id DESC
                LIMIT %s;
                """,
                (int(chat_id), bool(only_confirmed), safe_limit),
            )
            rows = cursor.fetchall() or []
    seen: set[int] = set()
    result: list[int] = []
    for row in rows:
        try:
            candidate = int(row[0])
        except Exception:
            continue
        if candidate in seen:
            continue
        seen.add(candidate)
        result.append(candidate)
    return result


def list_group_participants(chat_id: int) -> list[int]:
    """All user ids the bot has SEEN in a given group (for the group daily/weekly
    posters). No button confirmation required — if the bot saw you in the group,
    you count as a participant. Groups retired as dead by deactivate_group_chat
    (source='auto_group_dead') are excluded. Empty list if none."""
    with get_db_connection_context() as conn:
        with conn.cursor() as cursor:
            cursor.execute(
                """
                SELECT DISTINCT user_id
                FROM bt_3_webapp_group_contexts
                WHERE chat_id = %s AND user_id > 0
                  AND participation_confirmed_source IS DISTINCT FROM 'auto_group_dead'
                """,
                (int(chat_id),),
            )
            return [int(r[0]) for r in (cursor.fetchall() or []) if r and r[0] is not None]


def upsert_group_weekly_total(
    chat_id: int, week_start, total: int, translations: int, quizzes: int, words: int
) -> None:
    """Store/refresh one group's activity total for a given week (co-op baseline)."""
    with get_db_connection_context() as conn:
        with conn.cursor() as cursor:
            cursor.execute(
                """
                INSERT INTO bt_3_group_weekly_totals
                    (chat_id, week_start, total, translations, quizzes, words, updated_at)
                VALUES (%s, %s, %s, %s, %s, %s, NOW())
                ON CONFLICT (chat_id, week_start) DO UPDATE
                SET total = EXCLUDED.total,
                    translations = EXCLUDED.translations,
                    quizzes = EXCLUDED.quizzes,
                    words = EXCLUDED.words,
                    updated_at = NOW();
                """,
                (int(chat_id), week_start, int(total), int(translations), int(quizzes), int(words)),
            )


def get_group_recent_weekly_totals(chat_id: int, before_week_start, limit: int = 4) -> list[int]:
    """The group's `total` for up to `limit` most-recent COMPLETED weeks strictly before
    `before_week_start` — the baseline the current week is compared against. Newest first."""
    with get_db_connection_context() as conn:
        with conn.cursor() as cursor:
            cursor.execute(
                """
                SELECT total
                FROM bt_3_group_weekly_totals
                WHERE chat_id = %s AND week_start < %s
                ORDER BY week_start DESC
                LIMIT %s;
                """,
                (int(chat_id), before_week_start, int(limit)),
            )
            return [int(r[0] or 0) for r in (cursor.fetchall() or []) if r]


def deactivate_group_chat(chat_id: int) -> int:
    """Retire a group that no longer exists (deleted, bot kicked, or migrated to a new
    supergroup id). Marks ALL of the chat's membership rows as 'auto_group_dead' (not
    just the confirmed ones — the all-seen model counts every member), so its members
    stop being counted as group members and fall back to individual delivery (or to
    another live group they belong to, whose rows are untouched). Returns rows retired."""
    with get_db_connection_context() as conn:
        with conn.cursor() as cursor:
            cursor.execute(
                """
                UPDATE bt_3_webapp_group_contexts
                SET participation_confirmed = FALSE,
                    participation_confirmed_source = 'auto_group_dead'
                WHERE chat_id = %s
                  AND participation_confirmed_source IS DISTINCT FROM 'auto_group_dead'
                """,
                (int(chat_id),),
            )
            return int(cursor.rowcount or 0)


def list_known_webapp_group_chats(limit: int = 500) -> list[dict]:
    safe_limit = max(1, min(int(limit or 500), 5000))
    with get_db_connection_context() as conn:
        with conn.cursor() as cursor:
            cursor.execute(
                """
                SELECT chat_id, chat_type, chat_title, last_seen_at
                FROM (
                    SELECT DISTINCT ON (chat_id)
                        chat_id,
                        chat_type,
                        chat_title,
                        last_seen_at
                    FROM bt_3_webapp_group_contexts
                    ORDER BY chat_id, last_seen_at DESC
                ) latest
                ORDER BY last_seen_at DESC, chat_id DESC
                LIMIT %s;
                """,
                (safe_limit,),
            )
            rows = cursor.fetchall() or []
    result: list[dict] = []
    for row in rows:
        try:
            chat_id = int(row[0])
        except Exception:
            continue
        result.append(
            {
                "chat_id": chat_id,
                "chat_type": str(row[1] or "group"),
                "chat_title": str(row[2] or "").strip() or None,
                "last_seen_at": row[3].isoformat() if row[3] else None,
            }
        )
    return result


