def set_starter_dictionary_subscription(
    user_id: int, enabled: bool, *, subscription_limit: int | None = None
) -> None:
    """Включить/выключить подписку на словарь автора и задать её потолок.

    `subscription_limit=None` — без потолка («весь словарь»); число — «урезанный»:
    слова идут из той же очереди по нужности, просто их не больше указанного.
    Держится отдельно от upsert_starter_dictionary_state, чтобы десятки его вызовов
    из импорта не затирали выбор человека.
    """
    with get_db_connection_context() as conn:
        with conn.cursor() as cursor:
            cursor.execute(
                """
                INSERT INTO bt_3_starter_dictionary_state
                    (user_id, live_subscription, subscription_limit, updated_at)
                VALUES (%s, %s, %s, NOW())
                ON CONFLICT (user_id) DO UPDATE
                SET live_subscription = EXCLUDED.live_subscription,
                    subscription_limit = EXCLUDED.subscription_limit,
                    updated_at = NOW();
                """,
                (int(user_id), bool(enabled), int(subscription_limit) if subscription_limit else None),
            )
    invalidate_subscription_peek_cache(int(user_id))


def remove_untouched_subscription_words(user_id: int, cursor=None) -> int:
    """Удаляет слова, пришедшие ОТ АВТОРА, которых человек так и не коснулся.

    Правило владельца: «не учил — значит не нужно», но «трогал — значит его». Поэтому
    «нетронутое» — это не только отсутствие прогресса тренировки. Человек мог не отправить
    слово в тренировку, но переложить его в свою папку, поправить перевод или пометить
    выученным — это тоже след интереса, и такое остаётся.

    Удаляем строку, только если ВСЁ сразу: пришла от автора (подписка или старое
    копирование), нет состояния тренировки, нет ни одного ответа в журнале, не помечена
    выученной, не лежит в папке, не редактировалась после создания.

    Свои слова человека не трогаются вообще — под условие происхождения они не попадают.
    """
    def _run(cur) -> int:
        cur.execute(
            """
            DELETE FROM bt_3_webapp_dictionary_queries q
            WHERE q.user_id = %s
              AND (
                    q.origin_process = 'subscription'
                 OR (q.origin_process = 'import'
                     AND q.origin_meta->>'import_kind' = 'starter_dictionary_snapshot')
              )
              AND NOT EXISTS (
                    SELECT 1 FROM bt_3_card_srs_state s
                    WHERE s.user_id = q.user_id AND s.card_id = q.id
              )
              AND NOT EXISTS (
                    SELECT 1 FROM bt_3_card_review_log r
                    WHERE r.user_id = q.user_id AND r.card_id = q.id
              )
              AND COALESCE(q.is_learned, FALSE) = FALSE
              -- Папку НЕ считаем признаком интереса: импорт сам раскладывал слова по
              -- смысловым папкам, и из-за этого условия под защиту попадали все до одного
              -- (999 из 999 у первого же проверенного человека) — то есть не удалялось
              -- ничего. Осознанный перенос в папку виден по updated_at: перекладывание
              -- помечает запись изменённой.
              AND (q.updated_at IS NULL OR q.updated_at <= q.created_at + INTERVAL '5 seconds');
            """,
            (int(user_id),),
        )
        return int(cur.rowcount or 0)

    if cursor is not None:
        removed = _run(cursor)
    else:
        with get_db_connection_context() as conn:
            with conn.cursor() as cur:
                removed = _run(cur)
    invalidate_subscription_peek_cache(int(user_id))
    return removed


def subscription_drip_allowance(*, needed: int, delivered_total: int,
                                subscription_limit: int | None) -> int:
    """Сколько слов открыть человеку прямо сейчас.

    Правило одно: СКОЛЬКО НУЖНО. Тренажёру нужно пятнадцать карточек, своих хватило на
    девять — подписка добирает шесть. Не хватило ни одной — добирает пятнадцать.
    Человек подписался на объём и должен его получать, а не по расписанию.

    Единственный ограничитель — потолок самой подписки: «Быстрый старт» это тысяча слов,
    и больше тысячи по ней не откроется. У «Всего словаря» потолка нет."""
    allowance = max(0, int(needed or 0))
    if subscription_limit:
        left_total = int(subscription_limit) - int(delivered_total or 0)
        allowance = min(allowance, max(0, left_total))
    return max(0, allowance)


def top_up_subscription_words(
    *, user_id: int, source_user_id: int, source_lang: str | None, target_lang: str | None,
    needed: int, subscription_limit: int | None = None,
) -> int:
    """Добрать человеку недостающие слова из подписки.

    Зачем отдельно от тренажёров: раньше подписка отдавала слово ТОЛЬКО внутри очереди
    интервальных повторений, а её почти не открывают — за всё время подписка не выдала
    ни одного слова. Тренажёров пять, и вшивать подписку в каждый значило бы чинить одно
    правило в пяти местах.

    Поэтому слово просто появляется в библиотеке, а дальше его подхватывают ВСЕ
    тренажёры сами: они и так читают библиотеку. Порядок прежний — самые нужные слова
    вперёд, по частотности."""
    if int(needed or 0) <= 0:
        return 0
    allowance = subscription_drip_allowance(
        needed=int(needed),
        delivered_total=count_subscription_delivered(int(user_id)),
        subscription_limit=subscription_limit,
    )
    opened = 0
    for _ in range(allowance):
        card_id = materialize_subscription_card(
            user_id=int(user_id),
            source_user_id=int(source_user_id),
            source_lang=source_lang,
            target_lang=target_lang,
        )
        if not card_id:
            break  # подписка исчерпана — больше предлагать нечего
        opened += 1
    if opened:
        invalidate_subscription_peek_cache(int(user_id))
    return opened


def count_subscription_delivered(user_id: int, cursor=None) -> int:
    """Сколько слов человек уже получил ПО ПОДПИСКЕ (не считая своих и не считая
    скопированных когда-то «Быстрым стартом»). По этому числу считается потолок."""
    def _run(cur) -> int:
        cur.execute(
            """
            SELECT COUNT(*) FROM bt_3_webapp_dictionary_queries
            WHERE user_id = %s AND origin_process = 'subscription';
            """,
            (int(user_id),),
        )
        row = cur.fetchone()
        return int(row[0]) if row and row[0] is not None else 0

    if cursor is not None:
        return _run(cursor)
    with get_db_connection_context() as conn:
        with conn.cursor() as cur:
            return _run(cur)


# Порядок очереди подписки: сначала самые частотные, где ранг известен (это ~четверть
# пула), потом — те, что чаще берут себе другие пользователи, и лишь затем по дате.
# «Популярность» — честный сигнал полезности из наших же данных, и он крепнет с ростом
# базы. Раньше вторым ключом стояла дата, из-за чего три четверти слов выстраивались
# в произвольном порядке.
_SUBSCRIPTION_POPULARITY_JOIN_SQL = """
        LEFT JOIN (
            SELECT canonical_entry_id, COUNT(DISTINCT user_id) AS holders
            FROM bt_3_webapp_dictionary_queries
            WHERE canonical_entry_id IS NOT NULL
            GROUP BY canonical_entry_id
        ) p ON p.canonical_entry_id = a.canonical_entry_id
"""
_SUBSCRIPTION_ORDER_BY_SQL = (
    "e.frequency_rank ASC NULLS LAST, COALESCE(p.holders, 0) DESC, a.created_at ASC"
)


def _subscription_lang_filter(alias: str, source_lang: str | None, target_lang: str | None) -> tuple[str, list]:
    """ОБЕ стороны пары (ru→de И de→ru).

    Раньше фильтр брал одно направление, и это отсекало 8238 из 13951 слов словаря-донора
    — причём именно то направление, в котором он сейчас пишет: девять из десяти новых слов
    не доходили до подписчиков вообще. Очередь тренировки двунаправленная
    (_build_language_pair_filter_both в get_next_new_srs_candidate), поэтому
    материализованная карточка подхватывается в любом направлении.
    """
    clause, params = _build_language_pair_filter_both(source_lang, target_lang, table_alias=alias)
    if not clause:
        return "", []
    return clause.lstrip().removeprefix("AND ").strip(), params


def count_admin_subscription_available_words(
    *, user_id: int, source_user_id: int, source_lang: str | None, target_lang: str | None
) -> int:
    """How many of the admin's dictionary words this user does NOT yet have (matched by shared
    canonical entry). This is the live pool a subscriber's «new cards» still draw from — it
    grows automatically as the admin adds words, with no copying. (Stage 2 wiring uses this.)"""
    s = _normalize_lang_code(source_lang) or "ru"
    t = _normalize_lang_code(target_lang) or "de"
    lang_sql, lang_params = _subscription_lang_filter("a", s, t)
    lang_clause = f"AND {lang_sql}" if lang_sql else ""
    with get_db_connection_context() as conn:
        with conn.cursor() as cur:
            cur.execute(
                f"""
                -- Считаем РАЗНЫЕ слова общей базы, у которых есть разбор: без имени
                -- человека одно слово лежит столько раз, сколько людей его сохранили.
                -- Почему без владельца и почему с разбором — см. пояснение в
                -- list_admin_subscription_new_candidates.
                SELECT COUNT(DISTINCT a.canonical_entry_id)
                FROM bt_3_webapp_dictionary_queries a
                JOIN bt_3_lex_units lu ON lu.id = a.lex_unit_id AND lu.card IS NOT NULL
                WHERE a.canonical_entry_id IS NOT NULL
                  {lang_clause}
                  AND NOT EXISTS (
                      SELECT 1 FROM bt_3_webapp_dictionary_queries u
                      WHERE u.user_id = %s AND u.canonical_entry_id = a.canonical_entry_id
                  );
                """,
                (*lang_params, int(user_id)),
            )
            row = cur.fetchone()
    return int(row[0]) if row and row[0] is not None else 0


def has_admin_subscription_available(
    *, user_id: int, source_user_id: int, source_lang: str | None, target_lang: str | None, cursor=None
) -> bool:
    """Cheap EXISTS check (no ordering): does the subscriber still have ANY un-materialized admin
    word? Used on the hot queue path to keep the daily new-card budget non-zero for subscribers."""
    s = _normalize_lang_code(source_lang) or "ru"
    t = _normalize_lang_code(target_lang) or "de"
    lang_sql, lang_params = _subscription_lang_filter("a", s, t)
    lang_clause = f"AND {lang_sql}" if lang_sql else ""
    sql = f"""
        SELECT EXISTS (
            -- Тот же пул, что и у отбора: общая база, слово с разбором.
            SELECT 1
            FROM bt_3_webapp_dictionary_queries a
            JOIN bt_3_lex_units lu ON lu.id = a.lex_unit_id AND lu.card IS NOT NULL
            WHERE a.canonical_entry_id IS NOT NULL
              {lang_clause}
              AND NOT EXISTS (
                  SELECT 1 FROM bt_3_webapp_dictionary_queries u
                  WHERE u.user_id = %s AND u.canonical_entry_id = a.canonical_entry_id
              )
            LIMIT 1
        );
    """
    params = (*lang_params, int(user_id))

    def _run(cur) -> bool:
        cur.execute(sql, params)
        row = cur.fetchone()
        return bool(row[0]) if row else False

    if cursor is not None:
        return _run(cursor)
    with get_db_connection_context() as conn:
        with conn.cursor() as cur:
            return _run(cur)


# Слово, которое человеку предлагать незачем: голый артикль как заголовок — это не
# слово для изучения. Замер 05.08.2026: такой в словаре автора ровно один — «Eine»,
# и он стоит ПЕРВЫМ в очереди по частотности, то есть достался бы каждому подписчику.
_SUBSCRIPTION_BARE_ARTICLES = {
    "ein", "eine", "einen", "einem", "einer", "eines",
    "der", "die", "das", "den", "dem", "des",
}
_SUBSCRIPTION_RU_WORD_RE = re.compile(r"[а-я]+")


def _subscription_headword_key(text: str | None) -> str:
    """Заголовок без артикля и регистра — по нему узнаём, одно ли это слово."""
    return _normalize_dictionary_headword_key(text)


def _subscription_translation_words(text: str | None) -> set:
    """Слова перевода для сравнения. «ё» приводим к «е»: «твёрдый» и «твердый» — одно
    и то же слово, а без этого повтор «Hart» / «hart» проскакивал как разное."""
    return set(_SUBSCRIPTION_RU_WORD_RE.findall(str(text or "").lower().replace("ё", "е")))


def subscription_candidate_is_worth_offering(word_de: str | None, translation: str | None) -> bool:
    """Годится ли слово к выдаче вообще.

    Отсекаем только бесспорное: голый артикль и запись без русского перевода. Всё
    остальное оставляем — замер показал, что 95% очереди в порядке, и придирчивый
    фильтр отнял бы у людей больше, чем дал."""
    key = _subscription_headword_key(word_de)
    if not key or key in _SUBSCRIPTION_BARE_ARTICLES:
        return False
    return bool(_subscription_translation_words(translation))


def subscription_candidate_is_already_known(
    word_de: str | None, translation: str | None, owned: dict,
) -> bool:
    """Это слово человеку уже выдавали — просто в другом написании?

    Сверяем НЕ только заголовок, но и перевод. Замер 05.08.2026: из 673 совпадений по
    заголовку 194 оказались РАЗНЫМИ словами — «Der Gefallen» (одолжение) против
    «gefallen» (нравиться), «Das Verhalten» (поведение) против «Verhalten» (вести себя).
    Схлопни их по заголовку — человек потерял бы 194 настоящих слова. Поэтому повтором
    считаем только то, у чего пересекается ещё и перевод."""
    key = _subscription_headword_key(word_de)
    if not key:
        return False
    known = owned.get(key)
    if not known:
        return False
    return bool(known & _subscription_translation_words(translation))


def list_admin_subscription_new_candidates(
    *, user_id: int, source_user_id: int, source_lang: str | None, target_lang: str | None,
    limit: int = 20, cursor=None, phrases_only: bool = False,
) -> list[dict]:
    """The next admin words a subscriber hasn't materialized yet, most-frequent first (so the
    subscription drips in useful words before rare ones). Returns light rows for the new-card
    queue; the per-user copy + SRS state is created lazily on first study (Stage 3). Pass `cursor`
    so a materialize LOOP sees its own just-created rows (else it keeps returning the same word)."""
    s = _normalize_lang_code(source_lang) or "ru"
    t = _normalize_lang_code(target_lang) or "de"
    lang_sql, lang_params = _subscription_lang_filter("a", s, t)
    lang_clause = f"AND {lang_sql}" if lang_sql else ""
    phrase_clause = "AND a.is_phrase IS TRUE" if phrases_only else ""
    capped = max(1, min(int(limit or 20), 200))
    # ─────────────────────────────────────────────────────────────────────────────
    # ОТБОР ИДЁТ ПО ОБЩЕЙ БАЗЕ, А НЕ ПО СЛОВАРЮ ОДНОГО ЧЕЛОВЕКА.
    #
    # Как было до 15.08.2026: здесь стояло `a.user_id = %s` — стартовый набор брался
    # из карточек владельца. Владелец 15.08.2026: «я такой же обычный пользователь».
    # Замер того же дня: из 15 645 слов базы 15 290 (97,7%) первым сохранил он, так
    # что «его словарь» и «вся база» почти совпадали и разницы не было видно. На
    # тысяче людей она будет.
    #
    # УСЛОВИЕ КАЧЕСТВА. Раньше фильтр «только словарь владельца» работал ещё и
    # фильтром качества — случайно. Теперь требуем прямо: у слова должен быть разбор
    # в справочнике. Замер: из 15 098 слов прежнего набора у ~4 600 (31%) разбора нет,
    # и новичок получал пустую карточку. Годных слов с разбором — 10 708.
    #
    # DISTINCT ON нужен потому, что без имени человека одно и то же слово лежит в
    # базе столько раз, сколько людей его сохранили: без него один и тот же кандидат
    # приходил бы по нескольку раз подряд.
    # ─────────────────────────────────────────────────────────────────────────────
    # ⚠ ДВА ЭТАЖА СОРТИРОВКИ, И ЭТО НЕ УКРАШЕНИЕ. DISTINCT ON обязан сортировать
    # СНАЧАЛА по своему ключу, иначе Postgres его не примет. Значит внутри порядок
    # идёт по номеру слова, и «сначала самые частотные» там не работает: первый же
    # прогон 15.08.2026 выдал новичку длинные фразы без ранга. Поэтому нужный порядок
    # ставится СНАРУЖИ, после того как повторы слова уже схлопнуты.
    sql = f"""
        SELECT t.id, t.canonical_entry_id, t.word_de, t.frequency_rank, t.translation
        FROM (
                SELECT DISTINCT ON (a.canonical_entry_id)
                       a.id, a.canonical_entry_id, a.word_de, e.frequency_rank,
                       COALESCE(a.translation_ru, a.word_ru) AS translation,
                       COALESCE(p.holders, 0) AS holders, a.created_at
                FROM bt_3_webapp_dictionary_queries a
                JOIN bt_3_dictionary_entries e ON e.id = a.canonical_entry_id
                JOIN bt_3_lex_units lu ON lu.id = a.lex_unit_id AND lu.card IS NOT NULL
                {_SUBSCRIPTION_POPULARITY_JOIN_SQL}
                WHERE a.canonical_entry_id IS NOT NULL
                  {phrase_clause}
                  {lang_clause}
                  AND NOT EXISTS (
                      SELECT 1 FROM bt_3_webapp_dictionary_queries u
                      WHERE u.user_id = %s AND u.canonical_entry_id = a.canonical_entry_id
                  )
                ORDER BY a.canonical_entry_id, {_SUBSCRIPTION_ORDER_BY_SQL}
        ) t
        ORDER BY t.frequency_rank ASC NULLS LAST, t.holders DESC, t.created_at ASC
        LIMIT %s;
    """
    # Берём с запасом: часть кандидатов отсеется как повтор или как негодное слово,
    # а вызывающая сторона просит обычно один. Запас втрое перекрывает 3% отсева.
    fetch_limit = min(200, max(capped * 3, capped + 10))
    params = (*lang_params, int(user_id), fetch_limit)

    owned_sql = """
        SELECT COALESCE(word_de, ''), COALESCE(translation_ru, word_ru, '')
        FROM bt_3_webapp_dictionary_queries
        WHERE user_id = %s AND COALESCE(word_de, '') <> '';
    """

    def _run(cur) -> tuple:
        cur.execute(sql, params)
        rows = cur.fetchall() or []
        cur.execute(owned_sql, (int(user_id),))
        return rows, cur.fetchall() or []

    if cursor is not None:
        rows, owned_rows = _run(cursor)
    else:
        with get_db_connection_context() as conn:
            with conn.cursor() as cur:
                rows, owned_rows = _run(cur)

    owned: dict = {}
    for word, translation in owned_rows:
        key = _subscription_headword_key(word)
        if key:
            owned.setdefault(key, set()).update(_subscription_translation_words(translation))

    out = []
    for r in rows:
        word_de, translation = r[2], r[4]
        if not subscription_candidate_is_worth_offering(word_de, translation):
            continue
        if subscription_candidate_is_already_known(word_de, translation, owned):
            continue
        key = _subscription_headword_key(word_de)
        if key:
            owned.setdefault(key, set()).update(_subscription_translation_words(translation))
        out.append({
            "admin_card_id": int(r[0]), "canonical_entry_id": int(r[1]),
            "word_de": word_de, "frequency_rank": int(r[3]) if r[3] is not None else None,
        })
        if len(out) >= capped:
            break
    return out


def materialize_subscription_card(
    *, user_id: int, source_user_id: int, source_lang: str | None, target_lang: str | None, cursor=None
) -> int | None:
    """Lazily copy the NEXT admin subscription word (most-frequent first) into this user's own
    dictionary and return the new card_id — called only when the user actually needs a fresh new
    card and has budget. This is the «materialize on first study» step: no upfront bulk copy, and
    the ON CONFLICT (user_id, canonical_entry_id) guard makes it idempotent. Returns None when the
    subscription pool is exhausted. Pass `cursor` to run inside the caller's transaction (so the
    new row is visible to the very next candidate SELECT); otherwise opens its own connection."""
    def _do(cur) -> int | None:
        cands = list_admin_subscription_new_candidates(
            user_id=user_id, source_user_id=source_user_id,
            source_lang=source_lang, target_lang=target_lang, limit=1, cursor=cur,
        )
        if not cands:
            return None
        canonical_id = int(cands[0]["canonical_entry_id"])
        # Источник — ЛЮБАЯ карточка этого слова, а не карточка одного человека.
        # Стартовый набор больше не привязан к владельцу (см. пояснение в
        # list_admin_subscription_new_candidates), поэтому и текст берём оттуда, где
        # он лучше: сначала строки, у слова которых есть разбор, потом — самые полные.
        # source_user_id остаётся первым в очереди: его словарь вычитан руками.
        cur.execute(
            """
            SELECT q.word_ru, q.translation_de, q.word_de, q.translation_ru,
                   q.response_json, q.source_lang, q.target_lang, q.semantic_tag,
                   (u.card IS NOT NULL) AS unit_ready, q.lex_unit_id
            FROM bt_3_webapp_dictionary_queries q
            LEFT JOIN bt_3_lex_units u ON u.id = q.lex_unit_id
            WHERE q.canonical_entry_id = %s
            ORDER BY (q.user_id = %s) DESC,
                     (u.card IS NOT NULL) DESC,
                     length(COALESCE(q.response_json::text, '')) DESC
            LIMIT 1;
            """,
            (canonical_id, int(source_user_id)),
        )
        src = cur.fetchone()
        if not src:
            return None

        # ─────────────────────────────────────────────────────────────────────────
        # РАЗБОР НЕ КОПИРУЕТСЯ ЧЕЛОВЕКУ. Он кладётся НА СЛОВО — одно на всех.
        #
        # Как было до 15.08.2026: если у слова разбора ещё нет, разбор из карточки
        # владельца копировался новому человеку целиком. Решение принималось ОДИН раз,
        # в момент выдачи, и больше не пересматривалось: слово улучшали потом, а у
        # человека навсегда оставался снимок того дня. Замер: из 16 выданных по
        # подписке карточек копию несут ВСЕ 16.
        #
        # Как теперь: тот же разбор поднимается на общее слово, если там пусто. После
        # этого он виден всем, кто на слово подписан, и продолжает улучшаться. Карточка
        # человека остаётся лёгкой — читатели берут содержимое со слова (перепись:
        # docs/tasks/dictionary_readers_census.md).
        #
        # Курсор передаём свой: мы внутри чужой транзакции, второе соединение из пула
        # брать нельзя. Коммит сделает вызывающий — слово и карточка должны лечь вместе.
        # ─────────────────────────────────────────────────────────────────────────
        source_card = _coerce_json_object(src[4])
        unit_has_card = bool(src[8])
        unit_id = src[9]
        if not unit_has_card and unit_id and card_content_score(source_card) > 0:
            try:
                from backend.lex_units import save_unit_card_if_richer

                unit_has_card = save_unit_card_if_richer(
                    int(unit_id), source_card, source="выдача по подписке", cursor=cur,
                )
            except Exception:
                logging.warning(
                    "подписка: разбор не лёг на слово unit_id=%s", unit_id, exc_info=True,
                )
                unit_has_card = False
        entry_id, _inserted = _create_or_attach_user_dictionary_entry_with_cursor(
            cur,
            user_id=int(user_id),
            word_ru=src[0],
            translation_de=src[1],
            word_de=src[2],
            translation_ru=src[3],
            # Разбор приезжает с общего слова при показе. Копию кладём только в одном
            # случае: слова в слое единиц нет вовсе (lex_unit_id пуст) либо разбор на
            # него не лёг — иначе человек остался бы с пустой карточкой, а это хуже
            # лишней копии. Во всех остальных случаях карточка лёгкая.
            response_json=(
                strip_card_content_for_subscription(source_card)
                if unit_has_card else source_card
            ),
            folder_id=None,
            source_lang=src[5],
            target_lang=src[6],
            canonical_entry_id=canonical_id,
            origin_process="subscription",
            origin_meta={
                "subscription_source_user_id": int(source_user_id),
                "source_canonical_entry_id": canonical_id,
            },
            semantic_tag=src[7],
        )
        if not entry_id:
            return None

        # УКАЗАТЕЛЬ НА СЛОВО СТАВИМ СРАЗУ, В ЭТОЙ ЖЕ ТРАНЗАКЦИИ. Без него лёгкая
        # карточка была бы ПУСТОЙ: читатели берут содержимое по указателю, а он тут
        # при вставке не проставляется — его догоняет отдельный проход
        # (attach_missing_entries), и до него человек видел бы пустой экран.
        # Слово то же самое, что у исходной карточки: выдаётся ровно оно.
        if unit_id:
            cur.execute(
                "UPDATE bt_3_webapp_dictionary_queries SET lex_unit_id = %s "
                "WHERE id = %s AND lex_unit_id IS NULL;",
                (int(unit_id), int(entry_id)),
            )
        return int(entry_id)

    if cursor is not None:
        return _do(cursor)
    with get_db_connection_context() as conn:
        with conn.cursor() as own_cursor:
            result = _do(own_cursor)
        conn.commit()
    _attach_missing_entries_quietly()
    return result


def upsert_starter_dictionary_state(
    *,
    user_id: int,
    decision_status: str,
    source_user_id: int | None = None,
    template_version: str | None = None,
    source_lang: str | None = None,
    target_lang: str | None = None,
    last_imported_count: int = 0,
    decided_at: datetime | None = None,
    last_imported_at: datetime | None = None,
    import_status: str = "idle",
    active_job_id: str | None = None,
    last_error: str | None = None,
    import_started_at: datetime | None = None,
    import_finished_at: datetime | None = None,
) -> dict:
    normalized_decision = str(decision_status or "").strip().lower() or "pending"
    if normalized_decision not in {"pending", "accepted", "declined"}:
        raise ValueError("Invalid starter dictionary decision status")
    normalized_import_status = str(import_status or "idle").strip().lower() or "idle"
    if normalized_import_status not in {"idle", "running", "done", "failed"}:
        raise ValueError("Invalid starter dictionary import status")
    normalized_source = _normalize_lang_code(source_lang) or None
    normalized_target = _normalize_lang_code(target_lang) or None
    imported_count_value = max(0, int(last_imported_count or 0))
    with get_db_connection_context() as conn:
        with conn.cursor() as cursor:
            cursor.execute(
                """
                INSERT INTO bt_3_starter_dictionary_state (
                    user_id,
                    decision_status,
                    source_user_id,
                    template_version,
                    source_lang,
                    target_lang,
                    last_imported_count,
                    decided_at,
                    last_imported_at,
                    import_status,
                    active_job_id,
                    last_error,
                    import_started_at,
                    import_finished_at,
                    updated_at
                )
                VALUES (%s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s, NOW())
                ON CONFLICT (user_id) DO UPDATE
                SET
                    decision_status = EXCLUDED.decision_status,
                    source_user_id = EXCLUDED.source_user_id,
                    template_version = EXCLUDED.template_version,
                    source_lang = EXCLUDED.source_lang,
                    target_lang = EXCLUDED.target_lang,
                    last_imported_count = EXCLUDED.last_imported_count,
                    decided_at = EXCLUDED.decided_at,
                    last_imported_at = EXCLUDED.last_imported_at,
                    import_status = EXCLUDED.import_status,
                    active_job_id = EXCLUDED.active_job_id,
                    last_error = EXCLUDED.last_error,
                    import_started_at = EXCLUDED.import_started_at,
                    import_finished_at = EXCLUDED.import_finished_at,
                    updated_at = NOW()
                RETURNING
                    decision_status,
                    source_user_id,
                    template_version,
                    source_lang,
                    target_lang,
                    last_imported_count,
                    decided_at,
                    last_imported_at,
                    import_status,
                    active_job_id,
                    last_error,
                    import_started_at,
                    import_finished_at,
                    updated_at;
                """,
                (
                    int(user_id),
                    normalized_decision,
                    int(source_user_id) if source_user_id is not None else None,
                    str(template_version or "").strip() or None,
                    normalized_source,
                    normalized_target,
                    imported_count_value,
                    decided_at,
                    last_imported_at,
                    normalized_import_status,
                    str(active_job_id or "").strip() or None,
                    str(last_error or "").strip() or None,
                    import_started_at,
                    import_finished_at,
                ),
            )
            row = cursor.fetchone()
    return _map_starter_dictionary_state_row(row, user_id=int(user_id))


def count_dictionary_entries_for_language_pair(
    user_id: int,
    source_lang: str | None,
    target_lang: str | None,
    cursor=None,
    *,
    both_directions: bool = False,
) -> int:
    def _count(cur) -> int:
        where_clause = "WHERE user_id = %s"
        params: list = [int(user_id)]
        if both_directions:
            language_filter_sql, language_params = _build_language_pair_filter_both(source_lang, target_lang)
        else:
            language_filter_sql, language_params = _build_language_pair_filter(source_lang, target_lang)
        if language_filter_sql:
            where_clause += language_filter_sql
            params.extend(language_params)
        cur.execute(
            f"""
            SELECT COUNT(*)
            FROM bt_3_webapp_dictionary_queries
            {where_clause};
            """,
            params,
        )
        row = cur.fetchone()
        return int((row or [0])[0] or 0)

    if cursor is not None:
        return _count(cursor)
    with get_db_connection_context() as conn:
        with conn.cursor() as own_cursor:
            return _count(own_cursor)


