def fetch_random_pool_words(
    *,
    source_lang: str | None,
    target_lang: str | None,
    learning_lang: str | None = "de",
    limit: int = 12,
    exclude_norms=None,
) -> list[str]:
    """Random headwords in the LEARNING language from the SHARED pool
    (bt_3_dictionary_entries) — used only as a quiz-distractor fallback when a
    session/personal dictionary has too few words to fill 4 options (e.g. a single-word
    «разбор» session or a fresh account without the starter dictionary).

    Off the hot path: one small fetch per training session, not per card. The pool is a
    few thousand rows per pair, so ORDER BY RANDOM() is cheap enough. We over-fetch (×3)
    so caller-side exclusions still leave enough candidates.
    """
    safe_limit = max(1, min(60, int(limit or 12)))
    learn = str(learning_lang or "de").strip().lower()
    # word_de / word_ru are canonical, direction-independent columns (German is always in
    # word_de). Non-de/ru natives still learn German → default to word_de.
    word_col = "word_ru" if learn == "ru" else "word_de"
    src = str(source_lang or "").strip().lower()
    tgt = str(target_lang or "").strip().lower()
    exclude = {
        str(x or "").strip().lower()
        for x in (exclude_norms or set())
        if str(x or "").strip()
    }

    # В пуле лежит не только словарь: люди сохраняют оттуда фразы и целые предложения
    # из читалки и новостей. Замер 30.07.2026 по паре ru/de: из 14 339 разных значений
    # word_de одиночных слов только 26.7%, каждое пятое — предложение с точкой, 17%
    # длиннее 40 символов. Без фильтра такое прилетало в варианты ответа: рядом со
    # словом стояло «1972 erkannte die USA China an.» — и правильный ответ был очевиден,
    # а экран выглядел сломанным. Берём только то, что похоже на словарную единицу.
    alphabet_guard = (
        f" AND TRIM({word_col}) !~ '[А-Яа-яЁё]' " if word_col == "word_de"
        else f" AND TRIM({word_col}) ~ '[А-Яа-яЁё]' "
    )
    word_shaped_guard = (
        f" AND TRIM({word_col}) !~ '[.!?…]' "
        f" AND length(TRIM({word_col})) <= 32 "
        # Не больше двух значимых слов: одиночное слово или короткая связка
        # («eine Auffassung vertreten»), но не фраза и не предложение.
        f" AND COALESCE(array_length(regexp_split_to_array("
        f"     regexp_replace(TRIM({word_col}), "
        f"     '^(der|die|das|ein|eine|einen|einem|einer|eines)\\s+', '', 'i'), '\\s+'), 1), 1) <= 2 "
    ) + alphabet_guard

    def _fetch(cur) -> list[str]:
        # DISTINCT + ORDER BY RANDOM() в одном запросе Postgres не принимает
        # («for SELECT DISTINCT, ORDER BY expressions must appear in select list»),
        # поэтому раньше запрос падал ВСЕГДА, а доливка вариантов молча не работала:
        # в сессии с одним словом квиз оставался с одним вариантом. Сначала берём
        # уникальные значения, случайный порядок применяем снаружи.
        cur.execute(
            f"""
            SELECT w FROM (
                SELECT DISTINCT NULLIF(TRIM({word_col}), '') AS w
                FROM bt_3_dictionary_entries
                WHERE ((source_lang = %s AND target_lang = %s)
                    OR (source_lang = %s AND target_lang = %s))
                  AND NULLIF(TRIM({word_col}), '') IS NOT NULL
                  {word_shaped_guard}
            ) AS candidates
            ORDER BY RANDOM()
            LIMIT %s;
            """,
            [src, tgt, tgt, src, safe_limit * 3],
        )
        out: list[str] = []
        seen: set[str] = set()
        for row in cur.fetchall() or []:
            word = str((row or [None])[0] or "").strip()
            if not word:
                continue
            key = word.lower()
            if key in exclude or key in seen:
                continue
            seen.add(key)
            out.append(word)
            if len(out) >= safe_limit:
                break
        return out

    with get_db_connection_context() as conn:
        with conn.cursor() as own_cursor:
            return _fetch(own_cursor)


def delete_starter_dictionary_snapshot(
    *,
    user_id: int,
    source_lang: str | None,
    target_lang: str | None,
) -> dict:
    safe_user_id = int(user_id)
    deleted_count = 0
    with get_db_connection_context() as conn:
        with conn.cursor() as cursor:
            where_clause = """
                WHERE user_id = %s
                  AND origin_meta ->> 'import_kind' = 'starter_dictionary_snapshot'
            """
            params: list = [safe_user_id]
            language_filter_sql, language_params = _build_language_pair_filter(source_lang, target_lang)
            if language_filter_sql:
                where_clause += language_filter_sql
                params.extend(language_params)
            cursor.execute(
                f"""
                WITH doomed AS (
                    SELECT id
                    FROM bt_3_webapp_dictionary_queries
                    {where_clause}
                )
                DELETE FROM bt_3_card_srs_state
                WHERE user_id = %s
                  AND card_id IN (SELECT id FROM doomed);
                """,
                [*params, safe_user_id],
            )
            cursor.execute(
                f"""
                WITH doomed AS (
                    SELECT id
                    FROM bt_3_webapp_dictionary_queries
                    {where_clause}
                )
                DELETE FROM bt_3_card_review_log
                WHERE user_id = %s
                  AND card_id IN (SELECT id FROM doomed);
                """,
                [*params, safe_user_id],
            )
            cursor.execute(
                f"""
                DELETE FROM bt_3_webapp_dictionary_queries
                {where_clause}
                RETURNING id;
                """,
                params,
            )
            deleted_rows = cursor.fetchall() or []
            deleted_count = len(deleted_rows)
    return {
        "user_id": safe_user_id,
        "source_lang": _normalize_lang_code(source_lang),
        "target_lang": _normalize_lang_code(target_lang),
        "deleted_count": int(deleted_count),
    }


def import_starter_dictionary_snapshot(
    *,
    source_user_id: int,
    target_user_id: int,
    source_lang: str,
    target_lang: str,
    import_limit: int = 1000,
    folder_name: str = "Базовый словарь",
    folder_color: str = "#5ddcff",
    folder_icon: str = "book",
    template_version: str = "v1",
) -> dict:
    source_user = int(source_user_id)
    target_user = int(target_user_id)
    pair_source = _normalize_lang_code(source_lang) or DEFAULT_NATIVE_LANGUAGE
    pair_target = _normalize_lang_code(target_lang) or DEFAULT_LEARNING_LANGUAGE
    # Аварийный предел: строки вставляются ПО ОДНОЙ в одной транзакции под блокировкой,
    # так что абсурдный лимит держал бы её недопустимо долго. Молча не срезаем — пишем в лог.
    requested_limit = max(1, int(import_limit or 1000))
    safe_limit = min(requested_limit, 50000)
    if safe_limit != requested_limit:
        logging.warning(
            "starter import: запрошено %s записей, беру %s (построчная вставка в одной транзакции)",
            requested_limit, safe_limit,
        )
    resolved_folder_name = str(folder_name or "Базовый словарь").strip() or "Базовый словарь"
    resolved_folder_color = str(folder_color or "#5ddcff").strip() or "#5ddcff"
    resolved_folder_icon = str(folder_icon or "book").strip() or "book"
    resolved_template_version = str(template_version or "v1").strip() or "v1"
    advisory_lock_key = int.from_bytes(
        hashlib.blake2b(
            f"starter_dictionary_import:{target_user}:{pair_source}:{pair_target}".encode("utf-8"),
            digest_size=8,
        ).digest(),
        "big",
        signed=True,
    )

    with get_db_connection_context() as conn:
        with conn.cursor() as cursor:
            cursor.execute("SELECT pg_advisory_xact_lock(%s::bigint);", (advisory_lock_key,))
            cursor.execute(
                """
                SELECT id, name, color, icon, created_at
                FROM bt_3_dictionary_folders
                WHERE user_id = %s AND name = %s
                LIMIT 1;
                """,
                (target_user, resolved_folder_name),
            )
            folder_row = cursor.fetchone()
            if folder_row:
                folder_id = int(folder_row[0])
                folder_payload = {
                    "id": folder_id,
                    "name": folder_row[1],
                    "color": folder_row[2],
                    "icon": folder_row[3],
                    "created_at": folder_row[4].isoformat() if folder_row[4] else None,
                }
            else:
                cursor.execute(
                    """
                    INSERT INTO bt_3_dictionary_folders (user_id, name, color, icon)
                    VALUES (%s, %s, %s, %s)
                    RETURNING id, name, color, icon, created_at;
                    """,
                    (target_user, resolved_folder_name, resolved_folder_color, resolved_folder_icon),
                )
                created_row = cursor.fetchone()
                folder_id = int(created_row[0])
                folder_payload = {
                    "id": folder_id,
                    "name": created_row[1],
                    "color": created_row[2],
                    "icon": created_row[3],
                    "created_at": created_row[4].isoformat() if created_row[4] else None,
                }

            # Both directions: a ru↔de learner wants ALL the vocab, not just native→learning.
            language_filter_sql, language_params = _build_language_pair_filter_both(
                pair_source, pair_target, table_alias="q"
            )
            source_where = "WHERE q.user_id = %s"
            source_params: list = [source_user]
            if language_filter_sql:
                source_where += language_filter_sql
                source_params.extend(language_params)
            source_params.append(safe_limit)
            # Отбор по ЧАСТОТНОСТИ, а не по дате добавления. Раньше стояло
            # «ORDER BY created_at» — новичку доставалась тысяча самых старых слов автора,
            # то есть просто те, что были заведены первыми. Объяснить такой выбор нечем.
            # Живая подписка уже отдаёт слова «самые частотные вперёд» — теперь копия
            # работает по тому же правилу. Слова без ранга частотности идут последними.
            cursor.execute(
                f"""
                SELECT
                    q.id,
                    q.word_ru,
                    q.translation_de,
                    q.word_de,
                    q.translation_ru,
                    q.source_lang,
                    q.target_lang,
                    q.response_json,
                    q.semantic_tag,
                    (lu.card IS NOT NULL) AS unit_ready
                FROM bt_3_webapp_dictionary_queries q
                LEFT JOIN bt_3_dictionary_entries e ON e.id = q.canonical_entry_id
                LEFT JOIN bt_3_lex_units lu ON lu.id = q.lex_unit_id
                {source_where}
                ORDER BY e.frequency_rank ASC NULLS LAST, q.created_at ASC, q.id ASC
                LIMIT %s;
                """,
                source_params,
            )
            source_rows = cursor.fetchall() or []

            candidates: list[dict] = []
            candidate_keys: set[tuple[str, str]] = set()
            for row in source_rows:
                row_source_lang = _normalize_lang_code(row[5]) or pair_source
                row_target_lang = _normalize_lang_code(row[6]) or pair_target
                response_payload = _coerce_json_object(row[7])
                semantic_tag = normalize_dictionary_semantic_tag(
                    row[8]
                    or response_payload.get("semantic_category")
                    or response_payload.get("semantic_tag")
                )
                source_text, target_text = _resolve_dictionary_source_target_texts(
                    source_lang=row_source_lang,
                    target_lang=row_target_lang,
                    word_ru=row[1],
                    translation_de=row[2],
                    word_de=row[3],
                    translation_ru=row[4],
                    response_json=response_payload,
                )
                if not source_text or not target_text:
                    continue
                # Стартовый словарь — это снимок ЧУЖИХ карточек, и битая карточка
                # расходится по всем новичкам. Так одна старая запись «Взять*» без
                # немецкой стороны уехала десяти людям: когда немецкого нет, обе
                # стороны заполняются одним и тем же русским текстом, и проверка «непусто»
                # такое пропускает. Отсеиваем здесь, у источника раздачи.
                if _normalize_dictionary_text_key(source_text) == _normalize_dictionary_text_key(target_text):
                    continue
                if "de" in {row_source_lang, row_target_lang}:
                    german_side = source_text if row_source_lang == "de" else target_text
                    if not re.search(r"[A-Za-zÄÖÜäöüß]", german_side or ""):
                        continue  # немецкой стороны по факту нет — учить нечему
                key = (
                    _normalize_dictionary_text_key(source_text),
                    _normalize_dictionary_text_key(target_text),
                )
                if key in candidate_keys:
                    continue
                candidate_keys.add(key)

                resolved_word_ru = None
                resolved_translation_de = None
                resolved_word_de = None
                resolved_translation_ru = None

                if pair_source == "ru":
                    resolved_word_ru = source_text
                if pair_source == "de":
                    resolved_word_de = source_text
                if pair_target == "de":
                    resolved_translation_de = target_text
                    if not resolved_word_de:
                        resolved_word_de = target_text
                if pair_target == "ru":
                    resolved_translation_ru = target_text
                    if not resolved_word_ru:
                        resolved_word_ru = target_text
                if pair_source == "ru" and not resolved_translation_ru:
                    resolved_translation_ru = source_text
                if pair_source == "de" and not resolved_translation_de:
                    resolved_translation_de = source_text

                # Копия слова человеку не нужна: разбор приезжает с единицы при показе.
                # Оставляем опознавательные поля, а разбор копируем только когда на
                # единице его ещё нет — пустая карточка хуже лишней копии.
                merged_response = dict(
                    strip_card_content_for_subscription(response_payload)
                    if row[9] else response_payload
                )
                merged_response["source_text"] = source_text
                merged_response["target_text"] = target_text
                merged_response["source_lang"] = pair_source
                merged_response["target_lang"] = pair_target
                if semantic_tag:
                    merged_response["semantic_category"] = semantic_tag
                pair_payload = merged_response.get("language_pair")
                if not isinstance(pair_payload, dict):
                    pair_payload = {}
                pair_payload["source_lang"] = pair_source
                pair_payload["target_lang"] = pair_target
                merged_response["language_pair"] = pair_payload

                candidates.append(
                    {
                        "source_entry_id": int(row[0]),
                        "key": key,
                        "word_ru": resolved_word_ru,
                        "translation_de": resolved_translation_de,
                        "word_de": resolved_word_de,
                        "translation_ru": resolved_translation_ru,
                        "response_json": merged_response,
                        "semantic_tag": semantic_tag,
                    }
                )

            target_where = "WHERE user_id = %s"
            target_params: list = [target_user]
            if language_filter_sql:
                target_where += language_filter_sql
                target_params.extend(language_params)
            cursor.execute(
                f"""
                SELECT
                    word_ru,
                    translation_de,
                    word_de,
                    translation_ru,
                    source_lang,
                    target_lang,
                    response_json
                FROM bt_3_webapp_dictionary_queries
                {target_where};
                """,
                target_params,
            )
            target_rows = cursor.fetchall() or []
            existing_keys: set[tuple[str, str]] = set()
            for row in target_rows:
                existing_source, existing_target = _resolve_dictionary_source_target_texts(
                    source_lang=_normalize_lang_code(row[4]) or pair_source,
                    target_lang=_normalize_lang_code(row[5]) or pair_target,
                    word_ru=row[0],
                    translation_de=row[1],
                    word_de=row[2],
                    translation_ru=row[3],
                    response_json=_coerce_json_object(row[6]),
                )
                if not existing_source or not existing_target:
                    continue
                existing_keys.add(
                    (
                        _normalize_dictionary_text_key(existing_source),
                        _normalize_dictionary_text_key(existing_target),
                    )
                )

            skipped_existing_count = 0
            inserted_count = 0
            semantic_foldered_count = 0
            import_started_at = datetime.now(timezone.utc)
            for item in candidates:
                if item["key"] in existing_keys:
                    skipped_existing_count += 1
                    continue
                item_semantic_tag = normalize_dictionary_semantic_tag(item.get("semantic_tag"))
                item_persisted_semantic_tag = ""
                item_folder_id = int(folder_id) if folder_id is not None else None
                if item_semantic_tag:
                    try:
                        semantic_folder = _get_or_create_dictionary_semantic_folder_with_cursor(
                            cursor,
                            int(target_user),
                            item_semantic_tag,
                        )
                        if semantic_folder and semantic_folder.get("id") is not None:
                            item_folder_id = int(semantic_folder["id"])
                            item_persisted_semantic_tag = item_semantic_tag
                    except Exception:
                        logging.warning(
                            "starter dictionary semantic folder resolve failed target_user=%s source_entry_id=%s tag=%s",
                            int(target_user),
                            item.get("source_entry_id"),
                            item_semantic_tag,
                            exc_info=True,
                        )
                origin_meta = {
                    "import_kind": "starter_dictionary_snapshot",
                    "import_source_user_id": source_user,
                    "source_entry_id": item["source_entry_id"],
                    "template_version": resolved_template_version,
                    "source_lang": pair_source,
                    "target_lang": pair_target,
                    "semantic_tag": item_persisted_semantic_tag or None,
                }
                _entry_id, inserted = _save_webapp_dictionary_query_returning_id_with_conn(
                    conn,
                    user_id=int(target_user),
                    word_ru=item["word_ru"],
                    translation_de=item["translation_de"],
                    word_de=item["word_de"],
                    translation_ru=item["translation_ru"],
                    response_json=item["response_json"],
                    folder_id=item_folder_id,
                    source_lang=pair_source,
                    target_lang=pair_target,
                    origin_process="import",
                    origin_meta=origin_meta,
                    semantic_tag=item_persisted_semantic_tag or None,
                )
                if inserted:
                    inserted_count += 1
                    if item_persisted_semantic_tag:
                        semantic_foldered_count += 1
                else:
                    skipped_existing_count += 1
                existing_keys.add(item["key"])

    # Импорт кладёт карточки пачкой мимо обычного пути сохранения — сразу подбираем
    # их, чтобы у новичка слова с первой минуты были связаны со словарём.
    if inserted_count:
        _attach_missing_entries_quietly()
    return {
        "source_user_id": source_user,
        "target_user_id": target_user,
        "source_lang": pair_source,
        "target_lang": pair_target,
        "import_limit": safe_limit,
        "selected_count": len(source_rows),
        "candidates_count": len(candidates),
        "inserted_count": inserted_count,
        "skipped_existing_count": skipped_existing_count,
        "semantic_foldered_count": semantic_foldered_count,
        "folder": folder_payload,
        "template_version": resolved_template_version,
        "imported_at": import_started_at.isoformat(),
    }


def get_dictionary_entries_for_tts_prewarm(
    *,
    limit: int = 200,
    lookback_hours: int = 168,
) -> list[dict]:
    safe_limit = max(1, min(int(limit), 2000))
    safe_hours = max(1, min(int(lookback_hours), 24 * 90))
    with get_db_connection_context() as conn:
        with conn.cursor() as cursor:
            cursor.execute(
                """
                SELECT
                    id,
                    user_id,
                    word_ru,
                    translation_de,
                    word_de,
                    translation_ru,
                    source_lang,
                    target_lang,
                    response_json,
                    created_at
                FROM bt_3_webapp_dictionary_queries
                WHERE created_at >= NOW() - (%s || ' hours')::interval
                ORDER BY created_at DESC
                LIMIT %s;
                """,
                (safe_hours, safe_limit),
            )
            rows = cursor.fetchall()

    items: list[dict] = []
    for row in rows:
        items.append(
            {
                "id": int(row[0]),
                "user_id": int(row[1]),
                "word_ru": row[2],
                "translation_de": row[3],
                "word_de": row[4],
                "translation_ru": row[5],
                "source_lang": row[6],
                "target_lang": row[7],
                "response_json": row[8],
                "created_at": row[9].isoformat() if row[9] else None,
            }
        )
    return items


def get_recent_dictionary_user_ids(
    *,
    limit: int = 100,
    lookback_hours: int = 168,
) -> list[int]:
    safe_limit = max(1, min(int(limit), 2000))
    safe_hours = max(1, min(int(lookback_hours), 24 * 180))
    with get_db_connection_context() as conn:
        with conn.cursor() as cursor:
            cursor.execute(
                """
                SELECT user_id, MAX(created_at) AS last_created_at
                FROM bt_3_webapp_dictionary_queries
                WHERE created_at >= NOW() - (%s || ' hours')::interval
                GROUP BY user_id
                ORDER BY last_created_at DESC
                LIMIT %s;
                """,
                (safe_hours, safe_limit),
            )
            rows = cursor.fetchall()
    return [int(row[0]) for row in rows if row and row[0] is not None]


def create_deepdive_card(
    *,
    user_id: int,
    source_text: str,
    target_text: str,
    source_lang: str,
    target_lang: str,
    context_text: str = "",
) -> int | None:
    """Persist the word context for a quiz-result deep-dive (🔊/📌/🧩/❓) and
    return its id. The DM card links to the Mini-App via ?startapp=dive_<id>."""
    try:
        with get_db_connection_context() as conn:
            with conn.cursor() as cursor:
                cursor.execute(
                    """
                    INSERT INTO bt_3_deepdive_cards
                        (user_id, source_text, target_text, source_lang, target_lang, context_text)
                    VALUES (%s, %s, %s, %s, %s, %s)
                    RETURNING id;
                    """,
                    (
                        int(user_id),
                        str(source_text or "").strip(),
                        str(target_text or "").strip(),
                        str(source_lang or "").strip().lower(),
                        str(target_lang or "").strip().lower(),
                        str(context_text or "").strip(),
                    ),
                )
                row = cursor.fetchone()
        return int(row[0]) if row and row[0] is not None else None
    except Exception:
        logging.exception("❌ create_deepdive_card failed user_id=%s", user_id)
        return None


def get_deepdive_card(card_id: int) -> dict | None:
    """Return a deep-dive card row as a dict (or None)."""
    try:
        cid = int(card_id)
    except (TypeError, ValueError):
        return None
    if cid <= 0:
        return None
    with get_db_connection_context() as conn:
        with conn.cursor() as cursor:
            cursor.execute(
                """
                SELECT id, user_id, source_text, target_text,
                       source_lang, target_lang, context_text
                FROM bt_3_deepdive_cards
                WHERE id = %s;
                """,
                (cid,),
            )
            row = cursor.fetchone()
    if not row:
        return None
    return {
        "id": int(row[0]),
        "user_id": int(row[1]),
        "source_text": str(row[2] or ""),
        "target_text": str(row[3] or ""),
        "source_lang": str(row[4] or ""),
        "target_lang": str(row[5] or ""),
        "context_text": str(row[6] or ""),
    }


def create_mc_dispatch(
    *,
    user_id: int,
    chat_id: int,
    question: str,
    options: list,
    correct_option_id: int,
    correct_text: str,
    explanation: str = "",
    quiz_type: str = "",
    word_ru: str = "",
    freeform_option: str = "",
    hide_correct: bool = False,
    deepdive_card_id: int | None = None,
) -> int | None:
    """Persist a multiple-choice quiz as a Mini-App interactive; return its id."""
    try:
        with get_db_connection_context() as conn:
            with conn.cursor() as cursor:
                cursor.execute(
                    """
                    INSERT INTO bt_3_mc_dispatches
                        (user_id, chat_id, question, options_json, correct_option_id,
                         correct_text, explanation, quiz_type, word_ru, freeform_option,
                         hide_correct, deepdive_card_id)
                    VALUES (%s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s)
                    RETURNING id;
                    """,
                    (
                        int(user_id), int(chat_id), str(question or ""),
                        json.dumps([str(o) for o in (options or [])], ensure_ascii=False),
                        int(correct_option_id), str(correct_text or ""),
                        str(explanation or ""), str(quiz_type or ""), str(word_ru or ""),
                        str(freeform_option or ""), bool(hide_correct),
                        int(deepdive_card_id) if deepdive_card_id else None,
                    ),
                )
                row = cursor.fetchone()
        return int(row[0]) if row and row[0] is not None else None
    except Exception:
        logging.exception("❌ create_mc_dispatch failed user_id=%s", user_id)
        return None


def get_mc_dispatch_by_id(dispatch_id: int) -> dict | None:
    try:
        did = int(dispatch_id)
    except (TypeError, ValueError):
        return None
    with get_db_connection_context() as conn:
        with conn.cursor() as cursor:
            cursor.execute(
                """
                SELECT id, user_id, chat_id, question, options_json, correct_option_id,
                       correct_text, explanation, quiz_type, word_ru, freeform_option,
                       hide_correct, deepdive_card_id, telegram_message_id
                FROM bt_3_mc_dispatches
                WHERE id = %s;
                """,
                (did,),
            )
            row = cursor.fetchone()
    if not row:
        return None
    options = row[4]
    if isinstance(options, str):
        try:
            options = json.loads(options)
        except Exception:
            options = []
    return {
        "id": int(row[0]),
        "user_id": int(row[1]),
        "chat_id": int(row[2]),
        "question": str(row[3] or ""),
        "options": list(options or []),
        "correct_option_id": int(row[5]),
        "correct_text": str(row[6] or ""),
        "explanation": str(row[7] or ""),
        "quiz_type": str(row[8] or ""),
        "word_ru": str(row[9] or ""),
        "freeform_option": str(row[10] or ""),
        "hide_correct": bool(row[11]),
        "deepdive_card_id": int(row[12]) if row[12] is not None else None,
        "telegram_message_id": int(row[13]) if row[13] is not None else None,
    }


def get_mc_answer(*, dispatch_id: int, user_id: int) -> dict | None:
    with get_db_connection_context() as conn:
        with conn.cursor() as cursor:
            cursor.execute(
                """
                SELECT selected_option_id, freeform_text, is_correct
                FROM bt_3_mc_answers
                WHERE dispatch_id = %s AND user_id = %s;
                """,
                (int(dispatch_id), int(user_id)),
            )
            row = cursor.fetchone()
    if not row:
        return None
    return {
        "selected_option_id": int(row[0]),
        "freeform_text": str(row[1] or ""),
        "is_correct": bool(row[2]),
    }


def record_mc_answer(
    *, dispatch_id: int, user_id: int, selected_option_id: int,
    freeform_text: str, is_correct: bool,
) -> None:
    with get_db_connection_context() as conn:
        with conn.cursor() as cursor:
            cursor.execute(
                """
                INSERT INTO bt_3_mc_answers
                    (dispatch_id, user_id, selected_option_id, freeform_text, is_correct)
                VALUES (%s, %s, %s, %s, %s)
                ON CONFLICT (dispatch_id, user_id) DO NOTHING;
                """,
                (int(dispatch_id), int(user_id), int(selected_option_id),
                 str(freeform_text or ""), bool(is_correct)),
            )


def update_mc_dispatch_telegram_id(dispatch_id: int, telegram_message_id: int) -> None:
    with get_db_connection_context() as conn:
        with conn.cursor() as cursor:
            cursor.execute(
                "UPDATE bt_3_mc_dispatches SET telegram_message_id = %s WHERE id = %s;",
                (int(telegram_message_id), int(dispatch_id)),
            )


def set_mc_deepdive_card_id(dispatch_id: int, card_id: int) -> None:
    """Attach a (once-created) deep-dive card to the mc dispatch so the result's
    📌/🧩 don't mint a fresh card on every open."""
    with get_db_connection_context() as conn:
        with conn.cursor() as cursor:
            cursor.execute(
                "UPDATE bt_3_mc_dispatches SET deepdive_card_id = %s WHERE id = %s AND deepdive_card_id IS NULL;",
                (int(card_id), int(dispatch_id)),
            )


def _coerce_inbox_keyboard_json(value) -> list | None:
    """JSONB may come back as a parsed list or a raw string depending on the driver."""
    if value is None:
        return None
    if isinstance(value, (list, tuple)):
        return list(value)
    if isinstance(value, str):
        try:
            parsed = json.loads(value)
            return parsed if isinstance(parsed, list) else None
        except Exception:
            return None
    return None


def record_interactive_inbox(
    *, user_id: int, kind: str, dispatch_id: int, chat_id: int,
    telegram_message_id: int | None = None, deeplink: str = "", title: str = "",
    keyboard_json: list | None = None, pushed: bool = True,
) -> None:
    """Add a task to the user's interactive inbox (idempotent per task).

    pushed=False → the card was HELD (windowed user out of window); a release job
    delivers these as one batch when their window opens (Этап 3f).
    keyboard_json (optional): the card's original inline keyboard as
    [[{text, url|callback_data}, …], …] so the ✅ edit can keep ALL its buttons
    and just prepend a "✅ Выполнено" row."""
    try:
        kb_dump = json.dumps(keyboard_json, ensure_ascii=False) if keyboard_json else None
        with get_db_connection_context() as conn:
            with conn.cursor() as cursor:
                cursor.execute(
                    """
                    INSERT INTO bt_3_interactive_inbox
                        (user_id, kind, dispatch_id, chat_id, telegram_message_id, deeplink, title, keyboard_json, pushed)
                    VALUES (%s, %s, %s, %s, %s, %s, %s, %s, %s)
                    ON CONFLICT (user_id, kind, dispatch_id) DO UPDATE
                        SET telegram_message_id = COALESCE(EXCLUDED.telegram_message_id,
                                                           bt_3_interactive_inbox.telegram_message_id),
                            deeplink = EXCLUDED.deeplink,
                            title = EXCLUDED.title,
                            keyboard_json = COALESCE(EXCLUDED.keyboard_json, bt_3_interactive_inbox.keyboard_json);
                    """,
                    (int(user_id), str(kind), int(dispatch_id), int(chat_id),
                     int(telegram_message_id) if telegram_message_id else None,
                     str(deeplink or ""), str(title or ""), kb_dump, bool(pushed)),
                )
    except Exception:
        logging.warning("record_interactive_inbox failed user=%s kind=%s id=%s",
                        user_id, kind, dispatch_id, exc_info=True)


def mark_interactive_inbox_answered(*, user_id: int, kind: str, dispatch_id: int) -> dict | None:
    """Flip a task to answered (once). Returns the row (chat_id/message_id/deeplink/
    title) only on the first flip, so the caller can mark the message ✅; None if
    no such row or it was already answered."""
    try:
        with get_db_connection_context() as conn:
            with conn.cursor() as cursor:
                cursor.execute(
                    """
                    UPDATE bt_3_interactive_inbox
                    SET answered = TRUE, answered_at = NOW()
                    WHERE user_id = %s AND kind = %s AND dispatch_id = %s AND answered = FALSE
                    RETURNING chat_id, telegram_message_id, deeplink, title, keyboard_json;
                    """,
                    (int(user_id), str(kind), int(dispatch_id)),
                )
                row = cursor.fetchone()
        if not row:
            return None
        return {
            "chat_id": int(row[0]) if row[0] is not None else 0,
            "telegram_message_id": int(row[1]) if row[1] is not None else None,
            "deeplink": str(row[2] or ""),
            "title": str(row[3] or ""),
            "keyboard_json": _coerce_inbox_keyboard_json(row[4]),
        }
    except Exception:
        logging.warning("mark_interactive_inbox_answered failed user=%s kind=%s id=%s",
                        user_id, kind, dispatch_id, exc_info=True)
        return None


def mark_interactive_inbox_answered_all_kind(*, user_id: int, kind: str) -> list[dict]:
    """Flip ALL still-open inbox rows of a kind to answered (for self-contained
    games opened via a generic ?startapp=ans_<kind>_0 deeplink, where the submit
    endpoint doesn't know the exact dispatch id). Returns the freshly-flipped rows
    (id/chat_id/message_id/deeplink/title) so the caller can mark each message ✅."""
    try:
        with get_db_connection_context() as conn:
            with conn.cursor() as cursor:
                cursor.execute(
                    """
                    UPDATE bt_3_interactive_inbox
                    SET answered = TRUE, answered_at = NOW()
                    WHERE user_id = %s AND kind = %s AND answered = FALSE
                    RETURNING id, chat_id, telegram_message_id, deeplink, title, keyboard_json;
                    """,
                    (int(user_id), str(kind)),
                )
                rows = cursor.fetchall() or []
        return [
            {
                "id": int(r[0]),
                "chat_id": int(r[1]) if r[1] is not None else 0,
                "telegram_message_id": int(r[2]) if r[2] is not None else None,
                "deeplink": str(r[3] or ""),
                "title": str(r[4] or ""),
                "keyboard_json": _coerce_inbox_keyboard_json(r[5]),
            }
            for r in rows
        ]
    except Exception:
        logging.warning("mark_interactive_inbox_answered_all_kind failed user=%s kind=%s",
                        user_id, kind, exc_info=True)
        return []


def get_oldest_unanswered_inbox(user_id: int, *, max_age_days: int = 3) -> dict | None:
    """Oldest still-open (unanswered, recent) task for the jump button."""
    with get_db_connection_context() as conn:
        with conn.cursor() as cursor:
            cursor.execute(
                """
                SELECT kind, dispatch_id, deeplink, title, created_at
                FROM bt_3_interactive_inbox
                WHERE user_id = %s AND answered = FALSE
                  AND created_at > NOW() - (%s || ' days')::interval
                ORDER BY created_at ASC
                LIMIT 1;
                """,
                (int(user_id), int(max_age_days)),
            )
            row = cursor.fetchone()
    if not row:
        return None
    return {
        "kind": str(row[0] or ""),
        "dispatch_id": int(row[1]),
        "deeplink": str(row[2] or ""),
        "title": str(row[3] or ""),
    }


def get_inbox_next_and_count(user_id: int, *, max_age_days: int = 3) -> dict:
    """One round-trip for the "▶️ Следующее задание" button: the oldest open task
    AND the open count, on a single connection (was 2 separate queries)."""
    out = {"next": None, "open_count": 0}
    try:
        with get_db_connection_context() as conn:
            with conn.cursor() as cursor:
                cursor.execute(
                    """
                    SELECT kind, dispatch_id, deeplink, title,
                           COUNT(*) OVER () AS open_count
                    FROM bt_3_interactive_inbox
                    WHERE user_id = %s AND answered = FALSE
                      AND created_at > NOW() - (%s || ' days')::interval
                    ORDER BY created_at ASC
                    LIMIT 1;
                    """,
                    (int(user_id), int(max_age_days)),
                )
                row = cursor.fetchone()
        if row:
            out["next"] = {
                "kind": str(row[0] or ""),
                "dispatch_id": int(row[1]),
                "deeplink": str(row[2] or ""),
                "title": str(row[3] or ""),
            }
            out["open_count"] = int(row[4] or 0)
    except Exception:
        logging.warning("get_inbox_next_and_count failed user=%s", user_id, exc_info=True)
    return out


def count_open_inbox(user_id: int, *, max_age_days: int = 3) -> int:
    with get_db_connection_context() as conn:
        with conn.cursor() as cursor:
            cursor.execute(
                """
                SELECT COUNT(*) FROM bt_3_interactive_inbox
                WHERE user_id = %s AND answered = FALSE
                  AND created_at > NOW() - (%s || ' days')::interval;
                """,
                (int(user_id), int(max_age_days)),
            )
            row = cursor.fetchone()
    return int(row[0]) if row and row[0] is not None else 0


def get_inbox_open_today(user_id: int, *, since_ts, limit: int = 3, kind: str | None = None) -> dict:
    """Up to `limit` OLDEST still-open tasks created since `since_ts` (start of the
    user's day) + the total open count, in one round-trip — for the «Следующее
    задание» card's 2/3 buttons. Optional `kind` filter for the type chooser.

    Rows WITHOUT a deeplink are skipped: some kinds (article-quiz) are answered by
    inline buttons in the chat and have no Mini-App screen to open, so they belong in
    the daily count (get_inbox_delivery_stats_today) but never on this card."""
    out = {"tasks": [], "open_count": 0}
    where = ("user_id = %s AND answered = FALSE AND created_at >= %s "
             "AND COALESCE(deeplink, '') <> ''")
    params: list = [int(user_id), since_ts]
    if kind:
        where += " AND kind = %s"
        params.append(str(kind))
    params.append(max(1, int(limit)))
    try:
        with get_db_connection_context() as conn:
            with conn.cursor() as cursor:
                cursor.execute(
                    f"""
                    SELECT kind, dispatch_id, deeplink, title,
                           COUNT(*) OVER () AS open_count
                    FROM bt_3_interactive_inbox
                    WHERE {where}
                    ORDER BY created_at ASC
                    LIMIT %s;
                    """,
                    tuple(params),
                )
                rows = cursor.fetchall() or []
        for r in rows:
            out["tasks"].append({
                "kind": str(r[0] or ""),
                "dispatch_id": int(r[1]),
                "deeplink": str(r[2] or ""),
                "title": str(r[3] or ""),
            })
        if rows:
            out["open_count"] = int(rows[0][4] or 0)
    except Exception:
        logging.warning("get_inbox_open_today failed user=%s", user_id, exc_info=True)
    return out


def get_inbox_open_kinds_today(user_id: int, *, since_ts) -> list:
    """Distinct open kinds (with counts) created since `since_ts`, oldest-first — for
    the «Выбрать тип» chooser. Deeplink-less kinds are skipped for the same reason as
    in get_inbox_open_today — picking them would render a card with no buttons."""
    out: list = []
    try:
        with get_db_connection_context() as conn:
            with conn.cursor() as cursor:
                cursor.execute(
                    """
                    SELECT kind, COUNT(*) AS n, MIN(created_at) AS first_at
                    FROM bt_3_interactive_inbox
                    WHERE user_id = %s AND answered = FALSE AND created_at >= %s
                      AND COALESCE(deeplink, '') <> ''
                    GROUP BY kind
                    ORDER BY first_at ASC;
                    """,
                    (int(user_id), since_ts),
                )
                rows = cursor.fetchall() or []
        out = [(str(r[0] or ""), int(r[1] or 0)) for r in rows if r and r[0]]
    except Exception:
        logging.warning("get_inbox_open_kinds_today failed user=%s", user_id, exc_info=True)
    return out


def get_users_with_held_inbox(since_ts) -> list:
    """Distinct user_ids that have HELD (pushed=FALSE), still-open inbox items since
    `since_ts` — the release job's work list (Этап 3f)."""
    try:
        with get_db_connection_context() as conn:
            with conn.cursor() as cursor:
                cursor.execute(
                    "SELECT DISTINCT user_id FROM bt_3_interactive_inbox "
                    "WHERE pushed = FALSE AND answered = FALSE AND created_at >= %s;",
                    (since_ts,),
                )
                rows = cursor.fetchall() or []
        return [int(r[0]) for r in rows if r and r[0] is not None]
    except Exception:
        logging.warning("get_users_with_held_inbox failed", exc_info=True)
        return []


def get_held_inbox(user_id: int, *, since_ts, limit: int = 20) -> list:
    """The user's HELD (pushed=FALSE, open) tasks since `since_ts`, oldest-first."""
    out: list = []
    try:
        with get_db_connection_context() as conn:
            with conn.cursor() as cursor:
                cursor.execute(
                    """
                    SELECT kind, dispatch_id, deeplink, title
                    FROM bt_3_interactive_inbox
                    WHERE user_id = %s AND pushed = FALSE AND answered = FALSE AND created_at >= %s
                    ORDER BY created_at ASC
                    LIMIT %s;
                    """,
                    (int(user_id), since_ts, max(1, int(limit))),
                )
                for r in cursor.fetchall() or []:
                    out.append({"kind": str(r[0] or ""), "dispatch_id": int(r[1]),
                                "deeplink": str(r[2] or ""), "title": str(r[3] or "")})
    except Exception:
        logging.warning("get_held_inbox failed user=%s", user_id, exc_info=True)
    return out


def mark_inbox_pushed(user_id: int, *, since_ts) -> int:
    """Flip the user's HELD rows (since since_ts) to pushed=TRUE after the batch is
    delivered. Returns how many rows flipped."""
    try:
        with get_db_connection_context() as conn:
            with conn.cursor() as cursor:
                cursor.execute(
                    "UPDATE bt_3_interactive_inbox SET pushed = TRUE "
                    "WHERE user_id = %s AND pushed = FALSE AND created_at >= %s;",
                    (int(user_id), since_ts),
                )
                n = cursor.rowcount
            conn.commit()
        return int(n or 0)
    except Exception:
        logging.warning("mark_inbox_pushed failed user=%s", user_id, exc_info=True)
        return 0


# ── Daily send-rotation skips (Этап 0) ───────────────────────────────────────
# The bot's rotation gate thins the daily firehose to a fixed budget; a thinned
# slot doesn't deliver today. We record those skips so BOTH send-plan dashboards
# (bot DM + Mini-App) can show "ротация" instead of a false "не отправлено".
_rotation_skips_schema_ready = False


def _ensure_rotation_skips_schema() -> None:
    global _rotation_skips_schema_ready
    if _rotation_skips_schema_ready:
        return
    with get_db_connection_context() as conn:
        with conn.cursor() as cursor:
            cursor.execute(
                """
                CREATE TABLE IF NOT EXISTS bt_3_rotation_skips (
                    plan_date  DATE     NOT NULL,
                    kind       TEXT     NOT NULL,
                    hour       SMALLINT NOT NULL,
                    minute     SMALLINT NOT NULL,
                    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
                    PRIMARY KEY (plan_date, kind, hour, minute)
                );
                """
            )
        conn.commit()
    _rotation_skips_schema_ready = True


def record_rotation_skip(plan_date, kind: str, hour: int, minute: int) -> None:
    """Record that the daily rotation thinned this (kind, slot) on plan_date.
    Best-effort: a failure here must never block the scheduler."""
    try:
        _ensure_rotation_skips_schema()
        with get_db_connection_context() as conn:
            with conn.cursor() as cursor:
                cursor.execute(
                    """
                    INSERT INTO bt_3_rotation_skips (plan_date, kind, hour, minute)
                    VALUES (%s, %s, %s, %s)
                    ON CONFLICT (plan_date, kind, hour, minute) DO NOTHING;
                    """,
                    (plan_date, str(kind), int(hour), int(minute)),
                )
            conn.commit()
    except Exception:
        logging.warning("record_rotation_skip failed kind=%s %02d:%02d",
                        kind, int(hour), int(minute), exc_info=True)


def get_rotation_skips_today(plan_date) -> set:
    """Set of (kind, hour, minute) thinned by the daily rotation on plan_date."""
    try:
        _ensure_rotation_skips_schema()
        with get_db_connection_context() as conn:
            with conn.cursor() as cursor:
                cursor.execute(
                    "SELECT kind, hour, minute FROM bt_3_rotation_skips WHERE plan_date = %s;",
                    (plan_date,),
                )
                rows = cursor.fetchall() or []
        return {(str(r[0]), int(r[1]), int(r[2])) for r in rows}
    except Exception:
        return set()


# ── Per-user schedule/notification preferences (Этап 3) ──────────────────────
# One row per user (JSONB blobs + cache-friendly PK lookup). Absent row = the
# «Обычно» default — no backfill needed. Pro-only feature; Free always = 4/day.
_user_prefs_schema_ready = False


def _ensure_user_prefs_schema() -> None:
    global _user_prefs_schema_ready
    if _user_prefs_schema_ready:
        return
    with get_db_connection_context() as conn:
        with conn.cursor() as cursor:
            cursor.execute(
                """
                CREATE TABLE IF NOT EXISTS bt_3_user_prefs (
                    user_id       BIGINT PRIMARY KEY,
                    tz_name       TEXT,
                    preset        TEXT NOT NULL DEFAULT 'normal',
                    schedule      JSONB,
                    interactives  JSONB,
                    notifications JSONB,
                    updated_at    TIMESTAMPTZ NOT NULL DEFAULT NOW()
                );
                """
            )
        conn.commit()
    _user_prefs_schema_ready = True


def get_user_prefs(user_id: int) -> dict | None:
    try:
        _ensure_user_prefs_schema()
        with get_db_connection_context() as conn:
            with conn.cursor() as cursor:
                cursor.execute(
                    "SELECT user_id, tz_name, preset, schedule, interactives, notifications "
                    "FROM bt_3_user_prefs WHERE user_id = %s;",
                    (int(user_id),),
                )
                r = cursor.fetchone()
        if not r:
            return None
        return {
            "user_id": int(r[0]), "tz_name": r[1], "preset": str(r[2] or "normal"),
            "schedule": r[3], "interactives": r[4], "notifications": r[5],
        }
    except Exception:
        logging.warning("get_user_prefs failed user=%s", user_id, exc_info=True)
        return None


def get_user_presets_bulk(user_ids) -> dict:
    """{user_id: preset} for the given ids (one query) — for per-send tier sizing.
    Users without a row are simply absent (caller treats them as the default)."""
    out: dict = {}
    ids = [int(u) for u in (user_ids or []) if u]
    if not ids:
        return out
    try:
        _ensure_user_prefs_schema()
        with get_db_connection_context() as conn:
            with conn.cursor() as cursor:
                cursor.execute(
                    "SELECT user_id, preset FROM bt_3_user_prefs WHERE user_id = ANY(%s);",
                    (ids,),
                )
                for r in cursor.fetchall() or []:
                    out[int(r[0])] = str(r[1] or "normal")
    except Exception:
        logging.warning("get_user_presets_bulk failed", exc_info=True)
    return out


def set_user_preset(user_id: int, preset: str) -> bool:
    try:
        _ensure_user_prefs_schema()
        with get_db_connection_context() as conn:
            with conn.cursor() as cursor:
                cursor.execute(
                    """
                    INSERT INTO bt_3_user_prefs (user_id, preset, updated_at)
                    VALUES (%s, %s, NOW())
                    ON CONFLICT (user_id) DO UPDATE
                        SET preset = EXCLUDED.preset, updated_at = NOW();
                    """,
                    (int(user_id), str(preset)),
                )
            conn.commit()
        return True
    except Exception:
        logging.warning("set_user_preset failed user=%s preset=%s", user_id, preset, exc_info=True)
        return False


def set_user_schedule(user_id: int, schedule) -> bool:
    """Save the active-window schedule (JSONB {weekday:[[s,e]…], weekend:[…]} in
    minutes-from-midnight, user TZ). None clears it (= all day)."""
    try:
        _ensure_user_prefs_schema()
        payload = json.dumps(schedule) if schedule is not None else None
        with get_db_connection_context() as conn:
            with conn.cursor() as cursor:
                cursor.execute(
                    """
                    INSERT INTO bt_3_user_prefs (user_id, schedule, updated_at)
                    VALUES (%s, %s::jsonb, NOW())
                    ON CONFLICT (user_id) DO UPDATE
                        SET schedule = EXCLUDED.schedule, updated_at = NOW();
                    """,
                    (int(user_id), payload),
                )
            conn.commit()
        return True
    except Exception:
        logging.warning("set_user_schedule failed user=%s", user_id, exc_info=True)
        return False


def get_user_prefs_bulk(user_ids) -> dict:
    """{user_id: {preset, schedule, tz_name}} for the given ids (one query) — used to
    size + window-gate DM delivery per recipient. Absent users are simply omitted."""
    out: dict = {}
    ids = [int(u) for u in (user_ids or []) if u]
    if not ids:
        return out
    try:
        _ensure_user_prefs_schema()
        with get_db_connection_context() as conn:
            with conn.cursor() as cursor:
                cursor.execute(
                    "SELECT user_id, preset, schedule, tz_name FROM bt_3_user_prefs WHERE user_id = ANY(%s);",
                    (ids,),
                )
                for r in cursor.fetchall() or []:
                    out[int(r[0])] = {"preset": str(r[1] or "normal"), "schedule": r[2], "tz_name": r[3]}
    except Exception:
        logging.warning("get_user_prefs_bulk failed", exc_info=True)
    return out


def get_windowed_user_prefs() -> list:
    """Users with a non-null active-window schedule (the drip job's work list, Этап 3f
    Stage B). One query; Pro check happens caller-side."""
    out: list = []
    try:
        _ensure_user_prefs_schema()
        with get_db_connection_context() as conn:
            with conn.cursor() as cursor:
                cursor.execute(
                    "SELECT user_id, preset, schedule, tz_name FROM bt_3_user_prefs "
                    "WHERE schedule IS NOT NULL;"
                )
                for r in cursor.fetchall() or []:
                    out.append({"user_id": int(r[0]), "preset": str(r[1] or "normal"),
                                "schedule": r[2], "tz_name": r[3]})
    except Exception:
        logging.warning("get_windowed_user_prefs failed", exc_info=True)
    return out


def get_inbox_delivery_stats_today(user_id: int, since_ts) -> tuple:
    """(delivered_count, last_delivered_at) for the user's inbox since `since_ts`,
    excluding the spaced-rep review (kind='rv') which is delivered off-schedule —
    used to pace the drip (how many already today + when last)."""
    try:
        with get_db_connection_context() as conn:
            with conn.cursor() as cursor:
                cursor.execute(
                    "SELECT COUNT(*), MAX(created_at) FROM bt_3_interactive_inbox "
                    "WHERE user_id = %s AND created_at >= %s AND kind <> 'rv';",
                    (int(user_id), since_ts),
                )
                r = cursor.fetchone()
        return (int(r[0] or 0), r[1]) if r else (0, None)
    except Exception:
        logging.warning("get_inbox_delivery_stats_today failed user=%s", user_id, exc_info=True)
        return (0, None)


def get_inbox_kinds_today(user_id: int, since_ts) -> set:
    """Коды заданий, которые человек сегодня УЖЕ получил (по всем путям сразу —
    и по слотам, и капельной выдачей). Капля выбирает следующий тип, пропуская их:
    сперва человеку достаётся всё разное, и только когда разного не осталось,
    идёт второй круг. Повтор дня («работа над ошибками») сюда не входит."""
    try:
        with get_db_connection_context() as conn:
            with conn.cursor() as cursor:
                cursor.execute(
                    "SELECT DISTINCT kind FROM bt_3_interactive_inbox "
                    "WHERE user_id = %s AND created_at >= %s AND kind <> 'rv';",
                    (int(user_id), since_ts),
                )
                return {str(r[0]) for r in cursor.fetchall() or [] if r[0]}
    except Exception:
        logging.warning("get_inbox_kinds_today failed user=%s", user_id, exc_info=True)
        return set()


# ── DAU: daily streaks + earned Pro grants (Этап 4) ──────────────────────────
_dau_schema_ready = False


def _ensure_dau_schema() -> None:
    global _dau_schema_ready
    if _dau_schema_ready:
        return
    with get_db_connection_context() as conn:
        with conn.cursor() as cur:
            cur.execute("""
                CREATE TABLE IF NOT EXISTS bt_3_user_streaks (
                    user_id          BIGINT PRIMARY KEY,
                    current_streak   INT NOT NULL DEFAULT 0,
                    longest_streak   INT NOT NULL DEFAULT 0,
                    last_active_date DATE,
                    freezes          INT NOT NULL DEFAULT 0,
                    updated_at       TIMESTAMPTZ NOT NULL DEFAULT NOW()
                );
            """)
            cur.execute("""
                CREATE TABLE IF NOT EXISTS bt_3_pro_grants (
                    id            BIGSERIAL PRIMARY KEY,
                    user_id       BIGINT NOT NULL,
                    granted_until TIMESTAMPTZ NOT NULL,
                    reason        TEXT,
                    created_at    TIMESTAMPTZ NOT NULL DEFAULT NOW()
                );
            """)
            cur.execute("CREATE INDEX IF NOT EXISTS idx_pro_grants_user "
                        "ON bt_3_pro_grants (user_id, granted_until);")
            # Links a grant to the Stars charge that paid for it (support donations), so a
            # refund can claw back exactly the days it granted. NULL for streak/referral/trial.
            cur.execute("ALTER TABLE bt_3_pro_grants "
                        "ADD COLUMN IF NOT EXISTS source_charge_id TEXT;")
            cur.execute("""
                CREATE TABLE IF NOT EXISTS bt_3_referrals (
                    invited_user_id  BIGINT PRIMARY KEY,
                    referrer_user_id BIGINT NOT NULL,
                    created_at       TIMESTAMPTZ NOT NULL DEFAULT NOW(),
                    rewarded_at      TIMESTAMPTZ
                );
            """)
            cur.execute("CREATE INDEX IF NOT EXISTS idx_referrals_referrer "
                        "ON bt_3_referrals (referrer_user_id);")
            cur.execute("""
                CREATE TABLE IF NOT EXISTS bt_3_feature_announcements (
                    user_id     BIGINT NOT NULL,
                    feature_key TEXT NOT NULL,
                    sent_at     TIMESTAMPTZ NOT NULL DEFAULT NOW(),
                    PRIMARY KEY (user_id, feature_key)
                );
            """)
            cur.execute("""
                CREATE TABLE IF NOT EXISTS bt_3_user_onboarding (
                    user_id      BIGINT PRIMARY KEY,
                    completed    BOOLEAN NOT NULL DEFAULT FALSE,
                    current_step INT NOT NULL DEFAULT 0,
                    updated_at   TIMESTAMPTZ NOT NULL DEFAULT NOW()
                );
                CREATE TABLE IF NOT EXISTS bt_3_onboarding_nudges (
                    user_id      BIGINT PRIMARY KEY,
                    nudge_date   DATE,
                    count_today  INT NOT NULL DEFAULT 0,
                    total_nudges INT NOT NULL DEFAULT 0,
                    dismissed    BOOLEAN NOT NULL DEFAULT FALSE,
                    last_nudge_at TIMESTAMPTZ,
                    updated_at   TIMESTAMPTZ NOT NULL DEFAULT NOW()
                );
            """)
        conn.commit()
    _dau_schema_ready = True


def get_onboarding_state(user_id: int) -> dict:
    """{'completed': bool, 'current_step': int}. Absent row = never started."""
    try:
        _ensure_dau_schema()
        with get_db_connection_context() as conn:
            with conn.cursor() as cur:
                cur.execute("SELECT completed, current_step FROM bt_3_user_onboarding "
                            "WHERE user_id=%s;", (int(user_id),))
                r = cur.fetchone()
        if not r:
            return {"completed": False, "current_step": 0}
        return {"completed": bool(r[0]), "current_step": int(r[1] or 0)}
    except Exception:
        # Fail OPEN as "completed" so a DB blip never traps a user on onboarding.
        return {"completed": True, "current_step": 0}


