def get_tts_object_cache(cache_key: str, *, touch_hit: bool = True) -> dict | None:
    if not cache_key:
        return None
    with get_db_connection_context() as conn:
        with conn.cursor() as cursor:
            cursor.execute(
                """
                SELECT
                    cache_key,
                    status,
                    language,
                    voice,
                    speed,
                    source_text,
                    object_key,
                    url,
                    size_bytes,
                    error_code,
                    error_msg,
                    created_at,
                    updated_at,
                    last_hit_at
                FROM bt_3_tts_object_cache
                WHERE cache_key = %s
                LIMIT 1;
                """,
                (str(cache_key),),
            )
            row = cursor.fetchone()
            if not row:
                return None
            if touch_hit:
                cursor.execute(
                    """
                    UPDATE bt_3_tts_object_cache
                    SET last_hit_at = NOW(), updated_at = NOW()
                    WHERE cache_key = %s;
                    """,
                    (str(cache_key),),
                )
    return _map_tts_object_cache_row(row)


