def upsert_card_srs_state(
    user_id: int,
    card_id: int,
    status: str,
    due_at: datetime,
    last_review_at: datetime | None,
    interval_days: int,
    reps: int,
    lapses: int,
    stability: float,
    difficulty: float,
    step: int = 0,
    cursor=None,
) -> dict:
    def _upsert(cur):
        cur.execute(
            """
            INSERT INTO bt_3_card_srs_state (
                user_id,
                card_id,
                status,
                due_at,
                last_review_at,
                interval_days,
                reps,
                lapses,
                stability,
                difficulty,
                step,
                created_at,
                updated_at
            )
            VALUES (%s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s, NOW(), NOW())
            ON CONFLICT (user_id, card_id) DO UPDATE
            SET status = EXCLUDED.status,
                due_at = EXCLUDED.due_at,
                last_review_at = EXCLUDED.last_review_at,
                interval_days = EXCLUDED.interval_days,
                reps = EXCLUDED.reps,
                lapses = EXCLUDED.lapses,
                stability = EXCLUDED.stability,
                difficulty = EXCLUDED.difficulty,
                step = EXCLUDED.step,
                updated_at = NOW()
            RETURNING
                id,
                user_id,
                card_id,
                status,
                due_at,
                last_review_at,
                interval_days,
                reps,
                lapses,
                stability,
                difficulty,
                created_at,
                updated_at,
                step;
            """,
            (
                int(user_id),
                int(card_id),
                status,
                due_at,
                last_review_at,
                int(interval_days),
                int(reps),
                int(lapses),
                float(stability),
                float(difficulty),
                int(step),
            ),
        )
        row = cur.fetchone()
        return {
            "id": row[0],
            "user_id": row[1],
            "card_id": row[2],
            "status": row[3],
            "due_at": row[4],
            "last_review_at": row[5],
            "interval_days": row[6],
            "reps": row[7],
            "lapses": row[8],
            "stability": float(row[9] or 0.0),
            "difficulty": float(row[10] or 0.0),
            "created_at": row[11],
            "updated_at": row[12],
            "step": int(row[13] or 0),
        }
    if cursor is not None:
        return _upsert(cursor)
    with get_db_connection_context() as conn:
        with conn.cursor() as own_cursor:
            return _upsert(own_cursor)


def backfill_srs_counters_from_review_log(*, apply: bool = False) -> dict[str, Any]:
    """Recompute reps/lapses for EVERY card from the review log.

    Needed because both counters wrote 0 for months (the fsrs library dropped the fields we
    read them from). The log holds one row per answer with its rating, so the true values
    are recoverable exactly: reps = answers, lapses = answers rated «Again» (1).

    Idempotent — re-running changes nothing once the state matches. `apply=False` only
    reports how many rows would change, so the repair can be inspected before it is made.
    """
    aggregate_sql = """
        SELECT user_id, card_id,
               COUNT(*)::int AS reps,
               COUNT(*) FILTER (WHERE rating = 1)::int AS lapses
        FROM bt_3_card_review_log
        GROUP BY user_id, card_id
    """
    with get_db_connection_context() as conn:
        with conn.cursor() as cursor:
            cursor.execute(
                f"""
                SELECT COUNT(*)
                FROM bt_3_card_srs_state s
                JOIN ({aggregate_sql}) agg
                  ON agg.user_id = s.user_id AND agg.card_id = s.card_id
                WHERE s.reps IS DISTINCT FROM agg.reps OR s.lapses IS DISTINCT FROM agg.lapses;
                """
            )
            stale = int((cursor.fetchone() or [0])[0])
            updated = 0
            if apply and stale:
                cursor.execute(
                    f"""
                    UPDATE bt_3_card_srs_state s
                    SET reps = agg.reps, lapses = agg.lapses, updated_at = NOW()
                    FROM ({aggregate_sql}) agg
                    WHERE agg.user_id = s.user_id AND agg.card_id = s.card_id
                      AND (s.reps IS DISTINCT FROM agg.reps OR s.lapses IS DISTINCT FROM agg.lapses);
                    """
                )
                updated = int(cursor.rowcount or 0)
            cursor.execute("SELECT COUNT(*) FROM bt_3_card_srs_state;")
            total_cards = int((cursor.fetchone() or [0])[0])
    return {"total_cards": total_cards, "stale": stale, "updated": updated, "applied": bool(apply)}


def count_due_srs_cards(
    user_id: int,
    now_utc: datetime | None = None,
    source_lang: str | None = None,
    target_lang: str | None = None,
    allowed_card_ids: list[int] | None = None,
    bypass_due_at: bool = False,
    cursor=None,
) -> int:
    now_utc = now_utc or datetime.now(timezone.utc)
    normalized_allowed_ids = _normalize_positive_bigint_list(allowed_card_ids)
    if allowed_card_ids is not None and not normalized_allowed_ids:
        return 0
    def _count(cur):
        # Skip language pair filter when card IDs are explicitly specified (manual mode):
        # selected cards may have any direction (de→ru or ru→de) regardless of the user's profile.
        if normalized_allowed_ids:
            language_filter_sql, language_params = "", []
        else:
            language_filter_sql, language_params = _build_language_pair_filter_both(
                source_lang, target_lang, table_alias="q",
            )
        allowed_sql = " AND q.id = ANY(%s::bigint[])" if normalized_allowed_ids else ""
        due_filter_sql = "" if bypass_due_at else " AND s.due_at <= %s"
        due_params = [] if bypass_due_at else [now_utc]
        cur.execute(
            f"""
            SELECT COUNT(*)
            FROM bt_3_card_srs_state s
            JOIN bt_3_webapp_dictionary_queries q
              ON q.id = s.card_id AND q.user_id = s.user_id
            WHERE s.user_id = %s
              AND s.status <> 'suspended'
              {due_filter_sql}
              AND COALESCE(q.response_json->>'sentence_origin', '') <> 'gpt_seed'
              {language_filter_sql}
              {allowed_sql};
            """,
            [int(user_id), *due_params, *language_params, *([normalized_allowed_ids] if normalized_allowed_ids else [])],
        )
        row = cur.fetchone()
        return int(row[0] if row else 0)
    if cursor is not None:
        return _count(cursor)
    with get_db_connection_context() as conn:
        with conn.cursor() as own_cursor:
            return _count(own_cursor)


