def record_shortcut_run_check(
    user_id: int,
    *,
    allowed: bool,
    reason: str | None = None,
    is_pro: bool | None = None,
    in_window: bool | None = None,
    run_index: int | None = None,
    entitlement_source: str | None = None,
) -> bool:
    """Log a run-check decision (both approvals AND blocks) for enforcement + the admin
    report. Only allowed=True rows count toward the quotas (see count_* above)."""
    try:
        _ensure_shortcut_runs_schema()
        with get_db_connection_context() as conn:
            with conn.cursor() as cur:
                cur.execute(
                    "INSERT INTO bt_3_shortcut_runs "
                    "(user_id, allowed, reason, is_pro, in_window, run_index, entitlement_source) "
                    "VALUES (%s, %s, %s, %s, %s, %s, %s);",
                    (
                        int(user_id), bool(allowed),
                        (str(reason) if reason else None),
                        (None if is_pro is None else bool(is_pro)),
                        (None if in_window is None else bool(in_window)),
                        (None if run_index is None else int(run_index)),
                        (str(entitlement_source) if entitlement_source else None),
                    ),
                )
            conn.commit()
        return True
    except Exception:
        logging.warning("record_shortcut_run_check failed user=%s", user_id, exc_info=True)
        return False


def record_shortcut_run(user_id: int) -> bool:
    """Backward-compat: append an APPROVED run row."""
    return record_shortcut_run_check(int(user_id), allowed=True)


def reset_shortcut_runs(user_id: int) -> int:
    """Delete ALL «Ночной Переводчик» run rows for a user (both approvals AND blocks) so
    the Free-total and Pro-daily quotas start from zero again. Test/admin utility only —
    returns the number of deleted rows. Does NOT touch installations / grace (grace is
    time-since-install based, see _shortcut_setup_grace_active)."""
    try:
        _ensure_shortcut_runs_schema()
        with get_db_connection_context() as conn:
            with conn.cursor() as cur:
                cur.execute("DELETE FROM bt_3_shortcut_runs WHERE user_id=%s;", (int(user_id),))
                deleted = int(cur.rowcount or 0)
            conn.commit()
        return deleted
    except Exception:
        logging.warning("reset_shortcut_runs failed user=%s", user_id, exc_info=True)
        return 0


# ── Battle-create queue (Mini-App «⚔️ Battles» hub) ──────────────────────────
# The Mini-App create endpoint ENQUEUES a battle-create request (instant response);
# the bot drains this queue and runs the EXISTING _create_and_broadcast_* logic, so
# nothing about invites/images/nudges/digest changes. Scalable: fan-out off the web
# critical path, done by the bot with retry semantics.
_battle_create_queue_ready = False


def _ensure_battle_create_queue_schema() -> None:
    global _battle_create_queue_ready
    if _battle_create_queue_ready:
        return
    with get_db_connection_context() as conn:
        with conn.cursor() as cur:
            cur.execute("""
                CREATE TABLE IF NOT EXISTS bt_3_battle_create_queue (
                    id           BIGSERIAL PRIMARY KEY,
                    user_id      BIGINT NOT NULL,
                    user_name    TEXT,
                    kind         TEXT NOT NULL,
                    mode         TEXT NOT NULL,
                    targets      JSONB,
                    themes       JSONB,
                    status       TEXT NOT NULL DEFAULT 'pending',
                    created_at   TIMESTAMPTZ NOT NULL DEFAULT NOW(),
                    processed_at TIMESTAMPTZ
                );
            """)
            cur.execute("CREATE INDEX IF NOT EXISTS idx_battle_create_queue_pending "
                        "ON bt_3_battle_create_queue (status, created_at);")
        conn.commit()
    _battle_create_queue_ready = True


def enqueue_battle_create(user_id: int, user_name: str, kind: str, mode: str,
                          targets: list | None, themes: list | None) -> int:
    """Queue a battle-create request; returns the row id (0 on failure)."""
    try:
        _ensure_battle_create_queue_schema()
        with get_db_connection_context() as conn:
            with conn.cursor() as cur:
                cur.execute(
                    "INSERT INTO bt_3_battle_create_queue (user_id, user_name, kind, mode, targets, themes) "
                    "VALUES (%s, %s, %s, %s, %s, %s) RETURNING id;",
                    (int(user_id), str(user_name or ""), str(kind), str(mode),
                     json.dumps(list(targets or [])), json.dumps(list(themes or []))),
                )
                rid = cur.fetchone()[0]
            conn.commit()
        return int(rid)
    except Exception:
        logging.warning("enqueue_battle_create failed user=%s", user_id, exc_info=True)
        return 0


def claim_pending_battle_creates(limit: int = 10) -> list[dict]:
    """Atomically claim up to `limit` pending requests (status pending→claimed)."""
    try:
        _ensure_battle_create_queue_schema()
        with get_db_connection_context() as conn:
            with conn.cursor() as cur:
                cur.execute(
                    """
                    UPDATE bt_3_battle_create_queue SET status='claimed'
                    WHERE id IN (
                        SELECT id FROM bt_3_battle_create_queue
                        WHERE status='pending' ORDER BY created_at ASC
                        LIMIT %s FOR UPDATE SKIP LOCKED
                    )
                    RETURNING id, user_id, user_name, kind, mode, targets, themes;
                    """,
                    (int(limit),),
                )
                rows = cur.fetchall() or []
            conn.commit()
        out = []
        for r in rows:
            out.append({
                "id": int(r[0]), "user_id": int(r[1]), "user_name": r[2],
                "kind": r[3], "mode": r[4],
                "targets": r[5] if isinstance(r[5], list) else (json.loads(r[5]) if r[5] else []),
                "themes": r[6] if isinstance(r[6], list) else (json.loads(r[6]) if r[6] else []),
            })
        return out
    except Exception:
        logging.warning("claim_pending_battle_creates failed", exc_info=True)
        return []


def mark_battle_create_done(row_id: int, status: str = "done") -> bool:
    try:
        _ensure_battle_create_queue_schema()
        with get_db_connection_context() as conn:
            with conn.cursor() as cur:
                cur.execute(
                    "UPDATE bt_3_battle_create_queue SET status=%s, processed_at=NOW() WHERE id=%s;",
                    (str(status), int(row_id)),
                )
            conn.commit()
        return True
    except Exception:
        return False


def get_shortcut_installation_stats(user_id: int) -> dict:
    """How many times this user has paired a shortcut (≈ (re)installs — each pairing is
    a row in bt_3_shortcut_installations) and WHEN the latest pairing happened. Used for
    the first-day window grace (grace resets on re-pairing) + the admin report."""
    try:
        with get_db_connection_context() as conn:
            with conn.cursor() as cur:
                cur.execute(
                    "SELECT COUNT(*), MAX(created_at) FROM bt_3_shortcut_installations WHERE user_id=%s;",
                    (int(user_id),),
                )
                r = cur.fetchone()
        return {"install_count": int((r or [0])[0] or 0), "last_installed_at": (r[1] if r and len(r) > 1 else None)}
    except Exception:
        return {"install_count": 0, "last_installed_at": None}


def is_shortcut_setup_day(user_id: int, tz_name: str = "Europe/Vienna") -> bool:
    """True iff TODAY (in tz) is the calendar day of this user's FIRST-EVER shortcut
    activation (the earliest pairing row). The one-time first-day setup pool («наладка»)
    applies ONLY on this day. Anti-farm by construction: the setup day is pinned to
    MIN(created_at), so re-pairing on a LATER day never re-grants it, and a user whose
    first activation was on an earlier day gets no pool now. No pairing rows → False."""
    try:
        with get_db_connection_context() as conn:
            with conn.cursor() as cur:
                cur.execute(
                    "SELECT (MIN(created_at) AT TIME ZONE %s)::date = (NOW() AT TIME ZONE %s)::date "
                    "FROM bt_3_shortcut_installations WHERE user_id=%s;",
                    (str(tz_name), str(tz_name), int(user_id)),
                )
                r = cur.fetchone()
        return bool(r and r[0])
    except Exception:
        return False


def get_shortcut_runs_report(days: int = 7, tz_name: str = "Europe/Vienna") -> dict:
    """Admin monitoring for «Ночной Переводчик»: recent attempts with LOCAL time,
    decision, window/grace status + a summary + anomaly list (an ALLOWED run that was
    OUT of window and BEYOND grace ⇒ the block failed — likely an old/edited shortcut
    that skipped run-check)."""
    out: dict = {"rows": [], "summary": {}, "anomalies": [], "days": int(days)}
    try:
        _ensure_shortcut_runs_schema()
        with get_db_connection_context() as conn:
            with conn.cursor() as cur:
                cur.execute(
                    """
                    SELECT user_id,
                           to_char(ran_at AT TIME ZONE %s, 'YYYY-MM-DD HH24:MI') AS local_ts,
                           allowed, reason, is_pro, in_window, run_index
                    FROM bt_3_shortcut_runs
                    WHERE ran_at >= NOW() - (%s || ' days')::interval
                    ORDER BY ran_at DESC
                    LIMIT 500;
                    """,
                    (str(tz_name), int(days)),
                )
                rows = cur.fetchall() or []
        parsed = [{
            "user_id": int(r[0]), "local_ts": r[1], "allowed": bool(r[2]),
            "reason": r[3], "is_pro": r[4], "in_window": r[5], "run_index": r[6],
        } for r in rows]
        # Enrich each row with the user's (re)install stats so the admin can tell a
        # brand-new-today user from an old one whose out-of-window run should be blocked.
        install_by_user = {uid: get_shortcut_installation_stats(uid) for uid in {p["user_id"] for p in parsed}}
        for p in parsed:
            info = install_by_user.get(p["user_id"], {})
            p["install_count"] = info.get("install_count")
            li = info.get("last_installed_at")
            p["last_installed_at"] = (li.strftime("%Y-%m-%d %H:%M") if hasattr(li, "strftime") else None)
        # Anomaly: an ALLOWED run OUT of window whose reason is neither grace nor admin
        # ⇒ the block failed (e.g. an old/edited shortcut that skipped run-check).
        anomalies = [p for p in parsed if p["allowed"] and p["in_window"] is False
                     and str(p.get("reason") or "") not in ("grace", "admin")]
        out["rows"] = parsed
        out["anomalies"] = anomalies
        out["summary"] = {
            "total_checks": len(parsed),
            "allowed": sum(1 for p in parsed if p["allowed"]),
            "blocked_window": sum(1 for p in parsed if (not p["allowed"]) and p["reason"] == "time_window"),
            "blocked_quota": sum(1 for p in parsed if (not p["allowed"]) and p["reason"] in ("pro_daily", "free_total")),
            "unique_users": len({p["user_id"] for p in parsed}),
            "anomalies": len(anomalies),
        }
    except Exception:
        logging.warning("get_shortcut_runs_report failed", exc_info=True)
    return out


def get_shortcut_autosave_enabled(user_id: int) -> bool:
    """Whether the user has the Shortcut nightly auto-save (staging + digest) mode ON."""
    try:
        with get_db_connection_context() as conn:
            with conn.cursor() as cursor:
                cursor.execute(
                    "SELECT enabled FROM bt_3_shortcut_autosave_prefs WHERE user_id = %s LIMIT 1;",
                    (int(user_id),),
                )
                row = cursor.fetchone()
        # Default ON: the nightly batch/digest mode is the intended default flow.
        return bool(row[0]) if row else True
    except Exception:
        logging.debug("get_shortcut_autosave_enabled failed user_id=%s", user_id, exc_info=True)
        return True


def set_shortcut_autosave_enabled(user_id: int, enabled: bool) -> bool:
    """Upsert the toggle; returns the stored value."""
    with get_db_connection_context() as conn:
        with conn.cursor() as cursor:
            cursor.execute(
                """
                INSERT INTO bt_3_shortcut_autosave_prefs (user_id, enabled, updated_at)
                VALUES (%s, %s, NOW())
                ON CONFLICT (user_id)
                DO UPDATE SET enabled = EXCLUDED.enabled, updated_at = NOW();
                """,
                (int(user_id), bool(enabled)),
            )
        conn.commit()
    return bool(enabled)


def get_reply_keyboard_delivered_version(user_id: int) -> str | None:
    """The DM reply-keyboard version this user has already received, or None if never.
    Read-only; safe to call on the send hot path (best-effort, swallows errors)."""
    try:
        with get_db_connection_context() as conn:
            with conn.cursor() as cursor:
                cursor.execute(
                    "SELECT keyboard_version FROM bt_3_reply_keyboard_state WHERE user_id = %s LIMIT 1;",
                    (int(user_id),),
                )
                row = cursor.fetchone()
        return str(row[0]) if row and row[0] is not None else None
    except Exception:
        logging.debug("get_reply_keyboard_delivered_version failed user_id=%s", user_id, exc_info=True)
        return None


def has_reply_keyboard_delivered(user_id: int) -> bool:
    """True when the bot has ever delivered the DM keyboard to this user.

    Used as the «личка работает» signal: Telegram forbids the bot from writing first, so a
    delivered keyboard proves the user once pressed START. Someone who entered only through
    a Mini-App link has no row here — and no way to receive tasks — which is exactly who we
    want to nudge. One primary-key lookup; the caller caches it.
    """
    with get_db_connection_context() as conn:
        with conn.cursor() as cursor:
            cursor.execute(
                "SELECT 1 FROM bt_3_reply_keyboard_state WHERE user_id = %s LIMIT 1;",
                (int(user_id),),
            )
            return cursor.fetchone() is not None


def mark_reply_keyboard_delivered(user_id: int, keyboard_version: str) -> None:
    """Record that the given keyboard version reached this DM user (upsert)."""
    with get_db_connection_context() as conn:
        with conn.cursor() as cursor:
            cursor.execute(
                """
                INSERT INTO bt_3_reply_keyboard_state (user_id, keyboard_version, delivered_at)
                VALUES (%s, %s, NOW())
                ON CONFLICT (user_id)
                DO UPDATE SET keyboard_version = EXCLUDED.keyboard_version, delivered_at = NOW();
                """,
                (int(user_id), str(keyboard_version)),
            )
        conn.commit()


def get_reply_keyboard_delivered_age_days(user_id: int) -> float | None:
    """Сколько суток прошло с последнего прикрепления клавиатуры этому человеку.
    None — если записи нет. Только чтение, ошибки глотает."""
    try:
        with get_db_connection_context() as conn:
            with conn.cursor() as cursor:
                cursor.execute(
                    """
                    SELECT EXTRACT(EPOCH FROM (NOW() - delivered_at)) / 86400.0
                    FROM bt_3_reply_keyboard_state WHERE user_id = %s LIMIT 1;
                    """,
                    (int(user_id),),
                )
                row = cursor.fetchone()
        return float(row[0]) if row and row[0] is not None else None
    except Exception:
        logging.debug("get_reply_keyboard_delivered_age_days failed user_id=%s", user_id, exc_info=True)
        return None


def get_reply_keyboard_anchor(user_id: int) -> int | None:
    """message_id of the DM message currently holding this user's reply keyboard,
    or None if none recorded. Read-only; best-effort (swallows errors)."""
    try:
        with get_db_connection_context() as conn:
            with conn.cursor() as cursor:
                cursor.execute(
                    "SELECT anchor_message_id FROM bt_3_reply_keyboard_state WHERE user_id = %s LIMIT 1;",
                    (int(user_id),),
                )
                row = cursor.fetchone()
        return int(row[0]) if row and row[0] is not None else None
    except Exception:
        logging.debug("get_reply_keyboard_anchor failed user_id=%s", user_id, exc_info=True)
        return None


def set_reply_keyboard_anchor(user_id: int, message_id: int) -> None:
    """Record the message_id that now carries this user's reply keyboard (upsert)."""
    with get_db_connection_context() as conn:
        with conn.cursor() as cursor:
            cursor.execute(
                """
                INSERT INTO bt_3_reply_keyboard_state (user_id, anchor_message_id, delivered_at)
                VALUES (%s, %s, NOW())
                ON CONFLICT (user_id)
                -- delivered_at тоже обновляем: это «когда клавиатура последний раз реально
                -- прикреплялась». По этой отметке видно, что человек давно без кнопок.
                DO UPDATE SET anchor_message_id = EXCLUDED.anchor_message_id, delivered_at = NOW();
                """,
                (int(user_id), int(message_id)),
            )
        conn.commit()


def get_telegram_dictionary_folder_preference(
    user_id: int,
    *,
    source_lang: str,
    target_lang: str,
) -> dict | None:
    normalized_source_lang = _normalize_lang_code(source_lang)
    normalized_target_lang = _normalize_lang_code(target_lang)
    if not normalized_source_lang or not normalized_target_lang:
        return None
    with get_db_connection_context() as conn:
        with conn.cursor() as cursor:
            cursor.execute(
                """
                SELECT
                    p.folder_id,
                    f.name,
                    f.color,
                    f.icon,
                    p.updated_at
                FROM bt_3_telegram_dictionary_folder_preferences p
                LEFT JOIN bt_3_dictionary_folders f
                  ON f.id = p.folder_id AND f.user_id = p.user_id
                WHERE p.user_id = %s
                  AND p.source_lang = %s
                  AND p.target_lang = %s
                LIMIT 1;
                """,
                (int(user_id), normalized_source_lang, normalized_target_lang),
            )
            row = cursor.fetchone()
    if not row:
        return None
    folder_id = row[0]
    if folder_id is None:
        return {
            "folder_id": None,
            "name": "Без папки",
            "color": None,
            "icon": "📂",
            "updated_at": row[4].isoformat() if row[4] else None,
            "source_lang": normalized_source_lang,
            "target_lang": normalized_target_lang,
            "is_none": True,
        }
    return {
        "folder_id": int(folder_id),
        "name": str(row[1] or "").strip() or "GENERAL",
        "color": row[2],
        "icon": row[3] or "📁",
        "updated_at": row[4].isoformat() if row[4] else None,
        "source_lang": normalized_source_lang,
        "target_lang": normalized_target_lang,
        "is_none": False,
    }


def set_telegram_dictionary_folder_preference(
    user_id: int,
    *,
    source_lang: str,
    target_lang: str,
    folder_id: int | None,
) -> dict:
    normalized_source_lang = _normalize_lang_code(source_lang)
    normalized_target_lang = _normalize_lang_code(target_lang)
    if not normalized_source_lang or not normalized_target_lang:
        raise ValueError("source_lang и target_lang обязательны")

    folder_payload = None
    if folder_id is not None:
        with get_db_connection_context() as conn:
            with conn.cursor() as cursor:
                cursor.execute(
                    """
                    SELECT id, name, color, icon, created_at
                    FROM bt_3_dictionary_folders
                    WHERE user_id = %s AND id = %s
                    LIMIT 1;
                    """,
                    (int(user_id), int(folder_id)),
                )
                row = cursor.fetchone()
                if not row:
                    raise ValueError("Папка не найдена")
                folder_payload = {
                    "folder_id": int(row[0]),
                    "name": row[1],
                    "color": row[2],
                    "icon": row[3],
                    "created_at": row[4].isoformat() if row[4] else None,
                    "source_lang": normalized_source_lang,
                    "target_lang": normalized_target_lang,
                    "is_none": False,
                }
                cursor.execute(
                    """
                    INSERT INTO bt_3_telegram_dictionary_folder_preferences (
                        user_id,
                        source_lang,
                        target_lang,
                        folder_id,
                        updated_at
                    )
                    VALUES (%s, %s, %s, %s, NOW())
                    ON CONFLICT (user_id, source_lang, target_lang) DO UPDATE
                    SET folder_id = EXCLUDED.folder_id,
                        updated_at = NOW();
                    """,
                    (int(user_id), normalized_source_lang, normalized_target_lang, int(folder_id)),
                )
        return folder_payload

    with get_db_connection_context() as conn:
        with conn.cursor() as cursor:
            cursor.execute(
                """
                INSERT INTO bt_3_telegram_dictionary_folder_preferences (
                    user_id,
                    source_lang,
                    target_lang,
                    folder_id,
                    updated_at
                )
                VALUES (%s, %s, %s, NULL, NOW())
                ON CONFLICT (user_id, source_lang, target_lang) DO UPDATE
                SET folder_id = NULL,
                    updated_at = NOW();
                """,
                (int(user_id), normalized_source_lang, normalized_target_lang),
            )
    return {
        "folder_id": None,
        "name": "Без папки",
        "color": None,
        "icon": "📂",
        "source_lang": normalized_source_lang,
        "target_lang": normalized_target_lang,
        "is_none": True,
    }


def rename_dictionary_folder(user_id: int, folder_id: int, name: str, icon: str | None = None, color: str | None = None) -> dict | None:
    with get_db_connection_context() as conn:
        with conn.cursor() as cursor:
            set_parts = ["name = %s"]
            params: list = [name.strip()]
            if icon is not None:
                set_parts.append("icon = %s")
                params.append(icon.strip())
            if color is not None:
                set_parts.append("color = %s")
                params.append(color.strip())
            params.extend([int(user_id), int(folder_id)])
            cursor.execute(
                f"""
                UPDATE bt_3_dictionary_folders
                SET {', '.join(set_parts)}
                WHERE user_id = %s AND id = %s
                RETURNING id, name, color, icon, created_at;
                """,
                params,
            )
            row = cursor.fetchone()
            if not row:
                return None
            return {"id": row[0], "name": row[1], "color": row[2], "icon": row[3],
                    "created_at": row[4].isoformat() if row[4] else None}


def delete_dictionary_folder(user_id: int, folder_id: int, delete_words: bool = False) -> dict:
    """Delete folder. If delete_words=True, also deletes its words+SRS. Otherwise unlinks them."""
    with get_db_connection_context() as conn:
        with conn.cursor() as cursor:
            cursor.execute(
                "SELECT id FROM bt_3_dictionary_folders WHERE id = %s AND user_id = %s",
                (int(folder_id), int(user_id)),
            )
            if not cursor.fetchone():
                return {"found": False}

            if delete_words:
                cursor.execute(
                    """
                    DELETE FROM bt_3_card_srs_state
                    WHERE user_id = %s AND card_id IN (
                        SELECT id FROM bt_3_webapp_dictionary_queries
                        WHERE user_id = %s AND folder_id = %s
                    )
                    """,
                    (int(user_id), int(user_id), int(folder_id)),
                )
                cursor.execute(
                    """
                    DELETE FROM bt_3_card_review_log
                    WHERE user_id = %s AND card_id IN (
                        SELECT id FROM bt_3_webapp_dictionary_queries
                        WHERE user_id = %s AND folder_id = %s
                    )
                    """,
                    (int(user_id), int(user_id), int(folder_id)),
                )
                cursor.execute(
                    "DELETE FROM bt_3_webapp_dictionary_queries WHERE user_id = %s AND folder_id = %s",
                    (int(user_id), int(folder_id)),
                )
            else:
                cursor.execute(
                    """
                    UPDATE bt_3_webapp_dictionary_queries
                    SET folder_id = NULL,
                        updated_at = NOW()
                    WHERE user_id = %s AND folder_id = %s
                    """,
                    (int(user_id), int(folder_id)),
                )

            cursor.execute(
                "DELETE FROM bt_3_dictionary_folders WHERE id = %s AND user_id = %s",
                (int(folder_id), int(user_id)),
            )
            return {"found": True}


def list_user_vocabulary(
    user_id: int,
    folder_id: int | None = None,
    search: str | None = None,
    sort: str = "date_desc",
    limit: int = 50,
    offset: int = 0,
    updated_since=None,
) -> dict:
    """Return paginated vocabulary entries with SRS state for the library view."""
    conditions = ["q.user_id = %s"]
    params: list = [int(user_id)]

    if folder_id == -1:
        conditions.append("q.folder_id IS NULL")
    elif folder_id is not None:
        conditions.append("q.folder_id = %s")
        params.append(int(folder_id))

    if search:
        # Артикль в запросе игнорируем: карточка показывает «die Eltern», а в колонке лежит
        # «Eltern» — набрав ровно то, что видит на экране, человек не находил своё же слово.
        # Ищем по основе, поэтому «die Eltern», «Eltern» и «eltern» дают один результат.
        needle_text = re.sub(
            r"^(der|die|das|ein|eine|einen|einem|einer|eines)\s+",
            "",
            search.strip().lower(),
        ).strip() or search.strip().lower()
        needle = f"%{needle_text}%"
        conditions.append(
            "(LOWER(q.word_ru) LIKE %s OR LOWER(q.word_de) LIKE %s"
            " OR LOWER(q.translation_ru) LIKE %s OR LOWER(q.translation_de) LIKE %s)"
        )
        params.extend([needle, needle, needle, needle])
    if updated_since is not None:
        conditions.append("q.updated_at > %s")
        params.append(updated_since)

    where_clause = " AND ".join(conditions)

    order_map = {
        "date_desc": "q.created_at DESC",
        "date_asc":  "q.created_at ASC",
        "alpha_asc": "COALESCE(NULLIF(q.word_de,''), q.word_ru) ASC",
        "alpha_desc": "COALESCE(NULLIF(q.word_de,''), q.word_ru) DESC",
        "srs_status": "COALESCE(s.due_at, 'epoch'::timestamptz) ASC",
        "updated_desc": "q.updated_at DESC, q.id DESC",
        "updated_asc": "q.updated_at ASC, q.id ASC",
    }
    order_clause = order_map.get(sort, "q.created_at DESC")

    with get_db_connection_context() as conn:
        with conn.cursor() as cursor:
            cursor.execute(
                f"SELECT COUNT(*) FROM bt_3_webapp_dictionary_queries q WHERE {where_clause}",
                params,
            )
            total = int(cursor.fetchone()[0])

            cursor.execute(
                f"""
                SELECT
                    q.id,
                    q.word_ru,
                    q.translation_de,
                    q.word_de,
                    q.translation_ru,
                    q.source_lang,
                    q.target_lang,
                    q.folder_id,
                    q.created_at,
                    q.updated_at,
                    q.is_learned,
                    s.status        AS srs_status,
                    s.due_at        AS srs_due_at,
                    s.reps          AS srs_reps,
                    s.lapses        AS srs_lapses,
                    s.stability     AS srs_stability,
                    s.last_review_at,
                    f.name          AS folder_name,
                    f.icon          AS folder_icon,
                    f.color         AS folder_color,
                    q.response_json,
                    q.user_notes,
                    lu.card         AS unit_card,
                    lu.lemma_key    AS unit_lemma_key,
                    -- Голый запасной заголовок. Артикль сюда НЕ приклеивается намеренно:
                    -- склейка живёт в одном месте — compose_german_headword() ниже, — иначе
                    -- формул становится две и слово начинает выглядеть по-разному на разных
                    -- экранах. Ради этого сюда же добавлен lu.gender в выборку.
                    COALESCE(
                        NULLIF(q.word_de, ''),
                        q.word_ru
                    ) AS display_word,
                    COALESCE(
                        NULLIF(q.translation_ru, ''),
                        q.translation_de
                    ) AS display_translation,
                    -- ДОБАВЛЯТЬ ТОЛЬКО В КОНЕЦ: ниже строки разбираются по номерам
                    -- (row[24], row[25] …), и колонка, вставленная в середину, молча
                    -- сдвинет всё, что за ней.
                    lu.gender       AS unit_gender,
                    -- Принадлежит ли написание карточки этому слову — по справочнику форм.
                    COALESCE(EXISTS (
                        SELECT 1 FROM bt_3_lex_surfaces s
                        WHERE s.unit_id = lu.id
                          AND s.lang = lu.lang
                          AND s.surface_key = LOWER(BTRIM(REGEXP_REPLACE(
                                  COALESCE(q.word_de, ''),
                                  '^(der|die|das|ein|eine|einen|einem|einer|eines)[[:space:]]+', '', 'i')))
                    ), FALSE) AS surface_confirms
                FROM bt_3_webapp_dictionary_queries q
                LEFT JOIN bt_3_card_srs_state s
                    ON s.user_id = q.user_id AND s.card_id = q.id
                LEFT JOIN bt_3_dictionary_folders f
                    ON f.id = q.folder_id
                LEFT JOIN bt_3_lex_units lu
                    ON lu.id = q.lex_unit_id
                WHERE {where_clause}
                ORDER BY {order_clause}
                LIMIT %s OFFSET %s
                """,
                params + [int(limit), int(offset)],
            )
            rows = cursor.fetchall()

    items = []
    # Личные правки на всю пачку одним запросом: то, что человек написал своей рукой,
    # ложится поверх общего слова и не перебивается ничем.
    personal_overrides = get_user_word_overrides([r[0] for r in rows])
    for row in rows:
        response_json = _coerce_json_object(row[20])
        # Разбор живёт на ЕДИНИЦЕ — одной на всех. Личная карточка задаёт направление и
        # заголовок, а недостающие блоки берём с единицы: улучшили слово один раз —
        # увидели все, кто на него подписан. Только дополняем, никогда не заменяем.
        if DICTIONARY_UNITS_SERVE_ENABLED:
            unit_card = _coerce_json_object(row[22])
            if unit_card and unit_card_is_about_the_same_word_sql(
                unit_lemma_key=row[23],
                card_word=row[3] or response_json.get("word_de"),
                surface_confirms=bool(row[27]),
            ):
                response_json = merge_unit_card_for_serve(
                    response_json, unit_card, personal_overrides.get(int(row[0] or 0)))
        entry_source_lang = str(row[5] or "").strip().lower()
        entry_target_lang = str(row[6] or "").strip().lower()
        # Serve guard: a mis-oriented lookup can leave a Russian value in response_json.word_de
        # ("der Понос"), which the card renders as the German headword and inflects. The
        # trustworthy German lives in the q.word_de column (row[3]). When response_json's German
        # is Cyrillic, drop it so both the header and the grammar tables fall back to the column.
        _rj_word_de = str(response_json.get("word_de") or "")
        if _rj_word_de and _CYRILLIC_RE.search(_rj_word_de):
            _col_de = str(row[3] or "").strip()
            response_json["word_de"] = _col_de if (_col_de and not _CYRILLIC_RE.search(_col_de)) else ""
        response_source_text = str(response_json.get("source_text") or "").strip()
        response_target_text = str(response_json.get("target_text") or "").strip()
        german_display = str(
            response_json.get("word_de")
            or row[3]
            or (response_source_text if entry_source_lang == "de" else "")
            or (response_target_text if entry_target_lang == "de" else "")
            or row[24]
            or ""
        ).strip()
        dictionary_senses = response_json.get("dictionary_senses") if isinstance(response_json.get("dictionary_senses"), list) else []
        primary_sense = next(
            (
                str(item.get("value") or "").strip()
                for item in dictionary_senses
                if isinstance(item, dict) and str(item.get("value") or "").strip()
            ),
            "",
        )
        # dictionary_senses hold meanings in the entry's TARGET language. For a ru→de
        # entry (user looked a Russian word up and got German) the target IS German, so
        # taking the sense unconditionally printed the German headword on the translation
        # line as well — the card showed German twice and the Russian never appeared.
        # Use the senses only when the native (Russian) side is the target side.
        senses_are_native = entry_target_lang != "de"
        native_display = str(
            (primary_sense if senses_are_native else "")
            or response_json.get("translation_ru")
            or row[4]
            or (response_source_text if entry_source_lang == "ru" else "")
            or (response_target_text if entry_target_lang == "ru" else "")
            or response_json.get("word_ru")
            or row[1]
            or row[25]
            or ""
        ).strip()
        srs_due_at = row[12]
        srs_status = row[11]
        now_utc = __import__("datetime").datetime.now(__import__("datetime").timezone.utc)
        if srs_status is None:
            srs_label = "none"
        elif srs_status == "new":
            srs_label = "new"
        elif srs_due_at and srs_due_at <= now_utc:
            srs_label = "due"
        else:
            srs_label = "ok"

        items.append({
            "id": row[0],
            "word_ru": row[1] or "",
            "translation_de": row[2] or "",
            "word_de": row[3] or "",
            "translation_ru": row[4] or "",
            "source_lang": row[5] or "",
            "target_lang": row[6] or "",
            "folder_id": row[7],
            "created_at": row[8].isoformat() if row[8] else None,
            "updated_at": row[9].isoformat() if row[9] else None,
            "is_learned": bool(row[10]),
            "srs_status": srs_status,
            "srs_label": srs_label,
            "srs_reps": int(row[13]) if row[13] is not None else 0,
            "srs_lapses": int(row[14]) if row[14] is not None else 0,
            "srs_stability": float(row[15]) if row[15] is not None else 0.0,
            "last_review_at": row[16].isoformat() if row[16] else None,
            "folder_name": row[17] or None,
            "folder_icon": row[18] or None,
            "folder_color": row[19] or None,
            "response_json": response_json,
            # Заголовок собирается ОДНОЙ общей формулой — той же, что у карточки.
            # Раньше здесь стояло голое `german_display or row[24]`, и слово ехало на
            # экран без артикля, хотя род лежал рядом в разборе или на единице.
            "display_word": compose_german_headword(
                german_display or row[24] or "",
                article=response_json.get("article"),
                gender=row[26],
                number=response_json.get("grammatical_number"),
                # Часть речи нужна для регистра: существительное с заглавной, глагол и
                # прилагательное со строчной. Замер 15.08.2026: 357 карточек стояли с
                # заглавной при неименной части речи — «Abbuchen», «Akut».
                pos=response_json.get("part_of_speech"),
            ),
            "display_translation": native_display or row[25] or "",
            "user_notes": normalize_user_notes(row[21]),
        })

    return {"items": items, "total": total, "limit": limit, "offset": offset}


def search_dictionary_pool(
    user_id: int,
    query: str,
    source_lang: str | None = None,
    target_lang: str | None = None,
    limit: int = 40,
) -> list[dict]:
    """Поиск по ОБЩЕМУ словарю (`bt_3_dictionary_entries`) — тому самому пулу, куда
    попадает каждое разобранное слово, включая весь словарь автора.

    Зачем: у человека в личной библиотеке лежит лишь то, что ему уже открылось по ходу
    занятий (сотни слов), а в пуле — тысячи. Раньше поиск смотрел только в личное, и
    слово, которое у нас ЕСТЬ, человек не находил и шёл разбирать его через GPT — то
    есть мы платили за то, что уже знаем. Поиск по пулу открыт всем независимо от
    подписки на базовый словарь: чужого он не показывает, только наш общий материал.

    Замерено 04.08.2026 на живой базе: пул 15 743 записи, весь словарь автора (14 618)
    целиком в нём (нет ни одной строки без canonical_entry_id), поиск подстрокой —
    47 мс. Поэтому отдельного индекса под LIKE '%…%' не заводим.

    То, что у человека уже есть, из выдачи исключаем: связь личной карточки с записью
    пула — `canonical_entry_id`.
    """
    text = str(query or "").strip()
    if not text:
        return []
    needle_text = re.sub(
        r"^(der|die|das|ein|eine|einen|einem|einer|eines)\s+",
        "",
        text.lower(),
    ).strip() or text.lower()
    needle = f"%{needle_text}%"
    prefix = f"{needle_text}%"
    safe_limit = max(1, min(100, int(limit or 40)))

    conditions = [
        "(LOWER(e.source_text) LIKE %s OR LOWER(e.target_text) LIKE %s"
        " OR LOWER(COALESCE(e.word_de,'')) LIKE %s OR LOWER(COALESCE(e.word_ru,'')) LIKE %s"
        " OR LOWER(COALESCE(e.translation_ru,'')) LIKE %s OR LOWER(COALESCE(e.translation_de,'')) LIKE %s)"
    ]
    params: list = [needle] * 6

    language_filter_sql, language_params = _build_language_pair_filter_both(
        source_lang, target_lang, table_alias="e",
    )
    if language_filter_sql:
        # Хелпер отдаёт готовый кусок с ведущим « AND » — здесь условия склеиваются сами.
        conditions.append(language_filter_sql.strip()[len("AND "):].strip())
        params.extend(language_params)

    conditions.append(
        "NOT EXISTS (SELECT 1 FROM bt_3_webapp_dictionary_queries q"
        " WHERE q.user_id = %s AND q.canonical_entry_id = e.id)"
    )
    params.append(int(user_id))

    # Порядок как в личном поиске: точное слово → начинается с набранного → остальное.
    rank_sql = (
        "CASE"
        " WHEN COALESCE(NULLIF(e.source_headword_norm,''), e.source_text_norm) = %s THEN 0"
        " WHEN COALESCE(NULLIF(e.target_headword_norm,''), e.target_text_norm) = %s THEN 1"
        " WHEN COALESCE(NULLIF(e.source_headword_norm,''), e.source_text_norm) LIKE %s THEN 2"
        " WHEN LOWER(e.source_text) LIKE %s THEN 3"
        " ELSE 4 END"
    )
    rank_params = [needle_text, needle_text, prefix, prefix]

    with get_db_connection_context() as conn:
        with conn.cursor() as cursor:
            cursor.execute(
                f"""
                SELECT
                    e.id,
                    e.word_ru,
                    e.translation_de,
                    e.word_de,
                    e.translation_ru,
                    e.source_lang,
                    e.target_lang,
                    e.source_text,
                    e.target_text,
                    e.response_json,
                    {rank_sql} AS match_rank
                FROM bt_3_dictionary_entries e
                WHERE {' AND '.join(conditions)}
                ORDER BY match_rank ASC, LENGTH(e.source_text) ASC, e.id ASC
                LIMIT %s
                """,
                rank_params + params + [safe_limit],
            )
            rows = cursor.fetchall()

    items = []
    for row in rows:
        response_json = _coerce_json_object(row[9])
        entry_source_lang = str(row[5] or "").strip().lower()
        entry_target_lang = str(row[6] or "").strip().lower()
        source_text = str(row[7] or "").strip()
        target_text = str(row[8] or "").strip()
        german_display = str(
            row[3]
            or (source_text if entry_source_lang == "de" else "")
            or (target_text if entry_target_lang == "de" else "")
            or ""
        ).strip()
        native_display = str(
            row[4]
            or (target_text if entry_target_lang == "ru" else "")
            or (source_text if entry_source_lang == "ru" else "")
            or row[1]
            or ""
        ).strip()
        items.append({
            "id": int(row[0]),
            "pool_entry_id": int(row[0]),
            "is_pool": True,
            "word_ru": row[1] or "",
            "translation_de": row[2] or "",
            "word_de": row[3] or "",
            "translation_ru": row[4] or "",
            "source_lang": row[5] or "",
            "target_lang": row[6] or "",
            "source_text": source_text,
            "target_text": target_text,
            "folder_id": None,
            "srs_label": "none",
            "srs_reps": 0,
            "response_json": response_json,
            "display_word": german_display or source_text,
            "display_translation": native_display or target_text,
        })
    _attach_pool_articles(items)
    return items


# Немецкие части речи, у которых рода нет и артикль в заголовке был бы ошибкой. Список
# закрытый и держится отдельно от `_LOWERCASE_POS` регистра: там решается заглавная
# буква, здесь — принадлежность рода. Смешивать нельзя, это два разных вопроса.
_POOL_ARTICLE_ALLOWED_POS = ("noun",)

# ОТКУДА взялась часть речи — здесь это важнее, чем ЧТО она говорит.
#
# `pos_source='wiktionary'` значит, что часть речи взята ответом на вопрос «существует ли
# существительное с таким написанием». Это НЕ тот вопрос, который нам нужен: нам нужно
# «про существительное ли ЭТА карточка». Замер 24.08.2026 показал цену разницы:
#
#     «Manche»         единица: noun/die   карточка: «некоторые»    → «die Manche» ✗
#     «Eigen»          единица: noun/das   карточка: «собственный»  → «das Eigen»  ✗
#     «Unentschieden»  единица: noun/das   карточка: «ничейный»     → «das Unentschieden» ✗
#
# Справочник во всех трёх случаях прав: такие существительные в немецком есть. Неверен
# вопрос. Поэтому артикль клеим, только когда часть речи пришла из разбора САМОЙ записи
# (карточка, пул, справочник форм, дверь слова) — там она про это слово в этом значении.
#
# Цена решения названа числом: 162 заголовка получают артикль сразу, 111 со слабым
# подтверждением остаются без него и учитываются как незакрытая задача
# (scripts/dict_defect_audit.py, пункт «заголовки пула без артикля»). Среди этих 111 есть
# и заведомо хорошие «Auto», «Haus», «Frühstück» — они ждут не выдумки, а второго
# источника части речи. Показать неверный немецкий хуже, чем показать слово без артикля.
_POOL_ARTICLE_WEAK_POS_SOURCES = ("wiktionary",)


def _attach_pool_articles(items: list) -> None:
    """Приклеить артикль к заголовкам выдачи ОБЩЕГО словаря — по справочнику.

    Зачем это здесь
    ───────────────
    Личная карточка собирает заголовок через `compose_german_headword` и артикль
    показывает (`list_user_vocabulary`). Общий словарь этого не делал: `display_word`
    собирался как «что лежит, то и показываем». Из-за этого одно и то же слово выглядело
    по-разному на двух экранах, и человек, ищущий слово в общем словаре, видел «Kosten»
    вместо «die Kosten».

    Замер на живой базе 24.08.2026: 1871 заголовок выдачи пула стоял без артикля; из них
    306 — существительные с известным родом. После сверки со справочником склонений
    артикль можно поставить у 278. Остальные 28 не трогаем и вот почему:

        13  форма множественного или обрезок  «Türen», «Bücher», «Ausprägungen»
         1  род расходится со справочником    «Vertriebene» (у нас die, источник der)
        14  справочника не знает              «Kosten», «Eltern» (только множественное),
                                              «Finster», «Tärigkeiten» (опечатки)

    Три условия, и каждое поймано на живых данных (спасибо соседней сессии, 24.08.2026):

    1. **Часть речи — существительное.** «gehen», «wenn», «vier» лежали в единицах с
       `pos='noun'`, и справочник на них честно отвечает «das Gehen», «das Wenn»,
       «die Vier»: такие существительные ЕСТЬ, но карточка не про них. Источник прав,
       вопрос неверен — поэтому спрашиваем только там, где часть речи сама сказала «noun».
    2. **Справочник склонений подтвердил.** Внутри него стоит сторож множественного:
       артикль отдаётся, только если заголовок совпал с именительным единственного.
    3. **Наш род не спорит с источником.** Разошлись — не показываем ни тот, ни другой:
       выбирать между двумя ответами значит угадывать.

    Ничего не пишется в базу: это сборка ответа, а не правка данных.
    """
    if not items:
        return
    # Кандидаты: заголовок — одно слово, с заглавной, без артикля. Артикль уже стоящий
    # в строке трогать нельзя, а слово со строчной — не существительное.
    candidates = {}
    for item in items:
        head = str(item.get("display_word") or "").strip()
        if not head or " " in head or not head[:1].isupper():
            continue
        candidates.setdefault(head, []).append(item)
    if not candidates:
        return
    try:
        from backend.noun_declension_reference import articles_from_declension_reference
        verdicts = articles_from_declension_reference(list(candidates))
    except Exception:
        # Справочник недоступен — показываем заголовки как есть. Это не подмена ответа:
        # слово остаётся тем же, просто без артикля, и в логе видно, что сверки не было.
        logging.warning("общий словарь: сверка артиклей со справочником не отработала",
                        exc_info=True)
        return
    confirmed = {word: found for word, (found, _why) in verdicts.items() if found}
    if not confirmed:
        return
    # Часть речи и наш род — из слоя единиц, тем же ключом, что и везде.
    known = {}
    try:
        with get_db_connection_context() as conn:
            with conn.cursor() as cursor:
                cursor.execute(
                    "SELECT lemma_key, pos, pos_source, gender FROM bt_3_lex_units "
                    "WHERE lang = 'de' AND lemma_key = ANY(%s)",
                    ([w.casefold() for w in confirmed],),
                )
                known = {row[0]: (row[1], row[2], row[3]) for row in cursor.fetchall()}
    except Exception:
        logging.warning("общий словарь: часть речи для заголовков не прочиталась",
                        exc_info=True)
        return
    # Имена собственные: города и страны в немецком стоят БЕЗ артикля («Athen ist
    # schön», не «das Athen»). Справочник склонений про них отвечает — у него есть
    # таблица, — но вопрос к нему неверен. Разобранные с владельцем поимённо лежат
    # отметкой в таблице сплошного прохода; читаем её, а не гадаем по признакам.
    proper_nouns = set()
    try:
        with get_db_connection_context() as conn:
            with conn.cursor() as cursor:
                cursor.execute(
                    "SELECT lower(u.lemma) FROM bt_3_field_checks f "
                    "JOIN bt_3_lex_units u ON u.id = f.unit_id "
                    "WHERE f.field = 'gender' AND f.verdict = %s",
                    ("имя собственное — артикль не ставится",),
                )
                proper_nouns = {row[0] for row in cursor.fetchall()}
    except Exception:
        logging.warning("общий словарь: список имён собственных не прочитался",
                        exc_info=True)

    unresolved = 0
    for word, article in confirmed.items():
        if word.casefold() in proper_nouns:
            continue
        pos, pos_source, gender = known.get(word.casefold(), (None, None, None))
        if str(pos or "").strip().lower() not in _POOL_ARTICLE_ALLOWED_POS:
            continue
        if str(pos_source or "").strip().lower() in _POOL_ARTICLE_WEAK_POS_SOURCES:
            # Часть речи подтверждена слабо — см. комментарий у списка выше.
            unresolved += 1
            continue
        if gender and str(gender).strip().lower() != article:
            # Наш род спорит с источником. Выбирать между двумя ответами значит угадывать.
            unresolved += 1
            continue
        for item in candidates[word]:
            item["display_word"] = f"{article} {word}"
    if unresolved:
        # Молчащий счётчик неотличим от нуля: раз слова остались без артикля, это должно
        # быть видно числом, а не только на экране у человека.
        logging.info("общий словарь: %d заголовков остались без артикля — "
                     "часть речи подтверждена слабо или род спорит с источником", unresolved)


# Личные заметки к слову. Потолок сознательный: пять — это ещё заметки, дальше конспект,
# и на карточке повторения столько уже не помещается.
USER_NOTES_MAX = 5
USER_NOTE_LABEL_MAX = 24
USER_NOTE_TEXT_MAX = 300


def normalize_user_notes(raw) -> list[dict]:
    """Привести заметки к тому виду, в каком их можно хранить и показывать.

    Название необязательное: не написал — показываем просто текст. Пустая заметка
    выбрасывается молча (человек нажал «плюс» и передумал — это не ошибка).
    Обрезаем длину здесь, а не в интерфейсе: интерфейсов несколько, а правило одно."""
    if not isinstance(raw, list):
        return []
    notes = []
    for item in raw:
        if isinstance(item, str):
            item = {"text": item}
        if not isinstance(item, dict):
            continue
        text = str(item.get("text") or "").strip()[:USER_NOTE_TEXT_MAX]
        if not text:
            continue
        label = str(item.get("label") or "").strip()[:USER_NOTE_LABEL_MAX]
        notes.append({"label": label, "text": text})
        if len(notes) >= USER_NOTES_MAX:
            break
    return notes


def get_card_user_notes(user_id: int, entry_id: int) -> list[dict]:
    with get_db_connection_context() as conn:
        with conn.cursor() as cursor:
            cursor.execute(
                "SELECT user_notes FROM bt_3_webapp_dictionary_queries "
                "WHERE id = %s AND user_id = %s LIMIT 1;",
                (int(entry_id), int(user_id)),
            )
            row = cursor.fetchone()
    return normalize_user_notes(row[0]) if row else []


def save_card_user_notes(user_id: int, entry_id: int, notes) -> list[dict] | None:
    """Записать заметки. Чужую карточку тронуть нельзя — проверка по владельцу в самом
    запросе, а не отдельным чтением: между чтением и записью карточка могла смениться.

    Возвращает то, что реально сохранено, — интерфейс показывает именно его, чтобы на
    экране не осталось того, что не легло в базу."""
    cleaned = normalize_user_notes(notes)
    with get_db_connection_context() as conn:
        with conn.cursor() as cursor:
            cursor.execute(
                "UPDATE bt_3_webapp_dictionary_queries "
                "SET user_notes = %s::jsonb, updated_at = NOW() "
                "WHERE id = %s AND user_id = %s RETURNING id;",
                (Json(cleaned) if cleaned else None, int(entry_id), int(user_id)),
            )
            row = cursor.fetchone()
        conn.commit()
    return cleaned if row else None


def search_dictionary_units(
    user_id: int,
    query: str,
    limit: int = 40,
) -> list[dict]:
    """Поиск по СЛОЮ ЕДИНИЦ — по слову, а не по строке текста.

    Почему не по общему пулу: пул хранит пару «что спросили → что ответили», поэтому
    одно слово живёт в нём несколькими строками и находится только в том виде, в каком
    его когда-то набрали. Единица — это само слово: у неё есть написания (формы), связи
    с переводами и разбор. Замерено 05.08.2026: немецких единиц с переводом 13 578, из
    них с разбором 7 922 — против 6 969 полных записей в пуле.

    Ищем и по немецкой стороне, и по русской: «точка с запятой» находит «das Semikolon».
    Отдаём только то, у чего есть перевод — строка без правой стороны человеку не нужна.
    То, что у человека уже есть, исключаем по указателю карточки на единицу.
    """
    text = str(query or "").strip()
    if not text:
        return []
    needle_text = re.sub(
        r"^(der|die|das|ein|eine|einen|einem|einer|eines)\s+",
        "",
        text.lower(),
    ).strip() or text.lower()
    needle = f"%{needle_text}%"
    prefix = f"{needle_text}%"
    safe_limit = max(1, min(100, int(limit or 40)))

    with get_db_connection_context() as conn:
        with conn.cursor() as cursor:
            cursor.execute(
                """
                SELECT u.id, u.display, u.lemma, u.kind, u.gender, u.card,
                       (SELECT t.display
                          FROM bt_3_lex_links l
                          JOIN bt_3_lex_units t ON t.id = l.to_unit
                         WHERE l.from_unit = u.id AND l.rank < 900
                         ORDER BY l.rank, t.id LIMIT 1) AS translation
                FROM bt_3_lex_units u
                WHERE u.lang = 'de'
                  AND EXISTS (SELECT 1 FROM bt_3_lex_links l2
                               WHERE l2.from_unit = u.id AND l2.rank < 900)
                  AND NOT EXISTS (SELECT 1 FROM bt_3_webapp_dictionary_queries q
                                   WHERE q.user_id = %s AND q.lex_unit_id = u.id)
                  AND (
                        LOWER(u.display) LIKE %s
                     OR u.lemma_key LIKE %s
                     OR EXISTS (SELECT 1 FROM bt_3_lex_links l3
                                  JOIN bt_3_lex_units t3 ON t3.id = l3.to_unit
                                 WHERE l3.from_unit = u.id AND l3.rank < 900
                                   AND LOWER(t3.display) LIKE %s)
                  )
                ORDER BY (CASE WHEN u.lemma_key = %s THEN 0
                               WHEN u.lemma_key LIKE %s THEN 1
                               ELSE 2 END),
                         (u.card IS NULL),
                         LENGTH(u.display), u.id
                LIMIT %s
                """,
                (int(user_id), needle, needle, needle, needle_text, prefix, safe_limit),
            )
            rows = cursor.fetchall()

    items = []
    for unit_id, display, lemma, kind, gender, card, translation in rows:
        word = str(display or lemma or "").strip()
        if gender and not _GERMAN_LEADING_ARTICLE_RE.match(word.lower()):
            word = f"{gender} {word}"
        items.append({
            "id": f"unit-{int(unit_id)}",
            "unit_id": int(unit_id),
            "is_pool": True,
            "word_de": word,
            "word_ru": "",
            "translation_de": "",
            "translation_ru": str(translation or "").strip(),
            "source_lang": "de",
            "target_lang": "ru",
            "folder_id": None,
            "srs_label": "none",
            "srs_reps": 0,
            "response_json": _coerce_json_object(card),
            "display_word": word,
            "display_translation": str(translation or "").strip(),
        })
    return items


def search_shared_dictionary(
    user_id: int,
    query: str,
    source_lang: str | None = None,
    target_lang: str | None = None,
    limit: int = 40,
) -> list[dict]:
    """Всё, что у нас есть по этому слову и чего ещё нет у человека.

    Сначала единицы — там слово опознаётся как слово и лежит лучший разбор. Потом
    добираем из общего пула то, чего в единицах не нашлось: 822 записи пула единицы не
    имеют вовсе (это запросы перевода, которые никто не сохранял), и у 357 из них есть
    полный разбор. Терять их нельзя — ради них поиск и делался.

    Когда пул уйдёт совсем, отсюда просто исчезнет второе слагаемое."""
    units = search_dictionary_units(user_id=user_id, query=query, limit=limit)
    if len(units) >= limit:
        return units

    seen = {
        _normalize_dictionary_headword_key(item.get("display_word"))
        for item in units
        if item.get("display_word")
    }
    extra = []
    for item in search_dictionary_pool(
        user_id=user_id, query=query,
        source_lang=source_lang, target_lang=target_lang,
        limit=limit,
    ):
        key = _normalize_dictionary_headword_key(item.get("display_word"))
        if key and key in seen:
            continue
        seen.add(key)
        extra.append(item)
        if len(units) + len(extra) >= limit:
            break
    return units + extra


def get_dictionary_pool_entry(entry_id: int) -> dict | None:
    """Одна запись общего словаря по id — для переноса в личный словарь человека."""
    try:
        normalized_id = int(entry_id)
    except (TypeError, ValueError):
        return None
    if normalized_id <= 0:
        return None
    with get_db_connection_context() as conn:
        with conn.cursor() as cursor:
            cursor.execute(
                """
                SELECT id, word_ru, translation_de, word_de, translation_ru,
                       source_lang, target_lang, source_text, target_text, response_json
                FROM bt_3_dictionary_entries
                WHERE id = %s
                """,
                (normalized_id,),
            )
            row = cursor.fetchone()
    if not row:
        return None
    return {
        "id": int(row[0]),
        "word_ru": row[1] or "",
        "translation_de": row[2] or "",
        "word_de": row[3] or "",
        "translation_ru": row[4] or "",
        "source_lang": row[5] or "",
        "target_lang": row[6] or "",
        "source_text": row[7] or "",
        "target_text": row[8] or "",
        "response_json": _coerce_json_object(row[9]),
    }


def get_vocabulary_folders_with_counts(user_id: int) -> list[dict]:
    """Return all folders with word counts plus a synthetic 'no folder' entry."""
    with get_db_connection_context() as conn:
        with conn.cursor() as cursor:
            cursor.execute(
                """
                SELECT
                    f.id,
                    f.name,
                    f.color,
                    f.icon,
                    f.created_at,
                    COUNT(q.id) AS word_count
                FROM bt_3_dictionary_folders f
                LEFT JOIN bt_3_webapp_dictionary_queries q
                    ON q.folder_id = f.id AND q.user_id = f.user_id
                WHERE f.user_id = %s
                GROUP BY f.id, f.name, f.color, f.icon, f.created_at
                ORDER BY f.created_at DESC
                """,
                (int(user_id),),
            )
            folders = [
                {
                    "id": row[0],
                    "name": row[1],
                    "color": row[2],
                    "icon": row[3],
                    "created_at": row[4].isoformat() if row[4] else None,
                    "word_count": int(row[5]),
                }
                for row in cursor.fetchall()
            ]

            cursor.execute(
                """
                SELECT COUNT(*) FROM bt_3_webapp_dictionary_queries
                WHERE user_id = %s AND folder_id IS NULL
                """,
                (int(user_id),),
            )
            no_folder_count = int(cursor.fetchone()[0])

            cursor.execute(
                "SELECT COUNT(*) FROM bt_3_webapp_dictionary_queries WHERE user_id = %s",
                (int(user_id),),
            )
            total_count = int(cursor.fetchone()[0])

    return {
        "folders": folders,
        "no_folder_count": no_folder_count,
        "total_count": total_count,
    }


def delete_vocabulary_entry(user_id: int, entry_id: int) -> bool:
    """Delete a dictionary entry and its SRS state. Returns True if found and deleted."""
    with get_db_connection_context() as conn:
        with conn.cursor() as cursor:
            cursor.execute(
                "SELECT id FROM bt_3_webapp_dictionary_queries WHERE id = %s AND user_id = %s",
                (int(entry_id), int(user_id)),
            )
            if not cursor.fetchone():
                return False
            cursor.execute(
                "DELETE FROM bt_3_card_srs_state WHERE card_id = %s AND user_id = %s",
                (int(entry_id), int(user_id)),
            )
            cursor.execute(
                "DELETE FROM bt_3_card_review_log WHERE card_id = %s AND user_id = %s",
                (int(entry_id), int(user_id)),
            )
            cursor.execute(
                "DELETE FROM bt_3_webapp_dictionary_queries WHERE id = %s AND user_id = %s",
                (int(entry_id), int(user_id)),
            )
    return True


def bulk_delete_vocabulary_entries(user_id: int, entry_ids: list[int]) -> int:
    """Delete multiple dictionary entries and their SRS state. Returns deleted count."""
    safe_ids: list[int] = []
    for entry_id in list(entry_ids or []):
        try:
            normalized_entry_id = int(entry_id)
        except (TypeError, ValueError):
            continue
        if normalized_entry_id > 0:
            safe_ids.append(normalized_entry_id)
    if not safe_ids:
        return 0
    with get_db_connection_context() as conn:
        with conn.cursor() as cursor:
            cursor.execute(
                """
                SELECT id
                FROM bt_3_webapp_dictionary_queries
                WHERE user_id = %s
                  AND id = ANY(%s);
                """,
                (int(user_id), safe_ids),
            )
            found_ids = [int(row[0]) for row in cursor.fetchall() or []]
            if not found_ids:
                return 0
            cursor.execute(
                "DELETE FROM bt_3_card_srs_state WHERE user_id = %s AND card_id = ANY(%s)",
                (int(user_id), found_ids),
            )
            cursor.execute(
                "DELETE FROM bt_3_card_review_log WHERE user_id = %s AND card_id = ANY(%s)",
                (int(user_id), found_ids),
            )
            cursor.execute(
                "DELETE FROM bt_3_webapp_dictionary_queries WHERE user_id = %s AND id = ANY(%s)",
                (int(user_id), found_ids),
            )
    return len(found_ids)


def get_vocabulary_entry_for_user(*, user_id: int, entry_id: int) -> dict | None:
    """Одна карточка личного словаря — только своя: чужую по номеру не достать."""
    with get_db_connection_context() as conn:
        with conn.cursor() as cursor:
            cursor.execute(
                """
                SELECT id, word_ru, translation_de, word_de, translation_ru,
                       source_lang, target_lang, folder_id, lex_unit_id
                FROM bt_3_webapp_dictionary_queries
                WHERE id = %s AND user_id = %s;
                """,
                (int(entry_id), int(user_id)),
            )
            row = cursor.fetchone()
    if not row:
        return None
    keys = ("id", "word_ru", "translation_de", "word_de", "translation_ru",
            "source_lang", "target_lang", "folder_id", "lex_unit_id")
    return dict(zip(keys, row))


def split_vocabulary_entry_senses(
    user_id: int,
    entry_id: int,
    senses: list[dict],
) -> dict:
    """Разбить одну карточку на несколько — по одной на значение.

    Исходная карточка ОСТАЁТСЯ и получает первое значение: так у неё сохраняется вся
    накопленная история повторений, интервал и папка. Остальные значения становятся
    новыми карточками — они начинают с нуля, потому что человек их ещё не учил.

    Ничего не удаляется. Немецкая сторона, папка и привязка к слову словаря копируются
    как есть."""
    if not senses or len(senses) < 2:
        return {"ok": False, "reason": "nothing_to_split", "created": 0}
    with get_db_connection_context() as conn:
        with conn.cursor() as cursor:
            cursor.execute(
                """
                SELECT id, user_id, word_ru, translation_de, word_de, translation_ru,
                       source_lang, target_lang, response_json, folder_id,
                       canonical_entry_id, semantic_tag, lex_unit_id
                FROM bt_3_webapp_dictionary_queries
                WHERE id = %s AND user_id = %s;
                """,
                (int(entry_id), int(user_id)),
            )
            row = cursor.fetchone()
            if not row:
                return {"ok": False, "reason": "not_found", "created": 0}
            (_id, _user, _word_ru, translation_de, word_de, _translation_ru,
             source_lang, target_lang, response_json, folder_id,
             canonical_entry_id, semantic_tag, lex_unit_id) = row
            payload = _coerce_json_object(response_json)

            # ТУТ ТОЖЕ ПЕЧАТАЕТ ЧЕЛОВЕК: он разбивает свою карточку на значения и
            # набирает каждое руками. Дверь у такого текста должна быть та же, что и у
            # обычного сохранения, — иначе грязь заходит именно этим путём, потому что
            # ниже идёт ПРЯМОЙ INSERT мимо _create_or_attach_…, где чистка стоит.
            from backend.dictionary_intake import clean_text
            first = clean_text(senses[0].get("value"))
            if first:
                cursor.execute(
                    """
                    UPDATE bt_3_webapp_dictionary_queries
                    SET word_ru = %s, translation_ru = %s, updated_at = NOW()
                    WHERE id = %s AND user_id = %s;
                    """,
                    (first, first, int(entry_id), int(user_id)),
                )

            created = 0
            for sense in senses[1:]:
                value = clean_text(sense.get("value"))
                if not value:
                    continue
                sense_payload = dict(payload)
                # Разбор относится к СЛОВУ, а не к одному его значению: оставляем как есть,
                # но помечаем, какое значение учит эта карточка — иначе на обороте снова
                # вылезет весь список смыслов.
                sense_payload["sense_value"] = value
                sense_payload["translations"] = [{"value": value, "context": "", "is_primary": True}]
                sense_payload["dictionary_senses"] = [{
                    "rank": 1, "label": "main", "value": value,
                    "context": str(sense.get("label") or ""), "example_source": "", "example_target": "",
                }]
                cursor.execute(
                    """
                    INSERT INTO bt_3_webapp_dictionary_queries
                        (user_id, word_ru, translation_de, word_de, translation_ru,
                         source_lang, target_lang, response_json, folder_id,
                         canonical_entry_id, origin_process, semantic_tag, lex_unit_id)
                    VALUES (%s, %s, %s, %s, %s, %s, %s, %s, %s, %s, 'sense_split', %s, %s)
                    ON CONFLICT DO NOTHING;
                    """,
                    (int(user_id), value, translation_de, word_de, value,
                     source_lang, target_lang, Json(sense_payload), folder_id,
                     canonical_entry_id, semantic_tag, lex_unit_id),
                )
                created += cursor.rowcount
        conn.commit()
    return {"ok": True, "created": created, "kept": first}


# Поля, которые человек правит руками на карточке. Ровно те три, что принимает
# edit_vocabulary_entry ниже. Список закрытый: всё остальное — общее и правится централизованно.
USER_EDITABLE_CARD_FIELDS = ("word_de", "translation_ru", "dictionary_senses")


def ensure_user_word_overrides_schema() -> None:
    """Личный слой поверх общего слова: ТОЛЬКО то, что человек поправил сам.

    Зачем отдельная таблица, а не поле в карточке
    ─────────────────────────────────────────────
    Так устроено у всех, кто решал эту задачу до нас: WaniKani (`study_materials` рядом
    с общими `subjects`), Skritter («личные определения существуют только в вашем
    аккаунте»), AnkiHub и AnkiCollab (защита конкретных ПОЛЕЙ конкретной заметки).

    Anki показал, чем кончается обратный путь — когда личное кладут внутрь общей записи,
    меняя её форму: связь с обновлениями рвётся навсегда, и человек выбирает между
    «настроить под себя» и «получать исправления». У нас сегодня ровно это: правка
    человека ложится в тот же `response_json`, куда легла копия разбора, и отличить
    «человек написал сам» от «остатки старой копии» невозможно.

    Правило чтения: берём общее слово, сверху накладываем только те поля, которые
    человек правил. Всё остальное продолжает обновляться централизованно.

    Защита включается САМА при первой правке поля — без галочек. AnkiHub пришёл к этому
    не сразу: пока пометку ставили руками, люди её забывали и теряли свою работу.
    Обратная сторона, о которой они же предупреждают: защитил — перестал получать
    исправления в это поле. Поэтому здесь есть `released_at`: человек может вернуть поле
    «как в словаре», и запись перестаёт действовать, но остаётся видимой.
    """
    with get_db_connection_context() as conn:
        with conn.cursor() as cursor:
            cursor.execute(
                """
                CREATE TABLE IF NOT EXISTS bt_3_user_word_overrides (
                    id          BIGSERIAL PRIMARY KEY,
                    user_id     BIGINT NOT NULL,
                    entry_id    BIGINT NOT NULL,
                    unit_id     BIGINT,
                    field_key   TEXT   NOT NULL,
                    value       JSONB  NOT NULL,
                    created_at  TIMESTAMPTZ NOT NULL DEFAULT NOW(),
                    updated_at  TIMESTAMPTZ NOT NULL DEFAULT NOW(),
                    released_at TIMESTAMPTZ,
                    UNIQUE (user_id, entry_id, field_key)
                );
                """
            )
            cursor.execute(
                "CREATE INDEX IF NOT EXISTS idx_user_word_overrides_entry "
                "ON bt_3_user_word_overrides (entry_id) WHERE released_at IS NULL;"
            )
            cursor.execute(
                "CREATE INDEX IF NOT EXISTS idx_user_word_overrides_unit "
                "ON bt_3_user_word_overrides (unit_id) WHERE released_at IS NULL;"
            )
        conn.commit()


def record_user_word_override(cursor, *, user_id: int, entry_id: int, unit_id: int | None,
                              field_key: str, value) -> None:
    """Запомнить, что ЭТО поле человек написал сам. Централизованное обогащение его не тронет."""
    if field_key not in USER_EDITABLE_CARD_FIELDS:
        return
    cursor.execute(
        """
        INSERT INTO bt_3_user_word_overrides (user_id, entry_id, unit_id, field_key, value)
        VALUES (%s, %s, %s, %s, %s::jsonb)
        ON CONFLICT (user_id, entry_id, field_key)
        DO UPDATE SET value = EXCLUDED.value, unit_id = EXCLUDED.unit_id,
                      updated_at = NOW(), released_at = NULL;
        """,
        (int(user_id), int(entry_id), int(unit_id) if unit_id else None,
         str(field_key), json.dumps(value, ensure_ascii=False)),
    )


def get_user_word_overrides(entry_ids, cursor=None) -> dict[int, dict]:
    """Личные правки для пачки карточек: {entry_id: {field_key: value}}.

    Отпущенные (`released_at` заполнен) не возвращаются — человек сам сказал «верни как
    в словаре», и поле снова живёт общей жизнью.

    cursor передают те, кто уже держит транзакцию (ответ на повторении, например).
    Без этого мы брали бы из пула ВТОРОЕ соединение, не отпустив первого, — а это
    ровно тот способ, которым пул кончается под нагрузкой."""
    ids = [int(x) for x in (entry_ids or []) if x]
    if not ids:
        return {}
    out: dict[int, dict] = {}

    def _fetch(cur):
        cur.execute(
            "SELECT entry_id, field_key, value FROM bt_3_user_word_overrides "
            "WHERE entry_id = ANY(%s) AND released_at IS NULL;",
            (ids,),
        )
        for entry_id, field_key, value in cur.fetchall():
            out.setdefault(int(entry_id), {})[str(field_key)] = value

    try:
        if cursor is not None:
            _fetch(cursor)
        else:
            with get_db_connection_context() as conn:
                with conn.cursor() as own_cursor:
                    _fetch(own_cursor)
    except Exception:
        logging.debug("личные правки не прочитались", exc_info=True)
    return out


def edit_vocabulary_entry(
    user_id: int,
    entry_id: int,
    word_de: str | None = None,
    translation_ru: str | None = None,
    dictionary_senses: list | None = None,
    folder_id: int | None = None,
    clear_folder: bool = False,
) -> dict | None:
    """Patch mutable fields of a vocabulary entry. Returns updated entry or None if not found."""
    with get_db_connection_context() as conn:
        with conn.cursor() as cursor:
            cursor.execute(
                """
                SELECT id, word_ru, translation_de, word_de, translation_ru, source_lang, target_lang, response_json
                FROM bt_3_webapp_dictionary_queries
                WHERE id = %s AND user_id = %s
                """,
                (int(entry_id), int(user_id)),
            )
            existing_row = cursor.fetchone()
            if not existing_row:
                return None
            current_word_ru = str(existing_row[1] or "").strip()
            current_translation_de = str(existing_row[2] or "").strip()
            current_word_de = str(existing_row[3] or "").strip()
            current_translation_ru = str(existing_row[4] or "").strip()
            source_lang = _normalize_lang_code(existing_row[5])
            target_lang = _normalize_lang_code(existing_row[6])
            response_json = _coerce_json_object(existing_row[7])

            set_parts = []
            params: list = []
            # ЧЕЛОВЕК ПЕЧАТАЕТ РУКАМИ — значит вход проходит ту же дверь, что и всё
            # остальное. Здесь стоял голый `.strip()`, и в карточку ложилось ровно то,
            # что набрано: невидимые символы из буфера обмена, двойные пробелы, разные
            # начертания одной и той же буквы «ä». После этого одно и то же слово
            # перестаёт быть равно самому себе — не находится поиском, задваивается в
            # словаре, не сходится с общей записью.
            #
            # clean_text ничего не додумывает и смысл не меняет: только убирает грязь.
            # Она идемпотентна, поэтому чистый ввод проходит через неё без изменений.
            from backend.dictionary_intake import clean_text
            normalized_word = clean_text(word_de) if isinstance(word_de, str) else None
            normalized_translation = (
                clean_text(translation_ru) if isinstance(translation_ru, str) else None)
            normalized_senses = None
            if dictionary_senses is not None:
                normalized_senses = []
                for item in dictionary_senses:
                    if isinstance(item, dict):
                        value = clean_text(item.get("value"))
                    else:
                        value = clean_text(item)
                    if value:
                        normalized_senses.append(value)
                normalized_senses = normalized_senses[:3]
                if normalized_translation:
                    if normalized_senses:
                        normalized_senses[0] = normalized_translation
                    else:
                        normalized_senses = [normalized_translation]

            if translation_ru is not None and not normalized_senses:
                meanings = response_json.get("meanings")
                if isinstance(meanings, dict) and isinstance(meanings.get("primary"), dict):
                    meanings["primary"]["value"] = normalized_translation
                translations = response_json.get("translations")
                if isinstance(translations, list):
                    first_translation = next((entry for entry in translations if isinstance(entry, dict)), None)
                    if isinstance(first_translation, dict):
                        first_translation["value"] = normalized_translation
                senses = response_json.get("dictionary_senses")
                if isinstance(senses, list) and senses:
                    first_sense = senses[0]
                    if isinstance(first_sense, dict):
                        first_sense["value"] = normalized_translation

            if normalized_senses is not None and normalized_senses:
                primary_value = normalized_senses[0]
                existing_primary = response_json.get("meanings", {}).get("primary") if isinstance(response_json.get("meanings"), dict) else {}
                existing_secondary = response_json.get("meanings", {}).get("secondary") if isinstance(response_json.get("meanings", {}).get("secondary"), list) else []
                existing_senses = response_json.get("dictionary_senses") if isinstance(response_json.get("dictionary_senses"), list) else []
                rebuilt_senses = []
                rebuilt_secondary = []
                rebuilt_translations = []
                for index, value in enumerate(normalized_senses):
                    base_sense = existing_senses[index] if index < len(existing_senses) and isinstance(existing_senses[index], dict) else {}
                    if index == 0:
                        base_meaning = existing_primary if isinstance(existing_primary, dict) else {}
                    else:
                        candidate_secondary = existing_secondary[index - 1] if index - 1 < len(existing_secondary) and isinstance(existing_secondary[index - 1], dict) else {}
                        base_meaning = candidate_secondary
                    context_value = str(base_sense.get("context") or base_meaning.get("context") or "").strip()
                    example_source = str(base_sense.get("example_source") or base_meaning.get("example_source") or "").strip()
                    example_target = str(base_sense.get("example_target") or base_meaning.get("example_target") or "").strip()
                    rebuilt_sense = {
                        "rank": index + 1,
                        "label": "main" if index == 0 else "secondary",
                        "value": value,
                        "context": context_value,
                        "example_source": example_source,
                        "example_target": example_target,
                    }
                    rebuilt_senses.append(rebuilt_sense)
                    rebuilt_translations.append(
                        {
                            "value": value,
                            "context": context_value,
                            "is_primary": index == 0,
                        }
                    )
                    if index > 0:
                        rebuilt_secondary.append(
                            {
                                "value": value,
                                "priority": index + 1,
                                "context": context_value,
                                "example_source": example_source,
                                "example_target": example_target,
                            }
                        )
                response_json["dictionary_senses"] = rebuilt_senses
                response_json["translations"] = rebuilt_translations
                response_json["meanings"] = {
                    "primary": {
                        "value": rebuilt_senses[0]["value"],
                        "priority": 1,
                        "context": rebuilt_senses[0]["context"],
                        "example_source": rebuilt_senses[0]["example_source"],
                        "example_target": rebuilt_senses[0]["example_target"],
                    },
                    "secondary": rebuilt_secondary,
                }

            should_update_texts = (
                word_de is not None
                or translation_ru is not None
                or normalized_senses is not None
            )
            if should_update_texts:
                effective_german = normalized_word if word_de is not None else current_word_de
                if normalized_senses is not None and normalized_senses:
                    effective_russian = normalized_senses[0]
                elif translation_ru is not None:
                    effective_russian = normalized_translation
                else:
                    effective_russian = current_translation_ru

                aligned_columns, _source_text, _target_text, aligned_response_json = _apply_ru_de_dictionary_pair_alignment(
                    source_lang=source_lang,
                    target_lang=target_lang,
                    german_text=effective_german,
                    russian_text=effective_russian,
                    current_word_ru=current_word_ru,
                    current_translation_de=current_translation_de,
                    current_word_de=current_word_de,
                    current_translation_ru=current_translation_ru,
                    response_json=response_json,
                )
                response_json = aligned_response_json
                set_parts.extend(
                    [
                        "word_ru = %s",
                        "translation_de = %s",
                        "word_de = %s",
                        "translation_ru = %s",
                    ]
                )
                params.extend(
                    [
                        aligned_columns["word_ru"],
                        aligned_columns["translation_de"],
                        aligned_columns["word_de"],
                        aligned_columns["translation_ru"],
                    ]
                )

            if clear_folder:
                set_parts.append("folder_id = NULL")
            elif folder_id is not None:
                set_parts.append("folder_id = %s")
                params.append(int(folder_id))

            if word_de is not None or translation_ru is not None or normalized_senses is not None:
                set_parts.append("response_json = %s")
                params.append(json.dumps(response_json, ensure_ascii=False))

            if not set_parts:
                cursor.execute(
                    """
                    SELECT id, word_ru, translation_de, word_de, translation_ru,
                           source_lang, target_lang, folder_id, created_at, updated_at, is_learned, response_json
                    FROM bt_3_webapp_dictionary_queries WHERE id = %s
                    """,
                    (int(entry_id),),
                )
            else:
                set_parts.append("updated_at = NOW()")
                params.append(int(entry_id))
                params.append(int(user_id))
                cursor.execute(
                    f"""
                    UPDATE bt_3_webapp_dictionary_queries
                    SET {', '.join(set_parts)}
                    WHERE id = %s AND user_id = %s
                    RETURNING id, word_ru, translation_de, word_de, translation_ru,
                              source_lang, target_lang, folder_id, created_at, updated_at, is_learned, response_json
                    """,
                    params,
                )
            row = cursor.fetchone()
            if not row:
                return None

            # Запоминаем, какие поля человек написал СВОЕЙ рукой. С этого момента
            # централизованное обогащение их не трогает, а остальные поля продолжает
            # обновлять. Защита включается сама, без галочек: AnkiHub пришёл к этому не
            # сразу — пока пометку ставили руками, люди её забывали и теряли свою работу.
            try:
                ensure_user_word_overrides_schema()
                cursor.execute(
                    "SELECT lex_unit_id FROM bt_3_webapp_dictionary_queries WHERE id = %s;",
                    (int(entry_id),),
                )
                unit_row = cursor.fetchone()
                unit_id = int(unit_row[0]) if unit_row and unit_row[0] else None
                if word_de is not None:
                    record_user_word_override(cursor, user_id=user_id, entry_id=entry_id,
                                              unit_id=unit_id, field_key="word_de",
                                              value=normalized_word)
                if translation_ru is not None:
                    record_user_word_override(cursor, user_id=user_id, entry_id=entry_id,
                                              unit_id=unit_id, field_key="translation_ru",
                                              value=normalized_translation)
                if dictionary_senses is not None:
                    record_user_word_override(cursor, user_id=user_id, entry_id=entry_id,
                                              unit_id=unit_id, field_key="dictionary_senses",
                                              value=normalized_senses)
            except Exception:
                # Правка человека уже сохранена — пометка о ней второстепенна и не имеет
                # права уронить сохранение.
                logging.warning("личная правка не помечена как защищённая", exc_info=True)

            return {
                "id": row[0],
                "word_ru": row[1] or "",
                "translation_de": row[2] or "",
                "word_de": row[3] or "",
                "translation_ru": row[4] or "",
                "source_lang": row[5] or "",
                "target_lang": row[6] or "",
                "folder_id": row[7],
                "created_at": row[8].isoformat() if row[8] else None,
                "updated_at": row[9].isoformat() if row[9] else None,
                "is_learned": bool(row[10]),
                "response_json": _coerce_json_object(row[11]),
            }


def bulk_assign_vocabulary_folder(
    user_id: int,
    entry_ids: list[int],
    folder_id: int | None,
) -> int:
    """Set folder_id on multiple vocabulary entries. Returns number of updated rows."""
    if not entry_ids:
        return 0
    safe_ids = [int(eid) for eid in entry_ids]
    with get_db_connection_context() as conn:
        with conn.cursor() as cursor:
            placeholders = ", ".join(["%s"] * len(safe_ids))
            if folder_id is None:
                params: list = [int(user_id)] + safe_ids
                cursor.execute(
                    f"""
                    UPDATE bt_3_webapp_dictionary_queries
                    SET folder_id = NULL,
                        updated_at = NOW()
                    WHERE user_id = %s AND id IN ({placeholders})
                    """,
                    params,
                )
            else:
                params = [int(folder_id), int(user_id)] + safe_ids
                cursor.execute(
                    f"""
                    UPDATE bt_3_webapp_dictionary_queries
                    SET folder_id = %s,
                        updated_at = NOW()
                    WHERE user_id = %s AND id IN ({placeholders})
                    """,
                    params,
                )
            return cursor.rowcount


