def finish_scheduler_run_guard(
    *,
    job_key: str,
    run_period: str,
    target_scope: str = "global",
    status: str = "completed",
    metadata: dict | None = None,
) -> None:
    normalized_status = str(status or "completed").strip().lower()
    if normalized_status not in {"completed", "failed", "running"}:
        normalized_status = "completed"
    payload = metadata if isinstance(metadata, dict) else {}
    with get_db_connection_context() as conn:
        with conn.cursor() as cursor:
            cursor.execute(
                """
                UPDATE bt_3_scheduler_run_guards
                SET
                    status = %s,
                    metadata = COALESCE(metadata, '{}'::jsonb) || %s::jsonb,
                    finished_at = CASE
                        WHEN %s = 'running' THEN finished_at
                        ELSE NOW()
                    END,
                    updated_at = NOW()
                WHERE job_key = %s
                  AND run_period = %s
                  AND target_scope = %s;
                """,
                (
                    normalized_status,
                    Json(payload),
                    normalized_status,
                    str(job_key or "").strip()[:80],
                    str(run_period or "").strip()[:32],
                    str(target_scope or "global").strip()[:80] or "global",
                ),
            )


def record_scheduler_heartbeat(
    *,
    job_key: str,
    status: str = "completed",
    metadata: dict | None = None,
    target_scope: str = "global",
) -> None:
    """Non-gating 'this job just ran' marker, for observability ONLY.

    Unlike claim_scheduler_run_guard (a dedup LOCK that can REFUSE a second run and
    return False), this NEVER blocks execution and NEVER returns a claim decision — it
    simply upserts a single row per job_key so /scheduler_health can show a last-run
    time for jobs that don't need dedup (interactive deliveries, cleanups, sweeps).

    It writes under a FIXED run_period='hb' so exactly one heartbeat row exists per
    job and it coexists harmlessly with any real claim/finish guard rows for the same
    job_key (the health reader takes the newest row per job_key via DISTINCT ON, so a
    real guard that finishes later still wins). Best-effort: callers should also guard
    with try/except so a heartbeat write can never break the underlying job."""
    normalized_status = str(status or "completed").strip().lower()
    if normalized_status not in {"completed", "failed", "running"}:
        normalized_status = "completed"
    payload = metadata if isinstance(metadata, dict) else {}
    with get_db_connection_context() as conn:
        with conn.cursor() as cursor:
            cursor.execute(
                """
                INSERT INTO bt_3_scheduler_run_guards (
                    job_key,
                    run_period,
                    target_scope,
                    status,
                    metadata,
                    claimed_at,
                    finished_at,
                    updated_at
                )
                VALUES (%s, 'hb', %s, %s, %s::jsonb, NOW(), NOW(), NOW())
                ON CONFLICT (job_key, run_period, target_scope) DO UPDATE SET
                    status = EXCLUDED.status,
                    metadata = EXCLUDED.metadata,
                    finished_at = NOW(),
                    updated_at = NOW();
                """,
                (
                    str(job_key or "").strip()[:80],
                    str(target_scope or "global").strip()[:80] or "global",
                    normalized_status,
                    Json(payload),
                ),
            )


def get_latest_scheduler_run_guard(
    *,
    job_key: str,
    target_scope: str = "global",
    status: str | None = None,
) -> dict | None:
    normalized_status = str(status or "").strip().lower() or None
    with get_db_connection_context() as conn:
        with conn.cursor() as cursor:
            if normalized_status:
                cursor.execute(
                    """
                    SELECT
                        job_key,
                        run_period,
                        target_scope,
                        status,
                        metadata,
                        claimed_at,
                        finished_at,
                        updated_at
                    FROM bt_3_scheduler_run_guards
                    WHERE job_key = %s
                      AND target_scope = %s
                      AND status = %s
                    ORDER BY COALESCE(finished_at, updated_at, claimed_at) DESC
                    LIMIT 1;
                    """,
                    (
                        str(job_key or "").strip()[:80],
                        str(target_scope or "global").strip()[:80] or "global",
                        normalized_status,
                    ),
                )
            else:
                cursor.execute(
                    """
                    SELECT
                        job_key,
                        run_period,
                        target_scope,
                        status,
                        metadata,
                        claimed_at,
                        finished_at,
                        updated_at
                    FROM bt_3_scheduler_run_guards
                    WHERE job_key = %s
                      AND target_scope = %s
                    ORDER BY COALESCE(finished_at, updated_at, claimed_at) DESC
                    LIMIT 1;
                    """,
                    (
                        str(job_key or "").strip()[:80],
                        str(target_scope or "global").strip()[:80] or "global",
                    ),
                )
            row = cursor.fetchone()
    if not row:
        return None
    metadata = row[4] if isinstance(row[4], dict) else {}
    return {
        "job_key": str(row[0] or "").strip(),
        "run_period": str(row[1] or "").strip(),
        "target_scope": str(row[2] or "").strip(),
        "status": str(row[3] or "").strip(),
        "metadata": metadata,
        "claimed_at": row[5],
        "finished_at": row[6],
        "updated_at": row[7],
    }


def get_all_latest_scheduler_run_guards(*, target_scope: str = "global") -> list[dict]:
    """Latest run-guard row per job_key (any status), newest first by last activity.
    Used by the /scheduler_health admin command to see which scheduled jobs actually
    ran and when — the forensic source of truth for 'what silently stopped'."""
    with get_db_connection_context() as conn:
        with conn.cursor() as cursor:
            cursor.execute(
                """
                SELECT DISTINCT ON (job_key)
                    job_key,
                    run_period,
                    target_scope,
                    status,
                    metadata,
                    claimed_at,
                    finished_at,
                    updated_at
                FROM bt_3_scheduler_run_guards
                WHERE target_scope = %s
                ORDER BY job_key, COALESCE(finished_at, updated_at, claimed_at) DESC;
                """,
                (str(target_scope or "global").strip()[:80] or "global",),
            )
            rows = cursor.fetchall()
    result: list[dict] = []
    for row in rows:
        metadata = row[4] if isinstance(row[4], dict) else {}
        result.append(
            {
                "job_key": str(row[0] or "").strip(),
                "run_period": str(row[1] or "").strip(),
                "target_scope": str(row[2] or "").strip(),
                "status": str(row[3] or "").strip(),
                "metadata": metadata,
                "claimed_at": row[5],
                "finished_at": row[6],
                "updated_at": row[7],
            }
        )
    _epoch = datetime.min.replace(tzinfo=timezone.utc)
    result.sort(
        key=lambda item: (item.get("finished_at") or item.get("updated_at") or item.get("claimed_at") or _epoch),
        reverse=True,
    )
    return result


def get_all_latest_admin_scheduler_runs() -> list[dict]:
    """Latest run per job_key from bt_3_admin_scheduler_runs (a SEPARATE tracking table
    from bt_3_scheduler_run_guards — presence of a row = the job ran and delivered to a
    chat). Used by /scheduler_health so admin-report jobs (monthly_budget_report,
    weekly_user_removal_digest, group_enrollment_prompt) aren't falsely shown as 'never'."""
    with get_db_connection_context() as conn:
        with conn.cursor() as cursor:
            cursor.execute(
                """
                SELECT DISTINCT ON (job_key)
                    job_key,
                    run_period,
                    target_chat_id,
                    metadata,
                    created_at
                FROM bt_3_admin_scheduler_runs
                ORDER BY job_key, created_at DESC;
                """
            )
            rows = cursor.fetchall()
    result: list[dict] = []
    for row in rows:
        metadata = row[3] if isinstance(row[3], dict) else {}
        result.append(
            {
                "job_key": str(row[0] or "").strip(),
                "run_period": str(row[1] or "").strip(),
                "target_chat_id": int(row[2] or 0),
                "metadata": metadata,
                "created_at": row[4],
            }
        )
    return result


def _map_semantic_benchmark_library_row(row: tuple | None) -> dict | None:
    if not row:
        return None
    return {
        "id": int(row[0]),
        "source_lang": str(row[1] or "ru"),
        "target_lang": str(row[2] or "de"),
        "source_sentence": str(row[3] or ""),
        "source_sentence_hash": str(row[4] or ""),
        "benchmark_json": row[5] if isinstance(row[5], dict) else {},
        "benchmark_status": str(row[6] or "pending"),
        "benchmark_confidence": str(row[7] or "") or None,
        "sentence_level_anchor": str(row[8] or "") or None,
        "prompt_version": str(row[9] or "") or None,
        "llm_model": str(row[10] or "") or None,
        "notes": str(row[11] or "") or None,
        "metadata": row[12] if isinstance(row[12], dict) else {},
        "approved_at": row[13].isoformat() if row[13] else None,
        "last_used_at": row[14].isoformat() if row[14] else None,
        "created_at": row[15].isoformat() if row[15] else None,
        "updated_at": row[16].isoformat() if row[16] else None,
    }


def get_semantic_benchmark_library_entry(
    *,
    source_sentence: str,
    source_lang: str = "ru",
    target_lang: str = "de",
) -> dict | None:
    sentence_text = " ".join(str(source_sentence or "").strip().split())
    if not sentence_text:
        return None
    sentence_hash = _semantic_benchmark_sentence_hash(
        sentence_text,
        source_lang=source_lang,
        target_lang=target_lang,
    )
    with get_db_connection_context() as conn:
        with conn.cursor() as cursor:
            cursor.execute(
                """
                SELECT
                    id,
                    source_lang,
                    target_lang,
                    source_sentence,
                    source_sentence_hash,
                    benchmark_json,
                    benchmark_status,
                    benchmark_confidence,
                    sentence_level_anchor,
                    prompt_version,
                    llm_model,
                    notes,
                    metadata,
                    approved_at,
                    last_used_at,
                    created_at,
                    updated_at
                FROM bt_3_semantic_benchmark_library
                WHERE source_lang = %s
                  AND target_lang = %s
                  AND source_sentence_hash = %s
                LIMIT 1;
                """,
                (
                    str(source_lang or "ru").strip().lower(),
                    str(target_lang or "de").strip().lower(),
                    sentence_hash,
                ),
            )
            return _map_semantic_benchmark_library_row(cursor.fetchone())


def upsert_semantic_benchmark_library_entry(
    *,
    source_sentence: str,
    benchmark_json: dict | None,
    source_lang: str = "ru",
    target_lang: str = "de",
    benchmark_status: str = "ready",
    benchmark_confidence: str | None = None,
    sentence_level_anchor: str | None = None,
    prompt_version: str | None = None,
    llm_model: str | None = None,
    notes: str | None = None,
    metadata: dict | None = None,
    approved: bool = False,
) -> dict | None:
    sentence_text = " ".join(str(source_sentence or "").strip().split())
    if not sentence_text:
        return None
    status_value = str(benchmark_status or "ready").strip().lower() or "ready"
    confidence_value = str(benchmark_confidence or "").strip().lower() or None
    sentence_hash = _semantic_benchmark_sentence_hash(
        sentence_text,
        source_lang=source_lang,
        target_lang=target_lang,
    )
    with get_db_connection_context() as conn:
        with conn.cursor() as cursor:
            cursor.execute(
                """
                INSERT INTO bt_3_semantic_benchmark_library (
                    source_lang,
                    target_lang,
                    source_sentence,
                    source_sentence_hash,
                    benchmark_json,
                    benchmark_status,
                    benchmark_confidence,
                    sentence_level_anchor,
                    prompt_version,
                    llm_model,
                    notes,
                    metadata,
                    approved_at,
                    updated_at
                )
                VALUES (%s, %s, %s, %s, %s::jsonb, %s, %s, %s, %s, %s, %s, %s::jsonb, %s, NOW())
                ON CONFLICT (source_lang, target_lang, source_sentence_hash)
                DO UPDATE SET
                    source_sentence = EXCLUDED.source_sentence,
                    benchmark_json = EXCLUDED.benchmark_json,
                    benchmark_status = EXCLUDED.benchmark_status,
                    benchmark_confidence = EXCLUDED.benchmark_confidence,
                    sentence_level_anchor = EXCLUDED.sentence_level_anchor,
                    prompt_version = EXCLUDED.prompt_version,
                    llm_model = EXCLUDED.llm_model,
                    notes = EXCLUDED.notes,
                    metadata = EXCLUDED.metadata,
                    approved_at = COALESCE(EXCLUDED.approved_at, bt_3_semantic_benchmark_library.approved_at),
                    updated_at = NOW()
                RETURNING
                    id,
                    source_lang,
                    target_lang,
                    source_sentence,
                    source_sentence_hash,
                    benchmark_json,
                    benchmark_status,
                    benchmark_confidence,
                    sentence_level_anchor,
                    prompt_version,
                    llm_model,
                    notes,
                    metadata,
                    approved_at,
                    last_used_at,
                    created_at,
                    updated_at;
                """,
                (
                    str(source_lang or "ru").strip().lower(),
                    str(target_lang or "de").strip().lower(),
                    sentence_text,
                    sentence_hash,
                    Json(benchmark_json if isinstance(benchmark_json, dict) else {}),
                    status_value,
                    confidence_value,
                    str(sentence_level_anchor or "").strip() or None,
                    str(prompt_version or "").strip() or None,
                    str(llm_model or "").strip() or None,
                    str(notes or "").strip() or None,
                    Json(metadata if isinstance(metadata, dict) else {}),
                    datetime.now(timezone.utc) if approved else None,
                ),
            )
            return _map_semantic_benchmark_library_row(cursor.fetchone())


