def claim_reader_library_document_processing(
    *,
    user_id: int,
    document_id: int,
    source_lang: str,
    target_lang: str,
    stale_after_seconds: int = 0,
    include_failed: bool = False,
) -> dict | None:
    normalized_source = str(source_lang or "ru").strip().lower() or "ru"
    normalized_target = str(target_lang or "de").strip().lower() or "de"
    normalized_stale_after = max(0, int(stale_after_seconds or 0))
    with get_db_connection_context() as conn:
        with conn.cursor() as cursor:
            cursor.execute(
                """
                UPDATE bt_3_reader_library
                SET
                    processing_status = 'processing',
                    processing_error = NULL,
                    processing_started_at = NOW(),
                    processing_finished_at = NULL,
                    processing_attempts = COALESCE(processing_attempts, 0) + 1,
                    updated_at = NOW()
                WHERE id = %s
                  AND user_id = %s
                  AND source_lang = %s
                  AND target_lang = %s
                  AND (
                    processing_status = 'pending'
                    OR (%s AND processing_status = 'failed')
                    OR (
                        processing_status = 'processing'
                        AND %s > 0
                        AND COALESCE(processing_started_at, updated_at, created_at) <= NOW() - (%s * INTERVAL '1 second')
                    )
                  )
                RETURNING
                    id, user_id, source_lang, target_lang, title, source_type, source_url,
                    text_hash, total_chars, progress_percent, bookmark_percent, reading_mode,
                    processing_status, processing_error, processing_started_at, processing_finished_at,
                    is_archived, archived_at, last_opened_at, created_at, updated_at;
                """,
                (
                    int(document_id),
                    int(user_id),
                    normalized_source,
                    normalized_target,
                    bool(include_failed),
                    normalized_stale_after,
                    normalized_stale_after,
                ),
            )
            row = cursor.fetchone()
    if not row:
        return None
    return _reader_library_row_to_dict(row, include_content=False)


def finalize_reader_library_document_processing(
    *,
    user_id: int,
    document_id: int,
    source_lang: str,
    target_lang: str,
    title: str,
    source_type: str,
    source_url: str | None,
    content_text: str,
    content_pages: list | None = None,
    cover_image_url: str | None = None,
) -> dict | None:
    normalized_source = str(source_lang or "ru").strip().lower() or "ru"
    normalized_target = str(target_lang or "de").strip().lower() or "de"
    resolved_title = str(title or "Untitled").strip() or "Untitled"
    resolved_source_type = str(source_type or "text").strip().lower() or "text"
    resolved_source_url = str(source_url or "").strip() or None
    resolved_cover = str(cover_image_url or "").strip() or None
    resolved_content = str(content_text or "").strip()
    resolved_pages = content_pages if isinstance(content_pages, list) else []
    total_chars = len(resolved_content)
    text_hash = hashlib.sha256(resolved_content.encode("utf-8")).hexdigest()

    with get_db_connection_context() as conn:
        with conn.cursor() as cursor:
            cursor.execute(
                """
                SELECT progress_percent, bookmark_percent, reading_mode
                FROM bt_3_reader_library
                WHERE user_id = %s
                  AND source_lang = %s
                  AND target_lang = %s
                  AND text_hash = %s
                  AND id <> %s
                ORDER BY COALESCE(last_opened_at, updated_at, created_at) DESC
                LIMIT 1;
                """,
                (
                    int(user_id),
                    normalized_source,
                    normalized_target,
                    text_hash,
                    int(document_id),
                ),
            )
            duplicate_row = cursor.fetchone()
            duplicate_progress = float(duplicate_row[0] or 0.0) if duplicate_row else None
            duplicate_bookmark = float(duplicate_row[1] or 0.0) if duplicate_row else None
            duplicate_mode = str(duplicate_row[2] or "").strip().lower() if duplicate_row else ""
            if duplicate_mode not in {"vertical", "horizontal"}:
                duplicate_mode = ""
            if duplicate_row:
                cursor.execute(
                    """
                    DELETE FROM bt_3_reader_library
                    WHERE user_id = %s
                      AND source_lang = %s
                      AND target_lang = %s
                      AND text_hash = %s
                      AND id <> %s;
                    """,
                    (
                        int(user_id),
                        normalized_source,
                        normalized_target,
                        text_hash,
                        int(document_id),
                    ),
                )

            cursor.execute(
                """
                UPDATE bt_3_reader_library
                SET
                    title = %s,
                    source_type = %s,
                    source_url = %s,
                    cover_image_url = COALESCE(%s, cover_image_url),
                    text_hash = %s,
                    content_text = %s,
                    content_pages = %s::jsonb,
                    total_chars = %s,
                    progress_percent = COALESCE(%s, progress_percent),
                    bookmark_percent = COALESCE(%s, bookmark_percent),
                    reading_mode = COALESCE(NULLIF(%s, ''), reading_mode),
                    processing_status = 'ready',
                    processing_error = NULL,
                    processing_started_at = COALESCE(processing_started_at, NOW()),
                    processing_finished_at = NOW(),
                    ingest_payload = '{}'::jsonb,
                    is_archived = FALSE,
                    archived_at = NULL,
                    last_opened_at = NOW(),
                    updated_at = NOW()
                WHERE id = %s
                  AND user_id = %s
                  AND source_lang = %s
                  AND target_lang = %s
                RETURNING
                    id, user_id, source_lang, target_lang, title, source_type, source_url,
                    text_hash, total_chars, progress_percent, bookmark_percent, reading_mode,
                    processing_status, processing_error, processing_started_at, processing_finished_at,
                    is_archived, archived_at, last_opened_at, created_at, updated_at, content_text, content_pages, cover_image_url;
                """,
                (
                    resolved_title,
                    resolved_source_type,
                    resolved_source_url,
                    resolved_cover,
                    text_hash,
                    resolved_content,
                    json.dumps(resolved_pages, ensure_ascii=False),
                    total_chars,
                    duplicate_progress,
                    duplicate_bookmark,
                    duplicate_mode,
                    int(document_id),
                    int(user_id),
                    normalized_source,
                    normalized_target,
                ),
            )
            row = cursor.fetchone()
    if not row:
        return None
    return _reader_library_row_to_dict(row, include_content=True)


