def _normalize_subscription_status(status: str | None) -> str:
    value = str(status or "").strip().lower() or "inactive"
    allowed = {"active", "inactive", "past_due", "canceled", "trialing"}
    if value not in allowed:
        raise ValueError(f"Unsupported subscription status: {value!r}")
    return value


def get_or_create_user_subscription(
    user_id: int,
    now_ts: datetime | None = None,
    tz: str = TRIAL_POLICY_TZ,
) -> dict:
    """Race-safe create-or-get via INSERT .. ON CONFLICT DO NOTHING + SELECT."""
    user_id_value = int(user_id)
    with get_db_connection_context() as conn:
        with conn.cursor() as cursor:
            cursor.execute(
                """
                INSERT INTO user_subscriptions (
                    user_id,
                    plan_code,
                    status,
                    trial_ends_at,
                    updated_at
                )
                VALUES (%s, 'free', 'inactive', NULL, NOW())
                ON CONFLICT (user_id) DO NOTHING
                RETURNING
                    user_id,
                    plan_code,
                    status,
                    trial_ends_at,
                    current_period_end,
                    stripe_customer_id,
                    stripe_subscription_id,
                    created_at,
                    updated_at;
                """,
                (user_id_value,),
            )
            row = cursor.fetchone()
            if not row:
                cursor.execute(
                    """
                    SELECT
                        user_id,
                        plan_code,
                        status,
                        trial_ends_at,
                        current_period_end,
                        stripe_customer_id,
                        stripe_subscription_id,
                        created_at,
                        updated_at
                    FROM user_subscriptions
                    WHERE user_id = %s
                    LIMIT 1;
                    """,
                    (user_id_value,),
                )
                row = cursor.fetchone()
    if not row:
        raise RuntimeError("Failed to create or fetch user subscription")
    return _subscription_row_to_dict(row)


def bind_stripe_customer_to_user(user_id: int, stripe_customer_id: str, db_conn=None) -> dict:
    user_id_value = int(user_id)
    customer_id_value = str(stripe_customer_id or "").strip()
    if not customer_id_value:
        raise ValueError("stripe_customer_id is required")
    owns_conn = db_conn is None
    if owns_conn:
        with get_db_connection_context() as conn:
            with conn.cursor() as cursor:
                cursor.execute(
                    """
                    INSERT INTO user_subscriptions (
                        user_id,
                        plan_code,
                        status,
                        trial_ends_at,
                        stripe_customer_id,
                        updated_at
                    )
                    VALUES (%s, 'free', 'inactive', %s, %s, NOW())
                    ON CONFLICT (user_id) DO UPDATE
                    SET
                        stripe_customer_id = EXCLUDED.stripe_customer_id,
                        updated_at = NOW()
                    RETURNING
                        user_id,
                        plan_code,
                        status,
                        trial_ends_at,
                        current_period_end,
                        stripe_customer_id,
                        stripe_subscription_id,
                        created_at,
                        updated_at;
                    """,
                    (
                        user_id_value,
                        None,  # trial discontinued: bind starts as inactive-free, no trial_ends_at
                        customer_id_value,
                    ),
                )
                row = cursor.fetchone()
    else:
        with db_conn.cursor() as cursor:
            cursor.execute(
                """
                INSERT INTO user_subscriptions (
                    user_id,
                    plan_code,
                    status,
                    trial_ends_at,
                    stripe_customer_id,
                    updated_at
                )
                VALUES (%s, 'free', 'inactive', %s, %s, NOW())
                ON CONFLICT (user_id) DO UPDATE
                SET
                    stripe_customer_id = EXCLUDED.stripe_customer_id,
                    updated_at = NOW()
                RETURNING
                    user_id,
                    plan_code,
                    status,
                    trial_ends_at,
                    current_period_end,
                    stripe_customer_id,
                    stripe_subscription_id,
                    created_at,
                    updated_at;
                """,
                (
                    user_id_value,
                    None,  # trial discontinued: bind starts as inactive-free, no trial_ends_at
                    customer_id_value,
                ),
            )
            row = cursor.fetchone()
    if not row:
        raise RuntimeError("Failed to bind stripe customer to user subscription")
    _bust_entitlement_cache(int(user_id_value))  # subscription row changed → re-resolve
    return _subscription_row_to_dict(row)


def _shift_banked_grants_on_extension(
    user_id: int,
    plan_code: str,
    old_period_end: datetime | None,
    new_period_end: datetime | None,
) -> None:
    """Keep banked bonus Pro days sitting AFTER the paid period when coverage extends.

    `grant_pro_days` banks a paying user's bonus days to start at the paid-period end, but
    it fixes an absolute `granted_until`. A later renewal moves the paid period forward and
    would otherwise SWALLOW those banked days (they'd expire inside newly paid time, wasted).
    Here, whenever the paid coverage extends (a renewal, or a Free user with an active bonus
    switching to Pro), we push every still-future grant forward by the same amount so the
    reserve days always remain beyond the paid period. No-op for downgrades to Free (bonus
    should activate immediately) and for cancellations (period end unchanged → no extension)."""
    try:
        if str(plan_code or "free").strip().lower() == "free" or not new_period_end:
            return
        new_end = _to_aware_datetime(new_period_end)
        now_ref = datetime.now(timezone.utc)
        old_end = _to_aware_datetime(old_period_end) if old_period_end else None
        # Boundary the banked grants were anchored at (start of the coverage being extended).
        # max(now, old_end): renewal → old_end is in the future; free→paid or repurchase after
        # a lapse → old_end is None/past, so we bank past `now`.
        reference = old_end if (old_end and old_end > now_ref) else now_ref
        if new_end <= reference:
            return  # not an extension (cancellation keeps period_end unchanged)
        with get_db_connection_context() as conn:
            with conn.cursor() as cur:
                cur.execute(
                    """
                    UPDATE bt_3_pro_grants
                       SET granted_until = granted_until + (%s - %s)
                     WHERE user_id = %s AND granted_until > %s;
                    """,
                    (new_end, reference, int(user_id), reference),
                )
            conn.commit()
    except Exception:
        logging.warning("shift banked grants on extension failed user=%s", user_id, exc_info=True)


def set_subscription_from_stripe(
    user_id: int,
    plan_code: str,
    stripe_customer_id: str | None,
    stripe_subscription_id: str | None,
    status: str,
    current_period_end: datetime | None,
    db_conn=None,
) -> dict:
    user_id_value = int(user_id)
    plan_code_value = str(plan_code or "pro").strip().lower() or "pro"
    status_value = _normalize_subscription_status(status)
    period_end_value = _to_aware_datetime(current_period_end) if current_period_end else None
    # Capture the pre-existing paid period end BEFORE the upsert overwrites it, so we can
    # re-bank bonus grants forward when this call extends the coverage (see helper above).
    _old_period_end = None
    try:
        _existing_sub = get_user_subscription(user_id_value)
        _old_period_end = _existing_sub.get("current_period_end") if _existing_sub else None
    except Exception:
        _old_period_end = None
    customer_id_value = str(stripe_customer_id or "").strip() or None
    subscription_id_value = str(stripe_subscription_id or "").strip() or None
    owns_conn = db_conn is None
    if owns_conn:
        with get_db_connection_context() as conn:
            with conn.cursor() as cursor:
                cursor.execute(
                    """
                    INSERT INTO user_subscriptions (
                        user_id,
                        plan_code,
                        status,
                        trial_ends_at,
                        current_period_end,
                        stripe_customer_id,
                        stripe_subscription_id,
                        updated_at
                    )
                    VALUES (%s, %s, %s, NULL, %s, %s, %s, NOW())
                    ON CONFLICT (user_id) DO UPDATE
                    SET
                        plan_code = EXCLUDED.plan_code,
                        status = EXCLUDED.status,
                        trial_ends_at = NULL,
                        current_period_end = EXCLUDED.current_period_end,
                        stripe_customer_id = COALESCE(EXCLUDED.stripe_customer_id, user_subscriptions.stripe_customer_id),
                        stripe_subscription_id = COALESCE(EXCLUDED.stripe_subscription_id, user_subscriptions.stripe_subscription_id),
                        updated_at = NOW()
                    RETURNING
                        user_id,
                        plan_code,
                        status,
                        trial_ends_at,
                        current_period_end,
                        stripe_customer_id,
                        stripe_subscription_id,
                        created_at,
                        updated_at;
                    """,
                    (
                        user_id_value,
                        plan_code_value,
                        status_value,
                        period_end_value,
                        customer_id_value,
                        subscription_id_value,
                    ),
                )
                row = cursor.fetchone()
    else:
        with db_conn.cursor() as cursor:
            cursor.execute(
                """
                INSERT INTO user_subscriptions (
                    user_id,
                    plan_code,
                    status,
                    trial_ends_at,
                    current_period_end,
                    stripe_customer_id,
                    stripe_subscription_id,
                    updated_at
                )
                    VALUES (%s, %s, %s, NULL, %s, %s, %s, NOW())
                    ON CONFLICT (user_id) DO UPDATE
                    SET
                        plan_code = EXCLUDED.plan_code,
                    status = EXCLUDED.status,
                    trial_ends_at = NULL,
                    current_period_end = EXCLUDED.current_period_end,
                    stripe_customer_id = COALESCE(EXCLUDED.stripe_customer_id, user_subscriptions.stripe_customer_id),
                    stripe_subscription_id = COALESCE(EXCLUDED.stripe_subscription_id, user_subscriptions.stripe_subscription_id),
                    updated_at = NOW()
                RETURNING
                    user_id,
                    plan_code,
                    status,
                    trial_ends_at,
                    current_period_end,
                    stripe_customer_id,
                    stripe_subscription_id,
                    created_at,
                    updated_at;
                """,
                    (
                        user_id_value,
                        plan_code_value,
                        status_value,
                        period_end_value,
                        customer_id_value,
                    subscription_id_value,
                ),
            )
            row = cursor.fetchone()
    if not row:
        raise RuntimeError("Failed to upsert Stripe subscription")
    # Extension (renewal / free→paid) → push banked bonus days past the new paid period.
    _shift_banked_grants_on_extension(
        user_id_value, plan_code_value, _old_period_end, period_end_value
    )
    _bust_entitlement_cache(user_id_value)  # Stripe webhook changed the plan → re-resolve
    return _subscription_row_to_dict(row)


def try_mark_stripe_event_processed(event_id: str, db_conn=None) -> bool:
    """Insert-first idempotency marker. True only for the first successful insert."""
    event_id_value = str(event_id or "").strip()
    if not event_id_value:
        return False
    if db_conn is None:
        with get_db_connection_context() as conn:
            with conn.cursor() as cursor:
                cursor.execute(
                    """
                    INSERT INTO stripe_events_processed (event_id)
                    VALUES (%s)
                    ON CONFLICT (event_id) DO NOTHING
                    RETURNING event_id;
                    """,
                    (event_id_value,),
                )
                inserted = cursor.fetchone()
    else:
        with db_conn.cursor() as cursor:
            cursor.execute(
                """
                INSERT INTO stripe_events_processed (event_id)
                VALUES (%s)
                ON CONFLICT (event_id) DO NOTHING
                RETURNING event_id;
                """,
                (event_id_value,),
            )
            inserted = cursor.fetchone()
    return bool(inserted)


def mark_stripe_event_processed(event_id: str, db_conn=None) -> bool:
    # Backward-compatible alias; use try_mark_stripe_event_processed in webhook flow.
    return try_mark_stripe_event_processed(event_id, db_conn=db_conn)


def is_stripe_event_processed(event_id: str) -> bool:
    event_id_value = str(event_id or "").strip()
    if not event_id_value:
        return False
    with get_db_connection_context() as conn:
        with conn.cursor() as cursor:
            cursor.execute(
                """
                SELECT 1
                FROM stripe_events_processed
                WHERE event_id = %s
                LIMIT 1;
                """,
                (event_id_value,),
            )
            row = cursor.fetchone()
    return bool(row)


# Shared-pool / amortizable OpenAI work: enriching the GLOBAL dictionary pool
# (bt_3_dictionary_entries) benefits ALL users, so its cost must NOT count against the
# personal daily cost cap of whoever happened to trigger it — it's shared infrastructure,
# not personal consumption.
#
# DEFENSE-IN-DEPTH ONLY (since the source-attribution fix): these action_types are now
# forced to user_id=NULL at the billing chokepoint (openai_manager._SYSTEM_ATTRIBUTION_TASKS),
# so they never carry a user_id and are already invisible to the per-user cap's
# `WHERE user_id = %s` sum. This list is a belt-and-suspenders fallback, NOT the primary
# mechanism — you do NOT need to extend it when adding new shared work; add the task to
# _SYSTEM_ATTRIBUTION_TASKS instead (attribute at the source, don't subtract downstream).
DAILY_COST_CAP_EXCLUDED_ACTION_TYPES = (
    "enrich_word_multilang",
    "enrich_word",
    "dictionary_enrichment_multilang",
    # Sprint-game distractor bank generation (admin/nightly pool-building for the
    # synonym/antonym trainer, /admin_sprint_distractors). Shared content, not personal
    # consumption — must not land on the triggering user's daily cap.
    "sprint_distractor_setter",
    "sprint_distractor_prosecutor",
    "sprint_distractor_judge",
    "sprint_correct_examples",
    # Book narration (Reader). Two separate reasons, same conclusion — never on the
    # subscription's daily AI budget:
    #   • OWN books: the user already paid for that book's audio (per-book Stars unlock).
    #     Charging it again against the daily cap = paying twice (money + budget), and at
    #     ~€0.08/page it would burn a whole day's cap in under two pages.
    #   • CLASSICS: free for everyone by design; the narration is generated once and then
    #     served from cache to ALL readers, so it is shared content, not personal use.
    #     Its real constraint is the monthly google_tts_standard free bucket (4M chars),
    #     which the provider budget already guards — NOT a per-user euro cap.
    # OPEN QUESTION (parked with the owner): classics are synthesized on demand rather than
    # pre-generated (storage cost) while unread books get pruned ~2×/year — so how to fund
    # and pace classic narration still needs a decision. Revisit before launch.
    "reader_audio_tts",
    "reader_audio_tts_pages",
    "reader_audio_tts_fallback",
)

# Revenue-side infrastructure: what the PAYMENT rails cost us is a business expense tied to
# the user paying us — it is not something they "consumed". Left in, a single subscription
# payment (observed: €0.54 of Stripe fees) instantly exceeds a daily cap several times over
# and locks the user out of the app on the very day they paid.
DAILY_COST_CAP_EXCLUDED_PROVIDERS = (
    "stripe",
)


def get_today_cost_eur(user_id: int, tz: str = TRIAL_POLICY_TZ) -> float:
    user_id_value = int(user_id)
    tz_name = str(tz or TRIAL_POLICY_TZ).strip() or TRIAL_POLICY_TZ
    tzinfo = _resolve_timezone(tz_name)
    day_local = datetime.now(timezone.utc).astimezone(tzinfo).date()

    # Always recompute from source-of-truth billing events before writing rollup.
    # This avoids stale totals when new events arrive after an earlier rollup read.
    # Shared-pool building (DAILY_COST_CAP_EXCLUDED_ACTION_TYPES) is excluded — it is not
    # personal consumption and must not push a user into their daily cap.
    with get_db_connection_context() as conn:
        with conn.cursor() as cursor:
            cursor.execute(
                """
                SELECT currency, COALESCE(SUM(cost_amount), 0) AS total_cost
                FROM bt_3_billing_events
                WHERE user_id = %s
                  AND (event_time AT TIME ZONE %s)::date = %s
                  AND action_type <> ALL(%s)
                  AND provider <> ALL(%s)
                GROUP BY currency;
                """,
                (user_id_value, tz_name, day_local,
                 list(DAILY_COST_CAP_EXCLUDED_ACTION_TYPES),
                 list(DAILY_COST_CAP_EXCLUDED_PROVIDERS)),
            )
            rows = cursor.fetchall() or []
            total_eur = 0.0
            for row in rows:
                currency = str(row[0] or "EUR").upper()
                amount = float(row[1] or 0.0)
                try:
                    total_eur += convert_cost_to_eur(amount, currency)
                except ValueError:
                    continue

            cursor.execute(
                """
                INSERT INTO daily_cost_rollup (
                    user_id,
                    day,
                    currency,
                    total_cost_eur,
                    updated_at
                )
                VALUES (%s, %s, 'EUR', %s, NOW())
                ON CONFLICT (user_id, day) DO UPDATE
                SET
                    currency = 'EUR',
                    total_cost_eur = EXCLUDED.total_cost_eur,
                    updated_at = NOW();
                """,
                (user_id_value, day_local, total_eur),
            )
    return float(total_eur)


def get_today_cost_eur_fast(
    user_id: int,
    tz: str = TRIAL_POLICY_TZ,
    *,
    max_age_sec: int = 90,
) -> float:
    user_id_value = int(user_id)
    tz_name = str(tz or TRIAL_POLICY_TZ).strip() or TRIAL_POLICY_TZ
    tzinfo = _resolve_timezone(tz_name)
    day_local = datetime.now(timezone.utc).astimezone(tzinfo).date()
    max_age_value = max(0, int(max_age_sec or 0))

    with get_db_connection_context() as conn:
        with conn.cursor() as cursor:
            cursor.execute(
                """
                SELECT total_cost_eur, updated_at
                FROM daily_cost_rollup
                WHERE user_id = %s
                  AND day = %s
                LIMIT 1;
                """,
                (user_id_value, day_local),
            )
            row = cursor.fetchone()

    if row:
        total_cost_eur = float(row[0] or 0.0)
        updated_at = _to_aware_datetime(row[1]) if row[1] else None
        if updated_at is not None:
            age_sec = max(0.0, (datetime.now(timezone.utc) - updated_at).total_seconds())
            if age_sec <= float(max_age_value):
                return total_cost_eur

    return get_today_cost_eur(user_id_value, tz=tz_name)


def _next_local_midnight_iso(now_ts_utc: datetime | None = None, tz: str = TRIAL_POLICY_TZ) -> str:
    tzinfo = _resolve_timezone(tz)
    now_utc = _to_aware_datetime(now_ts_utc)
    local_now = now_utc.astimezone(tzinfo)
    next_day = local_now.date() + timedelta(days=1)
    next_midnight_local = datetime.combine(next_day, dt_time.min, tzinfo=tzinfo)
    return next_midnight_local.isoformat()


def _next_local_month_start_iso(now_ts_utc: datetime | None = None, tz: str = TRIAL_POLICY_TZ) -> str:
    tzinfo = _resolve_timezone(tz)
    now_utc = _to_aware_datetime(now_ts_utc)
    local_now = now_utc.astimezone(tzinfo)
    if local_now.month == 12:
        next_month_date = date(local_now.year + 1, 1, 1)
    else:
        next_month_date = date(local_now.year, local_now.month + 1, 1)
    next_month_local = datetime.combine(next_month_date, dt_time.min, tzinfo=tzinfo)
    return next_month_local.isoformat()


