def get_free_feature_limit_metadata(feature_key: str) -> dict[str, Any] | None:
    feature = str(feature_key or "").strip().lower()
    if not feature:
        return None
    meta = FREE_FEATURE_LIMITS.get(feature)
    if not isinstance(meta, dict):
        return None
    result = dict(meta)
    try:
        with get_db_connection_context() as conn:
            with conn.cursor() as cursor:
                return _free_feature_limit_metadata_from_cursor(feature, cursor) or result
    except Exception:
        result["source"] = "metadata"
    return result


def _free_feature_limit_metadata_from_cursor(feature_key: str, cursor) -> dict[str, Any] | None:
    feature = str(feature_key or "").strip().lower()
    meta = FREE_FEATURE_LIMITS.get(feature)
    if not feature or not isinstance(meta, dict):
        return None
    result = dict(meta)
    try:
        cursor.execute(
            """
            SELECT limit_value
            FROM plan_limits
            WHERE plan_code = 'free'
              AND feature_code = %s
              AND period = 'day'
              AND is_active = TRUE
            LIMIT 1;
            """,
            (feature,),
        )
        row = cursor.fetchone()
        if row:
            value = float(row[0] or 0.0)
            result["free_limit"] = int(value) if float(value).is_integer() else value
            result["source"] = "plan_limits"
        else:
            result["source"] = "metadata"
    except Exception:
        result["source"] = "metadata"
    return result


def ensure_admin_economics_schema() -> None:
    """Create admin economics tables and seed editable FREE limits.

    This is intentionally idempotent so both scheduler workers and Telegram
    callbacks can call it before using the dashboard.
    """
    with get_db_connection_context() as conn:
        with conn.cursor() as cursor:
            cursor.execute(
                """
                CREATE TABLE IF NOT EXISTS bt_3_limit_runtime_events (
                    id BIGSERIAL PRIMARY KEY,
                    user_id BIGINT,
                    feature_code TEXT NOT NULL,
                    event_type TEXT NOT NULL,
                    origin TEXT,
                    units_value DOUBLE PRECISION NOT NULL DEFAULT 1,
                    metadata JSONB NOT NULL DEFAULT '{}'::jsonb,
                    event_time TIMESTAMPTZ NOT NULL DEFAULT NOW(),
                    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
                    CHECK (units_value >= 0),
                    CHECK (event_type IN (
                        'accepted',
                        'blocked',
                        'cache_hit',
                        'db_cache_hit',
                        'memory_cache_hit',
                        'openai_execution',
                        'telemetry'
                    ))
                );
                """
            )
            cursor.execute(
                """
                CREATE INDEX IF NOT EXISTS idx_bt_3_limit_runtime_events_feature_time
                ON bt_3_limit_runtime_events (feature_code, event_type, event_time DESC);
                """
            )
            cursor.execute(
                """
                CREATE INDEX IF NOT EXISTS idx_bt_3_limit_runtime_events_user_time
                ON bt_3_limit_runtime_events (user_id, event_time DESC);
                """
            )
            cursor.execute(
                """
                CREATE TABLE IF NOT EXISTS bt_3_admin_limit_change_pending (
                    token TEXT PRIMARY KEY,
                    admin_user_id BIGINT NOT NULL,
                    plan_code TEXT NOT NULL DEFAULT 'free',
                    feature_code TEXT NOT NULL,
                    old_value NUMERIC(20, 10) NOT NULL,
                    new_value NUMERIC(20, 10) NOT NULL,
                    limit_unit TEXT NOT NULL DEFAULT 'count',
                    period TEXT NOT NULL DEFAULT 'day',
                    expires_at TIMESTAMPTZ NOT NULL,
                    metadata JSONB NOT NULL DEFAULT '{}'::jsonb,
                    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
                );
                """
            )
            cursor.execute(
                """
                CREATE INDEX IF NOT EXISTS idx_bt_3_admin_limit_change_pending_admin
                ON bt_3_admin_limit_change_pending (admin_user_id, expires_at DESC);
                """
            )
            cursor.execute(
                """
                CREATE TABLE IF NOT EXISTS bt_3_admin_limit_change_audit (
                    id BIGSERIAL PRIMARY KEY,
                    admin_user_id BIGINT NOT NULL,
                    plan_code TEXT NOT NULL DEFAULT 'free',
                    feature_code TEXT NOT NULL,
                    old_value NUMERIC(20, 10) NOT NULL,
                    new_value NUMERIC(20, 10) NOT NULL,
                    limit_unit TEXT NOT NULL DEFAULT 'count',
                    period TEXT NOT NULL DEFAULT 'day',
                    reason TEXT,
                    telegram_message_id BIGINT,
                    metadata JSONB NOT NULL DEFAULT '{}'::jsonb,
                    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
                );
                """
            )
            cursor.execute(
                """
                CREATE INDEX IF NOT EXISTS idx_bt_3_admin_limit_change_audit_feature_time
                ON bt_3_admin_limit_change_audit (feature_code, created_at DESC);
                """
            )
            cursor.execute(
                """
                CREATE TABLE IF NOT EXISTS bt_3_admin_economics_daily_snapshots (
                    day DATE PRIMARY KEY,
                    tz_name TEXT NOT NULL DEFAULT 'Europe/Vienna',
                    payload_json JSONB NOT NULL DEFAULT '{}'::jsonb,
                    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
                    updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
                );
                """
            )
            rows = []
            for feature, meta in sorted(FREE_FEATURE_LIMITS.items()):
                try:
                    free_limit = float(meta.get("free_limit"))
                except Exception:
                    continue
                rows.append(("free", feature, free_limit, "count", "day"))
            if rows:
                cursor.executemany(
                    """
                    INSERT INTO plan_limits (
                        plan_code,
                        feature_code,
                        limit_value,
                        limit_unit,
                        period,
                        is_active,
                        updated_at
                    )
                    VALUES (%s, %s, %s, %s, %s, TRUE, NOW())
                    ON CONFLICT (plan_code, feature_code, period) DO NOTHING;
                    """,
                    rows,
                )


# Unbounded telemetry/log tables: one row per event, never read by the long-term
# analytics (analytics.py reads CONTENT tables; cost history lives in the daily_cost_rollup
# aggregate). Old rows here are safe to drop so they can't fill a small DB volume.
# (table, timestamp_column). NEVER add a content/analytics/aggregate table here
# (daily_sentences, translations, user_progress, card_review_log, detailed_mistakes,
# webapp_dictionary_queries, daily_cost_rollup, *_daily_snapshots).
TELEMETRY_RETENTION_TABLES: tuple[tuple[str, str], ...] = (
    ("bt_3_billing_events", "created_at"),
    ("bt_3_user_api_snapshots", "refreshed_at"),
    ("bt_3_limit_runtime_events", "created_at"),
    ("bt_3_telegram_system_messages", "created_at"),
    # Per-event raw streams that grow one row per translation attempt / weak-topic
    # detection. Both are consumed shortly after write and never read long-term:
    # skill_events_v2 is folded into skill_state by the 5-min incremental aggregator
    # (id > last_event_id) and the daily read only touches events since the user's
    # reset; weak_topic_events is a `processed_at IS NULL` work queue. Old rows here
    # are safe to drop and were the largest unbounded-growth gap after the 30.06
    # disk-full incident (they were not covered by the original 4-table prune).
    ("bt_3_skill_events_v2", "created_at"),
    ("bt_3_weak_topic_events", "created_at"),
)


def prune_telemetry_retention(retention_days: int = 30) -> dict[str, int]:
    """Delete rows older than `retention_days` from the unbounded telemetry/log tables
    (TELEMETRY_RETENTION_TABLES) so they can never fill the DB volume. Each table is
    pruned independently — one failure never blocks the rest. Returns {table:
    deleted_rows} (-1 marks a per-table failure). autovacuum reclaims the freed space
    for reuse; no manual VACUUM (would need scarce disk on a tight volume)."""
    days = max(1, int(retention_days or 30))
    deleted: dict[str, int] = {}
    for table, ts_col in TELEMETRY_RETENTION_TABLES:
        try:
            with get_db_connection_context() as conn:
                with conn.cursor() as cursor:
                    cursor.execute(
                        f"DELETE FROM {table} WHERE {ts_col} < NOW() - make_interval(days => %s);",
                        (days,),
                    )
                    deleted[table] = cursor.rowcount or 0
            logging.info(
                "telemetry retention: pruned %s rows from %s (older than %sd)",
                deleted[table], table, days,
            )
        except Exception:
            logging.warning("telemetry retention: failed to prune %s", table, exc_info=True)
            deleted[table] = -1
    return deleted


def log_limit_runtime_event(
    *,
    feature_code: str,
    event_type: str,
    user_id: int | None = None,
    origin: str | None = None,
    units_value: float = 1.0,
    metadata: dict | None = None,
    event_time: datetime | None = None,
) -> None:
    feature = str(feature_code or "").strip().lower()
    event = str(event_type or "").strip().lower()
    if not feature or event not in {
        "accepted",
        "blocked",
        "cache_hit",
        "db_cache_hit",
        "memory_cache_hit",
        "openai_execution",
        "telemetry",
    }:
        return
    try:
        with get_db_connection_context() as conn:
            with conn.cursor() as cursor:
                cursor.execute(
                    """
                    INSERT INTO bt_3_limit_runtime_events (
                        user_id,
                        feature_code,
                        event_type,
                        origin,
                        units_value,
                        metadata,
                        event_time
                    )
                    VALUES (%s, %s, %s, %s, %s, %s, %s);
                    """,
                    (
                        int(user_id) if user_id is not None else None,
                        feature,
                        event,
                        str(origin or "").strip().lower() or None,
                        max(0.0, float(units_value or 0.0)),
                        Json(metadata if isinstance(metadata, dict) else {}),
                        event_time or datetime.now(timezone.utc),
                    ),
                )
    except Exception:
        logging.debug("admin limit runtime telemetry skipped", exc_info=True)


def list_admin_configurable_limits(plan_code: str = "free") -> list[dict[str, Any]]:
    ensure_admin_economics_schema()
    plan_value = str(plan_code or "free").strip().lower() or "free"
    with get_db_connection_context() as conn:
        with conn.cursor() as cursor:
            cursor.execute(
                """
                SELECT plan_code, feature_code, limit_value, limit_unit, period, is_active, updated_at
                FROM plan_limits
                WHERE plan_code = %s
                  AND period = 'day'
                  AND is_active = TRUE
                ORDER BY feature_code ASC;
                """,
                (plan_value,),
            )
            rows = cursor.fetchall() or []
    result = []
    for row in rows:
        feature = str(row[1] or "").strip().lower()
        meta = FREE_FEATURE_LIMITS.get(feature, {})
        value = float(row[2] or 0.0)
        result.append(
            {
                "plan_code": str(row[0] or plan_value),
                "feature_code": feature,
                "title": str(meta.get("title") or feature),
                "limit_value": int(value) if value.is_integer() else value,
                "limit_unit": str(row[3] or "count"),
                "period": str(row[4] or "day"),
                "is_active": bool(row[5]),
                "updated_at": row[6].isoformat() if row[6] else None,
            }
        )
    return result


def get_admin_configurable_limit(feature_code: str, plan_code: str = "free") -> dict[str, Any] | None:
    feature = str(feature_code or "").strip().lower()
    if not feature:
        return None
    for item in list_admin_configurable_limits(plan_code=plan_code):
        if str(item.get("feature_code")) == feature:
            return item
    return None


def create_admin_limit_change_preview(
    *,
    admin_user_id: int,
    feature_code: str,
    delta: float,
    plan_code: str = "free",
    ttl_minutes: int = 10,
) -> dict[str, Any]:
    ensure_admin_economics_schema()
    current = get_admin_configurable_limit(feature_code, plan_code=plan_code)
    if not current:
        raise ValueError(f"Unknown configurable limit: {feature_code}")
    old_value = float(current.get("limit_value") or 0.0)
    new_value = max(0.0, old_value + float(delta or 0.0))
    token = secrets.token_urlsafe(12)
    expires_at = datetime.now(timezone.utc) + timedelta(minutes=max(1, int(ttl_minutes or 10)))
    with get_db_connection_context() as conn:
        with conn.cursor() as cursor:
            cursor.execute(
                """
                INSERT INTO bt_3_admin_limit_change_pending (
                    token,
                    admin_user_id,
                    plan_code,
                    feature_code,
                    old_value,
                    new_value,
                    limit_unit,
                    period,
                    expires_at,
                    metadata
                )
                VALUES (%s, %s, %s, %s, %s, %s, %s, %s, %s, %s);
                """,
                (
                    token,
                    int(admin_user_id),
                    str(current.get("plan_code") or plan_code),
                    str(current.get("feature_code") or feature_code),
                    old_value,
                    new_value,
                    str(current.get("limit_unit") or "count"),
                    str(current.get("period") or "day"),
                    expires_at,
                    Json({"delta": float(delta or 0.0)}),
                ),
            )
    return {
        "token": token,
        "admin_user_id": int(admin_user_id),
        "plan_code": str(current.get("plan_code") or plan_code),
        "feature_code": str(current.get("feature_code") or feature_code),
        "title": str(current.get("title") or feature_code),
        "old_value": int(old_value) if old_value.is_integer() else old_value,
        "new_value": int(new_value) if new_value.is_integer() else new_value,
        "limit_unit": str(current.get("limit_unit") or "count"),
        "period": str(current.get("period") or "day"),
        "expires_at": expires_at.isoformat(),
    }


def get_admin_limit_change_preview(token: str, *, admin_user_id: int | None = None) -> dict[str, Any] | None:
    ensure_admin_economics_schema()
    token_value = str(token or "").strip()
    if not token_value:
        return None
    with get_db_connection_context() as conn:
        with conn.cursor() as cursor:
            cursor.execute(
                """
                SELECT token, admin_user_id, plan_code, feature_code, old_value, new_value,
                       limit_unit, period, expires_at, metadata, created_at
                FROM bt_3_admin_limit_change_pending
                WHERE token = %s
                  AND expires_at > NOW()
                  AND (%s IS NULL OR admin_user_id = %s)
                LIMIT 1;
                """,
                (
                    token_value,
                    int(admin_user_id) if admin_user_id is not None else None,
                    int(admin_user_id) if admin_user_id is not None else None,
                ),
            )
            row = cursor.fetchone()
    if not row:
        return None
    old_value = float(row[4] or 0.0)
    new_value = float(row[5] or 0.0)
    return {
        "token": str(row[0] or ""),
        "admin_user_id": int(row[1]),
        "plan_code": str(row[2] or "free"),
        "feature_code": str(row[3] or ""),
        "old_value": int(old_value) if old_value.is_integer() else old_value,
        "new_value": int(new_value) if new_value.is_integer() else new_value,
        "limit_unit": str(row[6] or "count"),
        "period": str(row[7] or "day"),
        "expires_at": row[8].isoformat() if row[8] else None,
        "metadata": row[9] if isinstance(row[9], dict) else {},
        "created_at": row[10].isoformat() if row[10] else None,
    }


def apply_admin_limit_change(
    *,
    token: str,
    admin_user_id: int,
    telegram_message_id: int | None = None,
    reason: str | None = None,
) -> dict[str, Any]:
    ensure_admin_economics_schema()
    token_value = str(token or "").strip()
    if not token_value:
        raise ValueError("token is required")
    with get_db_connection_context() as conn:
        with conn.cursor() as cursor:
            cursor.execute("SELECT pg_advisory_xact_lock(hashtext(%s));", (f"admin_limit:{token_value}",))
            cursor.execute(
                """
                SELECT token, admin_user_id, plan_code, feature_code, old_value, new_value,
                       limit_unit, period, expires_at, metadata
                FROM bt_3_admin_limit_change_pending
                WHERE token = %s
                  AND admin_user_id = %s
                  AND expires_at > NOW()
                LIMIT 1;
                """,
                (token_value, int(admin_user_id)),
            )
            row = cursor.fetchone()
            if not row:
                raise ValueError("pending_limit_change_not_found_or_expired")
            plan_code_value = str(row[2] or "free").strip().lower() or "free"
            feature_value = str(row[3] or "").strip().lower()
            old_value = float(row[4] or 0.0)
            new_value = float(row[5] or 0.0)
            unit_value = str(row[6] or "count")
            period_value = str(row[7] or "day")
            cursor.execute(
                """
                INSERT INTO plan_limits (
                    plan_code,
                    feature_code,
                    limit_value,
                    limit_unit,
                    period,
                    is_active,
                    updated_at
                )
                VALUES (%s, %s, %s, %s, %s, TRUE, NOW())
                ON CONFLICT (plan_code, feature_code, period) DO UPDATE
                SET
                    limit_value = EXCLUDED.limit_value,
                    limit_unit = EXCLUDED.limit_unit,
                    is_active = TRUE,
                    updated_at = NOW();
                """,
                (plan_code_value, feature_value, new_value, unit_value, period_value),
            )
            cursor.execute(
                """
                INSERT INTO bt_3_admin_limit_change_audit (
                    admin_user_id,
                    plan_code,
                    feature_code,
                    old_value,
                    new_value,
                    limit_unit,
                    period,
                    reason,
                    telegram_message_id,
                    metadata
                )
                VALUES (%s, %s, %s, %s, %s, %s, %s, %s, %s, %s)
                RETURNING id, created_at;
                """,
                (
                    int(admin_user_id),
                    plan_code_value,
                    feature_value,
                    old_value,
                    new_value,
                    unit_value,
                    period_value,
                    str(reason or "").strip() or None,
                    int(telegram_message_id) if telegram_message_id is not None else None,
                    Json(row[9] if isinstance(row[9], dict) else {}),
                ),
            )
            audit_row = cursor.fetchone()
            cursor.execute("DELETE FROM bt_3_admin_limit_change_pending WHERE token = %s;", (token_value,))
    return {
        "audit_id": int(audit_row[0]) if audit_row else None,
        "created_at": audit_row[1].isoformat() if audit_row and audit_row[1] else None,
        "admin_user_id": int(admin_user_id),
        "plan_code": plan_code_value,
        "feature_code": feature_value,
        "old_value": int(old_value) if old_value.is_integer() else old_value,
        "new_value": int(new_value) if new_value.is_integer() else new_value,
        "limit_unit": unit_value,
        "period": period_value,
    }


def cancel_admin_limit_change(token: str, *, admin_user_id: int) -> bool:
    ensure_admin_economics_schema()
    with get_db_connection_context() as conn:
        with conn.cursor() as cursor:
            cursor.execute(
                """
                DELETE FROM bt_3_admin_limit_change_pending
                WHERE token = %s
                  AND admin_user_id = %s;
                """,
                (str(token or "").strip(), int(admin_user_id)),
            )
            return int(cursor.rowcount or 0) > 0


def get_free_feature_usage_today(
    user_id: int,
    feature_key: str,
    *,
    now_ts_utc: datetime | None = None,
    tz: str = TRIAL_POLICY_TZ,
    cursor=None,
) -> float:
    feature = str(feature_key or "").strip().lower()
    if not get_free_feature_limit_metadata(feature):
        logging.error("free_usage_metadata_missing user_id=%s feature=%s", int(user_id), feature)
        raise ValueError(f"Missing free feature metadata for {feature!r}")
    tz_name = str(tz or TRIAL_POLICY_TZ).strip() or TRIAL_POLICY_TZ
    day_local = _to_aware_datetime(now_ts_utc).astimezone(_resolve_timezone(tz_name)).date()

    def _get(cur):
        cur.execute(
            """
            SELECT COALESCE(SUM(units_value), 0)
            FROM bt_3_billing_events
            WHERE user_id = %s
              AND action_type = %s
              AND units_type = 'requests'
              AND status IN ('estimated', 'final')
              AND (event_time AT TIME ZONE %s)::date = %s;
            """,
            (int(user_id), feature, tz_name, day_local),
        )
        return cur.fetchone()

    if cursor is not None:
        row = _get(cursor)
    else:
        with get_db_connection_context() as conn:
            with conn.cursor() as own_cursor:
                row = _get(own_cursor)
    return float((row or [0])[0] or 0.0)


def _insert_free_feature_usage_with_cursor(
    cursor,
    *,
    idempotency_key: str,
    user_id: int,
    feature_key: str,
    source_lang: str | None = None,
    target_lang: str | None = None,
    metadata: dict | None = None,
    event_time: datetime | None = None,
) -> dict | None:
    event_time_value = event_time or datetime.now(timezone.utc)
    metadata_payload = Json(metadata if isinstance(metadata, dict) else {})
    cursor.execute(
        """
        INSERT INTO bt_3_billing_events (
            idempotency_key,
            user_id,
            source_lang,
            target_lang,
            action_type,
            provider,
            units_type,
            units_value,
            price_snapshot_id,
            cost_amount,
            currency,
            status,
            metadata,
            event_time
        )
        VALUES (%s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s)
        ON CONFLICT (idempotency_key) DO NOTHING
        RETURNING
            id, idempotency_key, user_id, source_lang, target_lang, action_type, provider,
            units_type, units_value, price_snapshot_id, cost_amount, currency, status,
            metadata, event_time, created_at;
        """,
        (
            idempotency_key,
            int(user_id),
            str(source_lang or "").strip().lower() or None,
            str(target_lang or "").strip().lower() or None,
            feature_key,
            "app_internal",
            "requests",
            1.0,
            None,
            0.0,
            "USD",
            "estimated",
            metadata_payload,
            event_time_value,
        ),
    )
    row = cursor.fetchone()
    if not row:
        cursor.execute(
            """
            SELECT
                id, idempotency_key, user_id, source_lang, target_lang, action_type, provider,
                units_type, units_value, price_snapshot_id, cost_amount, currency, status,
                metadata, event_time, created_at
            FROM bt_3_billing_events
            WHERE idempotency_key = %s
            LIMIT 1;
            """,
            (idempotency_key,),
        )
        row = cursor.fetchone()
    return _billing_event_row_to_dict(row) if row else None


def refund_stolen_grammar_explains(*, days: int = 1, tz: str = "Europe/Vienna") -> dict:
    """Вернуть дневные разборы, которые съел служебный companion-запрос.

    С 15.07 по фикс модалка разбора слала ДВА запроса на /api/webapp/explain: сначала
    служебный `mode="grammar"`, следом сам разбор ошибок. Оба резервировали одну и ту же
    дневную единицу по общему ключу, но проверка лимита стояла ВЫШЕ дедупа — поэтому
    первый занимал единицу, а второй получал 429. Пользователь видел «на сегодня разборы
    закончились», не получив ни одного разбора.

    Строка с metadata->>'mode' = 'grammar' — это ровно такой случай: единица списана,
    разбор не отдан. После фикса резервация пишется с mode='explain', так что признак
    остаётся однозначным. Удаляем такие строки за последние `days` местных суток —
    счётчик дня считается по этой же таблице, значит день возвращается пользователю.
    """
    window_days = max(1, min(30, int(days or 1)))
    tz_name = str(tz or "Europe/Vienna").strip() or "Europe/Vienna"
    with get_db_connection_context() as conn:
        with conn.cursor() as cursor:
            cursor.execute(
                """
                DELETE FROM bt_3_billing_events
                WHERE action_type = 'dictionary_openai_explanation_daily'
                  AND units_type = 'requests'
                  AND metadata->>'mode' = 'grammar'
                  AND (event_time AT TIME ZONE %s)::date
                      > (NOW() AT TIME ZONE %s)::date - %s::int
                RETURNING user_id;
                """,
                (tz_name, tz_name, window_days),
            )
            rows = cursor.fetchall() or []
    user_ids = {int(row[0]) for row in rows if row and row[0] is not None}
    logging.info(
        "explain_grammar_refund deleted=%s users=%s days=%s", len(rows), len(user_ids), window_days
    )
    return {"deleted": len(rows), "users": len(user_ids), "days": window_days}


def _find_free_feature_usage_by_key(cursor, *, idempotency_key: str) -> dict | None:
    """Уже записанное событие с этим ключом идемпотентности (или None).
    Нужен, чтобы повтор одного и того же действия переиспользовал свою резервацию,
    а не упирался в дневной лимит, который сам же и занял."""
    cursor.execute(
        """
        SELECT
            id, idempotency_key, user_id, source_lang, target_lang, action_type, provider,
            units_type, units_value, price_snapshot_id, cost_amount, currency, status,
            metadata, event_time, created_at
        FROM bt_3_billing_events
        WHERE idempotency_key = %s
        LIMIT 1;
        """,
        (str(idempotency_key),),
    )
    row = cursor.fetchone()
    return _billing_event_row_to_dict(row) if row else None


def increment_free_feature_usage(
    *,
    user_id: int,
    feature_key: str,
    idempotency_key: str,
    source_lang: str | None = None,
    target_lang: str | None = None,
    metadata: dict | None = None,
    event_time: datetime | None = None,
    cursor=None,
) -> dict:
    feature = str(feature_key or "").strip().lower()
    if not get_free_feature_limit_metadata(feature):
        logging.error("free_usage_metadata_missing user_id=%s feature=%s", int(user_id), feature)
        raise ValueError(f"Missing free feature metadata for {feature!r}")
    key = str(idempotency_key or "").strip()
    if not key:
        raise ValueError("idempotency_key is required")
    if cursor is not None:
        item = _insert_free_feature_usage_with_cursor(
            cursor,
            idempotency_key=key,
            user_id=int(user_id),
            feature_key=feature,
            source_lang=source_lang,
            target_lang=target_lang,
            metadata=metadata,
            event_time=event_time,
        )
    else:
        item = log_billing_event(
            idempotency_key=key,
            user_id=int(user_id),
            action_type=feature,
            provider="app_internal",
            units_type="requests",
            units_value=1.0,
            source_lang=source_lang,
            target_lang=target_lang,
            status="estimated",
            metadata=metadata if isinstance(metadata, dict) else {},
            event_time=event_time,
        )
    if not item:
        logging.error("free_usage_increment_missing user_id=%s feature=%s", int(user_id), feature)
        raise RuntimeError(f"Failed to increment free feature usage for {feature!r}")
    log_limit_runtime_event(
        user_id=int(user_id),
        feature_code=feature,
        event_type="accepted",
        origin=(metadata or {}).get("origin") if isinstance(metadata, dict) else None,
        metadata=metadata,
        event_time=event_time,
    )
    return item


def reserve_free_feature_usage(
    *,
    user_id: int,
    feature_key: str,
    idempotency_key: str,
    source_lang: str | None = None,
    target_lang: str | None = None,
    metadata: dict | None = None,
    now_ts_utc: datetime | None = None,
    tz: str = TRIAL_POLICY_TZ,
) -> dict[str, Any]:
    feature = str(feature_key or "").strip().lower()
    if feature not in FREE_FEATURE_LIMITS:
        logging.error("free_usage_metadata_missing user_id=%s feature=%s", int(user_id), feature)
        raise ValueError(f"Missing free feature metadata for {feature!r}")
    key = str(idempotency_key or "").strip()
    if not key:
        raise ValueError("idempotency_key is required")

    safe_user_id = int(user_id)
    entitlement = resolve_entitlement(user_id=safe_user_id, now_ts_utc=now_ts_utc, tz=tz)
    effective_mode = str(entitlement.get("effective_mode") or "free").strip().lower() or "free"
    if effective_mode != "free":
        return {"ok": True, "blocked": False, "event": None, "used": None, "limit": None}

    now_value = now_ts_utc or datetime.now(timezone.utc)
    day_local = _to_aware_datetime(now_value).astimezone(_resolve_timezone(tz)).date()
    lock_material = f"free_feature:{safe_user_id}:{feature}:{day_local.isoformat()}"
    lock_key = int.from_bytes(hashlib.sha256(lock_material.encode("utf-8")).digest()[:8], "big", signed=True)
    # Лимит дневной — значит и ключ идемпотентности живёт один день. Иначе то же самое действие
    # завтра попадёт в старую запись (ON CONFLICT DO NOTHING), новая единица не спишется, и
    # платная работа уйдёт мимо счётчика. Со дня в ключе повтор внутри дня бесплатен, а завтра
    # честно списывается заново.
    scoped_key = f"{key}:{day_local.isoformat()}"

    with get_db_connection_context() as conn:
        with conn.cursor() as cursor:
            cursor.execute("SELECT pg_advisory_xact_lock(%s::bigint);", (lock_key,))
            limit_meta = _free_feature_limit_metadata_from_cursor(feature, cursor) or {}
            limit_value = float(limit_meta.get("free_limit") or 0.0)
            used_today = get_free_feature_usage_today(
                user_id=safe_user_id,
                feature_key=feature,
                now_ts_utc=now_value,
                tz=tz,
                cursor=cursor,
            )
            # Идемпотентность ДО проверки лимита. Ключ означает «это то же самое действие»:
            # ретрай после обрыва сети, параллельный companion-запрос того же экрана, повторное
            # открытие уже оплаченного разбора. Раньше дедуп стоял ниже лимита — и такой повтор
            # упирался в собственную же резервацию (used=1 при лимите 1) и получал 429. Для
            # пользователя это выглядело как «на сегодня закончились», хотя он не сделал ничего.
            existing = _find_free_feature_usage_by_key(cursor, idempotency_key=scoped_key)
            if existing:
                return {
                    "ok": True,
                    "blocked": False,
                    "event": existing,
                    "used": used_today,
                    "limit": limit_value,
                    "reused": True,
                }
            if limit_value >= 0 and used_today + 1.0 > limit_value:
                log_limit_runtime_event(
                    user_id=safe_user_id,
                    feature_code=feature,
                    event_type="blocked",
                    origin=(metadata or {}).get("origin") if isinstance(metadata, dict) else None,
                    metadata={
                        **(metadata if isinstance(metadata, dict) else {}),
                        "used": used_today,
                        "limit": limit_value,
                    },
                    event_time=now_value,
                )
                return {
                    "ok": False,
                    "blocked": True,
                    "event": None,
                    "used": used_today,
                    "limit": limit_value,
                    "error": build_free_limit_error(
                        feature,
                        used=used_today,
                        limit=limit_value,
                        now_ts_utc=now_value,
                        tz=tz,
                    ),
                }
            event = _insert_free_feature_usage_with_cursor(
                cursor,
                idempotency_key=scoped_key,
                user_id=safe_user_id,
                feature_key=feature,
                source_lang=source_lang,
                target_lang=target_lang,
                metadata=metadata,
                event_time=now_value,
            )
            if not event:
                logging.error("free_usage_reservation_missing user_id=%s feature=%s", safe_user_id, feature)
                raise RuntimeError(f"Failed to reserve free feature usage for {feature!r}")
            log_limit_runtime_event(
                user_id=safe_user_id,
                feature_code=feature,
                event_type="accepted",
                origin=(metadata or {}).get("origin") if isinstance(metadata, dict) else None,
                metadata={
                    **(metadata if isinstance(metadata, dict) else {}),
                    "used": used_today + 1.0,
                    "limit": limit_value,
                    "reservation": True,
                },
                event_time=now_value,
            )
            return {
                "ok": True,
                "blocked": False,
                "event": event,
                "used": used_today + 1.0,
                "limit": limit_value,
            }


def reserve_numdict_practice_pro_usage(
    *,
    user_id: int,
    idempotency_key: str,
    now_ts_utc: datetime | None = None,
    tz: str = TRIAL_POLICY_TZ,
) -> dict[str, Any]:
    """Cap a PAID (Pro/trial) user's self-paced numdict practice at
    NUMDICT_PRACTICE_PRO_DAILY_LIMIT/day, recording each serve in the usage ledger.
    Free users are blocked from on-demand practice upstream, so this only runs for paid
    tiers. Returns {blocked, used, limit}."""
    feature = "numdict_practice_daily"
    limit_value = float(NUMDICT_PRACTICE_PRO_DAILY_LIMIT)
    safe_user_id = int(user_id)
    now_value = now_ts_utc or datetime.now(timezone.utc)
    day_local = _to_aware_datetime(now_value).astimezone(_resolve_timezone(tz)).date()
    lock_material = f"pro_numdict:{safe_user_id}:{day_local.isoformat()}"
    lock_key = int.from_bytes(hashlib.sha256(lock_material.encode("utf-8")).digest()[:8], "big", signed=True)
    with get_db_connection_context() as conn:
        with conn.cursor() as cursor:
            cursor.execute("SELECT pg_advisory_xact_lock(%s::bigint);", (lock_key,))
            used_today = get_free_feature_usage_today(
                user_id=safe_user_id, feature_key=feature, now_ts_utc=now_value, tz=tz, cursor=cursor,
            )
            if limit_value >= 0 and used_today + 1.0 > limit_value:
                return {"blocked": True, "used": used_today, "limit": limit_value}
            _insert_free_feature_usage_with_cursor(
                cursor,
                idempotency_key=str(idempotency_key),
                user_id=safe_user_id,
                feature_key=feature,
                metadata={"origin": "numdict_practice_pro"},
                event_time=now_value,
            )
        conn.commit()
    return {"blocked": False, "used": used_today + 1.0, "limit": limit_value}


def build_free_limit_error(
    feature_key: str,
    *,
    used: float | int,
    limit: float | int | None = None,
    reset_at: str | None = None,
    now_ts_utc: datetime | None = None,
    tz: str = TRIAL_POLICY_TZ,
) -> dict:
    feature = str(feature_key or "").strip().lower()
    meta = get_free_feature_limit_metadata(feature)
    if not meta:
        logging.error("free_limit_error_metadata_missing feature=%s", feature)
        raise ValueError(f"Missing free feature metadata for {feature!r}")
    title = str(meta.get("title") or feature or "услуга").strip()
    limit_value = meta.get("free_limit") if limit is None else limit
    try:
        limit_float = float(limit_value)
        limit_out: int | float = int(limit_float) if limit_float.is_integer() else limit_float
    except Exception:
        limit_out = 0
    try:
        used_float = float(used)
        used_out: int | float = int(used_float) if used_float.is_integer() else used_float
    except Exception:
        used_out = 0
    reset_value = str(reset_at or "").strip() or _next_local_midnight_iso(now_ts_utc, tz=tz)
    return {
        "ok": False,
        "error": "free_limit_exceeded",
        "feature": feature,
        "feature_title": title,
        "limit": limit_out,
        "used": used_out,
        "reset_at": reset_value,
        "message": (
            f"На бесплатном тарифе лимит для услуги '{title}' на сегодня закончился. "
            "Лимит обновится завтра в 00:00 по Вене."
        ),
    }


def _get_billing_plan_with_cursor(cursor, plan_code: str) -> dict | None:
    code = str(plan_code or "").strip().lower()
    if not code:
        return None
    cursor.execute(
        """
        SELECT
            plan_code,
            name,
            is_paid,
            stripe_price_id,
            daily_cost_cap_eur,
            trial_days,
            is_active,
            created_at,
            updated_at
        FROM plans
        WHERE plan_code = %s
        LIMIT 1;
        """,
        (code,),
    )
    row = cursor.fetchone()
    if not row:
        return None
    return {
        "plan_code": str(row[0] or ""),
        "name": str(row[1] or ""),
        "is_paid": bool(row[2]),
        "stripe_price_id": str(row[3] or "") or None,
        "daily_cost_cap_eur": float(row[4]) if row[4] is not None else None,
        "trial_days": int(row[5] or 0),
        "is_active": bool(row[6]),
        "created_at": row[7].isoformat() if row[7] else None,
        "updated_at": row[8].isoformat() if row[8] else None,
    }


def _get_user_subscription_with_cursor(cursor, user_id: int) -> dict | None:
    cursor.execute(
        """
        SELECT
            user_id,
            plan_code,
            status,
            trial_ends_at,
            current_period_end,
            stripe_customer_id,
            stripe_subscription_id,
            created_at,
            updated_at
        FROM user_subscriptions
        WHERE user_id = %s
        LIMIT 1;
        """,
        (int(user_id),),
    )
    row = cursor.fetchone()
    return _subscription_row_to_dict(row) if row else None


def _bust_entitlement_cache(user_id: int) -> None:
    """Invalidate a user's cached entitlement after any plan-change write (Stripe/grant/bind)."""
    try:
        from backend import entitlement_cache as _ent_cache
        _ent_cache.invalidate(int(user_id))
    except Exception:
        pass


def resolve_entitlement(
    user_id: int,
    now_ts_utc: datetime | None = None,
    tz: str = TRIAL_POLICY_TZ,
    subscription: dict | None = None,
    cursor=None,
) -> dict:
    # Hot-path cache (2.1): a user's plan/cap doesn't change second-to-second, so serve the
    # resolved entitlement from Redis and skip the 2 Postgres reads (subscription + earned-Pro
    # grant). Only the plain READ path is cached (no transactional cursor, no pre-fetched sub,
    # default time). Busted on plan-change events (Stripe webhook / DAU grant / bind).
    # Fail-open: a cache miss falls straight through to the live DB path below.
    _cacheable = cursor is None and subscription is None and now_ts_utc is None
    if _cacheable:
        try:
            from backend import entitlement_cache as _ent_cache
            _cached = _ent_cache.get(int(user_id))
        except Exception:
            _cached = None
        if _cached is not None:
            return _cached
    now_utc = _to_aware_datetime(now_ts_utc)
    if isinstance(subscription, dict):
        subscription_row = dict(subscription)
    elif cursor is not None:
        subscription_row = _get_user_subscription_with_cursor(cursor, int(user_id))
    else:
        subscription_row = get_user_subscription(int(user_id))
    if not subscription_row:
        subscription = {
            "user_id": int(user_id),
            "plan_code": "free",
            "status": "inactive",
            "trial_ends_at": None,
            "current_period_end": None,
            "stripe_customer_id": None,
            "stripe_subscription_id": None,
            "created_at": None,
            "updated_at": None,
        }
    else:
        subscription = subscription_row

    plan_code = str(subscription.get("plan_code") or "free").strip().lower() or "free"
    status = _normalize_subscription_status(subscription.get("status"))
    _plan_unreadable = False
    current_plan = (
        _get_billing_plan_with_cursor(cursor, plan_code)
        if cursor is not None
        else get_billing_plan(plan_code)
    ) or {}
    if not current_plan and plan_code != "free":
        # ЕДИНСТВЕННЫЙ путь, которым человек с платной активной подпиской становится
        # бесплатным. «Тариф не прочитался» здесь молча превращается в «тариф бесплатный»,
        # и этот вердикт потом лежит в Redis 10 минут для веба, бота и воркеров.
        # 18.08.2026: 920 таких записей у платящего, а причина нигде не сохранялась.
        # Пока это только СИГНАЛ — поведение не меняем, иначе потеряем шанс увидеть причину.
        logging.error(
            "entitlement: тариф %r не прочитался, человек %s считается бесплатным",
            plan_code, user_id,
        )
        _plan_unreadable = True
        plan_code = "free"
        current_plan = (
            _get_billing_plan_with_cursor(cursor, "free")
            if cursor is not None
            else get_billing_plan("free")
        ) or {}

    trial_ends_at_value = subscription.get("trial_ends_at")
    trial_ends_at_dt = None
    if trial_ends_at_value:
        try:
            trial_ends_at_dt = datetime.fromisoformat(str(trial_ends_at_value))
            trial_ends_at_dt = _to_aware_datetime(trial_ends_at_dt)
        except Exception:
            trial_ends_at_dt = None

    # «Тариф не прочитался» и «человек правда бесплатный» — РАЗНЫЕ вещи, и запись о них
    # обязана быть разной. Иначе завтрашний разбор снова упрётся в неразличимое
    # «free_default», а журналы к тому времени уже стёрты (Railway хранит 33 часа).
    source_of_entitlement = "plan_unreadable" if _plan_unreadable else "free_default"
    if bool(current_plan.get("is_paid")) and status in {"active", "trialing"}:
        # Paid plan with a Stripe card-added trial (status 'trialing') stays Pro — KEEP.
        effective_mode = "pro"
        source_of_entitlement = "paid_subscription"
        # Telegram Stars subscriptions have no cancel/renewal-failure webhook, so a
        # lapsed one would otherwise read 'active' forever. Lapse it on read once the
        # paid period is well past (2-day grace covers auto-renewal timing). Strictly
        # guarded to stars_-sourced subs — Stripe subs stay current via webhooks.
        _sub_id = str(subscription.get("stripe_subscription_id") or "")
        if _sub_id.startswith("stars_"):
            _cpe = subscription.get("current_period_end")
            _cpe_dt = None
            try:
                if isinstance(_cpe, datetime):
                    _cpe_dt = _to_aware_datetime(_cpe)
                elif _cpe:
                    _cpe_dt = _to_aware_datetime(datetime.fromisoformat(str(_cpe)))
            except Exception:
                _cpe_dt = None
            _now_ref = now_utc or datetime.now(timezone.utc)
            if _cpe_dt is not None and _now_ref > _cpe_dt + timedelta(days=2):
                effective_mode = "free"
                source_of_entitlement = "stars_subscription_lapsed"
    else:
        # Free-plan product trial is discontinued: 'trialing' on the free plan = just Free.
        effective_mode = "free"
        if status == "trialing":
            source_of_entitlement = "legacy_free_trial"

    # Earned Pro grant (DAU reward Этап 4, or the one-time welcome trial) — honest earned
    # access. The reason distinguishes the welcome trial for the UI.
    try:
        _earned_until, _earned_reason = get_active_pro_grant_detail(int(user_id))
    except Exception:
        _earned_until, _earned_reason = (None, None)
    if _earned_until is not None:
        # A real paid subscription keeps its own source/label — the grant just banks extra
        # days beyond the paid period. Only let the grant BE the source when it's what makes
        # the user Pro (i.e. they'd otherwise be Free), so a payer never shows a 🎁 trial.
        _was_paid_pro = effective_mode == "pro" and source_of_entitlement == "paid_subscription"
        effective_mode = "pro"
        if not _was_paid_pro:
            source_of_entitlement = (
                "welcome_trial" if _earned_reason == WELCOME_TRIAL_REASON else "earned_grant"
            )

    free_plan = (
        _get_billing_plan_with_cursor(cursor, "free")
        if cursor is not None
        else get_billing_plan("free")
    ) or {}
    pro_plan = current_plan if bool(current_plan.get("is_paid")) else ((
        _get_billing_plan_with_cursor(cursor, "pro")
        if cursor is not None
        else get_billing_plan("pro")
    ) or {})
    if effective_mode == "pro":
        cap_eur = pro_plan.get("daily_cost_cap_eur")
    else:
        cap_eur = free_plan.get("daily_cost_cap_eur")
        if cap_eur is None:
            fallback = _env_decimal("FREE_DAILY_COST_CAP_EUR", "0.50")
            cap_eur = float(fallback) if fallback is not None else None

    effective_plan_code = "pro" if effective_mode == "pro" else "free"
    effective_plan_name = (
        str(pro_plan.get("name") or "Pro")
        if effective_mode == "pro"
        else str(free_plan.get("name") or "Free")
    )

    # Welcome trial: surface its end date as trial_ends_at (the subscription row has none)
    # so the UI shows a "Pro-триал до …" countdown, and flag it so we can badge it.
    is_welcome_trial = source_of_entitlement == "welcome_trial"
    if is_welcome_trial and trial_ends_at_dt is None and _earned_until is not None:
        try:
            trial_ends_at_dt = _to_aware_datetime(_earned_until)
        except Exception:
            pass

    result = {
        "user_id": int(user_id),
        "plan_code": effective_plan_code,
        "plan_name": effective_plan_name,
        "status": status,
        "trial_ends_at": trial_ends_at_dt.isoformat() if trial_ends_at_dt else None,
        "effective_mode": effective_mode,
        "source_of_entitlement": source_of_entitlement,
        "is_welcome_trial": bool(is_welcome_trial),
        # Furthest still-active earned-Pro grant (welcome trial + referral/support/streak bonus
        # days). The billing payload turns this into a friendly "days" count — either the Pro
        # the user has RIGHT NOW (Free) or the reserve banked past their paid period (Pro).
        "bonus_until": (_to_aware_datetime(_earned_until).isoformat() if _earned_until else None),
        "bonus_reason": (str(_earned_reason) if _earned_reason else None),
        "cap_eur": float(cap_eur) if cap_eur is not None else None,
        "reset_at": _next_local_midnight_iso(now_utc, tz=tz),
    }
    if _cacheable:
        try:
            from backend import entitlement_cache as _ent_cache
            _ent_cache.set(int(user_id), result)
        except Exception:
            pass
    return result


def get_trailing_days_cost_eur(user_id: int, days: int = 7, tz: str = TRIAL_POLICY_TZ) -> float:
    """Personal cost (EUR) over the trailing `days` local days INCLUDING today. Same
    shared-pool exclusion as get_today_cost_eur; read-only (does NOT write the rollup).
    Feeds the rolling-average arm of the daily cost cap."""
    user_id_value = int(user_id)
    tz_name = str(tz or TRIAL_POLICY_TZ).strip() or TRIAL_POLICY_TZ
    tzinfo = _resolve_timezone(tz_name)
    today_local = datetime.now(timezone.utc).astimezone(tzinfo).date()
    window = max(1, int(days or 1))
    start_local = today_local - timedelta(days=window - 1)
    with get_db_connection_context() as conn:
        with conn.cursor() as cursor:
            cursor.execute(
                """
                SELECT currency, COALESCE(SUM(cost_amount), 0) AS total_cost
                FROM bt_3_billing_events
                WHERE user_id = %s
                  AND (event_time AT TIME ZONE %s)::date BETWEEN %s AND %s
                  AND action_type <> ALL(%s)
                  AND provider <> ALL(%s)
                GROUP BY currency;
                """,
                (user_id_value, tz_name, start_local, today_local,
                 list(DAILY_COST_CAP_EXCLUDED_ACTION_TYPES),
                 list(DAILY_COST_CAP_EXCLUDED_PROVIDERS)),
            )
            rows = cursor.fetchall() or []
    total_eur = 0.0
    for row in rows:
        currency = str(row[0] or "EUR").upper()
        amount = float(row[1] or 0.0)
        try:
            total_eur += convert_cost_to_eur(amount, currency)
        except ValueError:
            continue
    return float(total_eur)


# The daily cost cap has TWO arms (see enforce_daily_cost_cap): a HARD single-day ceiling
# (cap_eur) AND a SOFTER rolling N-day average. An occasional heavy day is fine as long as
# the trailing average stays low; sustained overuse is still blocked; and no single day can
# spike past the hard ceiling. Env-tunable; Pro's average is on by default, Free's is off
# (Free already has a tight single-day cap).
DAILY_COST_CAP_AVG_WINDOW_DAYS = 7


def _resolve_weekly_avg_cap_eur(entitlement: dict) -> float | None:
    mode = str(entitlement.get("effective_mode") or "").strip().lower()
    if mode == "pro":
        # 0.12 ≈ what a Pro seat can sustain against €5/mo net (€0.167/day gross) while the
        # daily arm (0.25) still absorbs an occasional heavy day. Measured real usage sits at
        # €0.003–0.034 per active day, so this binds only on sustained outliers.
        value = _env_decimal("PRO_WEEKLY_AVG_COST_CAP_EUR", "0.12")
    else:
        value = _env_decimal("FREE_WEEKLY_AVG_COST_CAP_EUR", None)
    return float(value) if value is not None else None


def _cost_cap_error(entitlement: dict, *, gate: str, limit_eur: float, value_eur: float) -> dict:
    # Keep the error CODE "cost_cap_exceeded" (frontend contract → friendly plaque); `gate`
    # ("daily" | "weekly_avg") is extra telemetry the UI ignores.
    return {
        "error": "cost_cap_exceeded",
        "gate": gate,
        "cap_eur": float(round(limit_eur, 6)),
        "spent_eur": float(round(value_eur, 6)),
        "currency": "EUR",
        "reset_at": entitlement.get("reset_at"),
        "upgrade": {
            "available": True,
            "plan_code": "pro",
            "action": "checkout",
            "endpoint": "/api/billing/create-checkout-session",
        },
    }


def enforce_daily_cost_cap(
    user_id: int,
    now_ts_utc: datetime | None = None,
    tz: str = TRIAL_POLICY_TZ,
) -> dict | None:
    # Admins are exempt: they test heavily AND trigger pool-generation jobs (enrichment,
    # sprint distractors, …) whose cost is attributed to their own id but is shared
    # infrastructure, not personal consumption. Matches the admin exemption on run limits;
    # keeps the owner from being blocked inside their own app.
    try:
        if int(user_id) in get_admin_telegram_ids():
            return None
    except Exception:
        pass
    entitlement = resolve_entitlement(user_id=int(user_id), now_ts_utc=now_ts_utc, tz=tz)
    cap_eur = entitlement.get("cap_eur")
    if cap_eur is None:
        return None
    cap_eur = float(cap_eur)

    # Arm 1 — HARD single-day ceiling: no single day may blow past this (acute spike / abuse),
    # even when the trailing average is still low.
    today_eur = float(get_today_cost_eur(int(user_id), tz=tz))
    if today_eur >= cap_eur:
        return _cost_cap_error(entitlement, gate="daily", limit_eur=cap_eur, value_eur=today_eur)

    # Arm 2 — SOFT rolling N-day average (spike-tolerant): an occasional heavy day is fine as
    # long as the trailing average stays under the softer cap; this catches SUSTAINED overuse.
    # Average = trailing personal total / window (fixed divisor incl. zero-spend days, so a
    # single heavy day smooths out for an otherwise-light user instead of instantly blocking).
    avg_cap_eur = _resolve_weekly_avg_cap_eur(entitlement)
    if avg_cap_eur is not None and avg_cap_eur > 0:
        window = max(1, int(DAILY_COST_CAP_AVG_WINDOW_DAYS))
        week_eur = float(get_trailing_days_cost_eur(int(user_id), days=window, tz=tz))
        avg_eur = week_eur / float(window)
        if avg_eur >= avg_cap_eur:
            return _cost_cap_error(entitlement, gate="weekly_avg", limit_eur=avg_cap_eur, value_eur=avg_eur)
    return None


def get_plan_limit(plan_code: str, feature_code: str, period: str = "day") -> dict | None:
    plan_value = str(plan_code or "").strip().lower()
    feature_value = str(feature_code or "").strip().lower()
    period_value = str(period or "day").strip().lower() or "day"
    if not plan_value or not feature_value:
        return None
    with get_db_connection_context() as conn:
        with conn.cursor() as cursor:
            cursor.execute(
                """
                SELECT plan_code, feature_code, limit_value, limit_unit, period, is_active
                FROM plan_limits
                WHERE plan_code = %s
                  AND feature_code = %s
                  AND period = %s
                  AND is_active = TRUE
                LIMIT 1;
                """,
                (plan_value, feature_value, period_value),
            )
            row = cursor.fetchone()
    if not row:
        return None
    return {
        "plan_code": str(row[0] or ""),
        "feature_code": str(row[1] or ""),
        "limit_value": float(row[2] or 0.0),
        "limit_unit": str(row[3] or ""),
        "period": str(row[4] or "day"),
        "is_active": bool(row[5]),
    }


def _get_feature_usage_today(user_id: int, feature_code: str, tz: str = TRIAL_POLICY_TZ) -> float:
    feature = str(feature_code or "").strip().lower()
    tz_name = str(tz or TRIAL_POLICY_TZ).strip() or TRIAL_POLICY_TZ
    day_local = datetime.now(timezone.utc).astimezone(_resolve_timezone(tz_name)).date()

    if feature == "youtube_fetch_daily":
        with get_db_connection_context() as conn:
            with conn.cursor() as cursor:
                cursor.execute(
                    """
                    SELECT COUNT(*)
                    FROM bt_3_billing_events
                    WHERE user_id = %s
                      AND action_type = 'youtube_transcript_fetch'
                      AND (event_time AT TIME ZONE %s)::date = %s;
                    """,
                    (int(user_id), tz_name, day_local),
                )
                row = cursor.fetchone()
        return float((row or [0])[0] or 0)

    if feature == "tts_chars_daily":
        with get_db_connection_context() as conn:
            with conn.cursor() as cursor:
                cursor.execute(
                    """
                    SELECT COALESCE(SUM(units_value), 0)
                    FROM bt_3_billing_events
                    WHERE user_id = %s
                      AND action_type = 'webapp_tts_chars'
                      AND units_type = 'chars'
                      AND (event_time AT TIME ZONE %s)::date = %s;
                    """,
                    (int(user_id), tz_name, day_local),
                )
                row = cursor.fetchone()
        return float((row or [0])[0] or 0.0)

    if feature == "feel_word_daily":
        with get_db_connection_context() as conn:
            with conn.cursor() as cursor:
                cursor.execute(
                    """
                    SELECT COUNT(*)
                    FROM bt_3_billing_events
                    WHERE user_id = %s
                      AND action_type = 'flashcards_feel_request'
                      AND units_type = 'requests'
                      AND (event_time AT TIME ZONE %s)::date = %s;
                    """,
                    (int(user_id), tz_name, day_local),
                )
                row = cursor.fetchone()
        return float((row or [0])[0] or 0)

    if feature == "skill_training_daily":
        with get_db_connection_context() as conn:
            with conn.cursor() as cursor:
                cursor.execute(
                    """
                    SELECT COUNT(*)
                    FROM bt_3_billing_events
                    WHERE user_id = %s
                      AND action_type = 'theory_package_prepare'
                      AND (event_time AT TIME ZONE %s)::date = %s;
                    """,
                    (int(user_id), tz_name, day_local),
                )
                row = cursor.fetchone()
        return float((row or [0])[0] or 0)

    if feature == "translation_daily_sets":
        # One set a day means one set a day: a set counts as USED as soon as its
        # sentences were actually DELIVERED to the user, no matter how many of them
        # they went on to translate. Stopping at 5 of 7 does not buy a fresh set.
        # A set that never reached the screen (hung generation, empty session) leaves
        # no delivered rows and costs nothing. A set is dated by its FIRST delivered
        # sentence, so a set opened before midnight can't eat the next day's quota.
        window_start = datetime.combine(
            day_local - timedelta(days=1),
            dt_time.min,
            tzinfo=_resolve_timezone(tz_name),
        )
        with get_db_connection_context() as conn:
            with conn.cursor() as cursor:
                cursor.execute(
                    """
                    SELECT COUNT(*) FROM (
                        SELECT ds.session_id
                        FROM bt_3_daily_sentences ds
                        WHERE ds.user_id = %s
                          AND COALESCE(ds.shown_to_user, FALSE) = TRUE
                          AND ds.shown_to_user_at IS NOT NULL
                          AND ds.shown_to_user_at >= %s
                        GROUP BY ds.session_id
                        HAVING (MIN(ds.shown_to_user_at) AT TIME ZONE %s)::date = %s
                    ) q;
                    """,
                    (int(user_id), window_start, tz_name, day_local),
                )
                row = cursor.fetchone()
        return float(int((row or [0])[0] or 0))

    return 0.0


def enforce_feature_limit(
    user_id: int,
    feature_code: str,
    *,
    requested_units: float = 1.0,
    now_ts_utc: datetime | None = None,
    tz: str = TRIAL_POLICY_TZ,
) -> dict | None:
    entitlement = resolve_entitlement(user_id=int(user_id), now_ts_utc=now_ts_utc, tz=tz)
    effective_mode = str(entitlement.get("effective_mode") or "free")
    plan_code = str(entitlement.get("plan_code") or "free")

    lookup_plan = "free" if effective_mode == "free" else plan_code
    limit = get_plan_limit(lookup_plan, feature_code, period="day")
    if not limit:
        return None

    usage = _get_feature_usage_today(int(user_id), feature_code, tz=tz)
    requested = max(0.0, float(requested_units or 0.0))
    limit_value = float(limit.get("limit_value") or 0.0)
    if usage + requested > limit_value:
        used_value = float(round(usage, 6))
        limit_out = int(limit_value) if float(limit_value).is_integer() else float(limit_value)
        used_out = int(used_value) if float(used_value).is_integer() else float(used_value)
        return {
            "error": "feature_limit_exceeded",
            "feature": feature_code,
            "limit": limit_out,
            "used": used_out,
            "unit": str(limit.get("limit_unit") or "count"),
            "reset_at": entitlement.get("reset_at"),
            "upgrade": {
                "available": True,
                "plan_code": "pro",
                "action": "checkout",
                "endpoint": "/api/billing/create-checkout-session",
            },
        }
    return None


def get_user_action_month_usage(
    user_id: int,
    action_type: str,
    *,
    units_type: str = "chars",
    provider: str | None = None,
    period_month: date | datetime | None = None,
    tz: str = TRIAL_POLICY_TZ,
) -> float:
    action_value = str(action_type or "").strip().lower()
    units_type_value = str(units_type or "").strip().lower() or "chars"
    provider_value = str(provider or "").strip().lower() or None
    if not action_value:
        return 0.0
    period_start = _month_period_start(period_month, tz=tz)
    if period_start.month == 12:
        period_end = date(period_start.year + 1, 1, 1)
    else:
        period_end = date(period_start.year, period_start.month + 1, 1)

    provider_sql = ""
    provider_params: list = []
    if provider_value:
        provider_sql = " AND provider = %s"
        provider_params.append(provider_value)

    with get_db_connection_context() as conn:
        with conn.cursor() as cursor:
            cursor.execute(
                f"""
                SELECT COALESCE(SUM(units_value), 0)
                FROM bt_3_billing_events
                WHERE user_id = %s
                  AND action_type = %s
                  AND units_type = %s
                  {provider_sql}
                  AND event_time >= %s
                  AND event_time < %s;
                """,
                (
                    int(user_id),
                    action_value,
                    units_type_value,
                    *provider_params,
                    datetime.combine(period_start, dt_time.min, tzinfo=timezone.utc),
                    datetime.combine(period_end, dt_time.min, tzinfo=timezone.utc),
                ),
            )
            row = cursor.fetchone()
    return float((row or [0])[0] or 0.0)


def reader_audio_cache_total_bytes() -> int:
    """Total bytes of cached reader audio (for the costs report)."""
    try:
        with get_db_connection_context() as conn:
            with conn.cursor() as cursor:
                cursor.execute("SELECT COALESCE(SUM(audio_bytes_len), 0) FROM bt_3_reader_audio_pages")
                return int((cursor.fetchone() or [0])[0] or 0)
    except Exception:
        logging.exception("reader_audio_cache_total_bytes failed")
        return 0


def delete_stale_reader_audio_pages(older_than_days: int = 90, limit: int = 5000) -> list[str]:
    """Delete reader-audio cache rows not played (or created, if never played) within
    the last `older_than_days`, in a batch of up to `limit`. Returns the deleted rows'
    audio_url list so the caller can remove the R2 objects. Call repeatedly until it
    returns []. Active reading keeps a page 'hot' (last_played_at updates on play).

    "Классика" (public shared library) audio IS evicted on the same idle TTL now: we no
    longer pre-warm the whole shelf, so a public page only exists because someone actually
    read it — and if nobody has replayed it in `older_than_days`, storing it (and having
    burned the TTS to make it) is pure waste. It re-synthesises from the free Standard
    bucket the moment someone opens the page again (on-demand, from the wheels), so the
    cost of evicting is ~nothing. Active reading still keeps a page hot via last_played_at.

    NEVER evict PAID personal audio (a book someone unlocked with Stars): the per-page
    regen cost (Neural2 ≈ €16/1M chars) is ~thousands of times a month of R2 storage —
    break-even is centuries, so evicting a paid book just to re-synthesise it later burns
    OUR money. Rows whose book has ANY unlock are kept regardless of the idle TTL.
    (Reclaiming a churned user's audio is a separate, activity-based job.)"""
    try:
        with get_db_connection_context() as conn:
            with conn.cursor() as cursor:
                cursor.execute(
                    """
                    DELETE FROM bt_3_reader_audio_pages
                    WHERE id IN (
                        SELECT ap.id FROM bt_3_reader_audio_pages ap
                        JOIN bt_3_reader_library rl ON rl.id = ap.document_id
                        WHERE COALESCE(ap.last_played_at, ap.created_at) < NOW() - (%s * INTERVAL '1 day')
                          AND NOT EXISTS (
                              SELECT 1 FROM bt_3_book_audio_unlocks u
                              WHERE u.document_id = ap.document_id
                          )
                        LIMIT %s
                    )
                    RETURNING audio_url
                    """,
                    (int(older_than_days), int(limit)),
                )
                return [str(r[0]) for r in cursor.fetchall() if r and r[0]]
    except Exception:
        logging.exception("delete_stale_reader_audio_pages failed")
        return []


def delete_churned_user_reader_audio_pages(inactive_months: int = 12, limit: int = 5000) -> list[str]:
    """Reclaim PAID reader audio belonging to users who have LEFT the platform. Returns
    the deleted rows' audio_url list (caller removes the R2 objects). Call repeatedly
    until it returns []. This is the counterpart to the idle TTL: paid audio is normally
    kept forever (regen costs the owner ~thousands× a month of storage), but once a user
    is gone it will never be replayed, so keeping it is pure waste.

    We delete only the AUDIO PAGES, never the book row or the unlock — so if the user
    ever returns, their permanent unlock still lets the audio regenerate free for them.

    "Gone" is intentionally conservative — ALL of:
      • non-public book (classics never touched here);
      • the audio page itself is cold (not played in `inactive_months`) — so an active
        reader's book is safe even if their learning streak looks stale;
      • AND the owner shows a positive left-the-platform signal: either blocked the bot
        (bt_3_bot_blocked_users) or no learning activity for `inactive_months`
        (bt_3_user_streaks.last_active_date). Users with no positive signal are kept."""
    try:
        with get_db_connection_context() as conn:
            with conn.cursor() as cursor:
                cursor.execute(
                    """
                    DELETE FROM bt_3_reader_audio_pages
                    WHERE id IN (
                        SELECT ap.id FROM bt_3_reader_audio_pages ap
                        JOIN bt_3_reader_library rl ON rl.id = ap.document_id
                        WHERE rl.is_public = FALSE
                          AND ap.user_id > 0
                          AND COALESCE(ap.last_played_at, ap.created_at)
                              < NOW() - (%s * INTERVAL '1 month')
                          AND (
                              EXISTS (
                                  SELECT 1 FROM bt_3_bot_blocked_users b
                                  WHERE b.user_id = ap.user_id AND b.is_blocked = TRUE
                              )
                              OR EXISTS (
                                  SELECT 1 FROM bt_3_user_streaks s
                                  WHERE s.user_id = ap.user_id
                                    AND s.last_active_date
                                        < (CURRENT_DATE - (%s * INTERVAL '1 month'))
                              )
                          )
                        LIMIT %s
                    )
                    RETURNING audio_url
                    """,
                    (int(inactive_months), int(inactive_months), int(limit)),
                )
                return [str(r[0]) for r in cursor.fetchall() if r and r[0]]
    except Exception:
        logging.exception("delete_churned_user_reader_audio_pages failed")
        return []


def preview_churned_user_reader_audio(inactive_months: int = 12) -> dict:
    """Read-only DRY-RUN of delete_churned_user_reader_audio_pages: what WOULD be
    reclaimed right now, WITHOUT deleting anything. Same triple gate, grouped per user so
    the admin can eyeball it before trusting the weekly job. Returns
    {inactive_months, users, pages, bytes, rows:[{user_id, pages, bytes, books, titles,
    blocked, last_active, last_audio}, ...]} ordered by freed bytes desc."""
    try:
        with get_db_connection_context() as conn:
            with conn.cursor() as cursor:
                cursor.execute(
                    """
                    SELECT ap.user_id,
                           COUNT(*)                                        AS pages,
                           COALESCE(SUM(ap.audio_bytes_len), 0)            AS bytes,
                           COUNT(DISTINCT ap.document_id)                  AS books,
                           (array_agg(DISTINCT rl.title))[1:5]             AS titles,
                           BOOL_OR(b.user_id IS NOT NULL)                  AS blocked,
                           MAX(s.last_active_date)                         AS last_active,
                           MAX(COALESCE(ap.last_played_at, ap.created_at)) AS last_audio
                    FROM bt_3_reader_audio_pages ap
                    JOIN bt_3_reader_library rl ON rl.id = ap.document_id
                    LEFT JOIN bt_3_bot_blocked_users b
                           ON b.user_id = ap.user_id AND b.is_blocked = TRUE
                    LEFT JOIN bt_3_user_streaks s ON s.user_id = ap.user_id
                    WHERE rl.is_public = FALSE
                      AND ap.user_id > 0
                      AND COALESCE(ap.last_played_at, ap.created_at)
                          < NOW() - (%s * INTERVAL '1 month')
                      AND (
                          b.user_id IS NOT NULL
                          OR s.last_active_date < (CURRENT_DATE - (%s * INTERVAL '1 month'))
                      )
                    GROUP BY ap.user_id
                    ORDER BY bytes DESC
                    """,
                    (int(inactive_months), int(inactive_months)),
                )
                rows = []
                total_pages = 0
                total_bytes = 0
                for r in cursor.fetchall():
                    pages = int(r[1] or 0)
                    byts = int(r[2] or 0)
                    total_pages += pages
                    total_bytes += byts
                    rows.append({
                        "user_id": int(r[0]),
                        "pages": pages,
                        "bytes": byts,
                        "books": int(r[3] or 0),
                        "titles": [str(t) for t in (r[4] or []) if t],
                        "blocked": bool(r[5]),
                        "last_active": r[6].isoformat() if r[6] else None,
                        "last_audio": r[7].isoformat() if r[7] else None,
                    })
                return {
                    "inactive_months": int(inactive_months),
                    "users": len(rows),
                    "pages": total_pages,
                    "bytes": total_bytes,
                    "rows": rows,
                }
    except Exception:
        logging.exception("preview_churned_user_reader_audio failed")
        return {"inactive_months": int(inactive_months), "users": 0, "pages": 0, "bytes": 0, "rows": []}


def list_users_eligible_for_auto_purge(inactive_months: int = 12, limit: int = 500) -> list[dict]:
    """Read-only: candidates for the MONTHLY auto-purge of PERSONAL data — users who have
    left the platform. Eligibility is deliberately conservative and anchored on a single
    positive signal: no learning activity for `inactive_months`
    (bt_3_user_streaks.last_active_date older than the threshold). A user with NO streak
    row (unknown last-active) is never returned — silence is not a deletion signal. Having
    blocked the bot is reported for context (the `blocked` flag) but is NOT sufficient on
    its own, so someone who just blocked yesterday is not swept in.

    Admins and paying/Pro users are NOT filtered here — the caller excludes them via
    get_admin_telegram_ids() / resolve_entitlement() (Python-level checks). Users already
    purged (bt_3_user_removal_queue.status = 'purged') are skipped so the monthly run does
    not re-process the same people. Only shared data survives the eventual purge; this
    function itself deletes nothing. Returns [{user_id, last_active(iso|None), blocked}]
    oldest-inactive first."""
    try:
        with get_db_connection_context() as conn:
            with conn.cursor() as cursor:
                cursor.execute(
                    """
                    SELECT s.user_id,
                           s.last_active_date          AS last_active,
                           (b.user_id IS NOT NULL)     AS blocked
                    FROM bt_3_user_streaks s
                    LEFT JOIN bt_3_bot_blocked_users b
                           ON b.user_id = s.user_id AND b.is_blocked = TRUE
                    LEFT JOIN bt_3_user_removal_queue q
                           ON q.user_id = s.user_id
                    WHERE s.user_id > 0
                      AND s.last_active_date IS NOT NULL
                      AND s.last_active_date < (CURRENT_DATE - (%s * INTERVAL '1 month'))
                      AND COALESCE(q.status, '') <> 'purged'
                    ORDER BY s.last_active_date ASC
                    LIMIT %s
                    """,
                    (int(inactive_months), max(1, int(limit))),
                )
                out: list[dict] = []
                for r in cursor.fetchall():
                    out.append({
                        "user_id": int(r[0]),
                        "last_active": r[1].isoformat() if r[1] else None,
                        "blocked": bool(r[2]),
                    })
                return out
    except Exception:
        logging.exception("list_users_eligible_for_auto_purge failed")
        return []


def enforce_reader_audio_pro_monthly_limit(
    user_id: int,
    *,
    requested_units: float = 1.0,
    now_ts_utc: datetime | None = None,
    tz: str = TRIAL_POLICY_TZ,
) -> dict | None:
    if int(user_id) in READER_AUDIO_UNLIMITED_USER_IDS:
        return None
    used_units = float(
        get_user_action_month_usage(
            int(user_id),
            "reader_audio_tts",
            units_type="chars",
            provider="google_tts",
            period_month=now_ts_utc,
            tz=tz,
        )
    )
    requested = max(0.0, float(requested_units or 0.0))
    # Per-user override (admin-granted on request) wins over the global default.
    override_limit = get_reader_audio_limit_override(int(user_id))
    limit_value = float(override_limit) if override_limit else float(READER_AUDIO_PRO_MONTHLY_LIMIT_CHARS)
    if used_units + requested > limit_value:
        used_out = int(round(used_units))
        limit_out = int(round(limit_value))
        remaining_out = max(0, limit_out - used_out)
        return {
            "error": "reader_audio_monthly_limit_exceeded",
            "feature": "reader_audio_tts_monthly",
            "limit": limit_out,
            "used": used_out,
            "requested": int(round(requested)),
            "remaining": remaining_out,
            "unit": "chars",
            "reset_at": _next_local_month_start_iso(now_ts_utc, tz=tz),
            "message": (
                f"Лимит Reader Audio на месяц исчерпан: {used_out} / {limit_out} chars. "
                f"Следующий сброс: {_next_local_month_start_iso(now_ts_utc, tz=tz)}"
            ),
        }
    return None


def get_global_action_month_usage(
    action_type: str,
    *,
    units_type: str = "chars",
    provider: str | None = None,
    period_month: date | datetime | None = None,
    tz: str = TRIAL_POLICY_TZ,
) -> float:
    """Total usage across ALL users for the current month (no user filter).
    Mirrors get_user_action_month_usage but aggregates globally."""
    action_value = str(action_type or "").strip().lower()
    units_type_value = str(units_type or "").strip().lower() or "chars"
    provider_value = str(provider or "").strip().lower() or None
    if not action_value:
        return 0.0
    period_start = _month_period_start(period_month, tz=tz)
    if period_start.month == 12:
        period_end = date(period_start.year + 1, 1, 1)
    else:
        period_end = date(period_start.year, period_start.month + 1, 1)
    provider_sql = ""
    provider_params: list = []
    if provider_value:
        provider_sql = " AND provider = %s"
        provider_params.append(provider_value)
    with get_db_connection_context() as conn:
        with conn.cursor() as cursor:
            cursor.execute(
                f"""
                SELECT COALESCE(SUM(units_value), 0)
                FROM bt_3_billing_events
                WHERE action_type = %s
                  AND units_type = %s
                  {provider_sql}
                  AND event_time >= %s
                  AND event_time < %s;
                """,
                (
                    action_value,
                    units_type_value,
                    *provider_params,
                    datetime.combine(period_start, dt_time.min, tzinfo=timezone.utc),
                    datetime.combine(period_end, dt_time.min, tzinfo=timezone.utc),
                ),
            )
            row = cursor.fetchone()
    return float((row or [0])[0] or 0.0)


def enforce_reader_audio_global_monthly_limit(
    *,
    user_id: int,
    requested_units: float = 1.0,
    now_ts_utc: datetime | None = None,
    tz: str = TRIAL_POLICY_TZ,
) -> dict | None:
    """Hard global ceiling for Reader Audio chars/month across all users. Returns
    an error dict (→ 429) if this request would push the total over the limit, so
    one (or many) users cannot drain the external TTS budget. Whitelisted users
    bypass (trusted admins)."""
    if int(user_id) in READER_AUDIO_UNLIMITED_USER_IDS:
        return None
    used_units = float(
        get_global_action_month_usage(
            "reader_audio_tts",
            units_type="chars",
            provider="google_tts",
            period_month=now_ts_utc,
            tz=tz,
        )
    )
    requested = max(0.0, float(requested_units or 0.0))
    limit_value = float(READER_AUDIO_GLOBAL_MONTHLY_LIMIT_CHARS)
    if used_units + requested > limit_value:
        used_out = int(round(used_units))
        limit_out = int(round(limit_value))
        return {
            "error": "reader_audio_global_monthly_limit_exceeded",
            "feature": "reader_audio_tts_global_monthly",
            "limit": limit_out,
            "used": used_out,
            "requested": int(round(requested)),
            "remaining": max(0, limit_out - used_out),
            "unit": "chars",
            "reset_at": _next_local_month_start_iso(now_ts_utc, tz=tz),
            "message": (
                "Сервис аудио-озвучки временно достиг месячного лимита. "
                f"Сброс: {_next_local_month_start_iso(now_ts_utc, tz=tz)}"
            ),
        }
    return None


def get_cached_reader_audio_page(
    *,
    document_id: int,
    page_number: int,
    voice_name: str,
    speaking_rate: float,
    text_hash: str,
) -> dict | None:
    """Return cached audio page row if exists, else None."""
    try:
        with get_db_connection_context() as conn:
            with conn.cursor() as cursor:
                cursor.execute(
                    """
                    SELECT id, audio_url, audio_mime, duration_ms, word_timings
                    FROM bt_3_reader_audio_pages
                    WHERE document_id = %s
                      AND page_number = %s
                      AND voice_name  = %s
                      AND speaking_rate = %s
                      AND text_hash   = %s
                    LIMIT 1;
                    """,
                    (int(document_id), int(page_number), str(voice_name),
                     float(speaking_rate), str(text_hash)),
                )
                row = cursor.fetchone()
        if not row:
            return None
        row_id, audio_url, audio_mime, duration_ms, word_timings = row
        # Update last_played_at lazily
        try:
            with get_db_connection_context() as conn2:
                with conn2.cursor() as c2:
                    c2.execute(
                        "UPDATE bt_3_reader_audio_pages SET last_played_at = NOW() WHERE id = %s",
                        (int(row_id),),
                    )
        except Exception:
            pass
        return {
            "audio_url": str(audio_url or ""),
            "mime": str(audio_mime or "audio/mpeg"),
            "duration_ms": int(duration_ms or 0),
            "word_timings": list(word_timings or []),
        }
    except Exception:
        return None


def save_reader_audio_page_cache(
    *,
    user_id: int,
    document_id: int,
    page_number: int,
    voice_name: str,
    speaking_rate: float,
    text_hash: str,
    audio_url: str,
    audio_mime: str,
    audio_bytes_len: int,
    duration_ms: int,
    word_timings: list,
) -> None:
    """Insert or update cached audio page record."""
    import json as _json
    try:
        with get_db_connection_context() as conn:
            with conn.cursor() as cursor:
                cursor.execute(
                    """
                    INSERT INTO bt_3_reader_audio_pages
                        (user_id, document_id, page_number, voice_name, speaking_rate,
                         text_hash, audio_url, audio_mime, audio_bytes_len,
                         duration_ms, word_timings, last_played_at)
                    VALUES (%s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s::jsonb, NOW())
                    ON CONFLICT (document_id, page_number, voice_name, speaking_rate, text_hash)
                    DO UPDATE SET
                        audio_url      = EXCLUDED.audio_url,
                        audio_bytes_len = EXCLUDED.audio_bytes_len,
                        duration_ms    = EXCLUDED.duration_ms,
                        word_timings   = EXCLUDED.word_timings,
                        last_played_at = NOW();
                    """,
                    (
                        int(user_id), int(document_id), int(page_number),
                        str(voice_name), float(speaking_rate),
                        str(text_hash), str(audio_url), str(audio_mime),
                        int(audio_bytes_len), int(duration_ms),
                        _json.dumps(list(word_timings or [])),
                    ),
                )
    except Exception:
        pass  # cache write failure is non-fatal


