def claim_next_ready_image_quiz_template(
    *,
    user_id: int,
    source_lang: str,
    target_lang: str,
) -> dict | None:
    from backend.image_quiz_utils import validate_ready_image_quiz_template

    normalized_user_id = int(user_id)
    normalized_source_lang = str(source_lang or "").strip().lower() or "ru"
    normalized_target_lang = str(target_lang or "").strip().lower() or "de"

    for _ in range(8):
        template = claim_next_ready_template(
            normalized_user_id,
            normalized_source_lang,
            normalized_target_lang,
        )
        if not template:
            return None
        validation_error = validate_ready_image_quiz_template(template)
        if not validation_error:
            return template
        mark_image_quiz_template_failed(
            int(template.get("id") or 0),
            last_error=f"ready_template_invalid:{validation_error}",
            visual_status="rejected",
            provider_name="image_quiz_runtime_guard",
            provider_meta={
                "stage": "ready_claim_validation",
                "validation_error": validation_error,
            },
        )
    return None


def claim_next_blueprint_ready_template(
    *,
    user_id: int,
    source_lang: str,
    target_lang: str,
    provider_name: str | None = None,
    provider_meta: dict | None = None,
) -> dict | None:
    normalized_provider_name = str(provider_name or "").strip() or None
    with get_db_connection_context() as conn:
        with conn.cursor() as cursor:
            cursor.execute(
                """
                WITH selected AS (
                    SELECT t.id
                    FROM bt_3_image_quiz_templates t
                    WHERE t.user_id = %s
                      AND t.source_lang = %s
                      AND t.target_lang = %s
                      AND t.generation_status = 'blueprint_ready'
                      AND t.visual_status = 'valid'
                      AND COALESCE(NULLIF(t.image_prompt, ''), '') <> ''
                    ORDER BY
                        COALESCE(t.prepared_at, t.created_at) ASC,
                        t.id ASC
                    LIMIT 1
                    FOR UPDATE SKIP LOCKED
                )
                UPDATE bt_3_image_quiz_templates t
                SET
                    generation_status = 'rendering',
                    provider_name = COALESCE(%s, t.provider_name),
                    provider_meta = CASE
                        WHEN %s IS NULL THEN t.provider_meta
                        ELSE COALESCE(t.provider_meta, '{}'::jsonb) || %s::jsonb
                    END,
                    last_error = NULL,
                    updated_at = NOW()
                FROM selected
                WHERE t.id = selected.id
                RETURNING
                    t.id,
                    t.user_id,
                    t.source_dictionary_entry_id,
                    t.canonical_entry_id,
                    t.source_lang,
                    t.target_lang,
                    t.source_text,
                    t.target_text,
                    t.source_sentence,
                    t.image_prompt,
                    t.question_de,
                    t.answer_options,
                    t.correct_option_index,
                    t.explanation,
                    t.provider_name,
                    t.provider_meta,
                    t.image_object_key,
                    t.image_url,
                    t.generation_status,
                    t.visual_status,
                    t.last_error,
                    t.prepared_at,
                    t.last_used_at,
                    t.use_count,
                    t.created_at,
                    t.updated_at;
                """,
                (
                    int(user_id),
                    str(source_lang or "").strip().lower(),
                    str(target_lang or "").strip().lower(),
                    normalized_provider_name,
                    Json(provider_meta) if isinstance(provider_meta, dict) else None,
                    Json(provider_meta) if isinstance(provider_meta, dict) else None,
                ),
            )
            return _map_image_quiz_template_row(cursor.fetchone())


def fail_stale_rendering_image_quiz_templates(
    *,
    user_id: int,
    source_lang: str,
    target_lang: str,
    stale_after_minutes: int,
    provider_name: str | None = None,
    provider_meta: dict | None = None,
    limit: int = 25,
) -> list[dict]:
    normalized_provider_name = str(provider_name or "").strip() or None
    safe_limit = max(1, min(int(limit or 25), 500))
    safe_stale_after_minutes = max(5, int(stale_after_minutes or 30))
    failure_reason = f"stale_rendering_timeout:{safe_stale_after_minutes}m"
    with get_db_connection_context() as conn:
        with conn.cursor() as cursor:
            cursor.execute(
                """
                WITH stale_templates AS (
                    SELECT t.id
                    FROM bt_3_image_quiz_templates t
                    WHERE t.user_id = %s
                      AND t.source_lang = %s
                      AND t.target_lang = %s
                      AND t.generation_status = 'rendering'
                      AND t.updated_at <= NOW() - (%s || ' minutes')::interval
                    ORDER BY t.updated_at ASC, t.id ASC
                    LIMIT %s
                    FOR UPDATE SKIP LOCKED
                )
                UPDATE bt_3_image_quiz_templates t
                SET
                    generation_status = 'failed',
                    provider_name = COALESCE(%s, t.provider_name),
                    provider_meta = CASE
                        WHEN %s IS NULL THEN COALESCE(t.provider_meta, '{}'::jsonb)
                        ELSE COALESCE(t.provider_meta, '{}'::jsonb) || %s::jsonb
                    END,
                    last_error = %s,
                    updated_at = NOW()
                FROM stale_templates
                WHERE t.id = stale_templates.id
                RETURNING
                    t.id,
                    t.user_id,
                    t.source_dictionary_entry_id,
                    t.canonical_entry_id,
                    t.source_lang,
                    t.target_lang,
                    t.source_text,
                    t.target_text,
                    t.source_sentence,
                    t.image_prompt,
                    t.question_de,
                    t.answer_options,
                    t.correct_option_index,
                    t.explanation,
                    t.provider_name,
                    t.provider_meta,
                    t.image_object_key,
                    t.image_url,
                    t.generation_status,
                    t.visual_status,
                    t.last_error,
                    t.prepared_at,
                    t.last_used_at,
                    t.use_count,
                    t.created_at,
                    t.updated_at;
                """,
                (
                    int(user_id),
                    str(source_lang or "").strip().lower() or "ru",
                    str(target_lang or "").strip().lower() or "de",
                    str(safe_stale_after_minutes),
                    safe_limit,
                    normalized_provider_name,
                    Json(provider_meta) if isinstance(provider_meta, dict) else None,
                    Json(provider_meta) if isinstance(provider_meta, dict) else None,
                    failure_reason,
                ),
            )
            return [_map_image_quiz_template_row(row) for row in cursor.fetchall() or [] if row]


def create_image_quiz_dispatch(
    *,
    template_id: int,
    target_user_id: int,
    chat_id: int,
    message_id: int | None = None,
    delivery_scope: str = "private",
    delivery_slot: str | None = None,
    delivery_date_local: date | None = None,
    status: str = "claimed",
    sent_at: datetime | None = None,
) -> dict | None:
    with get_db_connection_context() as conn:
        with conn.cursor() as cursor:
            cursor.execute(
                """
                INSERT INTO bt_3_image_quiz_dispatches (
                    template_id,
                    target_user_id,
                    chat_id,
                    message_id,
                    delivery_scope,
                    delivery_slot,
                    delivery_date_local,
                    status,
                    created_at,
                    sent_at,
                    updated_at
                )
                VALUES (%s, %s, %s, %s, %s, %s, %s, %s, NOW(), %s, NOW())
                RETURNING
                    id,
                    template_id,
                    target_user_id,
                    chat_id,
                    message_id,
                    delivery_scope,
                    delivery_slot,
                    delivery_date_local,
                    status,
                    created_at,
                    sent_at,
                    updated_at;
                """,
                (
                    int(template_id),
                    int(target_user_id),
                    int(chat_id),
                    int(message_id) if message_id is not None else None,
                    _normalize_image_quiz_delivery_scope(delivery_scope),
                    str(delivery_slot or "").strip() or None,
                    delivery_date_local,
                    _normalize_image_quiz_dispatch_status(status),
                    sent_at,
                ),
            )
            return _map_image_quiz_dispatch_row(cursor.fetchone())


def mark_image_quiz_dispatch_sent(
    dispatch_id: int,
    *,
    message_id: int,
    sent_at: datetime | None = None,
) -> dict | None:
    with get_db_connection_context() as conn:
        with conn.cursor() as cursor:
            cursor.execute(
                """
                WITH updated_dispatch AS (
                    UPDATE bt_3_image_quiz_dispatches
                    SET
                        message_id = %s,
                        status = 'sent',
                        sent_at = COALESCE(%s, NOW()),
                        updated_at = NOW()
                    WHERE id = %s
                    RETURNING
                        id,
                        template_id,
                        target_user_id,
                        chat_id,
                        message_id,
                        delivery_scope,
                        delivery_slot,
                        delivery_date_local,
                        status,
                        created_at,
                        sent_at,
                        updated_at
                )
                UPDATE bt_3_image_quiz_templates t
                SET
                    last_used_at = COALESCE((SELECT sent_at FROM updated_dispatch), NOW()),
                    use_count = t.use_count + 1,
                    updated_at = NOW()
                FROM updated_dispatch
                WHERE t.id = updated_dispatch.template_id;
                """,
                (
                    int(message_id),
                    sent_at,
                    int(dispatch_id),
                ),
            )
            cursor.execute(
                """
                SELECT
                    id,
                    template_id,
                    target_user_id,
                    chat_id,
                    message_id,
                    delivery_scope,
                    delivery_slot,
                    delivery_date_local,
                    status,
                    created_at,
                    sent_at,
                    updated_at
                FROM bt_3_image_quiz_dispatches
                WHERE id = %s
                LIMIT 1;
                """,
                (int(dispatch_id),),
            )
            return _map_image_quiz_dispatch_row(cursor.fetchone())


