def record_image_quiz_answer(
    *,
    dispatch_id: int,
    user_id: int,
    selected_option_index: int,
    selected_text: str | None = None,
    is_correct: bool,
) -> dict | None:
    with get_db_connection_context() as conn:
        with conn.cursor() as cursor:
            cursor.execute(
                """
                INSERT INTO bt_3_image_quiz_answers (
                    dispatch_id,
                    user_id,
                    selected_option_index,
                    selected_text,
                    is_correct,
                    answered_at
                )
                VALUES (%s, %s, %s, %s, %s, NOW())
                ON CONFLICT (dispatch_id, user_id) DO NOTHING
                RETURNING
                    id,
                    dispatch_id,
                    user_id,
                    selected_option_index,
                    selected_text,
                    is_correct,
                    answered_at,
                    feedback_sent_at;
                """,
                (
                    int(dispatch_id),
                    int(user_id),
                    int(selected_option_index),
                    str(selected_text or "").strip() or None,
                    bool(is_correct),
                ),
            )
            row = cursor.fetchone()
            if row:
                answer = _map_image_quiz_answer_row(row)
                if answer is not None:
                    answer["created"] = True
                return answer
            cursor.execute(
                """
                SELECT
                    id,
                    dispatch_id,
                    user_id,
                    selected_option_index,
                    selected_text,
                    is_correct,
                    answered_at,
                    feedback_sent_at
                FROM bt_3_image_quiz_answers
                WHERE dispatch_id = %s
                  AND user_id = %s
                LIMIT 1;
                """,
                (int(dispatch_id), int(user_id)),
            )
            answer = _map_image_quiz_answer_row(cursor.fetchone())
            if answer is not None:
                answer["created"] = False
            return answer


