# Compound-word rebus DB helpers
# ─────────────────────────────────────────────────────────────────────────────

def upsert_rebus_bank_entry(entry: dict) -> None:
    """Insert or update a single compound entry from REBUS_COMPOUND_BANK."""
    import json
    with get_db_connection_context() as conn:
        with conn.cursor() as cursor:
            cursor.execute(
                """
                INSERT INTO bt_3_rebus_bank (
                    compound_id, compound_word, article, meaning_ru,
                    difficulty, parts_json, wrong_options_json, explanation_ru,
                    updated_at
                )
                VALUES (%s, %s, %s, %s, %s, %s::jsonb, %s::jsonb, %s, NOW())
                ON CONFLICT (compound_id) DO UPDATE SET
                    compound_word       = EXCLUDED.compound_word,
                    article             = EXCLUDED.article,
                    meaning_ru          = EXCLUDED.meaning_ru,
                    difficulty          = EXCLUDED.difficulty,
                    parts_json          = EXCLUDED.parts_json,
                    wrong_options_json  = EXCLUDED.wrong_options_json,
                    explanation_ru      = EXCLUDED.explanation_ru,
                    updated_at          = NOW()
                """,
                (
                    str(entry["id"]),
                    str(entry["compound"]),
                    str(entry.get("article") or ""),
                    str(entry.get("meaning_ru") or ""),
                    str(entry.get("difficulty") or "A2"),
                    json.dumps(entry.get("parts") or [], ensure_ascii=False),
                    json.dumps(entry.get("wrong_options") or [], ensure_ascii=False),
                    str(entry.get("explanation_ru") or ""),
                ),
            )
        conn.commit()


def sync_rebus_bank_from_code() -> dict:
    """Upsert all entries from REBUS_COMPOUND_BANK into DB. Returns stats.

    Also retires any DB entry whose compound_id is no longer present in code —
    otherwise a removed (e.g. broken) entry would linger in the DB and keep
    being scheduled, since pick selection only filters on retired = FALSE.
    """
    from backend.rebus_bank import REBUS_COMPOUND_BANK, validate_rebus_entry_consistency
    inserted = 0
    skipped_inconsistent = 0
    code_ids = []
    for entry in REBUS_COMPOUND_BANK:
        # Root-cause guard: never ship an entry whose part word does not match the
        # compound (image-vs-text desync, e.g. "Birne" mislabelled as «яйцо»).
        consistency_error = validate_rebus_entry_consistency(entry)
        if consistency_error:
            skipped_inconsistent += 1
            logging.error(
                "sync_rebus_bank: REJECTED %s — %s", entry.get("id"), consistency_error
            )
            continue
        try:
            upsert_rebus_bank_entry(entry)
            inserted += 1
            code_ids.append(str(entry.get("id")))
        except Exception:
            logging.warning("sync_rebus_bank: failed for %s", entry.get("id"), exc_info=True)
    retired = 0
    if code_ids:
        try:
            with get_db_connection_context() as conn:
                with conn.cursor() as cursor:
                    cursor.execute(
                        """
                        UPDATE bt_3_rebus_bank
                        SET retired = TRUE
                        WHERE retired = FALSE
                          AND compound_id <> ALL(%s)
                        """,
                        (code_ids,),
                    )
                    retired = cursor.rowcount or 0
                conn.commit()
        except Exception:
            logging.warning("sync_rebus_bank: retire-stale failed", exc_info=True)
    return {
        "synced": inserted,
        "total": len(REBUS_COMPOUND_BANK),
        "retired_stale": retired,
        "skipped_inconsistent": skipped_inconsistent,
    }


