def measure_task_supply(kind: str, *, window_days: int = 30) -> dict:
    """На сколько дней хватает банка этого вида самому продвинутому человеку.

    Расход берём ПО ФАКТУ из истории за окно, а не по весам ротации на бумаге: веса и
    расписание меняются, а замер не врёт. Глубину считаем по 95-му процентилю, чтобы
    один аномальный человек не завысил потребность для всех.
    """
    from backend.task_supply import percentile, shortfall, supply_days
    bank = _TASK_BANKS.get(str(kind))
    if not bank:
        return {"kind": kind, "error": "неизвестный вид задания"}
    table, id_col, ready = bank
    try:
        ensure_task_rotation_schema()
        with get_db_connection_context() as conn:
            with conn.cursor() as cursor:
                cursor.execute(f"SELECT COUNT(*) FROM {table} WHERE {ready};")
                bank_total = int((cursor.fetchone() or [0])[0])
                # Отдельно — заготовки: они уже в банке и уже стоили денег, но
                # человеку ещё не выдаются (кроссворду не нарисована картинка,
                # аудированию не доехал звук, заданию пула не прошла приёмка).
                # Без этого числа отчёт необъясним: 19.08.2026 владелец четвёртое
                # утро подряд читал «в банке 60» при живом ночном пополнении —
                # сделанное ночью просто не успевало стать выдаваемым к 04:25.
                cursor.execute(f"SELECT COUNT(*) FROM {table} WHERE retired = FALSE;")
                bank_alive = int((cursor.fetchone() or [0])[0])
                # Свободно ПРЯМО СЕЙЧАС: задание в банке, но недавно показанное лежит
                # «на отдыхе» и никому не предлагается. Отдых общий: показали кому
                # угодно — выпало у всех. Замер 19.08.2026: 61 готовый кроссворд, из них
                # свободны СЕМЬ — а отчёт бодро писал «хватит на 29 дней», потому что
                # делил весь банк на расход одного человека. Срок отдыха берётся оттуда
                # же, откуда его берёт выдача (`backend/task_cooldowns.py`), иначе отчёт
                # снова разойдётся с тем, что видит человек.
                # У кроссвордов и анаграмм общего отдыха больше НЕТ (решение владельца
                # 24.08.2026) — для них этой строки в отчёте не будет вовсе: печатать
                # «остальные отдыхают N дн.» про отдых, которого нет, значит соврать.
                from backend.task_cooldowns import COOLDOWN_DAYS_BY_KIND
                cooldown = COOLDOWN_DAYS_BY_KIND.get(str(kind))
                free_now = None
                if cooldown is not None:
                    cursor.execute(
                        f"""SELECT COUNT(*) FROM {table}
                            WHERE {ready}
                              AND (last_sent_at IS NULL
                                   OR last_sent_at < NOW() - (%s || ' days')::interval);""",
                        (int(cooldown),),
                    )
                    free_now = int((cursor.fetchone() or [0])[0])
                # РАСХОД БАНКА = СДАЧИ (решение владельца 24.08.2026, раскатано на все
                # игры). Фильтр «живых» тут не нужен: человек, который сдал задание,
                # живой по определению.
                # На число людей расход НЕ умножается: разным людям можно давать одно и
                # то же задание, поэтому банк от прихода новых не растёт.
                cursor.execute(_SOLVED_CONSUMPTION_SQL[str(kind)],
                               (int(window_days), int(window_days)))
                rates_by_user = {int(r[0]): float(r[1] or 0.0)
                                 for r in (cursor.fetchall() or [])}
                # ОТПРАВКИ — отдельное число с другим смыслом, и оно тоже нужно.
                # Во-первых, свободный запас у игр с общим отдыхом выедает именно
                # рассылка: показали кому угодно — карточка выпала у всех на N дней.
                # Делить «свободно прямо сейчас» на решения нельзя — решают втрое реже,
                # чем получают, и строка обещала бы запас, которого нет.
                # Во-вторых, без отправок неотличимы две разные беды: «игру не
                # выдавали» и «выдаём, а никто не открывает».
                cursor.execute(
                    """SELECT user_id, COUNT(*)::float / GREATEST(%s, 1)
                       FROM bt_3_interactive_inbox
                       WHERE kind = %s
                         AND created_at > NOW() - (%s || ' days')::interval
                       GROUP BY user_id;""",
                    (int(window_days), _INBOX_KIND.get(str(kind), str(kind)),
                     int(window_days)),
                )
                sent_rates = [float(r[1] or 0.0) for r in (cursor.fetchall() or [])]
                # Сколько заданий человеку уже закрыто — из памяти личной ротации.
                cursor.execute(
                    """SELECT user_id,
                              SUM(CASE WHEN retired_at IS NOT NULL
                                        OR next_eligible_at > NOW()
                                       THEN 1 ELSE 0 END)
                       FROM bt_3_user_task_state
                       WHERE kind = %s GROUP BY user_id;""",
                    (str(kind),),
                )
                blocked_by_user = {int(r[0]): int(r[1] or 0)
                                   for r in (cursor.fetchall() or [])}
        rows = [(uid, rate, blocked_by_user.get(uid, 0))
                for uid, rate in rates_by_user.items()]
    except Exception:
        logging.warning("measure_task_supply failed kind=%s", kind, exc_info=True)
        return {"kind": kind, "error": "замер не удался"}

    from backend.task_supply import FORECAST_MARGIN
    rates = [float(r[1] or 0.0) for r in rows]
    blocked = [int(r[2] or 0) for r in rows]
    # Эталон — САМЫЙ расходующий живой человек, а не средний. Дно наступает у него
    # первым, и его пустой экран мы и увидим. Проверка на числах владельца 15.08.2026:
    # один тратит 5 в сутки, другой 1; среднее 3; при банке 30 расчёт обещает 10 дней,
    # а прожорливый упрётся на шестой — запас в 30 дней ему не обеспечен.
    # Не буквальный максимум, а 95-й процентиль: один аномальный человек (владелец на
    # тестах) не должен задирать заказ для всех. Сверху 20% запаса.
    avg_rate = (sum(rates) / len(rates)) if rates else 0.0     # только для отчёта
    top_rate = percentile(rates, 0.95)
    per_day = top_rate * FORECAST_MARGIN
    # Запас считаем у самого «глубокого»: у него закрыто больше всего.
    deepest_blocked = int(percentile(blocked, 0.95))
    available = max(0, bank_total - deepest_blocked)
    days = supply_days(available, per_day)
    out = {
        "kind": str(kind), "title": TASK_KIND_TITLES.get(str(kind), str(kind)),
        "bank_total": bank_total, "bank_ripening": max(0, bank_alive - bank_total),
        "people": len(rows),
        # Расход банка везде считается по РЕШЁННЫМ. Отправки — отдельное число с другим
        # смыслом, оно живёт ниже в `sent_per_day` и подписывается своими словами.
        "spend_basis": "solved",
        "per_day": round(per_day, 2), "per_day_measured": round(top_rate, 2),
        "per_day_avg": round(avg_rate, 2),
        "people_active": len(rates), "blocked_deepest": deepest_blocked,
        "available": available, "supply_days": days,
        "order_now": shortfall(available, per_day),
    }
    # Сколько заданий этого вида уходит людям в сутки — ВСЕМ вместе. Это и есть ответ
    # на вопрос «а мы её вообще шлём?», без которого «никто не решает» читается как
    # «игра выключена».
    out["sent_total_per_day"] = round(sum(sent_rates), 2)
    if free_now is not None:
        # Свободный запас выедает рассылка, поэтому делим его на ОТПРАВКИ самого
        # активного получателя — тем же 95-м процентилем и с тем же запасом 20%.
        out["free_now"] = free_now
        out["cooldown_days"] = int(cooldown)
        out["sent_per_day"] = round(percentile(sent_rates, 0.95) * FORECAST_MARGIN, 2)
    return out


def measure_all_task_supply(*, window_days: int = 30) -> list:
    """Замер по всем видам сразу — основа ночного отчёта владельцу."""
    return [measure_task_supply(k, window_days=window_days) for k in _TASK_BANKS]


def get_user_blocked_content_ids(user_id: int, kind: str) -> list:
    """Что этому человеку по этому виду сейчас закрыто: выброшенное навсегда и то,
    чей срок возврата ещё не подошёл.

    Ключ в памяти лежит вместе с видом («rb:42» — так его строит `content_ranking_key`),
    а банку нужен голый номер записи, поэтому префикс снимается здесь.
    Память служебная: если она недоступна, не закрываем НИЧЕГО — человек получает
    задание по-старому, а не пустой экран.
    """

    if _task_rotation_writes_disabled():
        return []
    try:
        ensure_task_rotation_schema()
        with get_db_connection_context() as conn:
            with conn.cursor() as cursor:
                cursor.execute(
                    """SELECT task_key FROM bt_3_user_task_state
                       WHERE user_id = %s AND kind = %s
                         AND (retired_at IS NOT NULL OR next_eligible_at > NOW());""",
                    (int(user_id), str(kind)),
                )
                rows = cursor.fetchall()
        prefix = f"{kind}:"
        out = []
        for (key,) in rows:
            key = str(key or "")
            out.append(key[len(prefix):] if key.startswith(prefix) else key)
        return [k for k in out if k]
    except Exception:
        logging.warning("get_user_blocked_content_ids failed user=%s kind=%s",
                        user_id, kind, exc_info=True)
        return []


# Виды, у которых НЕТ своей очереди работы над ошибками: заваленное задание возвращает
# им сама ротация — через 7 дней, потом 14, потом 30 (решение владельца 24.08.2026).
# Замер 24.08.2026: в `bt_3_aufgabe_mistakes` лежат artikel 238, wofrage 109, cloze 10,
# transform 9, satzbau 8, wortbildung 8, wortgruppe 7, video 4, error 4 — и НИ ОДНОЙ
# строки кроссворда или анаграммы. Из-за этого неверно решённый кроссворд не закрывался
# для человека ничем, кроме общего отдыха карточки, а его тем же решением сняли.
# Остальные виды в карту не добавлять, не проверив, что их формат вправду попадает в
# очередь ошибок: иначе одно и то же задание будут держать два механизма сразу.
WRONG_LADDER_BY_KIND = {"cw": WRONG_LADDER_DAYS, "ag": WRONG_LADDER_DAYS}


def record_user_task_answer(*, user_id: int, kind: str, task_key: str,
                            is_correct: bool, source: str = "sprint") -> None:
    """Записать ответ и передвинуть лестницу возврата по правилу из `task_rotation`.

    Память служебная: если запись упала, ответ человеку всё равно должен пройти —
    поэтому наружу отсюда ничего не летит.

    Зовётся ТОЛЬКО на первой сдаче задания. Повторное открытие уже сданного лестницу
    двигать не должно: три захода в решённый кроссворд протащили бы человека
    90 → 120 → «никогда», а три захода в заваленный — 7 → 14 → 30. Сторож стоит у
    вызывающего (`backend/backend_server.py`, флаг `already_answered`).
    """
    if _task_rotation_writes_disabled():
        return
    from datetime import datetime, timezone
    from backend.task_rotation import next_state
    try:
        ensure_task_rotation_schema()
        now = datetime.now(timezone.utc)
        prev = get_user_task_state(int(user_id), str(kind), [str(task_key)]).get(
            str(task_key)) or {}
        st = next_state(seen_count=int(prev.get("seen_count") or 0),
                        correct_count=int(prev.get("correct_count") or 0),
                        is_correct=bool(is_correct), now=now,
                        wrong_ladder=WRONG_LADDER_BY_KIND.get(str(kind), ()))
        params = [int(user_id), str(kind), str(task_key), st["seen_count"],
                  st["correct_count"], str(source)[:16]]
        if st["next_eligible_at"] is not None:
            params.append(st["next_eligible_at"])
        if st["retired_at"] is not None:
            params.append(st["retired_at"])
        sql = (
            "INSERT INTO bt_3_user_task_state "
            "    (user_id, kind, task_key, seen_count, correct_count, source, "
            "     last_seen_at, next_eligible_at, retired_at) "
            "VALUES (%s, %s, %s, %s, %s, %s, NOW(), {due}, {ret}) "
            "ON CONFLICT (user_id, kind, task_key) DO UPDATE SET "
            "    seen_count = EXCLUDED.seen_count, "
            "    correct_count = EXCLUDED.correct_count, "
            "    source = EXCLUDED.source, "
            "    last_seen_at = NOW(), "
            "    next_eligible_at = EXCLUDED.next_eligible_at, "
            "    retired_at = COALESCE(bt_3_user_task_state.retired_at, "
            "                          EXCLUDED.retired_at);"
        ).format(due="%s" if st["next_eligible_at"] is not None else "NULL",
                 ret="%s" if st["retired_at"] is not None else "NULL")
        with get_db_connection_context() as conn:
            with conn.cursor() as cursor:
                cursor.execute(sql, tuple(params))
            conn.commit()
    except Exception:
        logging.warning("record_user_task_answer failed user=%s kind=%s key=%s",
                        user_id, kind, task_key, exc_info=True)


# ─── Unified challenge ranking (trophy / leaderboard across all games) ────────

def record_challenge_result(*, challenge_key: str, user_id: int, user_name: str,
                            is_correct: bool, time_ms: int) -> None:
    """First answer per (challenge, user) counts — anti-replay via DO NOTHING."""
    with get_db_connection_context() as conn:
        with conn.cursor() as cursor:
            cursor.execute(
                """
                INSERT INTO bt_3_challenge_results
                    (challenge_key, user_id, user_name, is_correct, time_ms)
                VALUES (%s, %s, %s, %s, %s)
                ON CONFLICT (challenge_key, user_id) DO NOTHING
                """,
                (str(challenge_key), int(user_id), str(user_name or "")[:64],
                 bool(is_correct), max(0, int(time_ms or 0))),
            )
        conn.commit()


def compute_challenge_ranking(*, challenge_key: str, user_id: int) -> dict:
    """Rank the user among everyone who answered this exact challenge: place by
    speed among the correct answers, the top-3 (with names), and the correct %."""
    with get_db_connection_context() as conn:
        with conn.cursor() as cursor:
            cursor.execute(
                """
                SELECT user_id, user_name, is_correct, time_ms
                FROM bt_3_challenge_results
                WHERE challenge_key = %s
                """,
                (str(challenge_key),),
            )
            rows = cursor.fetchall()

    total = len(rows)
    correct = [
        {"user_id": int(r[0]), "name": str(r[1] or ""), "time_ms": int(r[3] or 0)}
        for r in rows if bool(r[2])
    ]
    correct.sort(key=lambda x: x["time_ms"])
    for i, c in enumerate(correct):
        c["place"] = i + 1

    me = next((r for r in rows if int(r[0]) == int(user_id)), None)
    my_correct = bool(me[2]) if me else False
    my_time = int(me[3] or 0) if me else 0
    my_place = next((c["place"] for c in correct if c["user_id"] == int(user_id)), None)

    total_correct = len(correct)
    pct_correct = round(total_correct / total * 100) if total else 0
    return {
        "is_correct": my_correct,
        "total": total,
        "total_correct": total_correct,
        "pct_correct": pct_correct,
        "your_place": my_place,
        "your_time_ms": my_time,
        "your_name": str(me[1] or "") if me else "",
        "top3": [
            {"place": c["place"], "name": c["name"], "time_ms": c["time_ms"]}
            for c in correct[:3]
        ],
    }


def get_challenge_top2(challenge_key: str) -> list[dict]:
    """The two fastest CORRECT answerers of a challenge (with user_id) — used to
    detect a leader change (overtake) at submit time."""
    with get_db_connection_context() as conn:
        with conn.cursor() as cursor:
            cursor.execute(
                """
                SELECT user_id, user_name, time_ms
                FROM bt_3_challenge_results
                WHERE challenge_key = %s AND is_correct = TRUE
                ORDER BY time_ms ASC
                LIMIT 2
                """,
                (str(challenge_key),),
            )
            return [
                {"user_id": int(r[0]), "name": str(r[1] or ""), "time_ms": int(r[2] or 0)}
                for r in (cursor.fetchall() or [])
            ]


def enqueue_challenge_notification(*, user_id: int, kind: str, challenge_key: str, payload: dict) -> None:
    """Outbox a ranking notification (one per user+kind+challenge). Bot DMs it."""
    import json as _json
    with get_db_connection_context() as conn:
        with conn.cursor() as cursor:
            cursor.execute(
                """
                INSERT INTO bt_3_challenge_notifications (user_id, kind, challenge_key, payload)
                VALUES (%s, %s, %s, %s::jsonb)
                ON CONFLICT (user_id, kind, challenge_key) DO NOTHING
                """,
                (int(user_id), str(kind), str(challenge_key), _json.dumps(payload or {}, ensure_ascii=False)),
            )
        conn.commit()


def upsert_overtaken_notification(*, user_id: int, challenge_key: str, payload: dict) -> None:
    """Outbox an 'overtaken' plaque for a user, or refresh it in place.

    Unlike enqueue_challenge_notification (DO NOTHING), this UPDATES the payload
    and re-marks the row pending (sent_at = NULL) on conflict, keeping the same
    telegram_message_id — so the bot EDITS the existing plaque (new place) rather
    than spamming a new message each time the user sinks another rank."""
    import json as _json
    with get_db_connection_context() as conn:
        with conn.cursor() as cursor:
            cursor.execute(
                """
                INSERT INTO bt_3_challenge_notifications (user_id, kind, challenge_key, payload)
                VALUES (%s, 'overtaken', %s, %s::jsonb)
                ON CONFLICT (user_id, kind, challenge_key) DO UPDATE SET
                    payload = EXCLUDED.payload,
                    sent_at = NULL
                """,
                (int(user_id), str(challenge_key), _json.dumps(payload or {}, ensure_ascii=False)),
            )
        conn.commit()


