def get_challenge_results_since(since_hours: int = 24) -> list[dict]:
    """All challenge answers in the recent window — for the end-of-day digest.
    The caller groups by challenge_key and ranks the correct ones by time."""
    with get_db_connection_context() as conn:
        with conn.cursor() as cursor:
            cursor.execute(
                """
                SELECT challenge_key, user_id, user_name, is_correct, time_ms
                FROM bt_3_challenge_results
                WHERE created_at >= NOW() - INTERVAL '1 hour' * %s
                """,
                (int(since_hours),),
            )
            return [
                {"challenge_key": str(r[0]), "user_id": int(r[1]), "name": str(r[2] or ""),
                 "is_correct": bool(r[3]), "time_ms": int(r[4] or 0)}
                for r in (cursor.fetchall() or [])
            ]


def get_daily_interactive_activity(since_hours: int = 24) -> dict[int, dict[str, list]]:
    """Per-user, per-category ``[answered, correct]`` across EVERY fresh interactive
    type in the recent window — the honest source for the end-of-day «Итоги дня» digest.

    Each interactive persists its answer to its OWN table via the shared evaluator in
    ``answer_eval.py``, so those tables already hold answers from BOTH channels — the
    Mini-App in-place path AND the Telegram group path. Aggregating them directly (instead
    of only ``bt_3_challenge_results``, which the Mini-App path alone feeds) is what makes
    the digest count group answers, native poll quizzes, image/visual quizzes and the
    Sprint/Battle games — not just the handful that happened to be answered in the Mini-App.

    Scope: fresh sent-task interactives only. SRS mistake review, FSRS flashcards and the
    self-paced number practice (``np``) are intentionally excluded (they are review/drill,
    not answering a newly-dispatched task).

    Returns ``{user_id: {category: [answered, correct]}}`` for categories:
    art poll iq vr rb cw ag au ls nd qf sp ast ad. ``correct`` is fractional for the
    Sprint/Battle categories (sp/ast/ad), which count one task per set (see below).
    """
    parts: list[str] = []
    params: list[int] = []

    def _add_part(sql: str) -> None:
        parts.append(sql)
        params.append(int(since_hours))

    # Per-item tables: one row per answered item, boolean ``is_correct``. answered =
    # row count, correct = rows with is_correct. (Crossword rows are per-word, numdict
    # per-item — each counts as one answer, which is the honest "answers given" metric.)
    item_sources = [
        ("bt_3_article_quiz_answers",   "art",  "answered_at"),
        ("bt_3_telegram_quiz_attempts", "poll", "answered_at"),
        ("bt_3_image_quiz_answers",     "iq",   "answered_at"),
        ("bt_3_visual_riddle_answers",  "vr",   "answered_at"),
        ("bt_3_rebus_answers",          "rb",   "answered_at"),
        ("bt_3_crossword_answers",      "cw",   "answered_at"),
        ("bt_3_anagram_answers",        "ag",   "answered_at"),
        ("bt_3_aufgabe_answers",        "au",   "answered_at"),
        ("bt_3_numdict_answers",        "nd",   "submitted_at"),
        ("bt_3_quiz_freeform_answers",  "qf",   "answered_at"),
    ]
    for table, cat, ts in item_sources:
        _add_part(
            f"SELECT user_id, '{cat}' AS category, COUNT(*)::int AS answered, "
            f"COUNT(*) FILTER (WHERE is_correct)::int AS correct "
            f"FROM {table} WHERE {ts} >= NOW() - INTERVAL '1 hour' * %s GROUP BY user_id"
        )

    # Listening is graded async against a >=75% pass rule, so correctness is not a plain
    # column: count answered from its own table (both channels), and correct from the
    # grader's ranking rows (`ls:` in challenge_results, is_correct = passed) — recorded
    # by the Mini-App grader. A rare Telegram-group listening still counts as answered.
    _add_part(
        "SELECT user_id, 'ls' AS category, COUNT(*)::int AS answered, 0 AS correct "
        "FROM bt_3_listening_answers WHERE submitted_at >= NOW() - INTERVAL '1 hour' * %s GROUP BY user_id"
    )
    _add_part(
        "SELECT user_id, 'ls' AS category, 0 AS answered, "
        "COUNT(*) FILTER (WHERE is_correct)::int AS correct "
        "FROM bt_3_challenge_results WHERE created_at >= NOW() - INTERVAL '1 hour' * %s "
        "AND challenge_key LIKE 'ls:%%' GROUP BY user_id"
    )

    # Sprint/Battle games store ONE aggregate row per finished set. A set can hold 100+
    # words, so counting each word as an answer would dwarf every other category and skew
    # the daily analytics + accuracy share. Instead each finished set counts as exactly ONE
    # task, scored by how much of it was completed correctly, snapped to {0, 0.5, 1}:
    # pct>=0.75 -> 1, pct>=0.5 -> 0.5, else 0 (e.g. 113/143 = 0.79 -> 1). So `correct` here
    # is fractional (why the outer aggregate is numeric, not int).
    def _pct_bucket(correct_col: str, total_col: str) -> str:
        return (
            f"CASE WHEN {total_col} = 0 THEN 0 "
            f"WHEN {correct_col}::float / {total_col} >= 0.75 THEN 1 "
            f"WHEN {correct_col}::float / {total_col} >= 0.5 THEN 0.5 ELSE 0 END"
        )

    # syn/ant sprint records only correct_count (no attempt total) → no % to measure:
    # one task per session, credited (1) if the player got anything right.
    _add_part(
        "SELECT user_id, 'sp' AS category, COUNT(*)::int AS answered, "
        "SUM(CASE WHEN correct_count > 0 THEN 1 ELSE 0 END)::numeric AS correct "
        "FROM bt_3_sprint_results WHERE answered_at >= NOW() - INTERVAL '1 hour' * %s GROUP BY user_id"
    )
    _add_part(
        "SELECT user_id, 'ast' AS category, COUNT(*)::int AS answered, "
        "SUM(" + _pct_bucket("correct_count", "total_count") + ")::numeric AS correct "
        "FROM bt_3_article_sprint_results WHERE created_at >= NOW() - INTERVAL '1 hour' * %s GROUP BY user_id"
    )
    _add_part(
        "SELECT user_id, 'ad' AS category, COUNT(*)::int AS answered, "
        "SUM(" + _pct_bucket("correct", "total") + ")::numeric AS correct "
        "FROM bt_3_adjektiv_sprint_results WHERE created_at >= NOW() - INTERVAL '1 hour' * %s GROUP BY user_id"
    )
    _add_part(
        "SELECT user_id, 'wf' AS category, COUNT(*)::int AS answered, "
        "SUM(" + _pct_bucket("correct", "total") + ")::numeric AS correct "
        "FROM bt_3_wofrage_sprint_results WHERE created_at >= NOW() - INTERVAL '1 hour' * %s GROUP BY user_id"
    )

    sql = (
        "SELECT user_id, category, SUM(answered)::int, SUM(correct)::numeric FROM (\n    "
        + "\n    UNION ALL\n    ".join(parts)
        + "\n) t WHERE user_id < %s GROUP BY user_id, category"  # exclude synthetic test/load users
    )
    params.append(SYNTHETIC_TELEGRAM_USER_ID_MIN)
    out: dict[int, dict[str, list]] = {}
    with get_db_connection_context() as conn:
        with conn.cursor() as cursor:
            cursor.execute(sql, params)
            for uid, cat, answered, correct in (cursor.fetchall() or []):
                # correct is fractional only for the sprint/battle categories (sp/ast/ad);
                # keep whole numbers as int so the card shows "3" not "3.0".
                c = float(correct or 0)
                out.setdefault(int(uid), {})[str(cat)] = [int(answered or 0), int(c) if c.is_integer() else c]
    return out


def get_group_untimed_answers_since(since_hours: int = 24) -> list[dict]:
    """Interactive answers recorded ONLY in a per-type answer table — i.e. answered in a
    Telegram GROUP via inline buttons, not through the Mini-App in-place path — for the
    quiz leaderboard / champion. These tables carry no timing, so rows return time_ms=None
    (the leaderboard credits base points but no speed bonus / gold).

    Deduped against bt_3_challenge_results (the Mini-App path) by (user_id, content key),
    so a Mini-App answer is never counted twice. Content keys match content_ranking_key()
    exactly ('<kind>:<content_id>'). Crossword's per-word rows are folded into ONE puzzle
    result (all words correct = correct). Covers the challenge-typed tasks rb/cw/ag/au/qf
    (article/poll/image/visual quizzes and the Sprint games have their own leaderboards and
    are intentionally not merged into the speed-ranked champion).

    Returns ``[{challenge_key, user_id, name, is_correct, time_ms(None)}]``.
    """
    parts: list[str] = []
    params: list = []

    def _simple(table: str, dispatch_tbl: str, id_col: str, kind: str) -> None:
        # one answer row per (user, dispatch); content key = '<kind>:<content_id>'.
        parts.append(
            f"SELECT '{kind}:'||d.{id_col} AS challenge_key, a.user_id, a.is_correct "
            f"FROM {table} a JOIN {dispatch_tbl} d ON d.id = a.dispatch_id "
            f"WHERE a.answered_at >= NOW() - INTERVAL '1 hour' * %s "
            f"AND NOT EXISTS (SELECT 1 FROM bt_3_challenge_results c "
            f"WHERE c.user_id = a.user_id AND c.challenge_key = '{kind}:'||d.{id_col} "
            f"AND c.created_at >= NOW() - INTERVAL '1 hour' * %s)"
        )
        params.append(int(since_hours))
        params.append(int(since_hours))

    _simple("bt_3_rebus_answers", "bt_3_rebus_dispatches", "compound_id", "rb")
    _simple("bt_3_anagram_answers", "bt_3_anagram_dispatches", "card_id", "ag")
    _simple("bt_3_aufgabe_answers", "bt_3_aufgabe_dispatches", "aufgabe_id", "au")
    _simple("bt_3_quiz_freeform_answers", "bt_3_quiz_freeform_dispatches", "poll_id", "qf")
    # Crossword: per-word rows → one puzzle result via bool_and; dedup by content key.
    parts.append(
        "SELECT 'cw:'||d.crossword_id AS challenge_key, a.user_id, bool_and(a.is_correct) AS is_correct "
        "FROM bt_3_crossword_answers a JOIN bt_3_crossword_dispatches d ON d.id = a.dispatch_id "
        "WHERE a.answered_at >= NOW() - INTERVAL '1 hour' * %s "
        "GROUP BY d.crossword_id, a.user_id "
        "HAVING NOT EXISTS (SELECT 1 FROM bt_3_challenge_results c "
        "WHERE c.user_id = a.user_id AND c.challenge_key = 'cw:'||d.crossword_id "
        "AND c.created_at >= NOW() - INTERVAL '1 hour' * %s)"
    )
    params.append(int(since_hours))
    params.append(int(since_hours))

    sql = "\nUNION ALL\n".join(parts)
    rows: list[dict] = []
    with get_db_connection_context() as conn:
        with conn.cursor() as cursor:
            cursor.execute(sql, params)
            for key, uid, is_correct in (cursor.fetchall() or []):
                if int(uid) >= SYNTHETIC_TELEGRAM_USER_ID_MIN:
                    continue  # exclude synthetic from champion counting
                rows.append({"challenge_key": str(key), "user_id": int(uid), "name": "",
                             "is_correct": bool(is_correct), "time_ms": None})
    return rows


def get_sprint_leaderboard_rows_since(since_hours: int = 24) -> list[dict]:
    """Artikel/Adjektiv Sprint & Battle sets as leaderboard rows for the champion — ONE
    row per finished set (never per word, which would let a 143-word set dominate). Each
    carries a ``score`` snapped to {0, 0.5, 1} by completion % (pct>=0.75->1, >=0.5->0.5,
    else 0; e.g. 113/143=0.79->1); compute_quiz_leaderboard turns that into 0/5/10 points
    and counts it solved at >=0.5. Untimed (time_ms=None) → no speed bonus / gold. Unique
    per-set challenge_key so each set is its own one-task group. Returns
    ``[{challenge_key, user_id, name, is_correct, time_ms(None), score}]``."""
    bucket = (
        "CASE WHEN {total} = 0 THEN 0 "
        "WHEN {correct}::float / {total} >= 0.75 THEN 1 "
        "WHEN {correct}::float / {total} >= 0.5 THEN 0.5 ELSE 0 END"
    )
    sql = (
        "SELECT 'ast:'||set_id AS challenge_key, user_id, user_name, "
        + bucket.format(correct="correct_count", total="total_count") + " AS score "
        "FROM bt_3_article_sprint_results WHERE created_at >= NOW() - INTERVAL '1 hour' * %s "
        "UNION ALL "
        "SELECT 'ad:'||set_id AS challenge_key, user_id, user_name, "
        + bucket.format(correct="correct", total="total") + " AS score "
        "FROM bt_3_adjektiv_sprint_results WHERE created_at >= NOW() - INTERVAL '1 hour' * %s "
        "UNION ALL "
        "SELECT 'wf:'||set_id AS challenge_key, user_id, user_name, "
        + bucket.format(correct="correct", total="total") + " AS score "
        "FROM bt_3_wofrage_sprint_results WHERE created_at >= NOW() - INTERVAL '1 hour' * %s"
    )
    rows: list[dict] = []
    with get_db_connection_context() as conn:
        with conn.cursor() as cursor:
            cursor.execute(sql, (int(since_hours), int(since_hours), int(since_hours)))
            for key, uid, name, score in (cursor.fetchall() or []):
                if int(uid) >= SYNTHETIC_TELEGRAM_USER_ID_MIN:
                    continue  # exclude synthetic from the sprint leaderboard rows
                sc = float(score or 0)
                rows.append({"challenge_key": str(key), "user_id": int(uid), "name": str(name or ""),
                             "is_correct": sc >= 0.5, "time_ms": None, "score": sc})
    return rows


def get_display_names_for_users(user_ids: list[int]) -> dict[int, str]:
    """Имена для таблиц лидеров и прочих списков. Сначала единый источник — таблица
    личности; кого там ещё нет, ищем в старых таблицах результатов (там имя писалось
    копией) и тут же запоминаем, чтобы второй раз не искать. Возвращает только известные
    имена: строку без имени показываем как "Ученик", но не как "user_123"."""
    ids = sorted({int(u) for u in (user_ids or []) if u is not None})
    if not ids:
        return {}
    out = get_user_display_names(ids)
    ids = [uid for uid in ids if uid not in out]
    if not ids:
        return out
    sql = """
        SELECT DISTINCT ON (user_id) user_id, user_name
        FROM (
            SELECT user_id, username AS user_name, start_time::timestamptz AS ts
            FROM bt_3_user_progress
            WHERE user_id = ANY(%s) AND COALESCE(username, '') <> ''
            UNION ALL
            SELECT user_id, user_name, created_at::timestamptz AS ts
            FROM bt_3_challenge_results
            WHERE user_id = ANY(%s) AND COALESCE(user_name, '') <> ''
            UNION ALL
            SELECT user_id, user_name, created_at::timestamptz AS ts
            FROM bt_3_article_sprint_results
            WHERE user_id = ANY(%s) AND COALESCE(user_name, '') <> ''
            UNION ALL
            SELECT user_id, user_name, created_at::timestamptz AS ts
            FROM bt_3_adjektiv_sprint_results
            WHERE user_id = ANY(%s) AND COALESCE(user_name, '') <> ''
        ) t
        ORDER BY user_id, ts DESC;
    """
    with get_db_connection_context() as conn:
        with conn.cursor() as cursor:
            cursor.execute(sql, (ids, ids, ids, ids))
            for uid, name in (cursor.fetchall() or []):
                nm = clean_identity_name(name)
                if nm:
                    out[int(uid)] = nm
                    remember_user_identity(int(uid), display_name=nm, source="legacy_tables")
    return out


# ─── B2+ text tasks ("Aufgabe") DB functions ──────────────────────────────────

def create_aufgabe(*, aufgabe_id: str, format: str, level: str, payload: dict,
                   review_status: str = "approved") -> None:
    import json as _json
    with get_db_connection_context() as conn:
        with conn.cursor() as cursor:
            cursor.execute(
                """
                INSERT INTO bt_3_aufgabe_bank (aufgabe_id, format, level, payload, review_status)
                VALUES (%s, %s, %s, %s::jsonb, %s)
                ON CONFLICT (aufgabe_id) DO NOTHING
                """,
                (str(aufgabe_id), str(format), str(level or "B2"),
                 _json.dumps(payload or {}, ensure_ascii=False), str(review_status or "approved")),
            )
        conn.commit()


def get_aufgabe_by_id(aufgabe_id: str) -> dict | None:
    """The bank entry (format + payload) for an aufgabe content id, or None. Used to
    label the 'тебя обошли' plaque with the specific task (challenge keys are content-
    keyed, e.g. 'au:<aufgabe_id>')."""
    with get_db_connection_context() as conn:
        with conn.cursor() as cursor:
            cursor.execute(
                "SELECT format, payload FROM bt_3_aufgabe_bank WHERE aufgabe_id=%s;",
                (str(aufgabe_id),),
            )
            r = cursor.fetchone()
    if not r:
        return None
    return {"format": str(r[0] or ""), "payload": r[1] or {}}


def count_available_aufgaben(*, format: str | None = None) -> int:
    """Servable items only. Anything awaiting admin review does NOT count — otherwise a
    pool full of unreviewed items looks full, top-up never runs, and the format silently
    starves."""
    with get_db_connection_context() as conn:
        with conn.cursor() as cursor:
            if format:
                cursor.execute(
                    "SELECT count(*) FROM bt_3_aufgabe_bank "
                    "WHERE retired=FALSE AND review_status='approved' AND format=%s",
                    (str(format),),
                )
            else:
                cursor.execute("SELECT count(*) FROM bt_3_aufgabe_bank "
                               "WHERE retired=FALSE AND review_status='approved'")
            return int(cursor.fetchone()[0])


def pick_next_aufgabe(*, cooldown_days: int = 14, format: str | None = None,
                      exclude_ids: list | None = None) -> dict | None:
    """Oldest unsent (or cooldown-expired) active task, optionally of one format.

    Serve-time self-heal: a degenerate item (e.g. wortbildung whose answer-article
    is already printed in the sentence) must NEVER be served, even if it slipped
    into the pool before the deterministic guard existed and a purge hasn't run
    yet. So we scan the top candidates, skip any that `is_degenerate_aufgabe`
    flags, retire them on the spot (so they leave the rotation for good), and
    return the first clean one.

    `exclude_ids` — что закрыто ЛИЧНО этому человеку (см. `get_user_blocked_content_ids`)."""
    skip = [str(i) for i in (exclude_ids or []) if str(i)]
    with get_db_connection_context() as conn:
        with conn.cursor() as cursor:
            cursor.execute(
                """
                SELECT aufgabe_id, format, level, payload
                FROM bt_3_aufgabe_bank
                WHERE retired = FALSE
                  AND review_status = 'approved'
                  AND (%s IS NULL OR format = %s)
                  AND (last_sent_at IS NULL OR last_sent_at < NOW() - INTERVAL '1 day' * %s)
                """
                + ("  AND aufgabe_id::text <> ALL(%s)\n" if skip else "")
                + """
                ORDER BY last_sent_at NULLS FIRST, created_at
                LIMIT 12
                """,
                ((format, format, int(cooldown_days), skip) if skip
                 else (format, format, int(cooldown_days))),
            )
            rows = cursor.fetchall() or []
            picked = None
            degenerate_ids = []
            for row in rows:
                payload = row[3] if isinstance(row[3], dict) else {}
                if is_degenerate_aufgabe(row[1], payload):
                    degenerate_ids.append(row[0])
                    continue
                picked = {"aufgabe_id": row[0], "format": row[1], "level": row[2],
                          "payload": payload}
                break
            if degenerate_ids:
                # Retire the broken items so they never resurface (best-effort).
                cursor.execute(
                    "UPDATE bt_3_aufgabe_bank SET retired = TRUE WHERE aufgabe_id = ANY(%s);",
                    (degenerate_ids,),
                )
                conn.commit()
                logging.info("pick_next_aufgabe: retired %d degenerate item(s) at serve time",
                             len(degenerate_ids))
    return picked


def mark_aufgabe_sent(aufgabe_id: str) -> None:
    with get_db_connection_context() as conn:
        with conn.cursor() as cursor:
            cursor.execute(
                """
                UPDATE bt_3_aufgabe_bank
                SET send_count = send_count + 1, last_sent_at = NOW(), fail_count = 0
                WHERE aufgabe_id = %s
                """,
                (str(aufgabe_id),),
            )
        conn.commit()


def mark_aufgabe_send_failed(aufgabe_id: str, *, retire_after: int = 3) -> None:
    with get_db_connection_context() as conn:
        with conn.cursor() as cursor:
            cursor.execute(
                """
                UPDATE bt_3_aufgabe_bank
                SET fail_count = fail_count + 1, last_sent_at = NOW(),
                    retired = (fail_count + 1 >= %s)
                WHERE aufgabe_id = %s
                """,
                (int(retire_after), str(aufgabe_id)),
            )
        conn.commit()


# ── Crowd-mastery rotation ────────────────────────────────────────────────────
# When the active crowd has clearly mastered an item (enough distinct answerers and
# ≥ correct-ratio of them right), retire it and regenerate a fresh one — so content
# stays fresh and users don't keep seeing what everyone already knows. The retire is
# logical (retired=TRUE) so the row stays for stats + dedup history.

# Test/load users have IDs at/above this bound (env SYNTHETIC_TELEGRAM_USER_ID_MIN, kept
# in sync with bot_3.py / backend_server.py). They are never real people, so they are
# EXCLUDED from analytics, leaderboards and active-user counts. Filter in SQL with
# `AND user_id < SYNTHETIC_TELEGRAM_USER_ID_MIN`.
SYNTHETIC_TELEGRAM_USER_ID_MIN = max(
    1, int((os.getenv("SYNTHETIC_TELEGRAM_USER_ID_MIN") or "9100000001").strip() or "9100000001"))

_ACTIVE_USER_SOURCES = [
    ("bt_3_challenge_results", "created_at"),
    ("bt_3_aufgabe_answers", "answered_at"),
    ("bt_3_rebus_answers", "answered_at"),
    ("bt_3_crossword_answers", "answered_at"),
    ("bt_3_anagram_answers", "answered_at"),
    ("bt_3_article_quiz_answers", "answered_at"),
    ("bt_3_image_quiz_answers", "answered_at"),
    ("bt_3_visual_riddle_answers", "answered_at"),
    ("bt_3_listening_answers", "submitted_at"),
    ("bt_3_article_sprint_results", "created_at"),
    ("bt_3_adjektiv_sprint_results", "created_at"),
    ("bt_3_wofrage_sprint_results", "created_at"),
]


def count_active_users(days: int = 30) -> int:
    """Distinct users who answered ANY interactive in the last `days`. Used to size
    the mastery threshold off ACTIVE users (passive/nominal members don't block
    rotation). Each source queried independently so a missing table is skipped."""
    users: set[int] = set()
    for tbl, ts in _ACTIVE_USER_SOURCES:
        try:
            with get_db_connection_context() as conn:
                with conn.cursor() as cur:
                    cur.execute(
                        f"SELECT DISTINCT user_id FROM {tbl} "
                        f"WHERE {ts} >= NOW() - INTERVAL '1 day' * %s "
                        f"AND user_id < %s",  # noqa: S608 (names are constants) — exclude synthetic
                        (int(days), SYNTHETIC_TELEGRAM_USER_ID_MIN),
                    )
                    for r in cur.fetchall() or []:
                        if r[0] is not None:
                            users.add(int(r[0]))
        except Exception:
            continue
    return len(users)


def mastered_aufgabe_ids(*, min_answerers: int, ratio: float = 0.60) -> list[str]:
    """Active aufgaben the crowd has mastered: ≥ min_answerers distinct users answered
    and ≥ ratio of them got it right (a user counts as correct if they ever were)."""
    try:
        with get_db_connection_context() as conn:
            with conn.cursor() as cur:
                cur.execute(
                    """
                    SELECT d.aufgabe_id
                    FROM bt_3_aufgabe_answers a
                    JOIN bt_3_aufgabe_dispatches d ON d.id = a.dispatch_id
                    JOIN bt_3_aufgabe_bank b ON b.aufgabe_id = d.aufgabe_id
                    WHERE b.retired = FALSE
                    GROUP BY d.aufgabe_id
                    HAVING COUNT(DISTINCT a.user_id) >= %s
                       AND COUNT(DISTINCT a.user_id) FILTER (WHERE a.is_correct)::float
                           / NULLIF(COUNT(DISTINCT a.user_id), 0) >= %s
                    """,
                    (int(min_answerers), float(ratio)),
                )
                return [str(r[0]) for r in (cur.fetchall() or [])]
    except Exception:
        logging.warning("mastered_aufgabe_ids failed", exc_info=True)
        return []


def retire_aufgabe_ids(ids: list[str]) -> int:
    if not ids:
        return 0
    try:
        with get_db_connection_context() as conn:
            with conn.cursor() as cur:
                cur.execute(
                    "UPDATE bt_3_aufgabe_bank SET retired = TRUE "
                    "WHERE aufgabe_id = ANY(%s) AND retired = FALSE",
                    (list(ids),),
                )
                n = cur.rowcount
            conn.commit()
        return int(n or 0)
    except Exception:
        logging.warning("retire_aufgabe_ids failed", exc_info=True)
        return 0


# Single-item pool domains: answers → dispatches → bank, one bank item per dispatch.
# Names are a fixed whitelist (no injection) so the mastery query is generic.
_MASTERY_POOL_SPECS = {
    "rebus": {"ans": "bt_3_rebus_answers", "disp": "bt_3_rebus_dispatches",
              "item_col": "compound_id", "bank": "bt_3_rebus_bank", "id_col": "compound_id"},
    "anagram": {"ans": "bt_3_anagram_answers", "disp": "bt_3_anagram_dispatches",
                "item_col": "card_id", "bank": "bt_3_anagram_cards", "id_col": "card_id"},
    "article_quiz": {"ans": "bt_3_article_quiz_answers", "disp": "bt_3_article_quiz_dispatches",
                     "item_col": "word_id", "bank": "bt_3_article_quiz_bank", "id_col": "word_id"},
    # crossword: retire/count use the generic spec; mastery is computed by the
    # dedicated mastered_crossword_ids (puzzle = a user got ALL words right).
    "crossword": {"ans": "bt_3_crossword_answers", "disp": "bt_3_crossword_dispatches",
                  "item_col": "crossword_id", "bank": "bt_3_crossword_bank", "id_col": "crossword_id"},
    # listening: retire/count generic; mastery via listening_mastery_rows (the
    # answer is graded JSON, so "passed" is computed in Python with score_evaluation).
    "listening": {"ans": "bt_3_listening_answers", "disp": "bt_3_listening_dispatches",
                  "item_col": "listening_id", "bank": "bt_3_listening_bank", "id_col": "listening_id"},
}


def listening_mastery_rows() -> list[dict]:
    """Per done listening answer: {listening_id, n_questions, user_id, evaluation}.
    The caller scores each with score_evaluation to decide 'passed' (≥75%)."""
    try:
        with get_db_connection_context() as conn:
            with conn.cursor() as cur:
                cur.execute(
                    """
                    SELECT d.listening_id,
                           COALESCE(jsonb_array_length(b.questions_json), 0) AS nq,
                           a.user_id, a.evaluation_json
                    FROM bt_3_listening_answers a
                    JOIN bt_3_listening_dispatches d ON d.id = a.dispatch_id
                    JOIN bt_3_listening_bank b ON b.listening_id = d.listening_id
                    WHERE a.evaluation_status = 'done' AND b.retired = FALSE
                    """
                )
                return [{"listening_id": str(r[0]), "n_questions": int(r[1] or 0),
                         "user_id": int(r[2]), "evaluation": r[3] if isinstance(r[3], list) else []}
                        for r in (cur.fetchall() or [])]
    except Exception:
        logging.warning("listening_mastery_rows failed", exc_info=True)
        return []


# ── Sprint word-bank mastery (der/die/das nouns used by sprint / trainer / battles) ──
_SPRINT_WORD_ANSWERS_DONE = False


def ensure_sprint_word_answers_schema() -> None:
    global _SPRINT_WORD_ANSWERS_DONE
    if _SPRINT_WORD_ANSWERS_DONE:
        return
    with get_db_connection_context() as conn:
        with conn.cursor() as cur:
            cur.execute(
                """CREATE TABLE IF NOT EXISTS bt_3_article_sprint_word_answers (
                    set_id TEXT NOT NULL,
                    word TEXT NOT NULL,
                    article TEXT NOT NULL DEFAULT '',
                    user_id BIGINT NOT NULL,
                    is_correct BOOLEAN NOT NULL,
                    answered_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
                    PRIMARY KEY (set_id, word, user_id)
                );"""
            )
            cur.execute(
                "CREATE INDEX IF NOT EXISTS idx_bt_3_sprint_word_answers_word "
                "ON bt_3_article_sprint_word_answers (word);"
            )
        conn.commit()
    _SPRINT_WORD_ANSWERS_DONE = True


def record_article_sprint_word_answers(*, set_id: str, user_id: int, items: list[dict]) -> None:
    """Log per-word der/die/das correctness (first attempt per user/set/word) so the
    crowd-mastery rotation can retire words everyone aces. Off the critical path."""
    rows = [(str(set_id), str(it.get("word") or "").strip().lower(),
             str(it.get("article") or "").strip().lower(), int(user_id), bool(it.get("is_correct")))
            for it in (items or []) if str(it.get("word") or "").strip()]
    if not rows:
        return
    try:
        ensure_sprint_word_answers_schema()
        with get_db_connection_context() as conn:
            with conn.cursor() as cur:
                cur.executemany(
                    "INSERT INTO bt_3_article_sprint_word_answers "
                    "(set_id, word, article, user_id, is_correct) VALUES (%s, %s, %s, %s, %s) "
                    "ON CONFLICT (set_id, word, user_id) DO NOTHING;",
                    rows,
                )
            conn.commit()
    except Exception:
        logging.warning("record_article_sprint_word_answers failed set=%s", set_id, exc_info=True)


def mastered_article_sprint_words(*, min_answerers: int, ratio: float = 0.60) -> list[str]:
    """Lowercased words the crowd has mastered across all sets (≥ min distinct users,
    ≥ ratio of them correct)."""
    try:
        ensure_sprint_word_answers_schema()
        with get_db_connection_context() as conn:
            with conn.cursor() as cur:
                cur.execute(
                    """
                    SELECT word
                    FROM bt_3_article_sprint_word_answers
                    GROUP BY word
                    HAVING COUNT(DISTINCT user_id) >= %s
                       AND COUNT(DISTINCT user_id) FILTER (WHERE is_correct)::float
                           / NULLIF(COUNT(DISTINCT user_id), 0) >= %s
                    """,
                    (int(min_answerers), float(ratio)),
                )
                return [str(r[0]) for r in (cur.fetchall() or [])]
    except Exception:
        logging.warning("mastered_article_sprint_words failed", exc_info=True)
        return []


def retire_article_sprint_nouns_by_words(words: list[str]) -> int:
    """Retire verified nouns whose word the crowd mastered (autofill refills fresh)."""
    norm = [str(w).strip().lower() for w in (words or []) if str(w).strip()]
    if not norm:
        return 0
    try:
        with get_db_connection_context() as conn:
            with conn.cursor() as cur:
                cur.execute(
                    "UPDATE bt_3_article_sprint_nouns SET retired = TRUE, updated_at = NOW() "
                    "WHERE lower(word) = ANY(%s) AND retired = FALSE",
                    (norm,),
                )
                n = cur.rowcount
            conn.commit()
        return int(n or 0)
    except Exception:
        logging.warning("retire_article_sprint_nouns_by_words failed", exc_info=True)
        return 0


def mastered_crossword_ids(*, min_answerers: int, ratio: float = 0.60) -> list[str]:
    """Crossword puzzles the crowd mastered. A user 'mastered' a puzzle if every word
    they submitted for it was correct (BOOL_AND); retire when ≥ min_answerers distinct
    users tried it and ≥ ratio of them got the WHOLE puzzle right."""
    try:
        with get_db_connection_context() as conn:
            with conn.cursor() as cur:
                cur.execute(
                    """
                    WITH per_user AS (
                        SELECT d.crossword_id, a.user_id, BOOL_AND(a.is_correct) AS all_right
                        FROM bt_3_crossword_answers a
                        JOIN bt_3_crossword_dispatches d ON d.id = a.dispatch_id
                        JOIN bt_3_crossword_bank b ON b.crossword_id = d.crossword_id
                        WHERE b.retired = FALSE
                        GROUP BY d.crossword_id, a.user_id
                    )
                    SELECT crossword_id FROM per_user
                    GROUP BY crossword_id
                    HAVING COUNT(*) >= %s
                       AND COUNT(*) FILTER (WHERE all_right)::float / NULLIF(COUNT(*), 0) >= %s
                    """,
                    (int(min_answerers), float(ratio)),
                )
                return [str(r[0]) for r in (cur.fetchall() or [])]
    except Exception:
        logging.warning("mastered_crossword_ids failed", exc_info=True)
        return []


def mastered_pool_item_ids(domain: str, *, min_answerers: int, ratio: float = 0.60) -> list[str]:
    """Crowd-mastered bank items of a single-item pool domain (same rule as aufgabe)."""
    spec = _MASTERY_POOL_SPECS.get(domain)
    if not spec:
        return []
    try:
        with get_db_connection_context() as conn:
            with conn.cursor() as cur:
                cur.execute(
                    f"""
                    SELECT d.{spec['item_col']}
                    FROM {spec['ans']} a
                    JOIN {spec['disp']} d ON d.id = a.dispatch_id
                    JOIN {spec['bank']} b ON b.{spec['id_col']} = d.{spec['item_col']}
                    WHERE b.retired = FALSE
                    GROUP BY d.{spec['item_col']}
                    HAVING COUNT(DISTINCT a.user_id) >= %s
                       AND COUNT(DISTINCT a.user_id) FILTER (WHERE a.is_correct)::float
                           / NULLIF(COUNT(DISTINCT a.user_id), 0) >= %s
                    """,  # noqa: S608 (identifiers come from the whitelist above)
                    (int(min_answerers), float(ratio)),
                )
                return [str(r[0]) for r in (cur.fetchall() or [])]
    except Exception:
        logging.warning("mastered_pool_item_ids failed domain=%s", domain, exc_info=True)
        return []


def retire_pool_item_ids(domain: str, ids: list[str]) -> int:
    spec = _MASTERY_POOL_SPECS.get(domain)
    if not spec or not ids:
        return 0
    try:
        with get_db_connection_context() as conn:
            with conn.cursor() as cur:
                cur.execute(
                    f"UPDATE {spec['bank']} SET retired = TRUE "
                    f"WHERE {spec['id_col']} = ANY(%s) AND retired = FALSE",  # noqa: S608
                    (list(ids),),
                )
                n = cur.rowcount
            conn.commit()
        return int(n or 0)
    except Exception:
        logging.warning("retire_pool_item_ids failed domain=%s", domain, exc_info=True)
        return 0


def count_pool_non_retired(domain: str) -> int:
    spec = _MASTERY_POOL_SPECS.get(domain)
