def ensure_article_battle_available_schema() -> None:
    """Opt-in registry: users who agreed to be invited to Artikel battles."""
    with get_db_connection_context() as conn:
        with conn.cursor() as cursor:
            cursor.execute(
                """
                CREATE TABLE IF NOT EXISTS bt_3_article_battle_available (
                    user_id     BIGINT PRIMARY KEY,
                    opted_in    BOOLEAN NOT NULL DEFAULT TRUE,
                    user_name   TEXT NOT NULL DEFAULT '',
                    updated_at  TIMESTAMPTZ NOT NULL DEFAULT NOW()
                );
                """
            )
            cursor.execute(
                "ALTER TABLE bt_3_article_battle_available "
                "ADD COLUMN IF NOT EXISTS user_name TEXT NOT NULL DEFAULT '';"
            )
        conn.commit()


def toggle_article_battle_available(user_id: int, user_name: str = "") -> bool:
    """Flip the user's opt-in for battle invites. Returns the NEW state."""
    ensure_article_battle_available_schema()
    with get_db_connection_context() as conn:
        with conn.cursor() as cursor:
            cursor.execute(
                """
                INSERT INTO bt_3_article_battle_available (user_id, opted_in, user_name, updated_at)
                VALUES (%s, TRUE, %s, NOW())
                ON CONFLICT (user_id) DO UPDATE
                SET opted_in = NOT bt_3_article_battle_available.opted_in,
                    user_name = CASE WHEN EXCLUDED.user_name <> '' THEN EXCLUDED.user_name
                                     ELSE bt_3_article_battle_available.user_name END,
                    updated_at = NOW()
                RETURNING opted_in;
                """,
                (int(user_id), str(user_name or "")[:80]),
            )
            row = cursor.fetchone()
        conn.commit()
    return bool(row[0]) if row else True


def set_article_battle_available(user_id: int, opted_in: bool, user_name: str = "") -> bool:
    """Set the battle-invite opt-in to an EXPLICIT value (onboarding uses this, not
    the toggle). Returns the stored state."""
    ensure_article_battle_available_schema()
    with get_db_connection_context() as conn:
        with conn.cursor() as cursor:
            cursor.execute(
                """
                INSERT INTO bt_3_article_battle_available (user_id, opted_in, user_name, updated_at)
                VALUES (%s, %s, %s, NOW())
                ON CONFLICT (user_id) DO UPDATE
                SET opted_in = EXCLUDED.opted_in,
                    user_name = CASE WHEN EXCLUDED.user_name <> '' THEN EXCLUDED.user_name
                                     ELSE bt_3_article_battle_available.user_name END,
                    updated_at = NOW()
                RETURNING opted_in;
                """,
                (int(user_id), bool(opted_in), str(user_name or "")[:80]),
            )
            row = cursor.fetchone()
        conn.commit()
    return bool(row[0]) if row else bool(opted_in)


def is_article_battle_available(user_id: int) -> bool:
    ensure_article_battle_available_schema()
    with get_db_connection_context() as conn:
        with conn.cursor() as cursor:
            cursor.execute(
                "SELECT opted_in FROM bt_3_article_battle_available WHERE user_id = %s;",
                (int(user_id),),
            )
            row = cursor.fetchone()
    return bool(row[0]) if row else False


