# ── Synonym/Antonym SPRINT (60s, type as many as you can, rank by count) ──────
def ensure_sprint_schema() -> None:
    with get_db_connection_context() as conn:
        with conn.cursor() as cursor:
            cursor.execute(
                """
                CREATE TABLE IF NOT EXISTS bt_3_sprint_bank (
                    sprint_id    TEXT PRIMARY KEY,
                    relation     TEXT NOT NULL,
                    wort         TEXT NOT NULL,
                    accepted     JSONB NOT NULL DEFAULT '[]'::jsonb,
                    erklaerung   TEXT NOT NULL DEFAULT '',
                    tip          TEXT NOT NULL DEFAULT '',
                    hint_ru      TEXT NOT NULL DEFAULT '',
                    level        TEXT NOT NULL DEFAULT 'B2',
                    send_count   INTEGER NOT NULL DEFAULT 0,
                    last_sent_at TIMESTAMPTZ,
                    retired      BOOLEAN NOT NULL DEFAULT FALSE,
                    created_at   TIMESTAMPTZ NOT NULL DEFAULT NOW()
                );
                """
            )
            cursor.execute(
                """
                CREATE TABLE IF NOT EXISTS bt_3_sprint_dispatches (
                    id                  BIGSERIAL PRIMARY KEY,
                    sprint_id           TEXT NOT NULL,
                    relation            TEXT NOT NULL,
                    slot_date           DATE NOT NULL,
                    slot_hour           INTEGER NOT NULL,
                    target_user_id      BIGINT NOT NULL,
                    chat_id             BIGINT NOT NULL,
                    telegram_message_id BIGINT,
                    sent_at             TIMESTAMPTZ NOT NULL DEFAULT NOW(),
                    UNIQUE (target_user_id, slot_date, slot_hour)
                );
                """
            )
            cursor.execute(
                """
                CREATE TABLE IF NOT EXISTS bt_3_sprint_results (
                    id            BIGSERIAL PRIMARY KEY,
                    sprint_key    TEXT NOT NULL,
                    user_id       BIGINT NOT NULL,
                    user_name     TEXT NOT NULL DEFAULT '',
                    correct_count INTEGER NOT NULL DEFAULT 0,
                    time_ms       INTEGER NOT NULL DEFAULT 0,
                    answered_at   TIMESTAMPTZ NOT NULL DEFAULT NOW(),
                    UNIQUE (sprint_key, user_id)
                );
                """
            )
            # Trainer add-on (recognition game that feeds the sprint 3 days later):
            # one JSONB blob holds the verified distractors + example sentences built
            # by the nightly adversarial pipeline; trainer_ready gates rotation. The
            # bank is tiny (dozens of rows) so ADD COLUMN is cheap and idempotent.
            cursor.execute(
                "ALTER TABLE bt_3_sprint_bank "
                "ADD COLUMN IF NOT EXISTS trainer_json JSONB NOT NULL DEFAULT '{}'::jsonb;"
            )
            cursor.execute(
                "ALTER TABLE bt_3_sprint_bank "
                "ADD COLUMN IF NOT EXISTS trainer_ready BOOLEAN NOT NULL DEFAULT FALSE;"
            )
            # Trainer rotation + the rail: when a word went out as a TRAINER (so the
            # sprint can pick the SAME word `trainer_sent_date` + 3 days later).
            cursor.execute(
                "ALTER TABLE bt_3_sprint_bank ADD COLUMN IF NOT EXISTS trainer_last_sent_at TIMESTAMPTZ;"
            )
            cursor.execute(
                "ALTER TABLE bt_3_sprint_bank ADD COLUMN IF NOT EXISTS trainer_sent_date DATE;"
            )
            cursor.execute(
                "ALTER TABLE bt_3_sprint_bank ADD COLUMN IF NOT EXISTS trainer_send_count INTEGER NOT NULL DEFAULT 0;"
            )
        conn.commit()


def upsert_sprint_item(item: dict) -> None:
    import json as _json
    with get_db_connection_context() as conn:
        with conn.cursor() as cursor:
            cursor.execute(
                """
                INSERT INTO bt_3_sprint_bank
                    (sprint_id, relation, wort, accepted, erklaerung, tip, hint_ru, level)
                VALUES (%s, %s, %s, %s::jsonb, %s, %s, %s, %s)
                ON CONFLICT (sprint_id) DO NOTHING
                """,
                (
                    str(item["sprint_id"]), str(item["relation"]), str(item["wort"]),
                    _json.dumps(list(item.get("accepted") or []), ensure_ascii=False),
                    str(item.get("erklaerung") or ""), str(item.get("tip") or ""),
                    str(item.get("hint_ru") or ""), str(item.get("level") or "B2"),
                ),
            )
        conn.commit()


def delete_sprint_bank(*, relation: str | None = None) -> int:
    """Flush sprint bank items so the pool regenerates with the current prompt
    (e.g. accepted now carries per-word Russian). Returns rows deleted."""
    with get_db_connection_context() as conn:
        with conn.cursor() as cursor:
            if relation:
                cursor.execute("DELETE FROM bt_3_sprint_bank WHERE relation = %s", (str(relation),))
            else:
                cursor.execute("DELETE FROM bt_3_sprint_bank")
            n = cursor.rowcount
        conn.commit()
    return int(n or 0)


def count_available_sprint_items(*, relation: str, cooldown_days: int = 0) -> int:
    with get_db_connection_context() as conn:
        with conn.cursor() as cursor:
            cursor.execute(
                "SELECT COUNT(*) FROM bt_3_sprint_bank WHERE relation = %s AND retired = FALSE "
                "AND (last_sent_at IS NULL OR last_sent_at < NOW() - (%s || ' days')::INTERVAL)",
                (str(relation), int(cooldown_days)),
            )
            return int((cursor.fetchone() or [0])[0])


def ensure_sprint_word_outcomes_schema() -> None:
    """Какие слова человек НАЗВАЛ, а какие упустил. До 15.08.2026 не сохранялось нигде:
    в базу уходил только счёт «7 слов за минуту»."""
    if _task_rotation_writes_disabled():
        return
    with get_db_connection_context() as conn:
        with conn.cursor() as cur:
            cur.execute("""
                CREATE TABLE IF NOT EXISTS bt_3_sprint_word_outcomes (
                    id         BIGSERIAL PRIMARY KEY,
                    user_id    BIGINT NOT NULL,
                    sprint_id  TEXT NOT NULL,
                    relation   TEXT NOT NULL,
                    word       TEXT NOT NULL,
                    found      BOOLEAN NOT NULL,
                    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
                );
            """)
            cur.execute("CREATE INDEX IF NOT EXISTS idx_bt_3_sprint_word_outcomes_user "
                        "ON bt_3_sprint_word_outcomes (user_id, relation, created_at DESC);")
        conn.commit()


def record_sprint_word_outcomes(*, user_id: int, sprint_id: str, relation: str,
                                found: list, missed: list) -> None:
    """Слова раунда пачкой. Служебная запись: упала — раунд человеку всё равно засчитан."""
    if _task_rotation_writes_disabled():
        return
    rows = ([(str(w), True) for w in (found or []) if str(w).strip()]
            + [(str(w), False) for w in (missed or []) if str(w).strip()])
    if not rows:
        return
    try:
        ensure_sprint_word_outcomes_schema()
        with get_db_connection_context() as conn:
            with conn.cursor() as cur:
                for word, ok in rows:
                    cur.execute(
                        "INSERT INTO bt_3_sprint_word_outcomes "
                        "(user_id, sprint_id, relation, word, found) VALUES (%s,%s,%s,%s,%s);",
                        (int(user_id), str(sprint_id), str(relation), word[:64], bool(ok)),
                    )
            conn.commit()
    except Exception:
        logging.warning("record_sprint_word_outcomes failed user=%s sprint=%s",
                        user_id, sprint_id, exc_info=True)


def pick_next_sprint(*, relation: str, cooldown_days: int = 14,
                     exclude_ids: list | None = None) -> dict | None:
    """`exclude_ids` — что закрыто ЛИЧНО этому человеку (`get_user_blocked_content_ids`).

    Банк здесь крошечный (16 синонимов и 18 антонимов, замер 14.08.2026), поэтому
    повтор одного и того же слова заметен сильнее, чем где бы то ни было.
    """
    skip = [str(i).split(":", 1)[-1] for i in (exclude_ids or []) if str(i)]
    with get_db_connection_context() as conn:
        with conn.cursor() as cursor:
            cursor.execute(
                """
                SELECT sprint_id, relation, wort, accepted, erklaerung, tip, hint_ru
                FROM bt_3_sprint_bank
                WHERE relation = %s AND retired = FALSE
                  AND (last_sent_at IS NULL OR last_sent_at < NOW() - (%s || ' days')::INTERVAL)
                """
                + ("  AND sprint_id::text <> ALL(%s)\n" if skip else "")
                + """
                ORDER BY last_sent_at NULLS FIRST, send_count ASC
                LIMIT 1
                """,
                ((str(relation), int(cooldown_days), skip) if skip
                 else (str(relation), int(cooldown_days))),
            )
            row = cursor.fetchone()
    if not row:
        return None
    acc = row[3] if isinstance(row[3], list) else []
    return {"sprint_id": row[0], "relation": row[1], "wort": row[2], "accepted": acc,
            "erklaerung": row[4], "tip": row[5], "hint_ru": row[6]}


def _trainer_row_to_dict(row) -> dict:
    acc = row[3] if isinstance(row[3], list) else []
    return {"sprint_id": row[0], "relation": row[1], "wort": row[2], "accepted": acc, "hint_ru": row[4]}


def pick_next_trainer(*, relation: str, cooldown_days: int = 21) -> dict | None:
    """Next TRAINER word for the rail: a trainer-ready word, least-recently trained
    first (respecting a cooldown). Returns None if none are ready/available."""
    with get_db_connection_context() as conn:
        with conn.cursor() as cursor:
            cursor.execute(
                """
                SELECT sprint_id, relation, wort, accepted, hint_ru
                FROM bt_3_sprint_bank
                WHERE relation = %s AND retired = FALSE AND trainer_ready = TRUE
                  AND (trainer_last_sent_at IS NULL
                       OR trainer_last_sent_at < NOW() - (%s || ' days')::INTERVAL)
                ORDER BY trainer_last_sent_at NULLS FIRST, trainer_send_count ASC
                LIMIT 1
                """,
                (str(relation), int(cooldown_days)),
            )
            row = cursor.fetchone()
    return _trainer_row_to_dict(row) if row else None


def mark_trainer_sent(sprint_id: str, *, sent_date=None) -> None:
    """Record a trainer send (rotation + rail): stamps trainer_last_sent_at/date and
    bumps the counter so pick_next_trainer rotates and the sprint can pick it +3 days.

    `sent_date=None` = the NEXT-DAY REPEAT of the same word: count + last_sent_at move,
    but trainer_sent_date (the rail anchor) stays on the FIRST send — otherwise the
    repeat would push the sprint from day+3 to day+4."""
    with get_db_connection_context() as conn:
        with conn.cursor() as cursor:
            if sent_date is None:
                cursor.execute(
                    "UPDATE bt_3_sprint_bank SET trainer_last_sent_at = NOW(), "
                    "trainer_send_count = trainer_send_count + 1 WHERE sprint_id = %s",
                    (str(sprint_id),),
                )
            else:
                cursor.execute(
                    "UPDATE bt_3_sprint_bank SET trainer_last_sent_at = NOW(), "
                    "trainer_sent_date = %s, trainer_send_count = trainer_send_count + 1 "
                    "WHERE sprint_id = %s",
                    (sent_date, str(sprint_id)),
                )
        conn.commit()


def pick_repeat_trainer(*, relation: str, sent_date) -> dict | None:
    """The word that went out as a TRAINER on `sent_date` (i.e. yesterday) — the second,
    optional pass of the SAME training. No new generation, no rail change; the sprint
    still fires trainer_sent_date + 3 days. None → nothing was trained that day."""
    with get_db_connection_context() as conn:
        with conn.cursor() as cursor:
            cursor.execute(
                """
                SELECT sprint_id, relation, wort, accepted, hint_ru
                FROM bt_3_sprint_bank
                WHERE relation = %s AND retired = FALSE AND trainer_ready = TRUE
                  AND trainer_sent_date = %s
                ORDER BY trainer_last_sent_at DESC NULLS LAST
                LIMIT 1
                """,
                (str(relation), sent_date),
            )
            row = cursor.fetchone()
    return _trainer_row_to_dict(row) if row else None


def pick_rail_sprint(*, relation: str, target_date, lag_days: int = 3) -> dict | None:
    """The rail (used by the sprint sender): the word that went out as a TRAINER exactly
    `lag_days` before `target_date` and hasn't been sprinted since. Returns None → the
    caller falls back to the normal cooldown rotation."""
    with get_db_connection_context() as conn:
        with conn.cursor() as cursor:
            cursor.execute(
                """
                SELECT sprint_id, relation, wort, accepted, erklaerung, tip, hint_ru
                FROM bt_3_sprint_bank
                WHERE relation = %s AND retired = FALSE
                  AND trainer_sent_date = (%s::date - %s)
                  AND (last_sent_at IS NULL OR last_sent_at < trainer_sent_date)
                ORDER BY last_sent_at NULLS FIRST, send_count ASC
                LIMIT 1
                """,
                (str(relation), target_date, int(lag_days)),
            )
            row = cursor.fetchone()
    if not row:
        return None
    acc = row[3] if isinstance(row[3], list) else []
    return {"sprint_id": row[0], "relation": row[1], "wort": row[2], "accepted": acc,
            "erklaerung": row[4], "tip": row[5], "hint_ru": row[6]}


