def pool_demand_last_24h() -> dict:
    """Actual supply vs demand in the last 24h for the daily pool report:
    - "sent": distinct items dispatched per game (1 slot = 1 item, counted once
      regardless of how many recipients got it);
    - "answered": answers recorded per game kind from the unified challenge ledger.
    """
    sent: dict[str, int] = {}
    answered: dict[str, int] = {}
    with get_db_connection_context() as conn:
        with conn.cursor() as cursor:
            sent_queries = {
                "rebus": "SELECT COUNT(DISTINCT (slot_date, slot_hour)) FROM bt_3_rebus_dispatches WHERE sent_at >= NOW() - INTERVAL '24 hours'",
                "article": "SELECT COUNT(DISTINCT (slot_date, slot_hour)) FROM bt_3_article_quiz_dispatches WHERE sent_at >= NOW() - INTERVAL '24 hours'",
                "crossword": "SELECT COUNT(DISTINCT (slot_date, slot_hour)) FROM bt_3_crossword_dispatches WHERE sent_at >= NOW() - INTERVAL '24 hours'",
                "anagram": "SELECT COUNT(DISTINCT (slot_date, slot_hour)) FROM bt_3_anagram_dispatches WHERE sent_at >= NOW() - INTERVAL '24 hours'",
                "aufgabe": "SELECT COUNT(DISTINCT (slot_date, slot_hour)) FROM bt_3_aufgabe_dispatches WHERE sent_at >= NOW() - INTERVAL '24 hours'",
                "listening": "SELECT COUNT(DISTINCT slot_date) FROM bt_3_listening_dispatches WHERE sent_at >= NOW() - INTERVAL '24 hours'",
                "numdict": "SELECT COUNT(DISTINCT (slot_date, slot_hour)) FROM bt_3_numdict_dispatches WHERE sent_at >= NOW() - INTERVAL '24 hours'",
            }
            for game, q in sent_queries.items():
                try:
                    cursor.execute(q)
                    sent[game] = int((cursor.fetchone() or [0])[0])
                except Exception:
                    sent[game] = 0
            try:
                cursor.execute(
                    """
                    SELECT split_part(challenge_key, ':', 1) AS kind, COUNT(*)
                    FROM bt_3_challenge_results
                    WHERE created_at >= NOW() - INTERVAL '24 hours'
                    GROUP BY 1
                    """
                )
                answered = {str(r[0]): int(r[1]) for r in (cursor.fetchall() or [])}
            except Exception:
                answered = {}

            # Per-format breakdown of the Aufgabe engine (Lückentext … Pin-Bild), so the
            # report can show delivery/answers for each format instead of one aggregate.
            # Uses the dedicated aufgabe tables joined to the bank's `format` column —
            # independent of the challenge-ledger key scheme.
            sent_au_fmt: dict[str, int] = {}
            answered_au_fmt: dict[str, int] = {}
            try:
                cursor.execute(
                    """
                    SELECT b.format, COUNT(DISTINCT (d.slot_date, d.slot_hour))
                    FROM bt_3_aufgabe_dispatches d
                    JOIN bt_3_aufgabe_bank b ON b.aufgabe_id = d.aufgabe_id
                    WHERE d.sent_at >= NOW() - INTERVAL '24 hours'
                    GROUP BY b.format
                    """
                )
                sent_au_fmt = {str(r[0]): int(r[1]) for r in (cursor.fetchall() or [])}
            except Exception:
                sent_au_fmt = {}
            try:
                cursor.execute(
                    """
                    SELECT b.format, COUNT(*)
                    FROM bt_3_aufgabe_answers a
                    JOIN bt_3_aufgabe_dispatches d ON d.id = a.dispatch_id
                    JOIN bt_3_aufgabe_bank b ON b.aufgabe_id = d.aufgabe_id
                    WHERE a.answered_at >= NOW() - INTERVAL '24 hours'
                    GROUP BY b.format
                    """
                )
                answered_au_fmt = {str(r[0]): int(r[1]) for r in (cursor.fetchall() or [])}
            except Exception:
                answered_au_fmt = {}
    return {
        "sent": sent,
        "answered": answered,
        "sent_aufgabe_by_format": sent_au_fmt,
        "answered_aufgabe_by_format": answered_au_fmt,
    }


def pick_next_listening(*, cooldown_days: int = 7, exclude_ids: list | None = None) -> dict | None:
    """Pick the oldest ready listening entry not sent within cooldown.

    `exclude_ids` — что закрыто ЛИЧНО этому человеку (см. `get_user_blocked_content_ids`).
    Банк аудирования маленький (30 записей, замер 14.08.2026), поэтому без личной
    ротации человеку раз за разом достаётся текст, который он уже слушал.
    """
    skip = [str(i) for i in (exclude_ids or []) if str(i)]
    with get_db_connection_context() as conn:
        with conn.cursor() as cursor:
            cursor.execute(
                """
                SELECT listening_id, topic, difficulty, german_text,
                       questions_json, audio_object_key, send_count
                FROM bt_3_listening_bank
                WHERE audio_status = 'ready'
                  AND retired = FALSE
                  AND (last_sent_at IS NULL
                       OR last_sent_at < NOW() - (%s || ' days')::INTERVAL)
                """
                + ("  AND listening_id::text <> ALL(%s)\n" if skip else "")
                + """
                ORDER BY last_sent_at NULLS FIRST, created_at
                LIMIT 1
                """,
                ((int(cooldown_days), skip) if skip else (int(cooldown_days),)),
            )
            row = cursor.fetchone()
    if not row:
        return None
    cols = ["listening_id", "topic", "difficulty", "german_text",
            "questions_json", "audio_object_key", "send_count"]
    return dict(zip(cols, row))


