def retire_all_numdict() -> int:
    """Retire every active numdict entry (so pick_next stops using them) — used by the
    admin "regenerate fresh" flow when the generator logic changes. Returns count."""
    with get_db_connection_context() as conn:
        with conn.cursor() as cursor:
            cursor.execute(
                "UPDATE bt_3_numdict_bank SET retired = TRUE, updated_at = NOW() WHERE retired = FALSE"
            )
            n = cursor.rowcount
        conn.commit()
    return int(n or 0)


def reset_numdict_audio() -> int:
    """Force re-synthesis of all active numdict audio (e.g. after the reading logic
    changes): flip audio_status back to 'pending' so the backfill regenerates it.
    Returns the number of entries reset."""
    with get_db_connection_context() as conn:
        with conn.cursor() as cursor:
            cursor.execute(
                """
                UPDATE bt_3_numdict_bank
                SET audio_status = 'pending', updated_at = NOW()
                WHERE retired = FALSE
                """
            )
            n = cursor.rowcount
        conn.commit()
    return int(n or 0)


def numdict_dispatched_today(plan_date) -> bool:
    with get_db_connection_context() as conn:
        with conn.cursor() as cursor:
            cursor.execute(
                "SELECT 1 FROM bt_3_numdict_dispatches WHERE slot_date = %s LIMIT 1",
                (plan_date,),
            )
            return cursor.fetchone() is not None


# ── Analytics summary snapshots ───────────────────────────────────────────────

def get_analytics_summary_snapshot(
    *,
    user_id: int,
    source_lang: str,
    target_lang: str,
    scope_key: str,
    period: str,
    start_date,
    end_date,
) -> dict | None:
    """Return precomputed snapshot {summary, is_dirty, computed_at} or None."""
    with get_db_connection_context() as conn:
        with conn.cursor() as cursor:
            cursor.execute(
                """
                SELECT summary_json, is_dirty, computed_at
                FROM bt_3_analytics_summary_snapshot
                WHERE user_id = %s AND source_lang = %s AND target_lang = %s
                  AND scope_key = %s AND period = %s
                  AND start_date = %s AND end_date = %s
                """,
                (int(user_id), str(source_lang), str(target_lang),
                 str(scope_key), str(period), start_date, end_date),
            )
            row = cursor.fetchone()
    if not row:
        return None
    return {"summary": row[0], "is_dirty": bool(row[1]), "computed_at": row[2]}


def upsert_analytics_summary_snapshot(
    *,
    user_id: int,
    source_lang: str,
    target_lang: str,
    scope_key: str,
    period: str,
    start_date,
    end_date,
    summary_json: dict,
) -> None:
    """Write/refresh a precomputed snapshot and clear its dirty flag."""
    import json as _json
    from decimal import Decimal as _Decimal

    def _json_default(o):
        if isinstance(o, _Decimal):
            return float(o)
        if hasattr(o, "isoformat"):  # date/datetime
            return o.isoformat()
        return str(o)

    with get_db_connection_context() as conn:
        with conn.cursor() as cursor:
            cursor.execute(
                """
                INSERT INTO bt_3_analytics_summary_snapshot
                    (user_id, source_lang, target_lang, scope_key, period,
                     start_date, end_date, summary_json, is_dirty, computed_at, updated_at)
                VALUES (%s, %s, %s, %s, %s, %s, %s, %s::jsonb, FALSE, NOW(), NOW())
                ON CONFLICT (user_id, source_lang, target_lang, scope_key,
                             period, start_date, end_date)
                DO UPDATE SET
                    summary_json = EXCLUDED.summary_json,
                    is_dirty     = FALSE,
                    computed_at  = NOW(),
                    updated_at   = NOW()
                """,
                (int(user_id), str(source_lang), str(target_lang), str(scope_key),
                 str(period), start_date, end_date,
                 _json.dumps(summary_json, ensure_ascii=False, default=_json_default)),
            )
        conn.commit()


def mark_analytics_snapshots_dirty_for_user(
    *,
    user_id: int,
    source_lang: str | None = None,
    target_lang: str | None = None,
    include_member_groups: bool = True,
) -> int:
    """Mark a user's snapshots dirty so they get recomputed. Returns rows touched.
    If source/target lang given, scope to that pair; otherwise all pairs.
    When include_member_groups=True, also marks dirty the group-scope snapshots
    (keyed by the group's chat_id) for every group the user has been SEEN in — so
    group analytics reflect the member's same-day activity. No button confirmation
    required (all-seen model, 2026-07-19); excludes groups retired as dead."""
    # Snapshot rows the activity affects: the user's own (personal) rows plus
    # the group rows (stored under the group's chat_id) for their groups.
    group_subquery = (
        " OR user_id IN (SELECT chat_id FROM bt_3_webapp_group_contexts "
        "WHERE user_id = %s AND participation_confirmed_source IS DISTINCT FROM 'auto_group_dead')"
        if include_member_groups else ""
    )
    with get_db_connection_context() as conn:
        with conn.cursor() as cursor:
            if source_lang and target_lang:
                params = [int(user_id)]
                if include_member_groups:
                    params.append(int(user_id))
                params += [str(source_lang), str(target_lang)]
                cursor.execute(
                    f"""
                    UPDATE bt_3_analytics_summary_snapshot
                    SET is_dirty = TRUE, updated_at = NOW()
                    WHERE (user_id = %s{group_subquery})
                      AND source_lang = %s AND target_lang = %s
                      AND is_dirty = FALSE
                    """,
                    tuple(params),
                )
            else:
                params = [int(user_id)]
                if include_member_groups:
                    params.append(int(user_id))
                cursor.execute(
                    f"""
                    UPDATE bt_3_analytics_summary_snapshot
                    SET is_dirty = TRUE, updated_at = NOW()
                    WHERE (user_id = %s{group_subquery})
                      AND is_dirty = FALSE
                    """,
                    tuple(params),
                )
            count = cursor.rowcount
        conn.commit()
    return count


def list_dirty_analytics_snapshot_keys(*, limit: int = 200) -> list[dict]:
    """Return dirty snapshot keys to recompute (for incremental refresh worker)."""
    with get_db_connection_context() as conn:
        with conn.cursor() as cursor:
            cursor.execute(
                """
                SELECT user_id, source_lang, target_lang, scope_key,
                       period, start_date, end_date
                FROM bt_3_analytics_summary_snapshot
                WHERE is_dirty = TRUE
                ORDER BY updated_at
                LIMIT %s
                """,
                (int(limit),),
            )
            rows = cursor.fetchall()
    cols = ["user_id", "source_lang", "target_lang", "scope_key",
            "period", "start_date", "end_date"]
    return [dict(zip(cols, r)) for r in rows]


def prune_stale_analytics_snapshots(*, older_than_days: int = 14) -> int:
    """Delete snapshots whose end_date is far in the past (rolled-over periods)."""
    with get_db_connection_context() as conn:
        with conn.cursor() as cursor:
            cursor.execute(
                """
                DELETE FROM bt_3_analytics_summary_snapshot
                WHERE end_date < CURRENT_DATE - (%s || ' days')::INTERVAL
                """,
                (int(older_than_days),),
            )
            count = cursor.rowcount
        conn.commit()
    return count


# ── Тестовое меню интерактивов ────────────────────────────────────────────────────────
# Часть интерактивов открывается по конкретному заданию (ребус, кроссворд, аудирование,
# Aufgabe…), поэтому меню «открыть каждый интерактив» должно знать свежий id для этого
# человека. Одна выборка на все виды: последнее задание каждого вида, отправленное ему.
INTERACTIVE_DISPATCH_TABLES: dict[str, str] = {
    "rb": "bt_3_rebus_dispatches",
    "cw": "bt_3_crossword_dispatches",
    "ag": "bt_3_anagram_dispatches",
    "ls": "bt_3_listening_dispatches",
    "qf": "bt_3_quiz_freeform_dispatches",
    "au": "bt_3_aufgabe_dispatches",
    "mc": "bt_3_mc_dispatches",
    "sp": "bt_3_sprint_dispatches",
    "tr": "bt_3_trainer_dispatches",
    "nd": "bt_3_numdict_dispatches",
}


def get_latest_interactive_dispatch_ids(user_id: int) -> dict[str, int]:
    """kind → id последнего задания этого вида, отправленного пользователю.

    Виды, которых у человека ещё не было, в ответе просто отсутствуют — вызывающий сам
    решает, что показать вместо кнопки. Пропавшая таблица (старая база) не роняет всё
    меню: такой вид тихо пропускается.
    """
    out: dict[str, int] = {}
    uid = int(user_id or 0)
    if not uid:
        return out
    with get_db_connection_context() as conn:
        for kind, table in INTERACTIVE_DISPATCH_TABLES.items():
            try:
                with conn.cursor() as cursor:
                    cursor.execute(
                        f"SELECT id FROM {table} WHERE target_user_id = %s ORDER BY id DESC LIMIT 1;",
                        (uid,),
                    )
                    row = cursor.fetchone()
                if row and row[0]:
                    out[kind] = int(row[0])
            except Exception as exc:  # таблицы может не быть — это не повод терять остальные
                conn.rollback()
                logging.debug("interactive_dispatch_lookup_failed kind=%s err=%s", kind, exc)
    return out


def count_dm_users_without_reply_keyboard(stale_days: float = 1.0) -> dict:
    """Сколько людей в личке остались без кнопок ФАКТИЧЕСКИ.

    Не «давно не обновляли» — клавиатура может висеть месяцами и это нормально, — а именно
    «клавиатуры нет»: якорь не записан или его сообщение удалено. Считаем только по живым
    перепискам (кому бот писал за последний месяц), иначе цифра превращается в шум из тех,
    кто ботом не пользуется.

    Возвращает: {"total", "never" — ни разу не получали, "lost" — сообщение-якорь удалено,
                 "ok" — кнопки на месте}.
    """
    out = {"total": 0, "never": 0, "lost": 0, "ok": 0}
    try:
        with get_db_connection_context() as conn:
            with conn.cursor() as cursor:
                cursor.execute(
                    """
                    WITH active AS (
                        SELECT DISTINCT chat_id AS user_id
                        FROM bt_3_telegram_system_messages
                        WHERE created_at > NOW() - INTERVAL '30 days' AND chat_id > 0
                    ),
                    state AS (
                        SELECT a.user_id,
                               k.anchor_message_id,
                               (SELECT s.deleted_at IS NULL
                                  FROM bt_3_telegram_system_messages s
                                 WHERE s.chat_id = a.user_id
                                   AND s.message_id = k.anchor_message_id
                                 ORDER BY s.id DESC LIMIT 1) AS anchor_alive
                        FROM active a
                        LEFT JOIN bt_3_reply_keyboard_state k ON k.user_id = a.user_id
                    )
                    SELECT COUNT(*),
                           COUNT(*) FILTER (WHERE anchor_message_id IS NULL),
                           COUNT(*) FILTER (WHERE anchor_message_id IS NOT NULL
                                              AND COALESCE(anchor_alive, FALSE) = FALSE)
                    FROM state;
                    """,
                )
                row = cursor.fetchone()
        if row:
            out["total"] = int(row[0] or 0)
            out["never"] = int(row[1] or 0)
            out["lost"] = int(row[2] or 0)
            out["ok"] = max(0, out["total"] - out["never"] - out["lost"])
    except Exception:
        logging.warning("count_dm_users_without_reply_keyboard failed", exc_info=True)
    return out


def is_reply_keyboard_alive(user_id: int) -> bool:
    """Жива ли клавиатура у этого человека прямо сейчас.

    Клавиатура на стороне Telegram привязана к сообщению-якорю. Значит проверка простая:
    якорь записан И это сообщение не удалено. Если да — трогать клавиатуру НЕ НАДО: она на
    месте, иконка вызова у человека есть. Пере-прикрепление лишний раз разворачивает
    клавиатуру на экране и мешает — именно поэтому оно должно делаться только по факту
    пропажи, а не по расписанию.
    """
    try:
        with get_db_connection_context() as conn:
            with conn.cursor() as cursor:
                cursor.execute(
                    """
                    SELECT s.deleted_at IS NULL
                    FROM bt_3_reply_keyboard_state k
                    JOIN bt_3_telegram_system_messages s
                      ON s.chat_id = k.user_id AND s.message_id = k.anchor_message_id
                    WHERE k.user_id = %s
                    ORDER BY s.id DESC
                    LIMIT 1;
                    """,
                    (int(user_id),),
                )
                row = cursor.fetchone()
        return bool(row and row[0])
    except Exception:
        logging.debug("is_reply_keyboard_alive failed user_id=%s", user_id, exc_info=True)
        # Не знаем — считаем, что жива: лучше не трогать, чем мешать лишним сообщением.
        return True


# ---------------------------------------------------------------------------
# Время активной учёбы (секунды внимания к тренировкам слов) — учёт по отрезкам.
#
# Клиент считает ТОЛЬКО текущий незакрытый отрезок и досылает его каждые
# несколько секунд под одним и тем же segment_id. Сервер держит дневную сумму.
# Поэтому убитое приложение теряет максимум интервал досылки, а не весь сеанс,
# а повторная присылка того же отрезка ничего не задваивает.
# ---------------------------------------------------------------------------

_STUDY_TIME_SCHEMA_DONE = False

# Потолки — защита от битого клиента: один отрезок и один день не могут быть
# длиннее разумного, иначе одна кривая цифра навсегда испортит статистику.
STUDY_TIME_MAX_SEGMENT_SECONDS = 4 * 60 * 60
STUDY_TIME_MAX_DAY_SECONDS = 16 * 60 * 60
STUDY_TIME_SURFACES = {"words"}


def ensure_study_time_schema() -> None:
    global _STUDY_TIME_SCHEMA_DONE
    if _STUDY_TIME_SCHEMA_DONE:
        return
    with get_db_connection_context() as conn:
        with conn.cursor() as cur:
            cur.execute(
                """CREATE TABLE IF NOT EXISTS bt_3_study_time_segments (
                    id BIGSERIAL PRIMARY KEY,
                    user_id BIGINT NOT NULL,
                    surface TEXT NOT NULL,
                    local_day DATE NOT NULL,
                    segment_id TEXT NOT NULL,
                    active_seconds INTEGER NOT NULL DEFAULT 0,
                    started_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
                    updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
                );"""
            )
            cur.execute(
                """CREATE UNIQUE INDEX IF NOT EXISTS bt_3_study_time_segments_uniq
                   ON bt_3_study_time_segments (user_id, segment_id);"""
            )
            cur.execute(
                """CREATE INDEX IF NOT EXISTS bt_3_study_time_segments_day_idx
                   ON bt_3_study_time_segments (user_id, surface, local_day);"""
            )
        conn.commit()
    _STUDY_TIME_SCHEMA_DONE = True


def _normalize_study_surface(surface: str | None) -> str:
    normalized = str(surface or "").strip().lower()
    return normalized if normalized in STUDY_TIME_SURFACES else "words"


def get_study_time_day_seconds(
    *,
    user_id: int,
    surface: str,
    local_day: date,
) -> int:
    ensure_study_time_schema()
    with get_db_connection_context() as conn:
        with conn.cursor() as cursor:
            cursor.execute(
                """
                SELECT COALESCE(SUM(active_seconds), 0)
                FROM bt_3_study_time_segments
                WHERE user_id = %s AND surface = %s AND local_day = %s;
                """,
                (int(user_id), _normalize_study_surface(surface), local_day),
            )
            row = cursor.fetchone()
    total = int((row[0] if row else 0) or 0)
    return max(0, min(total, STUDY_TIME_MAX_DAY_SECONDS))


def upsert_study_time_segment(
    *,
    user_id: int,
    surface: str,
    local_day: date,
    segment_id: str,
    active_seconds: int,
    started_at: datetime | None = None,
) -> int:
    """Записывает отрезок и возвращает дневную сумму.

    active_seconds у отрезка только растёт (GREATEST): досылки могут прийти не по
    порядку, и опоздавшая старая копия не должна откатывать уже учтённое время.
    """
    ensure_study_time_schema()
    normalized_segment_id = str(segment_id or "").strip()[:80]
    if not normalized_segment_id:
        raise ValueError("segment_id обязателен")
    safe_seconds = max(0, min(int(active_seconds or 0), STUDY_TIME_MAX_SEGMENT_SECONDS))
    safe_started_at = started_at or datetime.now(timezone.utc)
    normalized_surface = _normalize_study_surface(surface)

    with get_db_connection_context() as conn:
        with conn.cursor() as cursor:
            cursor.execute(
                """
                INSERT INTO bt_3_study_time_segments
                    (user_id, surface, local_day, segment_id, active_seconds, started_at, updated_at)
                VALUES (%s, %s, %s, %s, %s, %s, NOW())
                ON CONFLICT (user_id, segment_id) DO UPDATE
                SET active_seconds = GREATEST(
                        bt_3_study_time_segments.active_seconds,
                        EXCLUDED.active_seconds
                    ),
                    updated_at = NOW();
                """,
                (
                    int(user_id),
                    normalized_surface,
                    local_day,
                    normalized_segment_id,
                    safe_seconds,
                    safe_started_at,
                ),
            )
            cursor.execute(
                """
                SELECT COALESCE(SUM(active_seconds), 0)
                FROM bt_3_study_time_segments
                WHERE user_id = %s AND surface = %s AND local_day = %s;
                """,
                (int(user_id), normalized_surface, local_day),
            )
            row = cursor.fetchone()
        conn.commit()
    total = int((row[0] if row else 0) or 0)
    return max(0, min(total, STUDY_TIME_MAX_DAY_SECONDS))
